// biology: 32 lessons, 10 units
LESSONS.push(
  {"id":"g9-bio-1-u1-1","grade":"g9","subject":"biology","term":1,"unit":1,"no":1,"title":"خصائص الكائنات الحية","summary":"شرح متحرك للخصائص السبع للكائنات الحية والتمييز بين الكائن الحي والجماد، ثم أنشطة بثلاثة مستويات.","page":"lesson-characteristics-of-living-organisms.html","video":"","pdf":"","notes":["تشترك جميع الكائنات الحية في سبع خصائص أساسية (تُختصر بـ MRS GREN).","الحركة: تغيير موضع الكائن الحيّ أو جزءٍ منه؛ والتنفُّس: تفاعلات كيميائية في الخلايا لإطلاق الطاقة من الغذاء.","الإحساس: رصد التغيرات في البيئة والاستجابة لها؛ والنمو: زيادة دائمة في الحجم والكتلة الجافة.","التكاثر: إنتاج أفراد جديدة من النوع نفسه؛ والإخراج: التخلص من الفضلات الأيضية السامة والمواد الزائدة.","التغذية: الحصول على المواد اللازمة للطاقة والنمو (ذاتية في النبات وغير ذاتية في الحيوان)."],"exercises":["فسّر لماذا لا يُعدّ الروبوت المتحرّك كائنًا حيًّا.","فرّق بين التنفُّس الخلوي والشهيق والزفير، وبين الإخراج والتبرّز."],"levels":{"easy":[{"type":"mcq","q":"كم عدد الخصائص الأساسية المشتركة بين جميع الكائنات الحية؟","options":["٧ خصائص","٥ خصائص","٦ خصائص","٩ خصائص"],"answer":0,"why":"الخصائص السبع هي: الحركة، التنفس، الإحساس، النمو، التكاثر، الإخراج، التغذية."},{"type":"mcq","q":"ما الخاصية التي تعني إنتاج أفراد جديدة من النوع نفسه؟","options":["التغذية","التكاثر","النمو","الإخراج"],"answer":1,"why":"التكاثر يحفظ بقاء النوع عبر الأجيال."},{"type":"mcq","q":"اتجاه ساق النبات نحو ضوء الشمس مثال على خاصيتي:","options":["الإخراج والتكاثر","التكاثر فقط","الحركة والإحساس","التنفس والإخراج"],"answer":2,"why":"النبات يحسّ بالضوء ويتحرك باتجاهه."},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ من فضلات الإخراج في الإنسان؟","options":["الجلوكوز","الأكسجين","النشا","ثاني أكسيد الكربون واليوريا"],"answer":3,"why":"تُخرج الرئتان ثاني أكسيد الكربون وتُخرج الكليتان اليوريا."}],"medium":[{"type":"mcq","q":"أيُّ تعريفٍ مما يأتي يصف «النمو» بدقة علمية؟","options":["زيادة دائمة في الحجم والكتلة الجافة","انتقال الكائن من مكان لآخر","إخراج الفضلات السامة","زيادة مؤقتة في الوزن بعد شرب الماء"],"answer":0,"why":"النمو زيادة دائمة بزيادة عدد الخلايا أو حجمها."},{"type":"tfr","q":"النباتات لا تتحرك أبدًا لأنها ثابتة في التربة.","answer":false,"reasons":["لأن النباتات تتحرك حركة بطيئة وموضعية كاتجاه الساق للضوء وتفتح الأزهار","لأن النباتات ليست كائنات حية","لأن النباتات تجري مثل الحيوانات"],"reason":0},{"type":"essay","q":"اذكر الخصائص السبع للكائنات الحية.","model":"الحركة، التنفُّس، الإحساس، النمو، التكاثر، الإخراج، التغذية."},{"type":"tfr","q":"التنفُّس الخلوي يحدث داخل خلايا النبات والحيوان معًا لإطلاق الطاقة.","answer":true,"reasons":["لأن التنفس يحدث في الرئتين فقط","لأن جميع الكائنات الحية تحتاج إلى الطاقة لإتمام عملياتها الحيوية","لأن النبات لا يتنفس"],"reason":1},{"type":"mcq","q":"كيف تحصل النباتات الخضراء على غذائها؟","options":["بتناول الحشرات فقط","بصنعه بنفسها عبر التمثيل الضوئي","بامتصاص البروتين من الهواء","لا تحتاج إلى تغذية"],"answer":1,"why":"النباتات ذاتية التغذية تصنع غذاءها بضوء الشمس والماء وثاني أكسيد الكربون."},{"type":"essay","q":"لماذا يُعدّ التخلّص من ثاني أكسيد الكربون عبر الرئتين «إخراجًا»؟","model":"لأنه مادة فضلات ناتجة عن تفاعلات التنفُّس الكيميائية داخل الخلايا، وتراكمه يضر بالجسم."},{"type":"tfr","q":"انتفاخ قطعة إسفنج عند وضعها في الماء يُعدّ مثالًا على النمو الحيوي.","answer":false,"reasons":["لأن الإسفنج كائن حي","لأن النمو يحدث بالماء فقط","لأن الزيادة مؤقتة وتزول بالعصر وليست زيادة دائمة في الكتلة الجافة"],"reason":2}],"hard":[{"type":"mcq","q":"أيُّ العبارات الآتية تفرّق بدقة بين «الإخراج» و«التبرّز»؟","options":["الإخراج لا يحدث في النباتات","التبرّز يحدث في الرئتين","الإخراج يزيل فضلات التفاعلات الخلوية، والتبرّز يزيل طعامًا غير مهضوم","كلاهما يحمل المعنى نفسه تمامًا"],"answer":2,"why":"الفضلات الأيضية كاليوريا وCO₂ هي إخراج، أما الطعام غير المهضوم فلم يدخل الخلايا أصلًا."},{"type":"essay","q":"قارن بين سيارة متحرّكة وحصان يركض باستخدام أربع خصائص من خصائص الكائنات الحية.","model":"كلاهما يتحرك ويستخدم مصدر طاقة (وقود/غذاء)، لكن الحصان ينمو بزيادة خلاياه، ويتكاثر، ويحسّ بمحيطه تلقائيًا، ويُصلح أنسجته؛ بينما السيارة تعجز عن ذلك."},{"type":"tfr","q":"تتوقف النباتات عن التنفُّس في الليل لغياب ضوء الشمس.","answer":false,"reasons":["لأن التنفُّس يستمر ليلًا ونهارًا لإطلاق الطاقة، والذي يتوقف ليلًا هو التمثيل الضوئي","لأن النبات ينام ليلًا","لأن النبات يتنفس نهارًا فقط"],"reason":0},{"type":"mcq","q":"ما المقصود بـ «الكتلة الجافة» عند قياس النمو؟","options":["وزن الكائن بعد الأكل مباشرة","طول الكائن بالسنتيمتر","كتلة الماء داخل الجسم فقط","كتلة الكائن بعد إزالة محتواه من الماء"],"answer":3,"why":"الكتلة الجافة تعكس الزيادة الحقيقية في المادة الحية دون تقلبات الماء."},{"type":"essay","q":"اشرح كيف ترتبط خاصية «التغذية» بخاصية «التنفُّس» في جسم الإنسان.","model":"توفر التغذية جزيئات الغذاء مثل الجلوكوز، ثم يقوم التنفُّس الخلوي بتكسيرها داخل الخلايا لإطلاق الطاقة اللازمة للحياة."},{"type":"tfr","q":"إذا فقد فردٌ واحدٌ القدرة على التكاثر فإنه لا يعود كائنًا حيًّا.","answer":false,"reasons":["لأن الفرد يموت فورًا","لأن التكاثر خاصية لبقاء النوع، والفرد يظل حيًّا بقيامه ببقية العمليات الحيوية","لأن التكاثر ليس من الخصائص السبع"],"reason":1},{"type":"mcq","q":"أيُّ مثالٍ يوضّح خاصية الإحساس في النبات؟","options":["انغلاق أوراق نبات المستحية عند اللمس","تبلّل الساق بالمطر","سقوط ورقة جافة بالرياح","كسر غصن باليد"],"answer":0,"why":"نبات المستحية يستجيب لمؤثر اللمس بطيّ وريقاته."},{"type":"essay","q":"فسّر: لماذا تُعدّ الحركة مهمةً لبقاء الحيوانات في بيئتها؟","model":"تساعدها في البحث عن الغذاء والماء، والهروب من المفترسات، والبحث عن شريك للتكاثر، وتجنب الظروف القاسية."},{"type":"tfr","q":"الخميرة كائن حيّ لأنها تتنفس وتتكاثر وتنمو وتتغذى.","answer":true,"reasons":["لأنها مادة كيميائية غير حية","لأنها لا تتكاثر","لأنها فطر وحيد الخلية يحقق خصائص الكائنات الحية"],"reason":2},{"type":"essay","q":"اذكر مثالين من حياتك اليومية تلاحظ فيهما تداخل خاصيتين من خصائص الكائنات الحية معًا.","model":"مثال ١: سحب اليد عن جسم ساخن (إحساس + حركة). مثال ٢: تنفس العضلات لإطلاق الطاقة أثناء الركض (تنفس + حركة)."}]}},
  {"id":"g9-bio-1-u1-2","grade":"g9","subject":"biology","term":1,"unit":1,"no":2,"title":"الخلايا","summary":"شرح متحرك لتركيب الخلية الحيوانية والنباتية ووظائف العضيات وحساب التكبير، ثم أنشطة بثلاثة مستويات.","page":"lesson-cells.html","video":"","pdf":"","notes":["الأجزاء المشتركة بين الخلية الحيوانية والنباتية: غشاء الخلية، السيتوبلازم، النواة، الميتوكوندريا، والريبوسومات.","الأجزاء التي تنفرد بها الخلية النباتية: الجدار الخلوي السليلوزي، البلاستيدات الخضراء (تحوي الكلوروفيل)، الفجوة العصارية الكبيرة الدائمة.","الميتوكوندريا موقع التنفُّس الهوائي، والريبوسومات موقع تصنيع البروتينات.","قانون التكبير: التكبير = طول الصورة ÷ الطول الحقيقي (بنفس الوحدة، دون وحدة قياس للناتج).","للتحويل: ١ مم = ١٠٠٠ ميكرومتر (μm)."],"exercises":["قارن في جدول بين الخلية الحيوانية والخلية النباتية من حيث الجدار الخلوي والبلاستيدات والفجوة.","طول خلية في صورة ٢٥ مم وطولها الحقيقي ٥٠ ميكرومتر، احسب مقدار التكبير."],"levels":{"easy":[{"type":"mcq","q":"ما وظيفة غشاء الخلية؟","options":["صنع الغذاء","التحكم في دخول المواد وخروجها","منح اللون الأخضر","تخزين العصارة"],"answer":1,"why":"غشاء الخلية شبه منفذ ينظّم حركة المواد."},{"type":"mcq","q":"أين تحدث معظم التفاعلات الكيميائية في الخلية؟","options":["خارج الخلية","في الجدار الخلوي","في السيتوبلازم","في الكلوروفيل فقط"],"answer":2,"why":"السيتوبلازم مادة هلامية تحدث فيها معظم التفاعلات الحيوية."},{"type":"mcq","q":"ما وظيفة الريبوسومات في الخلية؟","options":["التمثيل الضوئي","تخزين الماء","دعم الجدار","تصنيع البروتينات"],"answer":3,"why":"الريبوسومات مسؤولة عن بناء البروتينات."},{"type":"mcq","q":"كم ميكرومترًا في ١ ملليمتر؟","options":["١٠٠٠","١٠٠٠٠","١٠٠","١٠"],"answer":0,"why":"١ مم = ١٠٠٠ ميكرومتر."}],"medium":[{"type":"mcq","q":"لماذا تحتوي خلايا العضلات على أعداد كبيرة جدًّا من الميتوكوندريا؟","options":["لإنتاج الكلوروفيل","لأنها تحتاج طاقة كبيرة للانقباض","لتصنيع الجدار الخلوي","لتخزين النشا"],"answer":1,"why":"الميتوكوندريا تطلق الطاقة بالتنفس الهوائي."},{"type":"tfr","q":"توجد البلاستيدات الخضراء في جميع خلايا النبات بما فيها خلايا الجذور تحت التربة.","answer":false,"reasons":["لأن خلايا الجذور لا يصلها الضوء فلا تحتاج إلى بلاستيدات خضراء","لأن البلاستيدات في الحيوانات فقط","لأن الجذور تصنع الغذاء بالضوء"],"reason":0},{"type":"essay","q":"اذكر ثلاثة تراكيب توجد في الخلية النباتية ولا توجد في الخلية الحيوانية.","model":"الجدار الخلوي السليلوزي، البلاستيدات الخضراء، الفجوة العصارية الكبيرة الدائمة."},{"type":"tfr","q":"يسمح الجدار الخلوي السليلوزي بمرور الماء والمواد الذائبة بحرية (نفاذ تام).","answer":true,"reasons":["لأنه يمنع دخول الماء تمامًا","لأن الجدار الخلوي منفذ تامًا ووظيفته الدعم، أما غشاء الخلية فهو شبه المنفذ","لأنه يتحكم كغشاء الخلية"],"reason":1},{"type":"mcq","q":"طول صورة خلية ٥٠ مم وطولها الحقيقي ٠٫٢ مم. ما مقدار التكبير؟","options":["×١٠","×١٠٠","×٢٥٠","×٥٠٠"],"answer":2,"why":"٥٠ ÷ ٠٫٢ = ٢٥٠ مرة."},{"type":"essay","q":"ما وظيفة النواة في الخلية؟","model":"تحتوي على المادة الوراثية (DNA) وتتحكم في جميع أنشطة الخلية وتفاعلاتها وانقسامها."},{"type":"tfr","q":"لا يمكن رؤية الريبوسومات بوضوح باستخدام المجهر الضوئي المدرسي العادي.","answer":true,"reasons":["لأنها أكبر من النواة","لأنها غير موجودة في الخلايا","لأنها صغيرة جدًّا وتحتاج إلى المجهر الإلكتروني ذي التكبير العالي"],"reason":2}],"hard":[{"type":"mcq","q":"صورة خلية طولها ٤٥ مم بتكبير ×٣٠٠. ما طولها الحقيقي بالملليمتر؟","options":["١٫٥ مم","٠٫٠١٥ مم","١٣٥٠٠ مم","٠٫١٥ مم"],"answer":3,"why":"الطول الحقيقي = الصورة ÷ التكبير = ٤٥ ÷ ٣٠٠ = ٠٫١٥ مم."},{"type":"essay","q":"احسب الطول الحقيقي بالميكرومتر لخلية طولها في الصورة ٣٦ مم إذا كان التكبير ×٦٠٠.","model":"الطول الحقيقي = ٣٦ ÷ ٦٠٠ = ٠٫٠٦ مم. نحول لميكرومتر: ٠٫٠٦ × ١٠٠٠ = ٦٠ ميكرومتر."},{"type":"tfr","q":"تُقاس قيمة التكبير بوحدة الميكرومتر.","answer":false,"reasons":["لأن التكبير نسبة بين طولين متماثلي الوحدة فليس له وحدة قياس (نكتب ×٥٠٠)","لأنه يُقاس بالسنتيمتر","لأنه يُقاس بالجرام"],"reason":0},{"type":"mcq","q":"ما المادة الغذائية المخزّنة غالبًا في سيتوبلازم الخلية الحيوانية مقابل النشا في النباتية؟","options":["الجلايكوجين","اليوريا","الكلوروفيل","السليلوز"],"answer":0,"why":"تخزّن الخلايا الحيوانية الجلوكوز الزائد على هيئة جلايكوجين."},{"type":"essay","q":"قارن بين وظيفة الجدار الخلوي ووظيفة غشاء الخلية في الخلية النباتية.","model":"الجدار الخلوي خارجي سميك من السليلوز يدعم الخلية ويحميها من الانفجار وهو منفذ تامًا؛ أما غشاء الخلية فرقيق داخلي شبه منفذ يتحكم في دخول وخروج المواد."},{"type":"tfr","q":"إذا ضاعفنا التكبير من ×١٠٠ إلى ×٤٠٠ فإن الطول الحقيقي للخلية يتضاعف ٤ مرات.","answer":false,"reasons":["لأن الصورة تصغر","لأن الطول الحقيقي ثابت، والذي يتضاعف ٤ مرات هو طول الصورة فقط","لأن الخلية تكبر فعليًا تحت المجهر"],"reason":1},{"type":"mcq","q":"أيُّ عضيّة تمتلئ بالعصارة الخلوية وتضغط على الجدار الخلوي لإبقاء النبات قائمًا؟","options":["الميتوكوندريا","الفجوة العصارية الكبيرة","النواة","الريبوسوم"],"answer":1,"why":"امتلاء الفجوة العصارية بالماء يمنح الخلية النباتية دعامة وامتلاءً."},{"type":"essay","q":"طول بكتيريا حقيقي هو ٢ ميكرومتر، ورُسمت بطول ٢٠ مم. احسب التكبير خطوة بخطوة.","model":"نحوّل ٢٠ مم × ١٠٠٠ = ٢٠٠٠٠ ميكرومتر. التكبير = ٢٠٠٠٠ ÷ ٢ = ×١٠٠٠٠."},{"type":"tfr","q":"جميع الخلايا النباتية تحتوي على نواة وغشاء خلوي وسيتوبلازم.","answer":true,"reasons":["لأن النواة للحيوان فقط","لأن النبات ليس له غشاء خلوي","لأن هذه هي المكونات الأساسية للخلايا الحية (باستثناء حالات خاصة ناضجة كأوعية الخشب)"],"reason":2},{"type":"essay","q":"اشرح لماذا يظهر شكل الخلية النباتية هندسيًّا منتظمًا بينما يبدو شكل الخلية الحيوانية متغيّرًا وغير منتظم.","model":"لوجود الجدار الخلوي السليلوزي الصلب حول الخلية النباتية الذي يثبّت شكلها، بينما تفتقر الخلية الحيوانية لهذا الجدار وتُحاط بغشاء مرن فقط."}]}},
  {"id":"g9-bio-1-u1-3","grade":"g9","subject":"biology","term":1,"unit":1,"no":3,"title":"الخلايا والكائنات الحية","summary":"شرح متحرك للخلايا المتخصّصة وتكيّف تركيبها مع وظيفتها ومستويات التنظيم في الكائن الحي، ثم أنشطة بثلاثة مستويات.","page":"lesson-cells-and-organisms.html","video":"","pdf":"","notes":["الخلايا المتخصّصة لها تكيّفات تركيبية تلائم وظائفها المحددة.","خلايا الدم الحمراء: مقعّرة الوجهين، تحوي هيموجلوبين، وبلا نواة لنقل أكبر كمية من الأكسجين.","الخلايا العصبية لها محور طويل لنقل السيالات، والمهدّبة تحرّك المخاط، والشعيرات الجذرية تزيد مساحة سطح امتصاص الماء.","خلايا النسيج العمادي غنية بالبلاستيدات الخضراء للقيام بالتمثيل الضوئي.","مستويات التنظيم التصاعدية: خلية ← نسيج ← عضو ← جهاز ← كائن حيّ."],"exercises":["اذكر تكيّفين لخلية الشعيرة الجذرية وبيّن كيف يساعدانها في وظيفتها.","صنّف كلًّا مما يأتي (خلية / نسيج / عضو / جهاز): المعدة، الدم الأحمر، الجهاز التنفسي، النسيج العضلي."],"levels":{"easy":[{"type":"mcq","q":"ما الوظيفة الأساسية لخلايا الدم الحمراء؟","options":["امتصاص الماء","التمثيل الضوئي","نقل الأكسجين","تحريك المخاط"],"answer":2,"why":"تحمل الأكسجين عبر بروتين الهيموجلوبين."},{"type":"mcq","q":"ما وظيفة خلايا الشعيرات الجذرية في النبات؟","options":["صنع الغذاء بالضوء","نقل السيالات العصبية","حماية الرئتين","امتصاص الماء والأملاح من التربة"],"answer":3,"why":"امتدادها الطويل يزيد مساحة امتصاص الماء والأملاح."},{"type":"mcq","q":"يُعدّ القلب في جسم الإنسان مثالًا على:","options":["عضو","خلية","جهاز","نسيج"],"answer":0,"why":"القلب عضو يتكون من عدة أنسجة متعاونة."},{"type":"mcq","q":"مجموعة الخلايا المتشابهة التي تؤدي وظيفة واحدة تُسمّى:","options":["كائنًا حيًّا","نسيجًا","عضوًا","جهازًا"],"answer":1,"why":"النسيج مجموعة خلايا متشابهة التركيب والوظيفة."}],"medium":[{"type":"mcq","q":"أيُّ خليةٍ نباتيةٍ تحتوي على أكبر عدد من البلاستيدات الخضراء؟","options":["بشرة الجذر","وعاء الخشب","خلية النسيج العمادي","خلية الشعيرة الجذرية"],"answer":2,"why":"خلايا النسيج العمادي هي الموقع الرئيس للتمثيل الضوئي."},{"type":"tfr","q":"تُعدّ الورقة في النبات مثالًا على «نسيج» وليس «عضوًا».","answer":false,"reasons":["لأن الورقة تتكون من عدة أنسجة مختلفة (البشرة والعمادي والإسفنجي والخشب واللحاء) فهي عضو","لأنها خلية واحدة","لأن النبات ليس له أعضاء"],"reason":0},{"type":"essay","q":"اذكر تكيّفين في تركيب خلايا الدم الحمراء يلائمان وظيفتها.","model":"١) عدم وجود نواة لزيادة مساحة الهيموجلوبين. ٢) الشكل القرصي مقعّر الوجهين لزيادة مساحة السطح لانتشار الأكسجين."},{"type":"tfr","q":"تمتلك الخلايا العصبية محورًا طويلًا لنقل الإشارات الكهربائية لمسافات طويلة في الجسم.","answer":true,"reasons":["لأنها تخزن النشا","لأن ذلك يتيح نقل السيال العصبي بسرعة من الأطراف إلى الدماغ والحبل الشوكي","لأنها تمتص الماء"],"reason":1},{"type":"mcq","q":"أين توجد الخلايا المهدّبة في جسم الإنسان؟","options":["في الكبد","في الجلد الخارجي","في العظام","في القصبة الهوائية والشعب الهوائية"],"answer":3,"why":"تبطّن الممرات التنفسية لتنظيفها من المخاط والغبار."},{"type":"essay","q":"رتّب المصطلحات الآتية من الأصغر إلى الأكبر: عضو، خلية، كائن حيّ، نسيج، جهاز.","model":"خلية ← نسيج ← عضو ← جهاز ← كائن حيّ."},{"type":"tfr","q":"خلايا الشعيرات الجذرية غنية بالبلاستيدات الخضراء.","answer":false,"reasons":["لأنها تصنع النشا بالضوء","لأنها خضراء اللون","لأنها تنمو تحت التربة بعيدًا عن الضوء فلا تقوم بالتمثيل الضوئي"],"reason":2}],"hard":[{"type":"mcq","q":"ماذا يحدث لو توقّفت الأهداب في القصبة الهوائية عن الحركة بسبب التدخين؟","options":["يتراكم المخاط والبكتيريا وتزداد التهابات الرئة","يزداد الأكسجين في الدم","تتحسن عملية الهضم","لا يحدث أي تأثير"],"answer":0,"why":"الأهداب هي التي تكنس المخاط المحمّل بالميكروبات خارج الرئتين."},{"type":"essay","q":"فسّر كيف يزيد الامتداد الطويل في خلية الشعيرة الجذرية من كفاءة امتصاص الماء.","model":"يزيد الامتداد الطويل مساحة السطح الملامسة لجزيئات الماء في التربة، مما يسرّع دخول الماء بالأسموزية والأملاح."},{"type":"tfr","q":"الجهاز الهضمي يتكوّن من أعضاء مختلفة كالمعدة والأمعاء والكبد تتعاون معًا في الهضم والامتصاص.","answer":true,"reasons":["وهذا تعريف الجهاز الحيوي: مجموعة أعضاء متعاونة لأداء وظيفة كبرى","لأنه يتكون من خلية واحدة","لأنه نسيج واحد"],"reason":0},{"type":"mcq","q":"أيُّ زوجٍ يمثّل (خلية متخصّصة : وظيفتها) بشكل صحيح؟","options":["خلية مهدّبة : نقل الأكسجين","خلية عمادية : التمثيل الضوئي","شعيرة جذرية : نقل السيال العصبي","خلية دم حمراء : تحريك المخاط"],"answer":1,"why":"النسيج العمادي مخصّص للتمثيل الضوئي."},{"type":"essay","q":"أعطِ مثالًا كاملًا لتسلسل مستويات التنظيم في الإنسان يبدأ بخلية عضلية.","model":"خلية عضلية ← نسيج عضلي ← عضو (القلب أو المعدة) ← جهاز (الجهاز الدوري أو الهضمي) ← الإنسان (كائن حيّ)."},{"type":"tfr","q":"الكائنات وحيدة الخلية كالبكتيريا تمتلك أنسجة وأعضاء وأجهزة.","answer":false,"reasons":["لأنها تضم ملايين الخلايا","لأن جسمها كله خلية واحدة فقط تؤدي جميع الوظائف الحيوية","لأنها نباتات"],"reason":1},{"type":"mcq","q":"ما البروتين الأحمر الذي يوجد داخل خلايا الدم الحمراء ويرتبط بالأكسجين؟","options":["السليلوز","الكلوروفيل","الهيموجلوبين","الأميليز"],"answer":2,"why":"الهيموجلوبين يحتوي على الحديد ويرتبط بالأكسجين."},{"type":"essay","q":"قارن بين النسيج والعضو مع ذكر مثال واحد لكل منهما.","model":"النسيج مجموعة خلايا متشابهة تؤدي وظيفة واحدة (مثل النسيج العضلي)، أما العضو فيتكوّن من عدة أنسجة مختلفة تتعاون لوظيفة محددة (مثل المعدة أو الورقة)."},{"type":"tfr","q":"الشكل مقعّر الوجهين لخلايا الدم الحمراء يقلّل من مساحة سطحها.","answer":false,"reasons":["لأنه يحتوي على نواة كبيرة","لأنه يمنع مرورها في الشعيرات","بل يزيد مساحة السطح مقارنةً بالحجم لتسريع انتشار الأكسجين"],"reason":2},{"type":"essay","q":"اشرح المقصود بعبارة «التركيب يلائم الوظيفة» مستشهدًا بخلية حيوانية وأخرى نباتية.","model":"تعني أن شكل الخلية وعضياتها مصممة لعملها؛ فالخلية العصبية لها محور طويل لنقل الإشارات، والخلية العمادية مليئة بالبلاستيدات الخضراء لامتصاص الضوء وصنع الغذاء."}]}},
  {"id":"g9-bio-1-u2-1","grade":"g9","subject":"biology","term":1,"unit":2,"no":1,"title":"الانتشار","summary":"شرح متحرك لمفهوم الانتشار وأمثلة حيوية والعوامل المؤثرة في سرعته، ثم أنشطة بثلاثة مستويات.","page":"lesson-diffusion.html","video":"","pdf":"","notes":["الانتشار: صافي حركة الجزيئات أو الأيونات من منطقة التركيز الأعلى إلى منطقة التركيز الأقل (مع منحدر التركيز).","مصدر الطاقة هو الطاقة الحركية العشوائية للجزيئات، لذا لا يحتاج طاقة من التنفس الخلوي.","أمثلة حيوية: تبادل الأكسجين وثاني أكسيد الكربون في الرئتين وأوراق النبات، وامتصاص بعض المواد المهضومة.","يزداد معدل الانتشار بزيادة: مساحة السطح، درجة الحرارة، ومنحدر التركيز؛ وبنقصان: مسافة الانتشار.","عند تساوي التركيز تستمر الجزيئات في الحركة العشوائية لكن يصبح صافي الانتشار صفرًا."],"exercises":["فسّر لماذا ينتشر لون قطرة الحبر في كوب ماء ساخن أسرع منه في كوب ماء بارد.","اذكر العوامل الأربعة المؤثرة في معدل الانتشار."],"levels":{"easy":[{"type":"mcq","q":"الانتشار هو صافي حركة الجزيئات من:","options":["التركيز الأقل إلى الأعلى","الصلب إلى السائل فقط","البارد إلى الساخن","التركيز الأعلى إلى الأقل"],"answer":3,"why":"الانتشار يتحرك دائمًا مع منحدر التركيز."},{"type":"mcq","q":"أيُّ عاملٍ مما يأتي يسرّع معدل الانتشار؟","options":["رفع درجة الحرارة","تقليل مساحة السطح","خفض الحرارة","زيادة المسافة"],"answer":0,"why":"رفع الحرارة يزيد الطاقة الحركية للجزيئات."},{"type":"mcq","q":"كيف يدخل ثاني أكسيد الكربون إلى ورقة النبات نهارًا؟","options":["بضخ القلب","بالانتشار عبر الثغور","بالهضم","عبر الجذور"],"answer":1,"why":"تركيزه في الهواء أعلى من داخل الورقة فينتشر عبر الثغور."},{"type":"mcq","q":"عند رش العطر في غرفة، تنتشر رائحته بفضل:","options":["التمثيل الضوئي","التنفس الخلوي","الحركة العشوائية لجزيئات الغاز","الجاذبية فقط"],"answer":2,"why":"جزيئات الغاز تتحرك عشوائيًا في كل الاتجاهات."}],"medium":[{"type":"mcq","q":"أيُّ التغيرات الآتية يبطئ سرعة الانتشار عبر غشاء؟","options":["زيادة فرق التركيز","رفع درجة الحرارة","زيادة مساحة السطح","زيادة سمك الغشاء (المسافة)"],"answer":3,"why":"زيادة المسافة تجعل الجزيئات تستغرق وقتًا أطول للعبور."},{"type":"tfr","q":"عندما يتساوى تركيز المادة في كل أنحاء الكوب تتوقّف الجزيئات تمامًا عن الحركة.","answer":false,"reasons":["تستمر الجزيئات بالحركة العشوائية، لكن صافي الانتشار فقط يصبح صفرًا","تعود للتركيز العالي","تتجمد الجزيئات فورًا"],"reason":0},{"type":"essay","q":"اذكر العوامل الأربعة التي تؤثر في سرعة الانتشار.","model":"مساحة السطح، درجة الحرارة، منحدر التركيز (فرق التركيز)، ومسافة الانتشار."},{"type":"tfr","q":"يحتاج الانتشار إلى طاقة كيميائية من الميتوكوندريا ليحدث.","answer":false,"reasons":["لأنه عكس منحدر التركيز","لأنه عملية سلبية تعتمد على الطاقة الحركية الذاتية للجزيئات","لأنه يحدث في الخلايا الحية فقط"],"reason":1},{"type":"mcq","q":"لماذا تحتوي الأمعاء الدقيقة على آلاف الخملات الدقيقة؟","options":["لزيادة مساحة سطح الانتشار والامتصاص","لإنتاج الأكسجين","لتبريد الطعام","لتقليل مساحة السطح"],"answer":0,"why":"زيادة مساحة السطح تسرّع انتقال الغذاء المهضوم للدم."},{"type":"essay","q":"اشرح اتجاه انتشار كلٍّ من الأكسجين وثاني أكسيد الكربون في الحويصلات الهوائية بالرئة.","model":"ينتشر الأكسجين من الحويصلات (تركيز أعلى) إلى الدم (تركيز أقل)، وينتشر ثاني أكسيد الكربون من الدم (تركيز أعلى) إلى الحويصلات (تركيز أقل)."},{"type":"tfr","q":"كلما كان منحدر التركيز أكبر، كان معدل الانتشار أسرع.","answer":true,"reasons":["لأن المنحدر لا يؤثر","لأن الجزيئات تبطئ","لأن الفارق الكبير في التركيز يزيد صافي عدد الجزيئات المنتقلة في الثانية"],"reason":2}],"hard":[{"type":"mcq","q":"وضعنا مكعبًا صغيرًا ومكعبًا كبيرًا من الهلام المصبوغ في حمض؛ أيهما يصله الحمض إلى مركزه أسرع؟","options":["لا ينتشر الحمض","المكعب الصغير لقصر مسافة الانتشار وكبر نسبة السطح للحجم","يصلان في الوقت نفسه","المكعب الكبير"],"answer":1,"why":"الأجسام الأصغر لها نسبة مساحة سطح إلى حجم أكبر ومسافة أقصر للمركز."},{"type":"essay","q":"فسّر: لماذا تحتاج الكائنات الكبيرة كالإنسان إلى جهاز دوري لنقل المواد ولا تكتفي بالانتشار وحده؟","model":"لأن المسافة بين سطح الجسم والخلايا العميقة كبيرة جدًّا، والانتشار يصبح بطيئًا جدًّا عبر المسافات الطويلة، لذا ينقل الدم المواد بسرعة قرب الخلايا ليحدث الانتشار عبر مسافة قصيرة."},{"type":"tfr","q":"الانتشار في الغازات أسرع عمومًا من الانتشار في السوائل.","answer":true,"reasons":["لأن جزيئات الغاز أبعد عن بعضها وتتحرك بسرعة أكبر وحرية أعلى من جزيئات السائل","لأن جزيئات الغاز أثقل","لأن السوائل لا تنتشر"],"reason":0},{"type":"mcq","q":"في تجربة أنبوب زجاجي به قطنة أمونيا وقطنة حمض هيدروكلوريك، تتكون سحابة بيضاء أقرب للحمض لأن:","options":["جزيئات الحمض أخف","الحرارة أقل عند الأمونيا","جزيئات الأمونيا أخف فتنتشر أسرع","لا يوجد انتشار"],"answer":2,"why":"الجزيئات الأصغر والأخف كتلة تنتشر بسرعة أكبر."},{"type":"essay","q":"توقّع ما يحدث لمعدل انتشار الأكسجين إلى الدم إذا أصبحت جدران الحويصلات أكثر سمكًا بسبب مرض ما.","model":"تزداد مسافة الانتشار فيقل معدل انتشار الأكسجين إلى الدم، مما يسبب ضيق التنفس ونقص الأكسجين."},{"type":"tfr","q":"استمرار جريان الدم في الشعيرات المحيطة بالحويصلات يحافظ على منحدر تركيز حاد للأكسجين.","answer":true,"reasons":["لأنه يوقف الانتشار","لأن الدم يحمل الأكسجين بعيدًا ويأتي بدم فقير بالأكسجين باستمرار فيظل الفرق كبيرًا","لأنه يرفع سمك الجدار"],"reason":1},{"type":"mcq","q":"أيُّ العوامل الآتية لا يؤثر مباشرةً في سرعة الانتشار؟","options":["منحدر التركيز","مساحة السطح","درجة الحرارة","لون الإناء الزجاجي"],"answer":3,"why":"لون الإناء لا يغيّر الطاقة الحركية ولا المسافة ولا التركيز."},{"type":"essay","q":"صمّم تجربة بسيطة توضّح أثر درجة الحرارة على سرعة الانتشار باستخدام كوبين وملوّن طعام.","model":"نضع كمية متساوية من الماء البارد في كوب والماء الساخن في كوب آخر، ثم نضيف قطرة واحدة من ملوّن الطعام لكل منهما في اللحظة نفسها ونقيس زمن تلوّن الماء كاملًا؛ نلاحظ أن الساخن يتلوّن أسرع."},{"type":"tfr","q":"يحدث الانتشار فقط عبر الأغشية الحية ولا يحدث في الأوساط غير الحية.","answer":false,"reasons":["لأنه يحتاج كلوروفيل","لأنه يحتاج نواة","الانتشار ظاهرة فيزيائية تحدث في الغازات والسوائل الحية وغير الحية على السواء"],"reason":2},{"type":"essay","q":"اذكر مثالين لأعضاء في جسم الإنسان أو النبات تكيّفت لزيادة سرعة الانتشار وبيّن التكيّف.","model":"١) الحويصلات الهوائية: عددها هائل (مساحة سطح كبيرة) وجدرانها رقيقة (مسافة قصيرة). ٢) أوراق النبات: رقيقة وعريضة لزيادة السطح وتقليل المسافة لدخول CO₂."}]}},
  {"id":"g9-bio-1-u2-2","grade":"g9","subject":"biology","term":1,"unit":2,"no":2,"title":"الأسموزية","summary":"شرح متحرك لمفهوم الأسموزية والجهد المائي وأثرها في الخلايا النباتية والحيوانية، ثم أنشطة بثلاثة مستويات.","page":"lesson-osmosis.html","video":"","pdf":"","notes":["الأسموزية: صافي حركة جزيئات الماء من منطقة ذات جهد مائي أعلى (محلول مخفف) إلى منطقة ذات جهد مائي أقل (محلول مركز) عبر غشاء شبه منفذ.","في الماء النقي: تمتلئ الخلية النباتية (Turgid) ولا تنفجر لوجود الجدار الخلوي، بينما تنتفخ الخلية الحيوانية وتنفجر.","في المحلول المركّز: تفقد الخلية النباتية الماء فتصبح رخوة ثم تتبلزم (Plasmolysis)، وتنكمش الخلية الحيوانية.","ضغط الامتلاء يدعم النباتات غير الخشبية ويبقي أوراقها قائمة نحو الضوء.","يمتص النبات الماء من التربة عبر الشعيرات الجذرية بالأسموزية."],"exercises":["فسّر لماذا تُحفظ الأطعمة أحيانًا في محلول ملحي أو سكري مركّز (المربّى والمخلّل) لحمايتها من البكتيريا.","توقّع ما يحدث لكتلة أسطوانة بطاطس وُضعت في محلول سكر مركّز لمدة ساعة، وفسّر إجابتك."],"levels":{"easy":[{"type":"mcq","q":"أيُّ مادةٍ تنتقل تحديدًا في عملية الأسموزية؟","options":["الماء فقط","السكر فقط","الأكسجين","البروتين"],"answer":0,"why":"الأسموزية حالة خاصة من الانتشار تختص بجزيئات الماء."},{"type":"mcq","q":"أيُّ محلولٍ له أعلى جهد مائي؟","options":["ماء البحر","الماء المقطّر النقي","محلول ملحي مركّز","شراب سكري ثقيل"],"answer":1,"why":"الماء النقي يحتوي على أعلى تركيز من جزيئات الماء الحرة."},{"type":"mcq","q":"عند وضع خلية نباتية في ماء نقي فإنها:","options":["تذبل","تنفجر","تمتلئ وتصبح صلبة","تتبلزم"],"answer":2,"why":"يدخل الماء فتنتفخ ويحميها الجدار الخلوي."},{"type":"mcq","q":"ما نوع الغشاء الذي تحدث عبره الأسموزية؟","options":["جدار صلب غير منفذ","ورق ترشيح واسع","زجاج","غشاء شبه منفذ (منفذ جزئيًا)"],"answer":3,"why":"يمرّر الماء ويمنع الجزيئات المذابة الكبيرة."}],"medium":[{"type":"mcq","q":"وُضعت قطعة بطاطس كتلتها ٥ جم في ماء مقطر فأصبحت ٥٫٦ جم؛ السبب هو:","options":["دخول الماء لخلايا البطاطس بالأسموزية","خروج الماء منها","تبخّر الماء","دخول السكر إليها"],"answer":0,"why":"الجهد المائي للماء المقطر أعلى من خلايا البطاطس فدخل الماء."},{"type":"tfr","q":"الخلية النباتية والخلية الحيوانية تنفجران معًا عند وضعهما في ماء نقي.","answer":false,"reasons":["تنفجر الحيوانية فقط، أما النباتية فيحميها الجدار الخلوي السليلوزي","تنفجر النباتية فقط","كلاهما ينكمش"],"reason":0},{"type":"essay","q":"عرّف الأسموزية تعريفًا علميًا دقيقًا.","model":"هي صافي حركة (انتشار) جزيئات الماء من منطقة ذات جهد مائي أعلى إلى منطقة ذات جهد مائي أقل عبر غشاء شبه منفذ."},{"type":"tfr","q":"عند إضافة كمية كبيرة من السماد الكيميائي حول جذور نبات قد يذبل النبات ويموت.","answer":true,"reasons":["لأن الماء يدخل بكثرة","لأن زيادة الأملاح تخفض الجهد المائي للتربة فيخرج الماء من الجذور للتربة بالأسموزية","لأن السماد يمنع الضوء"],"reason":1},{"type":"mcq","q":"ما الحالة التي تصبح عليها الخلية النباتية عندما يبتعد غشاؤها عن جدارها الخلوي؟","options":["الانفجار","البلزمة","الامتلاء","الانقسام"],"answer":1,"why":"البلزمة تنتج عن خروج الماء في محلول مركّز."},{"type":"essay","q":"لماذا لا يُحقن المريض بالماء المقطّر النقي مباشرة في الوريد؟","model":"لأن الجهد المائي للماء النقي أعلى من خلايا الدم الحمراء، فيدخل الماء إليها بالأسموزية فتنتفخ وتنفجر."},{"type":"tfr","q":"يمتص النبات الماء من التربة لأن الجهد المائي في التربة أعلى من الجهد المائي في خلايا الشعيرات الجذرية.","answer":true,"reasons":["لأن الجذر يضخ الماء للخارج","لأن التربة أكثر تركيزًا بالأملاح من الجذر","فينتقل الماء تلقائيًا من التربة إلى الجذر بالأسموزية"],"reason":2}],"hard":[{"type":"mcq","q":"في تجربة بطاطس وُضعت شرائح في ٥ تراكيز سكر، وبقيت الكتلة ثابتة عند تركيز ٠٫٣ مول/لتر؛ ماذا يعني ذلك؟","options":["التركيز صفر","البطاطس ميتة","الجهد المائي لخلايا البطاطس يساوي الجهد المائي لمحلول ٠٫٣ مول/لتر","توقّف الماء عن الحركة تمامًا"],"answer":2,"why":"ثبات الكتلة يدل على تساوي الجهد المائي داخل الخلايا وخارجها (صافي حركة الماء = صفر)."},{"type":"essay","q":"فسّر علميًا لماذا يطيل حفظ الفاكهة في محلول سكري مركّز (المربّى) من مدة صلاحيتها.","model":"المحلول السكري المركّز ذو جهد مائي منخفض جدًّا، فإذا سقطت عليه بكتيريا أو فطريات خرج منها الماء بالأسموزية فتجفّ وتموت ولا تفسد الطعام."},{"type":"tfr","q":"كلما أذبنا سكرًا أكثر في كوب ماء، ارتفع الجهد المائي للمحلول.","answer":false,"reasons":["إذابة المزيد من السكر تقلل تركيز جزيئات الماء الحرة فينخفض الجهد المائي","يزداد الماء الحر","يبقى الجهد المائي ثابتًا"],"reason":0},{"type":"mcq","q":"في أنبوب دياليز (شبه منفذ) مملوء بمحلول سكر مركّز وموضوع في كأس ماء نقي، ماذا يحدث لمستوى السائل داخل الأنبوب؟","options":["يبقى ثابتًا","يفرغ الأنبوب","ينخفض لخروج السكر","يرتفع لدخول الماء بالأسموزية"],"answer":3,"why":"يدخل الماء من الكأس (جهد أعلى) إلى الأنبوب (جهد أقل) فيرتفع السائل."},{"type":"essay","q":"قارن بين مصير خلية دم حمراء وخلية بشرة بصل عند وضعهما في: (١) ماء مقطّر، (٢) محلول ملح مركّز.","model":"في الماء المقطّر: تنفجر خلية الدم الحمراء، وتمتلئ خلية البصل دون انفجار. في المحلول المركّز: تنكمش خلية الدم الحمراء، وتصبح خلية البصل رخوة ثم تتبلزم."},{"type":"tfr","q":"الأسموزية عملية نشطة تستهلك طاقة من التنفس الخلوي.","answer":false,"reasons":["لأنها عكس منحدر الجهد المائي","لأن الأسموزية نوع خاص من الانتشار (عملية سلبية) تعتمد على الطاقة الحركية لجزيئات الماء","لأنها تحتاج ميتوكوندريا"],"reason":1},{"type":"mcq","q":"ما المصطلح الذي يصف الخلية النباتية الممتلئة بالماء والتي تضغط على جدارها الخلوي؟","options":["ممتلئة / منتفخة (Turgid)","متبلزمة","منكمشة","منفجرة"],"answer":0,"why":"الامتلاء يعطي النبات الدعامة."},{"type":"essay","q":"شريحة بطاطس كتلتها الابتدائية ٤٫٠ جم وأصبحت ٣٫٦ جم بعد وضعها في محلول ملحي. احسب النسبة المئوية للتغيّر في الكتلة.","model":"التغير = ٣٫٦ − ٤٫٠ = −٠٫٤ جم. النسبة = (−٠٫٤ ÷ ٤٫٠) × ١٠٠٪ = −١٠٪ (نقص بنسبة ١٠٪)."},{"type":"tfr","q":"يسمح غشاء الدياليز (فيسكينج) بمرور جزيئات الماء بينما يمنع مرور جزيئات النشا الكبيرة.","answer":true,"reasons":["لأنه يمرر النشا فقط","لأنه يمنع الماء أيضًا","لأنه غشاء شبه منفذ ثقوبه صغيرة جدًّا لا تسمح بعبور الجزيئات الضخمة كالنشا"],"reason":2},{"type":"essay","q":"اشرح كيف يدعم ضغط الامتلاء الناتج عن الأسموزية ساق نبات عشبي صغير.","model":"تمتلئ الفجوات العصارية بالماء وتضغط من الداخل على الجدران الخلوية، فتتراص الخلايا الصلبة معًا وتبقي الساق قائمًا والأوراق منبسطة نحو الشمس."}]}},
  {"id":"g9-bio-1-u3-1","grade":"g9","subject":"biology","term":1,"unit":3,"no":1,"title":"ممَّ يتكون جسمك؟","summary":"شرح متحرك لمكونات الجسم من الماء والجزيئات الحيوية وأهمية الماء كمذيب حيوي، ثم أنشطة بثلاثة مستويات.","page":"lesson-what-are-you-made-of.html","video":"","pdf":"","notes":["يشكّل الماء ٧٠٪ – ٨٠٪ من كتلة أجسام معظم الكائنات الحية.","الماء مذيب حيوي أساسي: تحدث فيه التفاعلات الأيضية في السيتوبلازم، وينقل المواد في بلازما الدم والخشب واللحاء.","يشارك الماء في الهضم، وإذابة اليوريا لإخراجها في البول، وتبريد الجسم عبر العرق.","الجزيئات الحيوية العضوية الرئيسة هي: الكربوهيدرات، والدهون، والبروتينات.","تُبنى الجزيئات الكبيرة من وحدات أصغر (جلوكوز ← نشا، أحماض أمينية ← بروتين، جليسرول + ٣ أحماض دهنية ← دهون)."],"exercises":["اذكر أربع وظائف حيوية للماء في جسم الإنسان.","اربط بين كل جزيء حيوي ووحدته البنائية: النشا، البروتين، الدهون."],"levels":{"easy":[{"type":"mcq","q":"ما المادة الأكثر وفرة في جسم الإنسان؟","options":["النشا","الماء","الحديد","الدهون"],"answer":1,"why":"يشكّل الماء ٧٠–٨٠٪ من كتلة الجسم."},{"type":"mcq","q":"أيُّ جزيءٍ مما يأتي يُعدّ الوحدة البنائية للنشا؟","options":["الحمض الأميني","اليوريا","الجلوكوز","الجليسرول"],"answer":2,"why":"النشا سلسلة طويلة من جزيئات الجلوكوز."},{"type":"mcq","q":"كيف ينقل الدم الجلوكوز واليوريا في الجسم؟","options":["في العظام","بلا ماء","على هيئة غازات","مذابة في ماء بلازما الدم"],"answer":3,"why":"الماء هو المذيب الرئيس في بلازما الدم."},{"type":"mcq","q":"ما الوحدة البنائية للبروتينات؟","options":["الأحماض الأمينية","السكروز","الأحماض الدهنية","الماء"],"answer":0,"why":"ترتبط الأحماض الأمينية لتكوين البروتينات."}],"medium":[{"type":"mcq","q":"ما الدور الذي يؤديه الماء في عملية الإخراج عبر الكليتين؟","options":["بناء العظام","إذابة اليوريا والأملاح الزائدة لطرحها في البول","إنتاج الأكسجين","تخزين النشا"],"answer":1,"why":"الماء يذيب الفضلات السامة ليسهل إخراجها."},{"type":"tfr","q":"تحدث التفاعلات الكيميائية في السيتوبلازم بشكل طبيعي حتى عند غياب الماء تمامًا.","answer":false,"reasons":["لأن المواد المتفاعلة يجب أن تكون مذابة في الماء لتتفاعل داخل السيتوبلازم","لأن السيتوبلازم صلب","لأن الماء يوقف التفاعلات"],"reason":0},{"type":"essay","q":"اذكر أربع وظائف للماء في أجسام الكائنات الحية.","model":"١) مذيب للتفاعلات الكيميائية في الخلايا. ٢) نقل المواد في الدم والنبات. ٣) المساعدة في الهضم. ٤) إذابة الفضلات للإخراج وتنظيم الحرارة بالتعرق."},{"type":"tfr","q":"يتكوّن جزيء الدهن من جزيء جليسرول واحد مرتبط بثلاثة أحماض دهنية.","answer":true,"reasons":["لأنه يتكون من جلوكوز","هذا هو التركيب البنائي الأساسي للدهون والزيوت","لأنه يتكون من أحماض أمينية"],"reason":1},{"type":"mcq","q":"كيف ينتقل الماء والأملاح المعدنية في النبات من الجذور إلى الأوراق؟","options":["عبر الشرايين","عبر البلازما","عبر أوعية الخشب","عبر الثغور"],"answer":2,"why":"أوعية الخشب تنقل الماء والأملاح المذابة لأعلى."},{"type":"essay","q":"ما المقصود بـ «الجزيئات الحيوية»؟ اذكر مجموعاتها الثلاث الرئيسة.","model":"هي جزيئات عضوية كبيرة تحتوي على الكربون توجد في الكائنات الحية، ومجموعاتها الثلاث: الكربوهيدرات والدهون والبروتينات."},{"type":"tfr","q":"العناصر الثلاثة المشتركة بين الكربوهيدرات والدهون والبروتينات هي الكربون والهيدروجين والأكسجين.","answer":true,"reasons":["لأن الكربوهيدرات فيها نيتروجين","لأن الدهون بلا كربون","جميعها تحوي C و H و O، وتضيف البروتينات عنصر النيتروجين N"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا يُعدّ الماء مناسبًا جدًّا لتبريد جسم الإنسان عند ارتفاع الحرارة؟","options":["لأن الماء أثقل من الدهون","لأن الماء يمنع التنفس","لأن الماء يتجمد على الجلد","لأن تبخّر العرق يمتص طاقة حرارية كبيرة من الجلد"],"answer":3,"why":"تبخّر الماء يسحب الحرارة الكامنة من الجلد فيبرّده."},{"type":"essay","q":"فسّر: لماذا يموت الإنسان بسبب العطش أسرع بكثير من الموت بسبب الجوع؟","model":"لأن الماء يشكّل ٧٠–٨٠٪ من الجسم وتعتمد عليه فورًا التفاعلات الخلوية وحجم الدم ونقل المواد وإخراج السموم وتنظيم الحرارة، بينما يملك الجسم مخزونًا من الدهون والجلايكوجين يكفي لأيام."},{"type":"tfr","q":"السوائل التي تحيط بالخلايا تساعد على تبادل الغازات والمواد الغذائية عبر أغشيتها.","answer":true,"reasons":["لأن الغازات كالأكسجين تذوب في طبقة الماء الرقيقة قبل انتشارها عبر غشاء الخلية","لأن الخلايا جافة تمامًا","لأن الماء يمنع الانتشار"],"reason":0},{"type":"mcq","q":"أيُّ العبارات الآتية غير صحيحة حول دور الماء في الهضم؟","options":["الماء يُغني تمامًا عن الأنزيمات الهاضمة","الماء مذيب للأنزيمات والغذاء المهضوم","الماء يسهّل حركة الطعام في القناة الهضمية","الماء يشارك في تفاعلات التحلّل المائي"],"answer":0,"why":"الأنزيمات ضرورية لتسريع الهضم إلى جانب الماء."},{"type":"essay","q":"اشرح تشبيه «العقد والخرز» في وصف بناء الجزيئات الحيوية الكبيرة، مع ذكر مثالين.","model":"الجزيء الكبير يشبه العقد الطويل والوحدات الصغيرة تشبه الخرز؛ فمثلًا يرتبط الجلوكوز لبناء النشا، وترتبط الأحماض الأمينية لبناء البروتينات."},{"type":"tfr","q":"تحتاج البذور الجافة إلى امتصاص الماء لكي تبدأ في الإنبات.","answer":true,"reasons":["لأن الماء يوقف الأنزيمات","لأن الماء ينشّط الأنزيمات داخل البذرة ويذيب الغذاء المخزّن ليبدأ الجنين بالنمو","لأن البذور تنبت بلا ماء"],"reason":1},{"type":"mcq","q":"أيُّ جزيءٍ حيويٍّ يضيف عنصر النيتروجين (N) بشكل أساس إلى C و H و O؟","options":["الكربوهيدرات","البروتينات","الدهون","الماء"],"answer":1,"why":"الأحماض الأمينية المكوّنة للبروتينات تحتوي على النيتروجين."},{"type":"essay","q":"قارن بين دور الماء في الإنسان ودوره في النبات في عملية النقل.","model":"في الإنسان يشكّل الماء أساس بلازما الدم لنقل الغذاء والهرمونات واليوريا؛ وفي النبات ينقل الأملاح المعدنية في الخشب والسكريات في اللحاء."},{"type":"tfr","q":"المواد غير العضوية مثل الماء والأملاح المعدنية لا تحتوي على سلاسل كربون وهيدروجين عضوية.","answer":true,"reasons":["لأن الماء مركب عضوي","لأن الماء يحتوي على كربون","لأن الماء H₂O مركب غير عضوي بخلاف الكربوهيدرات والدهون والبروتينات العضوية"],"reason":2},{"type":"essay","q":"كيف تتأثر عملية الإخراج في الكليتين إذا قلّ شرب الماء في يوم حار؟","model":"يحتفظ الجسم بأكبر قدر من الماء، فيصبح البول قليل الحجم ومركزًا باليوريا والأملاح ولونه داكنًا."}]}},
  {"id":"g9-bio-1-u3-2","grade":"g9","subject":"biology","term":1,"unit":3,"no":2,"title":"الكربوهيدرات","summary":"شرح متحرك لأنواع الكربوهيدرات ووظائفها واختباري اليود وبندكت للكشف عنها، ثم أنشطة بثلاثة مستويات.","page":"lesson-carbohydrates.html","video":"","pdf":"","notes":["تتكوّن الكربوهيدرات من عناصر الكربون (C) والهيدروجين (H) والأكسجين (O)، وهي المصدر السريع للطاقة.","السكريات البسيطة (مثل الجلوكوز C₆H₁₂O₆) صغيرة وحلوة وذائبة في الماء.","السكريات المتعددة غير ذائبة في الماء: النشا (تخزين في النبات)، الجلايكوجين (تخزين في كبد وعضلات الحيوان)، السليلوز (جدار الخلية النباتية).","اختبار النشا: محلول اليود يتغيّر من بني مصفر إلى أزرق مسود.","اختبار السكريات المختزلة (كالجلوكوز): محلول بندكت الأزرق + تسخين في حمام مائي ← أخضر / أصفر / برتقالي / أحمر طوبي."],"exercises":["قارن بين الجلوكوز والنشا من حيث الذوبان في الماء والوظيفة واختبار الكشف.","اختبر طالب عصير عنب بمحلول بندكت دون تسخين فبقي أزرق، ما الخطأ الذي وقع فيه؟"],"levels":{"easy":[{"type":"mcq","q":"ما العناصر الكيميائية المكوّنة للكربوهيدرات؟","options":["Fe و O","H و N فقط","C و H و O","C و N فقط"],"answer":2,"why":"الكربون والهيدروجين والأكسجين."},{"type":"mcq","q":"ما الكاشف المستخدم للكشف عن وجود النشا؟","options":["الإيثانول","محلول بندكت","محلول بيوريت","محلول اليود"],"answer":3,"why":"اليود يتحول لأزرق مسود مع النشا."},{"type":"mcq","q":"أين يُخزَّن الجلايكوجين في جسم الإنسان؟","options":["في الكبد والعضلات","في العظام","في الجدار الخلوي","في الرئتين"],"answer":0,"why":"يُخزّن الجلوكوز الزائد كجلايكوجين في الكبد والعضلات."},{"type":"mcq","q":"ما لون محلول بندكت قبل التسخين؟","options":["بني مصفر","أزرق","أبيض","أحمر طوبي"],"answer":1,"why":"بندكت محلول أزرق اللون."}],"medium":[{"type":"mcq","q":"أيُّ لونٍ في اختبار بندكت يدلّ على أعلى تركيز من الجلوكوز؟","options":["الأزرق","الأخضر","الأحمر الطوبي","البني المصفر"],"answer":2,"why":"تدرج الألوان من الأزرق (صفر) حتى الأحمر الطوبي (تركيز عالٍ)."},{"type":"tfr","q":"النشا يذوب بسهولة في الماء البارد وطعمه حلو كالجلوكوز.","answer":false,"reasons":["لأن النشا سكر متعدد جزيئاته ضخمة لا تذوب في الماء وليس له طعم حلو","لأن النشا سكر أحادي","لأنه يذوب فورًا"],"reason":0},{"type":"essay","q":"اشرح خطوات إجراء اختبار بندكت للكشف عن الجلوكوز في عينة غذائية.","model":"نضع العينة السائلة في أنبوب اختبار، ونضيف كمية مناسبة من محلول بندكت الأزرق، ثم نسخّن الأنبوب في حمام مائي ساخن (٨٠°م) لبضع دقائق ونلاحظ تغيّر اللون إلى أخضر أو أصفر أو برتقالي أو أحمر طوبي."},{"type":"tfr","q":"يُستخدم السليلوز في بناء جدران الخلايا النباتية.","answer":true,"reasons":["لأنه من الدهون","لأنه يتكون من ألياف جلوكوز قوية تمنح الخلية النباتية الدعامة","لأنه يُخزن في الكبد"],"reason":1},{"type":"mcq","q":"أيُّ الكربوهيدرات الآتية يُستخدم مباشرةً في التنفس الخلوي لإطلاق الطاقة؟","options":["اليود","السليلوز","الماء","الجلوكوز"],"answer":3,"why":"الجلوكوز هو الوقود المباشر للخلايا."},{"type":"essay","q":"لماذا يُعدّ عدم ذوبان النشا في الماء ميزةً مهمة لتخزينه في الخلايا النباتية؟","model":"لأنه لا يؤثر في الجهد المائي داخل الخلية، فلا يتسبب في دخول الماء باستمرار بالأسموزية."},{"type":"tfr","q":"عند إضافة اليود إلى محلول جلوكوز نقي يتحول اللون إلى أزرق مسود.","answer":false,"reasons":["الجلوكوز هو نفسه النشا","اليود يعطي أحمر طوبي","اليود يكشف النشا فقط، لذا يبقى بنيًّا مصفرًّا مع الجلوكوز"],"reason":2}],"hard":[{"type":"mcq","q":"أعطت عينة غذاء أزرق مسود مع اليود، وبقيت زرقاء مع بندكت بالتسخين؛ ماذا تحتوي؟","options":["تحتوي على نشا ولا تحتوي على سكر مختزل","تحتوي على جلوكوز فقط","تحتوي على كليهما","خالية منهما"],"answer":0,"why":"إيجابية لليود (نشا) وسلبية لبندكت (لا سكر مختزل)."},{"type":"essay","q":"قارن بين النشا والجلايكوجين والسليلوز من حيث: الوحدة البنائية، ومكان الوجود، والوظيفة.","model":"الوحدة البنائية للثلاثة هي الجلوكوز. النشا في النبات لتخزين الطاقة، الجلايكوجين في كبد وعضلات الحيوان لتخزين الطاقة، والسليلوز في الجدار الخلوي النباتي للدعامة."},{"type":"tfr","q":"في الجزيء الواحد من الكربوهيدرات يكون عدد ذرات الهيدروجين ضعف عدد ذرات الأكسجين عادةً (كما في الماء).","answer":true,"reasons":["كما في الجلوكوز C₆H₁₂O₆ (١٢ هيدروجين مقابل ٦ أكسجين)","لأن الأكسجين ضعف الهيدروجين","لأنهما متساويان"],"reason":0},{"type":"mcq","q":"ماذا ينتج عن تحلّل جزيء النشا بالكامل بواسطة الأنزيمات؟","options":["أحماض أمينية","جزيئات جلوكوز","جليسرول","أحماض دهنية"],"answer":1,"why":"النشا مبني من سلاسل جلوكوز."},{"type":"essay","q":"لماذا يأكل الرياضي وجبة غنية بالكربوهيدرات قبل السباق بساعات، وقطعة تمر قبل البدء مباشرة؟","model":"الكربوهيدرات المعقدة تبني مخزون الجلايكوجين للطاقة الممتدة، أما التمر فغني بالسكريات البسيطة التي تُمتص سريعًا لتوفير طاقة فورية."},{"type":"tfr","q":"تتغيّر نتيجة اختبار بندكت من الأزرق إلى الأحمر الطوبي في وجود تركيز عالٍ من السكر المختزل.","answer":true,"reasons":["لأنها لا تحتاج تسخينًا","لأن السكر المختزل يختزل أيونات النحاس في محلول بندكت عند التسخين مكوّنًا راسبًا أحمر طوبيًّا","لأنها تتحول للأزرق المسود"],"reason":1},{"type":"mcq","q":"ما نوع السكر الذي ينتقل عادةً عبر اللحاء في النبات؟","options":["النشا غير الذائب","الجلايكوجين","السكروز (سكر ثنائي ذائب)","السليلوز"],"answer":2,"why":"السكروز ذائب في الماء فينتقل بسهولة في اللحاء."},{"type":"essay","q":"فسّر: لماذا نستخدم حمامًا مائيًا لتسخين أنابيب اختبار بندكت بدل اللهب المباشر؟","model":"لتوزيع الحرارة بانتظام وأمان ومنع غليان المحلول فجأة واندفاعه خارج الأنبوب."},{"type":"tfr","q":"السكريات المتعددة حلوة المذاق لأنها تتكوّن من جلوكوز.","answer":false,"reasons":["لأنها ليست كربوهيدرات","لأنها أحلى من الجلوكوز","رغم أنها مبنية من الجلوكوز، فإن كبر حجمها وعدم ذوبانها يجعلانها غير حلوة المذاق"],"reason":2},{"type":"essay","q":"كيف يمكنك مقارنة تركيز الجلوكوز في ثلاثة عصائر مختلفة باستخدام اختبار بندكت؟","model":"نأخذ حجومًا متساوية من العصائر الثلاثة مع حجوم متساوية من بندكت ونسخّنها للمدة نفسها في الحمام المائي نفسه، ثم نقارن الألوان: الأحمر الطوبي أعلى تركيزًا، ثم البرتقالي فالأصفر فالأخضر."}]}},
  {"id":"g9-bio-1-u3-3","grade":"g9","subject":"biology","term":1,"unit":3,"no":3,"title":"الدهون","summary":"شرح متحرك لتركيب الدهون والزيوت ووظائفها في الجسم واختبار مستحلب الإيثانول، ثم أنشطة بثلاثة مستويات.","page":"lesson-fats.html","video":"","pdf":"","notes":["تتكوّن الدهون والزيوت من C و H و O (بنسبة أكسجين أقل من الكربوهيدرات).","جزيء الدهن = ١ جليسرول + ٣ أحماض دهنية، وهي لا تذوب في الماء وتذوب في الإيثانول.","الدهون صلبة في حرارة الغرفة (حيوانية غالبًا)، والزيوت سائلة (نباتية غالبًا).","وظائف الدهون: تخزين الطاقة (ضعف طاقة الكربوهيدرات لكل جرام)، العزل الحراري، حماية الأعضاء، وبناء أغشية الخلايا.","اختبار مستحلب الإيثانول: رجّ العينة مع إيثانول ثم إضافة ماء مقطّر ← مستحلب أبيض معكّر (بعيدًا عن اللهب)."],"exercises":["اذكر أربع وظائف للدهون في جسم الإنسان.","اشرح خطوات الكشف عن الزيت في بذور السمسم مع ذكر احتياط الأمان."],"levels":{"easy":[{"type":"mcq","q":"كم عدد الأحماض الدهنية في جزيء الدهن الواحد؟","options":["١","٢","٦","٣"],"answer":3,"why":"جزيء جليسرول واحد + ٣ أحماض دهنية."},{"type":"mcq","q":"في أي سائلٍ تذوب الدهون في اختبار الكشف عنها؟","options":["الإيثانول","اليود","الماء المقطّر","بندكت"],"answer":0,"why":"تذوب الدهون في الإيثانول ولا تذوب في الماء."},{"type":"mcq","q":"ما المظهر الذي يدلّ على وجود دهون في اختبار مستحلب الإيثانول؟","options":["لون أزرق داكن","مستحلب أبيض معكّر","سائل صافٍ تمامًا","لون أخضر"],"answer":1,"why":"النتيجة الإيجابية هي مستحلب أبيض معكّر."},{"type":"mcq","q":"أيُّ مادةٍ تعطي طاقةً أكبر لكل ١ جرام منها؟","options":["الكربوهيدرات","الألياف","الدهون","الماء"],"answer":2,"why":"تعطي الدهون نحو ضعف طاقة الكربوهيدرات لكل جرام."}],"medium":[{"type":"mcq","q":"ما وظيفة الدهون المحيطة بالكليتين والقلب؟","options":["هضم الطعام","التمثيل الضوئي","نقل الأكسجين","حمايتها من الصدمات"],"answer":3,"why":"تعمل كوسادة واقية للأعضاء الحساسة."},{"type":"tfr","q":"تحتاج تجربة الكشف عن الدهون بالإيثانول إلى تسخينها فوق لهب بنسن.","answer":false,"reasons":["لا تحتاج للتسخين أبدًا، كما أن الإيثانول سريع الاشتعال ويشكّل خطرًا قرب اللهب","لأن الإيثانول لا يشتعل","لأن التسخين يظهر اللون الأزرق"],"reason":0},{"type":"essay","q":"اشرح خطوات إجراء اختبار مستحلب الإيثانول للكشف عن الدهون في بذور الفول السوداني.","model":"نهرس البذور ونضيف إليها إيثانول ونرجّ جيدًا لإذابة الدهون، ثم نصبّ السائل الصافي في أنبوب به ماء مقطّر ونرجّه؛ فيظهر مستحلب أبيض معكّر."},{"type":"tfr","q":"تُخزّن الثدييات البحرية كالحيتان والفقمات طبقةً سميكةً من الدهون تحت جلدها للعزل الحراري.","answer":true,"reasons":["لأن الدهون تبرّد الجسم","لأن الدهون موصل رديء للحرارة فتمنع فقدان حرارة الجسم في المياه المتجمدة","لأنها لا تستخدم الطاقة"],"reason":1},{"type":"mcq","q":"أيُّ الجزيئات الآتية يدخل أساسًا في بناء أغشية الخلايا؟","options":["الدهون (الليبيدات)","النشا","اليود","السليلوز"],"answer":0,"why":"الأغشية الخلوية تتكوّن أساسًا من طبقة دهنية مزدوجة وبروتينات."},{"type":"essay","q":"ما الفرق بين الدهون والزيوت؟ أعطِ مثالًا لكل منهما.","model":"الدهون صلبة في حرارة الغرفة ومصدرها حيواني غالبًا (الزبدة والشحم)، والزيوت سائلة ومصدرها نباتي غالبًا (زيت الزيتون وزيت الذرة)."},{"type":"tfr","q":"إذا بقي السائل صافيًا وشفافًا بعد إضافة الماء في اختبار الإيثانول فهذا يدلّ على وجود دهون.","answer":false,"reasons":["لأن الماء يذيب الدهون","لأن الدهون شفافة في الماء","بل يدل على غياب الدهون (نتيجة سلبية)، لأن وجودها يعطي مستحلبًا أبيض معكّرًا"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا تتكوّن طبقة بيضاء معكّرة عند صبّ خليط الإيثانول والزيت في الماء؟","options":["لأن الماء يذيب الزيت تمامًا","لأن الزيت لا يذوب في الماء فينفصل كقطيرات مجهرية مشتّتة للضوء","لأن الزيت يتفاعل كيميائيًا ليكوّن نشا","لأن الإيثانول يتجمد"],"answer":1,"why":"تكوّن القطيرات الدقيقة العالقة في الماء هو ما يسمى المستحلب."},{"type":"essay","q":"فسّر: لماذا تُخزّن البذور النباتية مثل السمسم واللوز طاقتها في صورة زيوت بدلًا من النشا فقط؟","model":"لأن الزيوت تعطي طاقةً تعادل ضعف طاقة النشا لكل جرام، مما يتيح للبذرة الصغيرة تخزين كمية كبيرة من الطاقة بوزن خفيف يسهل انتشارها."},{"type":"tfr","q":"تتشابه الدهون والكربوهيدرات في العناصر المكوّنة لها (C و H و O) وتختلف في نسبتها وتركيبها.","answer":true,"reasons":["كلاهما يحتوي على C و H و O، لكن نسبة الأكسجين في الدهون أقل بكثير","لأن الدهون تحوي نيتروجين","لأن الكربوهيدرات بلا أكسجين"],"reason":0},{"type":"mcq","q":"عند هضم جزيء دهن واحد بالكامل في الأمعاء، ما النواتج التي نحصل عليها؟","options":["أحماض أمينية","جزيئات جلوكوز","١ جليسرول + ٣ أحماض دهنية","٣ جليسرول + ١ حمض دهني"],"answer":2,"why":"تتحلّل الدهون إلى وحداتها البنائية الأصلية."},{"type":"essay","q":"قارن بين استخدام الجسم للكربوهيدرات واستخدامه للدهون كمصدرين للطاقة.","model":"الكربوهيدرات (الجلوكوز) تُستخدم أولًا كمصدر سريع وسهل للطاقة، بينما تُستخدم الدهون كمخزون احتياطي عالي الكثافة على المدى الطويل."},{"type":"tfr","q":"الإفراط الشديد في تناول الدهون الحيوانية المشبعة قد يرفع خطر أمراض القلب والسمنة.","answer":true,"reasons":["لأن الدهون لا تعطي طاقة","لأن الطاقة الفائضة تُخزّن كدهون زائدة وقد تترسب في جدران الشرايين التاجية","لأنها تخرج كلها في البول"],"reason":1},{"type":"mcq","q":"أيُّ العيّنات الآتية ستعطي أوضح مستحلب أبيض معكّر في اختبار الإيثانول؟","options":["ماء مقطّر","محلول جلوكوز نقي","محلول ملح طعام","مستخلص بذور عباد الشمس"],"answer":3,"why":"بذور عباد الشمس غنية جدًّا بالزيوت."},{"type":"essay","q":"لماذا نرجّ العينة مع الإيثانول أولًا قبل إضافة الماء في اختبار الدهون؟","model":"لأن الدهون لا تذوب في الماء، فنحتاج إلى الإيثانول لاستخلاص الدهون وإذابتها من العينة أولًا، ثم عند إضافة الماء تنفصل كمستحلب أبيض مرئي."},{"type":"tfr","q":"جميع الدهون في الغذاء يجب حذفها تمامًا للحصول على نظام غذائي صحي.","answer":false,"reasons":["لأن الدهون هي المكون الوحيد للدم","لأن الجسم لا يهضم الكربوهيدرات","لأن الجسم يحتاج كميات معتدلة من الدهون لبناء أغشية الخلايا وحماية الأعضاء والعزل الحراري وامتصاص بعض الفيتامينات"],"reason":2},{"type":"essay","q":"اذكر سببًا واحدًا يجعل الدهون أفضل من الجلايكوجين لتخزين الطاقة في الحيوانات المهاجرة كالطيور.","model":"لأن الدهون توفر ضعف الطاقة لنفس الكتلة ولا تحبس ماءً معها، فتجعل وزن الطائر أخفّ لمسافات الطيران الطويلة."}]}},
  {"id":"g9-bio-1-u3-4","grade":"g9","subject":"biology","term":1,"unit":3,"no":4,"title":"البروتينات","summary":"شرح متحرك لتركيب البروتينات من الأحماض الأمينية وأهمية شكلها ثلاثي الأبعاد واختبار بيوريت، ثم أنشطة بثلاثة مستويات.","page":"lesson-proteins.html","video":"","pdf":"","notes":["تتكوّن البروتينات من C و H و O و N (النيتروجين)، وبعضها يحتوي على الكبريت (S).","تُبنى البروتينات من سلاسل طويلة من الأحماض الأمينية (يوجد نحو ٢٠ نوعًا منها).","تسلسل الأحماض الأمينية يحدّد الشكل ثلاثي الأبعاد للبروتين وبالتالي وظيفته.","وظائف البروتينات: النمو وإصلاح الأنسجة، الأنزيمات، الأجسام المضادة، الهيموجلوبين، وبعض الهرمونات كالأنسولين.","اختبار البروتينات: كاشف بيوريت (أزرق ← بنفسجي) دون الحاجة إلى تسخين."],"exercises":["اذكر أربعة أمثلة لبروتينات مهمة في جسم الإنسان ووظيفة كل منها.","قارن بين اختبار بندكت واختبار بيوريت من حيث الكاشف والتسخين واللون الإيجابي."],"levels":{"easy":[{"type":"mcq","q":"ما الوحدة البنائية للبروتينات؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","الماء"],"answer":0,"why":"البروتينات سلاسل طويلة من الأحماض الأمينية."},{"type":"mcq","q":"ما الكاشف المستخدم للكشف عن البروتينات؟","options":["محلول بندكت","كاشف بيوريت","محلول اليود","الإيثانول"],"answer":1,"why":"بيوريت يعطي لونًا بنفسجيًا مع البروتين."},{"type":"mcq","q":"أيُّ الأطعمة الآتية غنية جدًّا بالبروتينات؟","options":["الماء المقطر","السكر النقي","البيض والسمك والعدس","زيت الذرة فقط"],"answer":2,"why":"اللحوم والأسماك والبيض والبقوليات مصادر رئيسة للبروتين."},{"type":"mcq","q":"كم تقريبًا عدد أنواع الأحماض الأمينية التي تبني البروتينات؟","options":["٣ أنواع","نوعان فقط","١٠٠٠ نوع","٢٠ نوعًا"],"answer":3,"why":"نحو ٢٠ نوعًا تتنوع ترتيباتها لبناء آلاف البروتينات."}],"medium":[{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ بروتينًا ينتجه جهاز المناعة لمحاربة الميكروبات؟","options":["الأجسام المضادة","الجليسرول","السليلوز","الجلايكوجين"],"answer":0,"why":"الأجسام المضادة بروتينات متخصصة الشكل لمقاومة مسببات المرض."},{"type":"tfr","q":"يحتاج اختبار بيوريت إلى تسخين العينة في حمام مائي لتظهر النتيجة.","answer":false,"reasons":["لا يحتاج اختبار بيوريت إلى تسخين، بل يظهر اللون البنفسجي في حرارة الغرفة","لأنه لا يعمل إلا بالغليان","لأنه مثل اختبار بندكت"],"reason":0},{"type":"essay","q":"اذكر أربع وظائف للبروتينات في جسم الإنسان.","model":"١) النمو وبناء الخلايا وإصلاح الأنسجة. ٢) تكوين الأنزيمات. ٣) تكوين الأجسام المضادة. ٤) نقل الأكسجين (الهيموجلوبين) وبعض الهرمونات كالأنسولين."},{"type":"tfr","q":"تتطابق جميع البروتينات في شكلها ثلاثي الأبعاد لأنها مبنية من الأحماض الأمينية نفسها.","answer":false,"reasons":["لأنها كلها كروية متطابقة","اختلاف عدد وترتيب الأحماض الأمينية يجعل كل بروتين ينطوي في شكل ثلاثي أبعاد فريد","لأن الشكل لا يعتمد على الترتيب"],"reason":1},{"type":"mcq","q":"بقي لون كاشف بيوريت أزرق عند إضافته لمحلول ما؛ ماذا نستنتج؟","options":["المحلول يحتوي على نشا","المحلول لا يحتوي على بروتين","المحلول غني بالبروتين","المحلول يحتوي على دهون"],"answer":1,"why":"بقاء اللون الأزرق نتيجة سلبية تعني عدم وجود بروتين."},{"type":"essay","q":"لماذا يحتاج الأطفال والمراهقون إلى نسبة أعلى من البروتين في غذائهم مقارنةً بالكبار؟","model":"لأنهم في مرحلة نمو سريع تتطلب بناء أعداد كبيرة من الخلايا والأنسجة الجديدة."},{"type":"tfr","q":"تحتوي البروتينات على عنصر النيتروجين (N) إضافةً إلى الكربون والهيدروجين والأكسجين.","answer":true,"reasons":["لأن البروتينات بلا كربون","لأن النيتروجين في الكربوهيدرات فقط","وجود النيتروجين سمة مميزة للأحماض الأمينية والبروتينات"],"reason":2}],"hard":[{"type":"mcq","q":"أيُّ اختبارين من الاختبارات الغذائية الأربعة يكون لون كاشفهما الأصلي أزرق؟","options":["الإيثانول واليود","اليود وبيوريت","بندكت وبيوريت","اليود وبندكت"],"answer":2,"why":"كل من بندكت وبيوريت أزرق؛ بندكت يحتاج تسخينًا ويعطي أحمر طوبي، وبيوريت بلا تسخين ويعطي بنفسجيًّا."},{"type":"essay","q":"فسّر: لماذا يؤدي تغيّر ترتيب حمض أميني واحد أحيانًا إلى تعطّل وظيفة البروتين؟","model":"لأن تسلسل الأحماض الأمينية يحدّد كيفية انطواء السلسلة وتشكيلها ثلاثي الأبعاد؛ وأي تغيّر قد يغيّر الشكل الفريد للموقع النشط أو موقع الارتباط فيفقد البروتين وظيفته."},{"type":"tfr","q":"الأجسام المضادة لها أشكال مكمّلة لأشكال مولّدات الضد على سطح مسبّبات المرض.","answer":true,"reasons":["وهذا الشكل المكمّل يمكّن الجسم المضاد من الارتباط بمسبّب المرض وتحييده","لأنها ترتبط عشوائيًا بأي شيء","لأنها سكريات"],"reason":0},{"type":"mcq","q":"مريض يعاني من صعوبة التئام الجروح وضعف العضلات؛ أيُّ مجموعة غذائية يرجّح نقصها في غذائه؟","options":["النشا فقط","الألياف فقط","الماء فقط","البروتينات"],"answer":3,"why":"البروتينات ضرورية لبناء العضلات وإصلاح الأنسجة التالفة."},{"type":"essay","q":"كيف تميّز مخبريًّا بين أنبوبين مجهولين يحتوي أحدهما على محلول جلوكوز والآخر على زلال بيض (بروتين)؟","model":"نضيف كاشف بيوريت لعينة من كل أنبوب: الذي يتحول إلى بنفسجي هو زلال البيض. وللتأكيد نختبر الآخر بمحلول بندكت مع التسخين فيعطي راسبًا أحمر طوبيًّا (جلوكوز)."},{"type":"tfr","q":"عندما نأكل لحمًا، تُمتص بروتيناته كما هي وتنتقل مباشرةً لبناء عضلاتنا دون هضم.","answer":false,"reasons":["لأن البروتين يمر عبر جدار الأمعاء مباشرة","تُهضم البروتينات أولًا إلى أحماض أمينية صغيرة تُمتص للدم ثم تعيد الخلايا ترتيبها لبناء بروتينات الجسم","لأن اللحم لا يحتوي على أحماض أمينية"],"reason":1},{"type":"mcq","q":"أيُّ المركبات الآتية ليس بروتينًا؟","options":["السليلوز","الأنسولين","الهيموجلوبين","الأميليز"],"answer":0,"why":"السليلوز من الكربوهيدرات المتعددة وليس بروتينًا."},{"type":"essay","q":"اذكر مصدرين نباتيين غنيين بالبروتين ومصدرين حيوانيين غنيين بالبروتين.","model":"نباتية: العدس، الفول، الحمص، الصويا. حيوانية: السمك، اللحوم، الدجاج، البيض، الحليب."},{"type":"tfr","q":"تُخزّن الأحماض الأمينية الزائدة عن حاجة الجسم كما هي في الكبد لسنوات طويلة.","answer":false,"reasons":["لأنها تتحول لنشا","لأنها تُخزن في العضلات إلى الأبد","لا يخزّن الجسم الأحماض الأمينية الزائدة، بل يفكّكها الكبد ويحوّل نيتروجينها إلى يوريا تُخرج في البول"],"reason":2},{"type":"essay","q":"صمّم جدولًا سريعًا يلخّص الكاشف والنتيجة الإيجابية لكل من: النشا، الجلوكوز، الدهون، البروتينات.","model":"النشا: اليود ← أزرق مسود. الجلوكوز: بندكت + تسخين ← أحمر طوبي. الدهون: إيثانول + ماء ← مستحلب أبيض معكّر. البروتينات: بيوريت ← بنفسجي."}]}},
  {"id":"g9-bio-1-u3-5","grade":"g9","subject":"biology","term":1,"unit":3,"no":5,"title":"الأنزيمات","summary":"شرح متحرك لمفهوم الأنزيمات وآلية القفل والمفتاح وأثر الحرارة والرقم الهيدروجيني والتماسّخ، ثم أنشطة بثلاثة مستويات.","page":"lesson-enzymes.html","video":"","pdf":"","notes":["الأنزيمات: بروتينات تعمل كعوامل حفّازة حيوية تسرّع التفاعلات الكيميائية دون أن تُستهلك.","الخصوصية (القفل والمفتاح): للموقع النشط شكل ثلاثي أبعاد مكمّل لمادة متفاعلة محددة فقط.","أمثلة: الأميليز (نشا ← مالتوز)، البروتياز (بروتين ← أحماض أمينية)، الليبيز (دهون ← جليسرول + أحماض دهنية).","تزداد سرعة التفاعل برفع الحرارة حتى الدرجة المثلى (~٣٧°م في الإنسان)، وعند الحرارة العالية يتمسّخ الأنزيم (يتغيّر شكل موقعه النشط بشكل دائم).","لكل أنزيم pH أمثل (البيبسين ~٢ في المعدة، الأميليز ~٧ في الفم)، وتغيّر الـ pH الشديد يسبب التمسّخ أيضًا."],"exercises":["فسّر لماذا لا يستطيع أنزيم الأميليز هضم البروتينات.","قارن بين سبب بطء الأنزيم عند درجة ٥°م وتوقّفه عند درجة ٧٠°م."],"levels":{"easy":[{"type":"mcq","q":"ممَّ تتكوّن الأنزيمات كيميائيًا؟","options":["من الماء","من البروتينات","من الدهون","من النشا"],"answer":1,"why":"جميع الأنزيمات بروتينات."},{"type":"mcq","q":"ما الأنزيم الذي يحوّل النشا إلى مالتوز؟","options":["البروتياز","الليبيز","الأميليز","الكاتاليز"],"answer":2,"why":"الأميليز في اللعاب والبنكرياس يهضم النشا."},{"type":"mcq","q":"ما درجة الحرارة المثلى تقريبًا لمعظم أنزيمات جسم الإنسان؟","options":["٧٠°م","١٠٠°م","٠°م","٣٧°م"],"answer":3,"why":"توافق درجة حرارة جسم الإنسان الطبيعية."},{"type":"mcq","q":"هل يُستهلك الأنزيم أثناء التفاعل الكيميائي؟","options":["لا، يبقى كما هو ويُعاد استخدامه","يتحول إلى ماء","نعم، يختفي فورًا","يتحول إلى سكر"],"answer":0,"why":"العامل الحفّاز لا يُستهلك في التفاعل."}],"medium":[{"type":"mcq","q":"ما المقصود بـ «تمسّخ الأنزيم» (Denaturation)؟","options":["تجمّد الأنزيم مؤقتًا","تغيّر دائم في شكل الموقع النشط فلا يرتبط بالمادة المتفاعلة","انقسام الأنزيم","زيادة سرعة الأنزيم"],"answer":1,"why":"الحرارة العالية أو pH الشديد يغيّران شكل الموقع النشط."},{"type":"tfr","q":"عند تبريد الأنزيم إلى ٠°م يتمسّخ الأنزيم ولا يعود للعمل إذا أعدنا تدفئته.","answer":false,"reasons":["التبريد يبطئ الحركة فقط دون تمسّخ، فيعود الأنزيم للعمل عند تدفئته","لأن الأنزيم يموت بالبرد","لأن التبريد يكسّر الروابط"],"reason":0},{"type":"essay","q":"اشرح آلية «القفل والمفتاح» لعمل الأنزيمات.","model":"يمتلك الأنزيم موقعًا نشطًا ذا شكل محدد يتطابق فقط مع المادة المتفاعلة الخاصة به، فيرتبط بها ليكوّن معقد الأنزيم والمادة، ثم تتحرر النواتج ويبقى الأنزيم سليمًا."},{"type":"tfr","q":"يعمل أنزيم البيبسين في المعدة بأفضل كفاءة في وسط حمضي (pH ≈ ٢).","answer":true,"reasons":["لأنه يعمل في وسط قلوي","لأن المعدة تفرز حمض الهيدروكلوريك الذي يوفر الوسط الحمضي الأمثل للبيبسين","لأنه لا يتأثر بالـ pH"],"reason":1},{"type":"mcq","q":"ما المادة المتفاعلة التي يعمل عليها أنزيم الليبيز؟","options":["النشا","السليلوز","الدهون","البروتين"],"answer":2,"why":"الليبيز يفكّك الدهون إلى جليسرول وأحماض دهنية."},{"type":"essay","q":"لماذا يُعدّ ارتفاع حرارة جسم الإنسان فوق ٤١°م (الحمّى الشديدة) أمرًا خطيرًا على الحياة؟","model":"لأن الحرارة المرتفعة قد تبدأ في تمسّخ الأنزيمات الحيوية في خلايا الجسم والدماغ، فتتوقف التفاعلات الضرورية للحياة."},{"type":"tfr","q":"تتطابق درجة الـ pH المثلى لجميع الأنزيمات في جسم الإنسان عند ٧.","answer":false,"reasons":["لأن الـ pH لا يؤثر","لأن كل الجسم متعادل","تختلف حسب مكان عمل الأنزيم؛ فالبيبسين في المعدة أمثله ٢، وأميليز اللعاب ٧، وأنزيمات الأمعاء قلوية قليلًا"],"reason":2}],"hard":[{"type":"mcq","q":"أضفنا أميليزًا مغليًّا إلى محلول نشا، وبعد ١٠ دقائق اختبرناه باليود؛ ما اللون المتوقّع؟","options":["أحمر طوبي","بنفسجي","بني مصفر","أزرق مسود (بقي النشا لم يُهضم)"],"answer":3,"why":"غلي الأميليز أدى إلى تمسّخه فلم يحلّل النشا، فبقي النشا وأعطى أزرق مسود مع اليود."},{"type":"essay","q":"فسّر سبب الفرق بين تأثير درجة حرارة ٥°م ودرجة حرارة ٧٠°م على نشاط أنزيم الأميليز.","model":"عند ٥°م تقل الطاقة الحركية للجزيئات فتقل التصادمات ويبطؤ التفاعل مؤقتًا دون تلف الأنزيم؛ أما عند ٧٠°م فيتمسّخ الأنزيم ويتغير شكل موقعه النشط بشكل دائم فيتوقف التفاعل تمامًا."},{"type":"tfr","q":"تُستخدم الأنزيمات في مساحيق الغسيل الحيوية لإزالة البقع البروتينية والدهنية عند درجات حرارة منخفضة (٣٠–٤٠°م).","answer":true,"reasons":["لأن الأنزيمات تفكّك البقع بكفاءة عند حرارة معتدلة مما يوفّر الكهرباء ويمنع تمسّخها","لأنها لا تفكّك البقع","لأنها تعمل فقط عند ١٠٠°م"],"reason":0},{"type":"mcq","q":"لماذا يتوقّف عمل أميليز اللعاب بمجرد وصول الطعام إلى المعدة؟","options":["لأن الوسط الحمضي القوي في المعدة يغيّر شكل موقعه النشط فيتمسّخ","لأن حرارة المعدة ٠°م","لأن المعدة جافة","لأن النشا ينتهي في الفم"],"answer":0,"why":"أميليز اللعاب أمثله pH=7، وحموضة المعدة (pH=2) تمسّخه."},{"type":"essay","q":"اشرح بدقة لماذا تزداد سرعة التفاعل الأنزيمي عند رفع الحرارة من ٢٠°م إلى ٣٧°م.","model":"بزيادة الحرارة تزداد الطاقة الحركية لجزيئات الأنزيم والمادة المتفاعلة، فتتحرك أسرع وتزداد التصادمات الناجحة بين المادة المتفاعلة والموقع النشط في الثانية الواحدة."},{"type":"tfr","q":"من الصواب علميًا القول إن الحرارة العالية «تقتل» الأنزيمات.","answer":false,"reasons":["لأن الحرارة لا تؤثر فيها","الأنزيمات جزيئات بروتينية وليست كائنات حية، لذا المصطلح العلمي الصحيح هو «تتمسّخ» وليس «تموت»","لأن الأنزيمات كائنات حية"],"reason":1},{"type":"mcq","q":"في تجربة استقصاء أثر الـ pH على نشاط الأميليز، ما المتغير الذي يجب تثبيته (ضبطه)؟","options":["لون الأنبوب","درجة الحرارة وتركيز النشا وتركيز الأنزيم","قيمة الـ pH فقط","زمن اختفاء النشا"],"answer":1,"why":"لضمان عدالة التجربة نغيّر pH فقط ونثبّت الحرارة والتراكيز."},{"type":"essay","q":"ما دور أنزيم الكاتاليز الموجود في خلايا الكبد والبطاطس؟ اكتب المعادلة اللفظية.","model":"يفكّك فوق أكسيد الهيدروجين السام إلى ماء وأكسجين: فوق أكسيد الهيدروجين —(كاتاليز)→ ماء + أكسجين."},{"type":"tfr","q":"تسمح خصوصية الموقع النشط بأن يعمل أنزيم واحد على تفكيك جميع أنواع الغذاء معًا.","answer":false,"reasons":["لأن الموقع النشط يغيّر شكله لأي مادة","لأن الغذاء كله متشابه","بل يعمل كل أنزيم على مادة متفاعلة واحدة متكاملة الشكل مع موقعه النشط فقط"],"reason":2},{"type":"essay","q":"أجريت تجربة بأميليز ونشا في ٣ أنابيب عند pH = ٢ و ٧ و ١١؛ في أي أنبوب يختفي النشا أسرع؟ فسّر.","model":"يختفي أسرع في الأنبوب ذي pH = ٧ لأنه الرقم الهيدروجيني الأمثل للأميليز، بينما يتمسّخ أو يبطؤ بشدة عند ٢ و ١١."}]}},
  {"id":"g9-bio-1-u4-1","grade":"g9","subject":"biology","term":1,"unit":4,"no":1,"title":"النظام الغذائي","summary":"شرح متحرك للنظام الغذائي المتوازن ومكوناته السبعة واختلاف احتياجات الطاقة، ثم أنشطة بثلاثة مستويات.","page":"lesson-diet.html","video":"","pdf":"","notes":["النظام الغذائي المتوازن يوفّر العناصر السبعة بالنسب الصحيحة: كربوهيدرات، دهون، بروتينات، فيتامينات، أملاح معدنية، ألياف، وماء.","فيتامين C (الحمضيات): للجلد واللثة، نقصه يسبّب الإسقربوط. فيتامين D (أشعة الشمس، السمك): لامتصاص الكالسيوم، نقصه يسبّب الكساح.","الكالسيوم (الحليب): للعظام والأسنان، نقصه يسبّب الكساح. الحديد (اللحوم والسبانخ): للهيموجلوبين، نقصه يسبّب فقر الدم.","الألياف الغذائية تنشّط حركة الأمعاء وتمنع الإمساك.","تتغيّر احتياجات الطاقة حسب العمر، والجنس، ومستوى النشاط البدني، والحمل والرضاعة."],"exercises":["اربط كل عنصر بوظيفته ومرض نقصه: فيتامين C، فيتامين D، الكالسيوم، الحديد.","لماذا يحتاج عامل البناء إلى طاقة يومية أعلى من موظف يعمل على مكتب؟"],"levels":{"easy":[{"type":"mcq","q":"كم عدد المكونات الرئيسة للنظام الغذائي المتوازن؟","options":["٣","١٠","٧","٥"],"answer":2,"why":"كربوهيدرات، دهون، بروتينات، فيتامينات، أملاح، ألياف، ماء."},{"type":"mcq","q":"أيُّ طعامٍ غنيٌّ جدًّا بفيتامين C؟","options":["السكر","الأرز الأبيض","الزبدة","البرتقال والليمون"],"answer":3,"why":"الحمضيات والفواكه الطازجة غنية بفيتامين C."},{"type":"mcq","q":"ما العنصر المعدني الأساسي لبناء العظام والأسنان؟","options":["الكالسيوم","اليود","الحديد","النيتروجين"],"answer":0,"why":"الكالسيوم يمنح العظام والأسنان الصلابة."},{"type":"mcq","q":"نقص الحديد في الغذاء يؤدي إلى الإصابة بـ:","options":["الإسقربوط","فقر الدم (الأنيميا)","الكساح","السمنة"],"answer":1,"why":"الحديد ضروري لصنع الهيموجلوبين في خلايا الدم الحمراء."}],"medium":[{"type":"mcq","q":"ما دور فيتامين D في الجسم؟","options":["منع الإمساك","نقل الأكسجين","المساعدة في امتصاص الكالسيوم لبناء العظام","هضم النشا"],"answer":2,"why":"بدون فيتامين D لا يمتص الجسم الكالسيوم بكفاءة."},{"type":"tfr","q":"الألياف الغذائية تُهضم في المعدة وتُعطي طاقةً عاليةً للجسم.","answer":false,"reasons":["الإنسان لا يهضم الألياف (السليلوز) ولا تعطي طاقة، لكنها تحرّك الأمعاء وتمنع الإمساك","لأنها تتحول لجلوكوز فورًا","لأنها نوع من الدهون"],"reason":0},{"type":"essay","q":"اذكر أربعة عوامل تجعل حاجة الإنسان اليومية للطاقة تختلف من شخص لآخر.","model":"١) العمر (النمو). ٢) الجنس. ٣) مستوى النشاط البدني. ٤) الحمل والرضاعة."},{"type":"tfr","q":"التعرّض المعتدل لأشعة الشمس يساعد الجلد على تصنيع فيتامين D.","answer":true,"reasons":["لأن الشمس تصنع الحديد","لأن الأشعة فوق البنفسجية في ضوء الشمس تحفّز الجلد على إنتاج فيتامين D","لأن الشمس تصنع فيتامين C"],"reason":1},{"type":"mcq","q":"أيُّ شخصٍ مما يأتي يحتاج أكبر كمية يومية من الطاقة؟","options":["طفل رضيع","مسنّ قليل الحركة","موظف مكتبي","شاب رياضي يتدرّب ٣ ساعات يوميًا"],"answer":3,"why":"النشاط العضلي العالي والكتلة العضلية الكبيرة يرفعان استهلاك الطاقة."},{"type":"essay","q":"اشرح سبب شعور الشخص المصاب بنقص الحديد (فقر الدم) بالتعب السريع وضيق التنفس.","model":"لأن نقص الحديد يقلّل إنتاج الهيموجلوبين، فيقلّ الأكسجين المنقول إلى الخلايا، مما يخفض معدل التنفس الهوائي وإطلاق الطاقة."},{"type":"tfr","q":"تحتاج المرأة الحامل إلى زيادة في البروتين والكالسيوم والحديد لدعم نمو الجنين.","answer":true,"reasons":["لأن الجنين لا يحتاج كالسيوم","لأن الحامل تحتاج ماءً فقط","البروتين لبناء أنسجة الجنين، والكالسيوم لعظامه، والحديد للدم والهيموجلوبين"],"reason":2}],"hard":[{"type":"mcq","q":"طفل لا يتعرض للشمس أبدًا ويعاني من تقوّس الساقين ولين العظام؛ ما الفيتامين الناقص لديه غالبًا؟","options":["فيتامين D","فيتامين C","الحديد","الألياف"],"answer":0,"why":"نقص فيتامين D يمنع امتصاص الكالسيوم ويسبّب الكساح."},{"type":"essay","q":"لماذا كان البحّارة قديمًا يصابون بنزيف اللثة وتساقط الأسنان في الرحلات البحرية الطويلة، وكيف عولج ذلك؟","model":"بسبب غياب الفواكه والخضار الطازجة فحدث نقص حاد في فيتامين C (مرض الإسقربوط)، وعولج بتزويد السفن بالليمون والحمضيات."},{"type":"tfr","q":"الفتيات في سن المراهقة يحتجن إلى كمية أكبر من الحديد مقارنةً بالفتيان في العمر نفسه.","answer":true,"reasons":["لتعويض الدم المفقود شهريًا خلال الدورة الشهرية والوقاية من فقر الدم","لأن الفتيات لا يحتجن كالسيوم","لأن الحديد يعطي طاقة"],"reason":0},{"type":"mcq","q":"أيُّ وجبةٍ مما يأتي تفتقر بشدة إلى الألياف الغذائية وفيتامين C؟","options":["سمك + أرز بني + سلطة خضراء + برتقال","برجر بالجبن + بطاطس مقلية + مشروب غازي","دجاج مشوي + خضار مطهوة + تفاحة","عدس + خبز قمح كامل + خضار طازجة"],"answer":1,"why":"الوجبات السريعة فقيرة بالخضار والفواكه الطازجة والحبوب الكاملة."},{"type":"essay","q":"فسّر: لماذا يُنصح بعدم غلي الخضار الغنية بفيتامين C لفترات طويلة؟","model":"لأن فيتامين C يتلف بالحرارة العالية ويذوب في ماء السلق، فتقل قيمته الغذائية."},{"type":"tfr","q":"تحتاج جميع الأطعمة الصحية إلى أن تكون غالية الثمن حتى تكون متوازنة.","answer":false,"reasons":["لأن الخضار غير متوفرة","يمكن تحقيق نظام متوازن بأطعمة محلية ميسورة كالتمر والسمك والعدس والخضار والحليب","لأن البروتين في اللحم الغالي فقط"],"reason":1},{"type":"mcq","q":"ما المكونان الغذائيان اللذان لا يمدّان الجسم بأي طاقة حرارية (كيلوجول)؟","options":["الكربوهيدرات والدهون","السكريات والنشا","الماء والألياف (وكذلك الفيتامينات والأملاح)","البروتينات والدهون"],"answer":2,"why":"الطاقة تأتي فقط من الكربوهيدرات والدهون والبروتينات."},{"type":"essay","q":"صمّم وجبة إفطار متوازنة لطالب في الصف التاسع وحدّد مصدر كل مكون غذائي فيها.","model":"خبز قمح كامل (كربوهيدرات وألياف)، بيضة أو جبن (بروتين ودهون وكالسيوم)، شرائح طماطم وخيار وعصير برتقال (فيتامين C وألياف وماء)، كوب ماء."},{"type":"tfr","q":"تُقاس الطاقة في الغذاء عادةً بوحدة الكيلوجول (kJ) أو السعرة الحرارية.","answer":true,"reasons":["لأنها تُقاس بالمتر","لأنها تُقاس باللتر","الكيلوجول هي الوحدة العلمية القياسية لقياس محتوى الطاقة في الأطعمة"],"reason":2},{"type":"essay","q":"اشرح العلاقة التكاملية بين فيتامين D ومعدن الكالسيوم في الوقاية من مرض الكساح.","model":"الكالسيوم هو المادة البنائية للعظام، وفيتامين D ضروري لامتصاص الكالسيوم من الأمعاء إلى الدم وترسيبه في العظام؛ ونقص أي منهما يؤدي للكساح."}]}},
  {"id":"g9-bio-1-u4-2","grade":"g9","subject":"biology","term":1,"unit":4,"no":2,"title":"السُّمنة وسوء التغذية","summary":"شرح متحرك لمفهوم سوء التغذية وأسباب السمنة ومخاطرها وأمراض النقص الغذائي وطرق الوقاية، ثم أنشطة بثلاثة مستويات.","page":"lesson-obesity-and-malnutrition.html","video":"","pdf":"","notes":["سوء التغذية يعني نظامًا غذائيًا غير متوازن، ويشمل نقص التغذية وفرط التغذية (السُّمنة).","تحدث السُّمنة عندما تزيد الطاقة المتناولة في الطعام على الطاقة المستهلكة في النشاط، فيُخزّن الفائض كدهون.","مخاطر السُّمنة: أمراض القلب التاجية، السكري من النوع الثاني، ارتفاع ضغط الدم، وآلام المفاصل.","أمراض النقص الغذائي: كواشيوركور (نقص البروتين)، الهزال (نقص الطاقة والبروتين)، الكساح، الإسقربوط، وفقر الدم.","الوقاية: غذاء متوازن، تقليل السكريات والدهون المشبعة، وممارسة الرياضة بانتظام."],"exercises":["اشرح كيف يؤدي الإفراط في الدهون المشبعة إلى زيادة خطر أمراض القلب التاجية.","قدّم ثلاث نصائح عملية لزميل يعاني من زيادة الوزن ليعيد توازن الطاقة في جسمه."],"levels":{"easy":[{"type":"mcq","q":"أين تُخزَّن الطاقة الزائدة عن حاجة الجسم على المدى الطويل؟","options":["على هيئة ماء","على هيئة ألياف","تختفي فورًا","على هيئة دهون في الجسم"],"answer":3,"why":"الطاقة الفائضة تُخزّن كدهون فتسبب السمنة."},{"type":"mcq","q":"أيُّ مرضٍ من الآتي يرتبط مباشرةً بالسُّمنة؟","options":["السكري من النوع الثاني","عمى الألوان","الإسقربوط","الكساح"],"answer":0,"why":"السمنة ترفع خطر السكري وأمراض القلب وارتفاع الضغط."},{"type":"mcq","q":"أيُّ سلوكٍ يساعد في الوقاية من السُّمنة؟","options":["الإكثار من المشروبات الغازية","ممارسة الرياضة وتقليل السكريات","الجلوس طوال اليوم","تجاهل الخضار"],"answer":1,"why":"النشاط البدني والغذاء المتوازن يوازنان الطاقة."},{"type":"mcq","q":"ما الشرايين التي تضيق عند تراكم الدهون وتسبّب أمراض القلب التاجية؟","options":["القصبة الهوائية","المريء","الشرايين التاجية المغذّية لعضلة القلب","أوعية الخشب"],"answer":2,"why":"الشرايين التاجية تزوّد عضلة القلب بالأكسجين والغذاء."}],"medium":[{"type":"mcq","q":"ما السبب الرئيس لمرض «كواشيوركور» عند بعض الأطفال في المناطق الفقيرة؟","options":["زيادة الدهون","زيادة الفيتامينات","شرب الماء","نقص حاد في البروتين"],"answer":3,"why":"نقص البروتين يسبب بطء النمو وانتفاخ البطن وضعف العضلات."},{"type":"tfr","q":"سوء التغذية يصيب الأشخاص النحيفين فقط ولا يصيب المصابين بالسمنة.","answer":false,"reasons":["سوء التغذية يعني اختلال توازن الغذاء سواء بالنقص أو بالإفراط كالسمنة","لأن النحافة فقط مرض","لأن السمنة دليل صحة دائمًا"],"reason":0},{"type":"essay","q":"اذكر ثلاثة مخاطر صحية تسبّبها السُّمنة المفرطة.","model":"١) أمراض القلب التاجية. ٢) السكري من النوع الثاني. ٣) ارتفاع ضغط الدم وآلام وتآكل المفاصل."},{"type":"tfr","q":"قلة الحركة والجلوس الطويل أمام الشاشات يسهمان في زيادة معدلات السمنة.","answer":true,"reasons":["لأنهما يمنعان الأكل","لأنهما يقللان الطاقة المستهلكة فيتراكم فائض الطاقة كدهون","لأنهما يحرقان طاقة كبيرة"],"reason":1},{"type":"mcq","q":"ماذا يحدث عندما تتساوى الطاقة المتناولة يوميًا مع الطاقة المستهلكة؟","options":["يبقى وزن الجسم ثابتًا","يصاب الشخص بالكساح","يزداد الوزن بسرعة","ينقص الوزن بشدة"],"answer":0,"why":"توازن الكفتين يحافظ على ثبات الوزن الصحي."},{"type":"essay","q":"اشرح بإيجاز كيف تؤدي الدهون المتراكمة في الشرايين التاجية إلى نوبة قلبية.","model":"تضيق الشرايين وتقلّل تدفق الدم والأكسجين إلى عضلة القلب، وإذا انسد الشريان بجلطة تموت خلايا جزء من عضلة القلب فتحدث النوبة القلبية."},{"type":"tfr","q":"المشروبات الغازية المحلّاة بالسكر تحتوي على طاقة عالية جدًّا دون فائدة غذائية حقيقية.","answer":true,"reasons":["لأنها خالية من السكر","لأنها غنية بالبروتين","لأنها غنية بالسكر البسيط وتخلو من الفيتامينات والألياف والبروتين، مما يرفع خطر السمنة"],"reason":2}],"hard":[{"type":"mcq","q":"شخص يتناول وجبات سريعة يوميًا ولا يأكل فواكه؛ أيُّ حالتين قد تجتمعان لديه في وقت واحد؟","options":["توازن غذائي تام","السُّمنة مع نقص بعض الفيتامينات والألياف","زيادة الألياف فقط","الهزال فقط"],"answer":1,"why":"الوجبات السريعة عالية الطاقة وفقيرة بالفيتامينات والألياف، فتجمع السمنة مع نقص العناصر!"},{"type":"essay","q":"قارن بين «كواشيوركور» و«الهزال (الماراسمس)» من حيث السبب الرئيس.","model":"كواشيوركور ينتج أساسًا عن نقص حاد في البروتين مع توفر بعض الكربوهيدرات، بينما الهزال (الماراسمس) ينتج عن نقص شديد في الطاقة (الكربوهيدرات والدهون) والبروتين معًا."},{"type":"tfr","q":"استبدال المشروبات الغازية بالماء والمشي ٣٠ دقيقة يوميًا يساعدان على خفض الوزن تدريجيًا.","answer":true,"reasons":["لأن ذلك يقلل الطاقة الداخلة ويزيد الطاقة المستهلكة فيحرق الجسم الدهون المخزنة","لأنه يسبب فقر الدم","لأنه يزيد الوزن"],"reason":0},{"type":"mcq","q":"أيُّ العوامل الآتية لا يُعدّ من عوامل الخطر لأمراض القلب التاجية؟","options":["الإفراط في الدهون المشبعة","السمنة","ممارسة الرياضة بانتظام وتناول الخضار","التدخين"],"answer":2,"why":"الرياضة والغذاء الصحي يحميان القلب."},{"type":"essay","q":"لماذا يُعدّ إنقاص الوزن السريع بالتجويع الكامل (الامتناع عن الطعام) غير صحي وخطيرًا؟","model":"لأنه يحرم الجسم من البروتينات والفيتامينات والأملاح الضرورية، فيُضعف العضلات والمناعة ويسبّب فقر الدم والدوخة، والأفضل التوازن التدريجي مع الرياضة."},{"type":"tfr","q":"يزداد خطر تآكل مفاصل الركبتين لدى المصابين بالسمنة بسبب الحمل الميكانيكي الزائد عليها.","answer":true,"reasons":["لأن السمنة تقوي الركبتين","لأن وزن الجسم الزائد يضغط باستمرار على الغضاريف في الركبتين","لأن المفاصل لا تحمل الوزن"],"reason":1},{"type":"mcq","q":"كيف يؤثر تناول كمية كافية من الألياف في المساعدة على الوقاية من السمنة؟","options":["تمنع شرب الماء","ترفع السكر سريعًا","تزيد الدهون","تمنح شعورًا بالشبع دون إضافة طاقة حرارية"],"answer":3,"why":"الألياف تملأ المعدة وتبطئ الامتصاص دون سعرات عالية."},{"type":"essay","q":"قدّم خطة صحية بسيطة من أربع نقاط لخفض خطر السمنة في المدرسة والمنزل.","model":"١) اختيار وجبات إفطار وغداء متوازنة. ٢) استبدال الحلويات والمشروبات الغازية بالفواكه والماء. ٣) ممارسة نشاط رياضي يومي. ٤) تقليل وقت الجلوس أمام الشاشات."},{"type":"tfr","q":"قد يعاني شخصٌ مصابٌ بالسمنة من فقر الدم إذا كان طعامه يفتقر إلى الحديد.","answer":true,"reasons":["لأن السمنة تمنع فقر الدم","لأن الدهون تحوي حديدًا","لأن زيادة الوزن لا تعني توفر جميع الأملاح والفيتامينات الضرورية"],"reason":2},{"type":"essay","q":"اشرح معنى عبارة: «المعدة بيت الداء، والحمية رأس كل دواء» في ضوء درس السمنة وسوء التغذية.","model":"الإفراط في الطعام غير المتوازن يسبّب أمراضًا خطيرة كالسمنة والسكري وأمراض القلب، بينما الاعتدال والتوازن الغذائي يحميان الجسم من معظم هذه الأمراض."}]}},
  {"id":"g9-bio-1-u5-1","grade":"g9","subject":"biology","term":1,"unit":5,"no":1,"title":"التنفُّس","summary":"شرح متحرك للتنفُّس الخلوي الهوائي واللاهوائي ومعادلاتهما واستخدامات الطاقة في الجسم، ثم أنشطة بثلاثة مستويات.","page":"lesson-respiration.html","video":"","pdf":"","notes":["التنفُّس الخلوي: تفاعلات كيميائية داخل الخلايا تكسّر الجلوكوز لإطلاق الطاقة اللازمة للحركة والنمو والنقل النشط وثبات الحرارة.","التنفُّس الهوائي (في الميتوكوندريا): جلوكوز + أكسجين ← ثاني أكسيد الكربون + ماء + طاقة كبيرة (C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O).","التنفُّس اللاهوائي في عضلات الإنسان: جلوكوز ← حمض اللاكتيك + طاقة قليلة (بلا أكسجين).","التنفُّس اللاهوائي في الخميرة: جلوكوز ← إيثانول + ثاني أكسيد الكربون + طاقة قليلة (يُستخدم في نفخ عجين الخبز).","يعكّر غاز ثاني أكسيد الكربون ماء الجير الرائق."],"exercises":["اكتب المعادلة اللفظية والرمزية الموزونة للتنفُّس الهوائي.","قارن بين التنفُّس اللاهوائي في عضلات الإنسان والتنفُّس اللاهوائي في الخميرة."],"levels":{"easy":[{"type":"mcq","q":"ما المادة الغذائية الرئيسة التي تتكسر في التنفُّس الخلوي لإطلاق الطاقة؟","options":["الجلوكوز","اليود","الماء","السليلوز"],"answer":0,"why":"الجلوكوز هو الوقود الأساسي للتنفس الخلوي."},{"type":"mcq","q":"أيُّ نوعٍ من التنفُّس يطلق كمية أكبر بكثير من الطاقة من جزيء جلوكوز واحد؟","options":["التنفُّس اللاهوائي في العضلات","التنفُّس الهوائي","التنفُّس اللاهوائي في الخميرة","كلها متساوية"],"answer":1,"why":"التنفس الهوائي يكسّر الجلوكوز بالكامل فيطلق طاقة كبيرة."},{"type":"mcq","q":"ما ناتجا التنفُّس الهوائي إلى جانب الطاقة؟","options":["الجلوكوز والنشا","الإيثانول والأكسجين","ثاني أكسيد الكربون والماء","حمض اللاكتيك فقط"],"answer":2,"why":"جلوكوز + أكسجين ← ثاني أكسيد الكربون + ماء."},{"type":"mcq","q":"ماذا يحدث لماء الجير الرائق عند مرور ثاني أكسيد الكربون فيه؟","options":["يتحول إلى أزرق","يتحول إلى بنفسجي","يبقى صافيًا","يتعكّر ويصبح أبيض حليبيًّا"],"answer":3,"why":"تعكّر ماء الجير هو الكشف القياسي عن CO₂."}],"medium":[{"type":"mcq","q":"أيٌّ مما يأتي ليس من نواتج التنفُّس اللاهوائي في عضلات الإنسان؟","options":["طاقة قليلة","ثاني أكسيد الكربون","حمض اللاكتيك","لا شيء مما سبق"],"answer":1,"why":"في عضلات الإنسان ينتج حمض اللاكتيك وطاقة قليلة دون CO₂."},{"type":"tfr","q":"تُنتج الخميرة حمض اللاكتيك عند تنفسها لاهوائيًا.","answer":false,"reasons":["تنتج الخميرة إيثانول وثاني أكسيد الكربون، أما حمض اللاكتيك فينتج في عضلات الإنسان","الخميرة لا تتنفس","تنتج الخميرة أكسجينًا"],"reason":0},{"type":"essay","q":"اذكر أربعة استخدامات للطاقة الناتجة عن التنفُّس الخلوي في جسم الإنسان.","model":"١) انقباض العضلات. ٢) بناء البروتينات. ٣) انقسام الخلايا والنمو. ٤) الحفاظ على ثبات درجة حرارة الجسم، والنقل النشط، ونقل السيالات العصبية."},{"type":"tfr","q":"في تجربة انطلاق الحرارة من البذور النابتة نغسل البذور بمطهّر خفيف قبل وضعها في الترمس.","answer":true,"reasons":["لمنع البذور من التنفس","لقتل البكتيريا والفطريات على سطح البذور حتى نضمن أن الحرارة ناتجة عن تنفس البذور وحدها","لتبريد البذور"],"reason":1},{"type":"mcq","q":"ما المعادلة الرمزية الموزونة الصحيحة للتنفُّس الهوائي؟","options":["C₆H₁₂O₆ + O₂ → CO₂ + H₂O","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","C₆H₁₂O₆ → 2CO₂","6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂"],"answer":1,"why":"موزونة بـ ٦ جزيئات O₂ و ٦ CO₂ و ٦ H₂O."},{"type":"essay","q":"اشرح دور الخميرة في صناعة الخبز.","model":"تتنفس الخميرة لاهوائيًا فتحلّل السكر إلى إيثانول وغاز ثاني أكسيد الكربون؛ وتحتبس فقاعات الغاز داخل العجين فتجعله ينتفخ ويصبح هشًّا، ثم يتبخر الإيثانول في الفرن."},{"type":"tfr","q":"التمثيل الضوئي والتنفُّس الهوائي هما نفس العملية بالاتجاه نفسه.","answer":false,"reasons":["لأنهما يطلقان ثاني أكسيد الكربون","لأنهما يحدثان في الميتوكوندريا","بل هما متعاكسان تقريبًا؛ التنفس الهوائي يستهلك جلوكوز وأكسجين ويطلق طاقة، بينما التمثيل الضوئي يصنع الجلوكوز والأكسجين باستخدام الضوء"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا يطلق التنفُّس اللاهوائي طاقةً أقل بكثير من التنفُّس الهوائي؟","options":["لأنه لا يستخدم الجلوكوز","لأنه يحدث في البرد فقط","لأن الجلوكوز يتكسّر جزئيًّا فقط وتبقى معظم الطاقة مخزّنة في حمض اللاكتيك أو الإيثانول","لأنه يستهلك أكسجينًا أكثر"],"answer":2,"why":"التكسير غير الكامل للجلوكوز يحرر جزءًا صغيرًا فقط من طاقته."},{"type":"essay","q":"قارن في جدول بين التنفُّس الهوائي والتنفُّس اللاهوائي في الإنسان من حيث: الحاجة للأكسجين، النواتج، كمية الطاقة، ومكان الحدوث.","model":"الهوائي: يحتاج O₂، ينتج CO₂ وماء، طاقة كبيرة، في الميتوكوندريا. اللاهوائي: بلا O₂، ينتج حمض اللاكتيك، طاقة قليلة، في السيتوبلازم."},{"type":"tfr","q":"يُعدّ التنفُّس الهوائي تفاعلًا محفّزًا بالأنزيمات داخل الخلايا.","answer":true,"reasons":["لأن سلسلة تفاعلات التنفس تعتمد على أنزيمات متخصصة، لذا يتأثر معدل التنفس بدرجة الحرارة","لأنه يحدث بلا أنزيمات","لأنه احتراق مباشر بلهب"],"reason":0},{"type":"mcq","q":"في تجربة التنفس اللاهوائي للخميرة في أنبوب اختبار، لماذا نضيف طبقةً رقيقةً من الزيت فوق محلول السكر والخميرة؟","options":["لامتصاص CO₂","لتسخين المحلول","لإعطاء الخميرة غذاءً إضافيًا","لمنع دخول الأكسجين من الهواء لضمان حدوث تنفّس لاهوائي"],"answer":3,"why":"طبقة الزيت تعزل المحلول عن الأكسجين الجوي."},{"type":"essay","q":"لماذا نغلي البذور في الترمس الضابط (الشاهد) في تجربة انطلاق الحرارة من التنفس؟","model":"لقتل خلايا البذور وتمسّخ أنزيماتها فتتوقف عن التنفس تمامًا، لنقارن بها البذور الحية ونتأكد أن ارتفاع الحرارة سببه التنفس الحيوي."},{"type":"tfr","q":"تتوقف البذور الجافة المخزّنة عن التنفُّس تمامًا مثل البذور المغلية.","answer":false,"reasons":["البذور الجافة ميتة","البذور الجافة حيّة وتتنفس بمعدل بطيء جدًّا، ويزداد تنفسها بشدة عند الإنبات بالماء، أما المغلية فميتة","البذور المغلية تتنفس بسرعة"],"reason":1},{"type":"mcq","q":"ما اللون الذي يتحول إليه كاشف بيكربونات الهيدروجين عند زيادة تركيز CO₂؟","options":["الأصفر","الأرجواني","الأخضر الداكن","الأزرق المسود"],"answer":0,"why":"CO₂ حمضي فيحول الكاشف من الأحمر إلى الأصفر."},{"type":"essay","q":"فسّر: لماذا تتنفس بذور النباتات النابتة بمعدل أعلى بكثير من البذور الجافة؟","model":"لأن البذرة النابتة تنمو بسرعة وتنقسم خلاياها وتبني أنسجة الجذير والرويشة، فتحتاج كمية كبيرة من الطاقة من التنفس الخلوي."},{"type":"tfr","q":"يمكن لخلايا العضلات أن تقوم بالتنفس الهوائي واللاهوائي معًا أثناء الجري السريع.","answer":true,"reasons":["لأن العضلات لا تستخدم الأكسجين","لأن الهوائي يتوقف كليًا فور بدء الجري","تستمر بالتنفس الهوائي بقدر ما يصلها من أكسجين، وتضيف إليه التنفس اللاهوائي لتوفير الطاقة الإضافية السريعة"],"reason":2},{"type":"essay","q":"لماذا لا يعتمد جسم الإنسان على التنفُّس اللاهوائي دائمًا بدلاً من الهوائي؟","model":"لسببين: ١) يطلق طاقةً قليلةً جدًّا لا تكفي حاجات الجسم المستمرة. ٢) يراكم حمض اللاكتيك السام الذي يسبّب إجهاد العضلات وألمها."}]}},
  {"id":"g9-bio-1-u5-2","grade":"g9","subject":"biology","term":1,"unit":5,"no":2,"title":"التمارين الرياضية ومُعدَّل التنفُّس","summary":"شرح متحرك لأثر الرياضة على معدل وعمق التنفس ونبض القلب ودَين الأكسجين والتخلص من حمض اللاكتيك، ثم أنشطة بثلاثة مستويات.","page":"lesson-exercise-and-breathing-rate.html","video":"","pdf":"","notes":["أثناء التمرين يرتفع معدل التنفُّس الخلوي في العضلات فتزداد حاجتها للأكسجين والجلوكوز ويزداد إنتاج CO₂.","استجابة الجسم: زيادة معدل التنفس (عدد الأنفاس/دقيقة)، وزيادة عمق التنفس (حجم الهواء/نفس)، وتسارع نبض القلب.","ارتفاع CO₂ في الدم يخفض pH الدم قليلًا، فيرصده الدماغ ويرسل سيالات عصبية أسرع للحجاب الحاجز وعضلات الضلوع.","دَيْن الأكسجين: كمية الأكسجين الإضافية المطلوبة بعد التمرين الشديد لتفكيك حمض اللاكتيك المتراكم.","ينقل الدم حمض اللاكتيك إلى الكبد حيث يُفكّك بالأكسجين؛ وقِصر زمن التعافي يدل على ارتفاع اللياقة البدنية."],"exercises":["اشرح تسلسل الأحداث التي تجعل الدماغ يرفع معدل التنفس أثناء الجري.","لماذا يبقى معدل نبض القلب مرتفعًا لفترة قصيرة بعد توقّف العدّاء عن السباق؟"],"levels":{"easy":[{"type":"mcq","q":"ماذا يحدث لمعدل التنفُّس عند الانتقال من الجلوس إلى الجري؟","options":["ينخفض","يرتفع","يبقى ثابتًا","يتوقف"],"answer":1,"why":"تحتاج العضلات لمزيد من الأكسجين لإطلاق الطاقة."},{"type":"mcq","q":"أين ينتقل حمض اللاكتيك عبر الدم ليُفكّك بعد التمرين؟","options":["إلى العين","إلى الجلد","إلى الكبد","إلى المعدة"],"answer":2,"why":"الكبد هو العضو الذي يفكّك حمض اللاكتيك بالأكسجين."},{"type":"mcq","q":"أيُّ عضلةٍ رئيسةٍ تتلقى إشارات الدماغ لتسريع التنفُّس؟","options":["عضلات اللسان","عضلات الأصابع","عضلات العين","الحجاب الحاجز وعضلات الضلوع"],"answer":3,"why":"انقباض الحجاب الحاجز والعضلات بين الضلوع يتحكم في التهوية."},{"type":"mcq","q":"قِصر «زمن التعافي» بعد التمرين الرياضي يدلّ على:","options":["لياقة بدنية عالية","نقص الحديد","السمنة","ضعف اللياقة"],"answer":0,"why":"الشخص الأكثر لياقة يعود تنفسه ونبضه للطبيعي أسرع."}],"medium":[{"type":"mcq","q":"كيف يؤثر ارتفاع ثاني أكسيد الكربون في الدم على الرقم الهيدروجيني (pH) للدم؟","options":["يرفعه كثيرًا","يخفضه قليلًا (يزيد الحموضة قليلًا)","لا يؤثر فيه","يجعله صفرًا"],"answer":1,"why":"ذوبان CO₂ في الدم يشكّل حمضًا ضعيفًا فيخفض الـ pH قليلًا."},{"type":"tfr","q":"بمجرد توقّف العدّاء عن الجري يعود معدل تنفسه فورًا في الثانية نفسها إلى معدل الراحة.","answer":false,"reasons":["يستمر التنفس السريع والعميق لعدة دقائق لسداد دَيْن الأكسجين وتفكيك حمض اللاكتيك","لأن القلب يتوقف","لأن الرئتين لا تتوقفان عن الجري"],"reason":0},{"type":"essay","q":"عرّف «دَيْن الأكسجين» واشرح كيف يسدّده الجسم بعد انتهاء التمرين.","model":"هو كمية الأكسجين الإضافية التي يحتاجها الجسم بعد التمرين الشديد لتفكيك حمض اللاكتيك؛ ويُسدد باستمرار التنفس السريع والعميق ونبض القلب السريع لنقل الحمض إلى الكبد وأكسدته."},{"type":"tfr","q":"يزداد عمق التنفُّس أثناء الرياضة ليدخل حجم أكبر من الهواء في كل نفس.","answer":true,"reasons":["لأن الرئتين تنكمشان","بذلك يزداد الأكسجين الواصل للحويصلات في كل نفس إلى جانب زيادة عدد الأنفاس","لأن حجم الهواء يقل"],"reason":1},{"type":"mcq","q":"لماذا يرتفع معدل نبض القلب أثناء التمرين الرياضي؟","options":["لإيقاف التنفس","لتقليل تدفق الدم","لضخ الدم أسرع ونقل الأكسجين والجلوكوز للعضلات وإزالة CO₂","لتبريد العظام"],"answer":2,"why":"تسارع الدم يواكب الطلب العالي للعضلات."},{"type":"essay","q":"لماذا يشعر العدّاء بألم وتعب في عضلات ساقيه في نهاية سباق قصير سريع جدًّا؟","model":"بسبب لجوء العضلات للتنفُّس اللاهوائي وتراكم حمض اللاكتيك فيها."},{"type":"tfr","q":"يراقب الدماغ تركيز CO₂ وحموضة الدم لتنظيم معدل التنفُّس تلقائيًا.","answer":true,"reasons":["لأن المعدة هي التي تنظم التنفس","لأن التنفس لا يتأثر بـ CO₂","وهذا يضمن مطابقة كمية الهواء الداخل لحاجة الخلايا الفعلية"],"reason":2}],"hard":[{"type":"mcq","q":"كان معدل تنفس طالب وقت الراحة ١٥ نفسًا/دقيقة وبحجم ٠٫٥ لتر للنفس، وأصبح أثناء الجري ٣٠ نفسًا/دقيقة وبحجم ١٫٥ لتر؛ كم تضاعف حجم الهواء الداخل في الدقيقة؟","options":["تضاعف مرتين","لم يتغير","تضاعف ٣ مرات","تضاعف ٦ مرات (من ٧٫٥ إلى ٤٥ لتر/دقيقة)"],"answer":3,"why":"وقت الراحة ١٥×٠٫٥ = ٧٫٥ لتر؛ أثناء الجري ٣٠×١٫٥ = ٤٥ لتر ← ٤٥ ÷ ٧٫٥ = ٦ أضعاف!"},{"type":"essay","q":"فسّر لماذا يستمر «نبض القلب» سريعًا بعد التمرين الشديد تمامًا كما يستمر «معدّل التنفس» سريعًا.","model":"لأن نبض القلب السريع ضروري لنقل حمض اللاكتيك من العضلات إلى الكبد، ونقل الأكسجين الإضافي من الرئتين إلى الكبد لتفكيك الحمض."},{"type":"tfr","q":"في سباق الماراثون الطويل (٤٢ كم) يعتمد العدّاء أساسًا على التنفُّس الهوائي وليس اللاهوائي وحده.","answer":true,"reasons":["لأن التنفس اللاهوائي يطلق طاقة قليلة ويراكم حمض اللاكتيك سريعًا فلا يمكن الاستمرار به لساعات","لأن اللاهوائي يعطي طاقة أكبر","لأن الماراثون بلا أكسجين"],"reason":0},{"type":"mcq","q":"أيُّ منحنى يمثّل بشكل صحيح معدل التنفس قبل وأثناء وبعد التمرين؟","options":["ثابت ومنخفض ← يرتفع أثناء التمرين ← ينخفض تدريجيًا بعد التوقف حتى يعود للطبيعي","خط أفقي ثابت طوال الوقت","يرتفع ثم يهبط للصفر فور التوقف","ينخفض أثناء التمرين ثم يرتفع"],"answer":0,"why":"الانخفاض التدريجي بعد التمرين يمثّل فترة سداد دَين الأكسجين."},{"type":"essay","q":"صمّم استقصاءً عمليًّا بسيطًا لقياس أثر التمرين الرياضي على معدل التنفس في صفك، مع ذكر متغيرين يجب ضبطهما.","model":"نقيس عدد الأنفاس في الدقيقة وقت الراحة، ثم نمارس الجري في المكان لمدة دقيقتين، ثم نقيس عدد الأنفاس فورًا وكل دقيقة حتى يعود للطبيعي. المتغيرات المضبوطة: مدة التمرين، ونوع التمرين، والقياس بالطريقة نفسها."},{"type":"tfr","q":"انخفاض الرقم الهيدروجيني للدم أثناء الرياضة ينتج عن تراكم ثاني أكسيد الكربون وحمض اللاكتيك معًا.","answer":true,"reasons":["لأنهما لا يذوبان في الدم","كلاهما يرفع حموضة الدم قليلًا فيحفّز الدماغ على زيادة معدل وعمق التنفس","لأنهما مادتان قلويتان"],"reason":1},{"type":"mcq","q":"ما أثر ممارسة الرياضة المنتظمة على عضلة القلب على المدى الطويل؟","options":["تضعف عضلة القلب","تقوّي عضلة القلب فيضخ حجمًا أكبر من الدم في كل نبضة ويقل نبض الراحة","تزيد دَين الأكسجين وقت الراحة","تضيّق الشرايين"],"answer":1,"why":"القلب الرياضي أقوى وأكثر كفاءة في ضخ الدم."},{"type":"essay","q":"لماذا تزداد حاجة العضلات للجلوكوز أثناء الرياضة، ومن أين يحصل الدم على جلوكوز إضافي؟","model":"لزيادة معدل التنفس الخلوي وإطلاق الطاقة، ويحصل الدم على جلوكوز إضافي بتحويل الجلايكوجين المخزّن في الكبد والعضلات إلى جلوكوز."},{"type":"tfr","q":"يمكن التخلص من حمض اللاكتيك في العضلات دون أي حاجة للأكسجين.","answer":false,"reasons":["لأنه يخرج مع العرق فقط","لأنه يتحول لماء وحده","تحتاج عملية تفكيك حمض اللاكتيك في الكبد إلى الأكسجين (وهذا هو دَيْن الأكسجين)"],"reason":2},{"type":"essay","q":"قارن بين طالب رياضي وطالب قليل الحركة عند أدائهما التمرين نفسه من حيث: ارتفاع معدل التنفس وزمن التعافي.","model":"الطالب الرياضي يرتفع معدل تنفسه بدرجة أقل نسبيًا، ويعود إلى معدل الراحة في وقت أقصر (زمن تعافٍ أقصر) لكفاءة قلبه ورئتيه."}]}},
  {"id":"g9-bio-1-u6-1","grade":"g9","subject":"biology","term":1,"unit":6,"no":1,"title":"التنظيم في الإنسان","summary":"شرح متحرك لمفهوم التنظيم والاستجابة ومسار المؤثر إلى الاستجابة ومقارنة الجهاز العصبي والهرموني، ثم أنشطة بثلاثة مستويات.","page":"lesson-coordination-in-humans.html","video":"","pdf":"","notes":["المؤثّر: تغيّر في البيئة الخارجية أو الداخلية يرصده «المستقبل الحسي» في عضو الحس.","مسار التنظيم: مؤثّر ← مستقبل حسي ← منظّم (الدماغ/الحبل الشوكي) ← مستجيب (عضلة أو غدة) ← استجابة.","أعضاء الاستجابة في الإنسان نوعان: العضلات (تنقبض) والغدد (تفرز).","الجهاز العصبي: إشارات كهربائية عبر الأعصاب، سريع جدًّا، قصير الأمد، محدد النطاق.","جهاز الغدد الصماء (الهرموني): هرمونات كيميائية عبر الدم، أبطأ، أطول أثرًا، أوسع نطاقًا."],"exercises":["قارن في جدول بين التنظيم العصبي والتنظيم الهرموني من حيث وسيلة النقل والسرعة ومدة الأثر.","حدّد المؤثّر والمستقبل والمنظّم والمستجيب عند سماع جرس المدرسة والنهوض من المقعد."],"levels":{"easy":[{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ «عضو استجابة» (مستجيبًا)؟","options":["الأنف","العين","العضلة","الأذن"],"answer":2,"why":"المستجيبات هي العضلات والغدد، أما العين والأذن والأنف فأعضاء حس."},{"type":"mcq","q":"كيف تنتقل الهرمونات من الغدد الصماء إلى الأعضاء المستهدفة؟","options":["عبر المريء","عبر الأعصاب","عبر القصبة الهوائية","عبر الدم"],"answer":3,"why":"تُفرز الهرمونات مباشرةً في مجرى الدم."},{"type":"mcq","q":"ما المؤثّر الذي تستقبله العين؟","options":["الضوء","الصوت","الضغط","الحرارة فقط"],"answer":0,"why":"مستقبلات الشبكية في العين حساسة للضوء."},{"type":"mcq","q":"أيُّ جهازٍ يعمل بسرعة فائقة جدًّا (أجزاء من الثانية)؟","options":["الجهاز الهضمي","الجهاز العصبي","جهاز الغدد الصماء","الجهاز البولي"],"answer":1,"why":"السيالات الكهربائية تنتقل عبر الأعصاب بسرعة فائقة."}],"medium":[{"type":"mcq","q":"عندما تشم رائحة ليمون فيسيل لعابك، ما عضو الاستجابة في هذا الموقف؟","options":["الدماغ","الأنف","الغدد اللعابية","العين"],"answer":2,"why":"الغدد اللعابية هي التي استجابت بإفراز اللعاب."},{"type":"tfr","q":"يقتصر التنظيم في جسم الإنسان على الجهاز العصبي وحده.","answer":false,"reasons":["يتعاون الجهازان العصبي والهرموني معًا لتنظيم وظائف الجسم","لأن الإنسان ليس له هرمونات","لأن الهرمونات في النبات فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاثة فروق بين التنظيم العصبي والتنظيم الهرموني.","model":"١) طبيعة الرسالة: كهربائية (عصبي) مقابل كيميائية (هرموني). ٢) السرعة: سريع جدًّا مقابل أبطأ. ٣) مدة الأثر: قصيرة مقابل طويلة."},{"type":"tfr","q":"يُعدّ الدماغ والحبل الشوكي هما المركز المنظّم في الجهاز العصبي.","answer":true,"reasons":["لأنهما غدد صماء","يعالجان المعلومات الواردة من المستقبلات ويرسلان الأوامر للمستجيبات","لأنهما أعضاء استجابة"],"reason":1},{"type":"mcq","q":"ما نوع المؤثّرات التي يلتقطها الأنف واللسان؟","options":["مؤثّرات مغناطيسية","مؤثّرات ضوئية","مؤثّرات صوتية","مؤثّرات كيميائية"],"answer":3,"why":"الشم والتذوق يعتمدان على رصد جزيئات كيميائية."},{"type":"essay","q":"تتبّع مسار الاستجابة عند لمس إبرة حادة وسحب اليد بسرعة.","model":"المؤثّر (الوخز) ← مستقبلات الألم في الجلد ← المنظّم (الحبل الشوكي) ← المستجيب (عضلات الذراع) ← الاستجابة (سحب اليد)."},{"type":"tfr","q":"تستجيب الغدد للأوامر العصبية بالانقباض مثل العضلات.","answer":false,"reasons":["العضلات تفرز هرمونات","الغدد لا تستجيب أبدًا","العضلات تستجيب بالانقباض، أما الغدد فتستجيب بإفراز مواد كيميائية"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا نحتاج إلى التنظيم العصبي السريع بدل الاكتفاء بالهرموني عند لمس جسم ساخن؟","options":["لحماية الأنسجة من الحرق فورًا قبل حدوث تلف كبير","لأن العضلات لا تستجيب للدم","لأن الحرارة تمنع جريان الدم","لأن الهرمونات لا تصل لليد"],"answer":0,"why":"الاستجابة الهرمونية بطيئة جدًّا مقارنةً بالحاجة الفورية لتجنب الحرق."},{"type":"essay","q":"فسّر لماذا يناسب التنظيم الهرموني عملية «النمو والبلوغ» أكثر من التنظيم العصبي.","model":"لأن النمو والبلوغ عمليتان تدريجيتان طويلتا الأمد وتشملان معظم أعضاء الجسم معًا، وهذا يتوافق مع طبيعة الهرمونات المنتقلة بالدم ذات الأثر الممتد والواسع."},{"type":"tfr","q":"يمكن أن يكون المؤثّر داخليًا مثل انخفاض مستوى الجلوكوز في الدم، وليس خارجيًا فقط.","answer":true,"reasons":["لأن التنظيم يشمل رصد التغيرات داخل الجسم كحرارة الدم وسكر الدم والاستجابة لها","لأن المؤثرات خارجية فقط","لأن الجسم لا يرصد سكر الدم"],"reason":0},{"type":"mcq","q":"في موقف خوف مفاجئ، أيّ جملة تصف التكامل بين الجهازين بدقة؟","options":["تُفرز الأعصاب هرمونات في المعدة","يرصد الجهاز العصبي الخطر ويحفّز الغدة الكظرية لإفراز الأدرينالين في الدم","يوقف الأدرينالين عمل الجهاز العصبي","يعمل كل جهاز بمعزل تام عن الآخر"],"answer":1,"why":"الجهاز العصبي ينبّه الغدة الصماء لتدعم الاستجابة هرمونيًا."},{"type":"essay","q":"صنّف كلًّا مما يأتي إلى (مؤثّر / مستقبل / منظّم / مستجيب): ضوء الشمس، الشبكية، عضلة القزحية، الدماغ.","model":"ضوء الشمس: مؤثّر. الشبكية: مستقبل. الدماغ: منظّم. عضلة القزحية: مستجيب."},{"type":"tfr","q":"الأذن تحتوي على مستقبلات للصوت ومستقبلات للتوازن معًا.","answer":true,"reasons":["الأذن للسمع فقط","الأذن الداخلية تضم القوقعة للسمع والقنوات الهلالية للتوازن","التوازن في العين فقط"],"reason":1},{"type":"mcq","q":"أيُّ وصفٍ ينطبق على نطاق تأثير السيال العصبي مقارنةً بالهرمون؟","options":["ينتشر لكل خلايا الجسم عبر الدم","بطيء جدًّا","موضعي ومحدد جدًّا في عضو معيّن","يبقى لعدة سنوات"],"answer":2,"why":"السيال العصبي يصل مباشرةً لعضلة أو غدة محددة عبر ليف عصبي."},{"type":"essay","q":"أعطِ مثالًا لمؤثّر داخلي ومثالًا لمؤثّر خارجي، واذكر الاستجابة المناسبة لكل منهما.","model":"مؤثّر خارجي: ضوء ساطع ← تضيق حدقة العين. مؤثّر داخلي: ارتفاع حرارة الدم ← التعرق وتوسع الأوعية السطحية."},{"type":"tfr","q":"لا يمكن للعضلة أن تنقبض إلا بعد وصول سيال عصبي إليها من المنظّم.","answer":true,"reasons":["العضلات تنقبض بلا أعصاب دائمًا","الأعصاب تمنع الانقباض","العضلات الإرادية والهيكلية تنقبض استجابة للأوامر العصبية الواردة عبر الخلايا العصبية الحركية"],"reason":2},{"type":"essay","q":"لخّص في سطرين أهمية وجود جهازين للتنظيم في الإنسان بدلًا من جهاز واحد.","model":"يوفّر الجهاز العصبي استجابات فورية دقيقة لحماية الجسم والحركة السريعة، بينما يوفّر الجهاز الهرموني تنظيمًا مستمرًا وطويل الأمد للنمو والاتزان الداخلي."}]}},
  {"id":"g9-bio-1-u6-2","grade":"g9","subject":"biology","term":1,"unit":6,"no":2,"title":"الجهاز العصبي في الإنسان","summary":"شرح متحرك لأقسام الجهاز العصبي وأنواع الخلايا العصبية والفعل المنعكس والقوس الانعكاسية، ثم أنشطة بثلاثة مستويات.","page":"lesson-human-nervous-system.html","video":"","pdf":"","notes":["الجهاز العصبي المركزي (CNS): الدماغ والحبل الشوكي. والجهاز الطرفي (PNS): الأعصاب.","الخلية العصبية تحوي جسم الخلية، زوائد شجيرية، محورًا طويلًا، وغمدًا ميالينيًا يسرّع السيال.","الخلايا العصبية ثلاث: حسية (مستقبل ← مركزي)، موصّلة (داخل المركزي)، حركية (مركزي ← مستجيب).","القوس الانعكاسية: مستقبل ← خلية حسية ← خلية موصّلة ← خلية حركية ← مستجيب (استجابة تلقائية سريعة للحماية).","التشابك العصبي فجوة مجهرية تعبرها نواقل عصبية كيميائية وتضمن انتقال السيال في اتجاه واحد."],"exercises":["ارسم مخططًا سهميًا يوضّح مسار القوس الانعكاسية عند وخز الإصبع بشوكة.","قارن بين الخلية العصبية الحسية والخلية العصبية الحركية من حيث اتجاه نقل السيال."],"levels":{"easy":[{"type":"mcq","q":"أين توجد الخلايا العصبية الموصّلة (البينية)؟","options":["في المعدة","في الجلد","في العظام","في الدماغ والحبل الشوكي"],"answer":3,"why":"تربط بين الحسية والحركية داخل الجهاز العصبي المركزي."},{"type":"mcq","q":"ما وظيفة الغمد المياليني حول محور الخلية العصبية؟","options":["العزل وتسريع انتقال السيال العصبي","امتصاص الضوء","هضم الغذاء","إفراز العرق"],"answer":0,"why":"الغمد المياليني يعزل المحور ويسرّع الإشارة."},{"type":"mcq","q":"أيُّ مثالٍ مما يأتي يُعدّ فعلًا منعكسًا؟","options":["رسم لوحة","رمش العين عند اقتراب جسم فجأة","كتابة الواجب","قراءة كتاب"],"answer":1,"why":"رمش العين استجابة لا إرادية سريعة لحماية العين."},{"type":"mcq","q":"ما اسم الفجوة المجهرية بين خليتين عصبيتين؟","options":["الفجوة العصارية","الحويصلة الهوائية","التشابك العصبي","البقعة العمياء"],"answer":2,"why":"التشابك العصبي هو موضع التقاء خليتين عصبيتين."}],"medium":[{"type":"mcq","q":"كيف ينتقل السيال عبر التشابك العصبي؟","options":["بسلك نحاسي","بالأسموزية","بانتقال خلايا الدم","بانتشار مواد كيميائية (نواقل عصبية)"],"answer":3,"why":"تُفرز النواقل العصبية وتنتشر عبر الفجوة."},{"type":"tfr","q":"تنقل الخلية العصبية الحسية الإشارات من العضلات إلى أعضاء الحس.","answer":false,"reasons":["بل تنقلها من أعضاء الحس (المستقبلات) إلى الجهاز العصبي المركزي","لأنها تنقلها للغدد","لأنها لا تنقل إشارات"],"reason":0},{"type":"essay","q":"اذكر خطوات القوس الانعكاسية الخمس بالترتيب.","model":"مستقبل حسي ← خلية عصبية حسية ← خلية عصبية موصّلة (في الحبل الشوكي) ← خلية عصبية حركية ← عضو الاستجابة (عضلة أو غدة)."},{"type":"tfr","q":"يمكن للفعل المنعكس أن يحدث دون تفكير واعٍ من الدماغ.","answer":true,"reasons":["لأنه فعل بطيء","لأن المركز المنظم في منعكس سحب اليد هو الحبل الشوكي لتسريع الحماية","لأن الدماغ لا يعمل"],"reason":1},{"type":"mcq","q":"ما الفرق في موقع جسم الخلية بين الحسية والحركية؟","options":["في الحركية يقع جسم الخلية في أحد الطرفين، وفي الحسية يقع على جانب الليف","كلاهما بلا محور","لا يوجد فرق","ليس للحسية جسم خلية"],"answer":0,"why":"هذا يسهّل التمييز بينهما في الرسوم التخطيطية."},{"type":"essay","q":"اذكر فرقَين بين الفعل الإرادي والفعل المنعكس مع مثال لكل منهما.","model":"الإرادي: واعٍ، أبطأ، يتحكم به الدماغ (الكتابة). المنعكس: تلقائي لا إرادي، سريع جدًّا، للحماية (سحب اليد عن الساخن)."},{"type":"tfr","q":"يسمح التشابك العصبي بانتقال السيال العصبي في الاتجاهين الأمامي والخلفي.","answer":false,"reasons":["لأنه سلك ثنائي الاتجاه","لأنه بلا نواقل","لأن النواقل العصبية تُفرز من نهاية المحور فقط والمستقبلات على الخلية التالية فقط، فيسير في اتجاه واحد"],"reason":2}],"hard":[{"type":"mcq","q":"إذا قُطع المحور الحركي المتصل بعضلة ذراع شخص وبقي الحسي سليمًا؛ ماذا يحدث عند لمسه جسمًا ساخنًا؟","options":["لا يشعر ولا يسحب يده","يشعر بالألم لكنه لا يستطيع سحب يده","يسحب يده ولا يشعر بالألم","تعمل العضلة طبيعيًا"],"answer":1,"why":"السيال الحسي يصل للدماغ فيشعر بالألم، لكن الأمر الحركي لا يصل للعضلة."},{"type":"essay","q":"فسّر لماذا يبطؤ انتقال السيال العصبي قليلًا عند مروره بالتشابك العصبي مقارنةً بمروره داخل المحور.","model":"لأنه يتحوّل من إشارة كهربائية سريعة جدًّا إلى انتشار كيميائي بطيء نسبيًا للنواقل العصبية عبر فجوة التشابك."},{"type":"tfr","q":"بعض الأدوية والمخدرات تؤثر في الجسم عبر تغيير عمل النواقل العصبية في التشابكات العصبية.","answer":true,"reasons":["لأنها قد تمنع ارتباط النواقل أو تزيد إفرازها فتغيّر انتقال الإشارات في الدماغ","لأنها لا تصل للجهاز العصبي","لأنها تعمل على العظام فقط"],"reason":0},{"type":"mcq","q":"لو تضرّرت الخلايا الحسية في إصبع شخص وبقيت الحركية سليمة؛ ماذا يحدث عند وخزه؟","options":["يشعر بألم شديد","يسحب يده تلقائيًا","لا يشعر بالوخز ولا يحدث الفعل المنعكس، لكنه يحرّك يده إراديًا","تنفصل العضلة"],"answer":2,"why":"لأن الإشارة لا تبدأ من المستقبل، لكن الأمر الإرادي من الدماغ عبر الحركية لا يزال سليمًا."},{"type":"essay","q":"اشرح كيف يتكيّف تركيب الخلية العصبية الحركية مع وظيفتها (اذكر تكيّفين).","model":"١) لها محور طويل جدًّا ينقل السيال لمسافات طويلة من الحبل الشوكي إلى العضلة. ٢) لها غمد مياليني يعزل المحور ويسرّع السيال، وزوائد شجيرية كثيرة للاتصال بخلايا أخرى."},{"type":"tfr","q":"العصب الواحد يتكوّن من حزمة تضم مئات أو آلاف المحاور العصبية معًا.","answer":true,"reasons":["العصب مكوّن من عضلات","مثل كابل كهربائي يضم أسلاكًا كثيرة معزولة معًا","العصب هو خلية واحدة فقط"],"reason":1},{"type":"mcq","q":"في القوس الانعكاسية، كم عدد التشابكات العصبية عادةً بين الحسية والموصّلة والحركية؟","options":["١٠٠ تشابك","لا يوجد تشابك","تشابك واحد فقط","تشابكان على الأقل (حسية-موصلة، وموصلة-حركية)"],"answer":3,"why":"يوجد تشابك بين الحسية والموصلة وآخر بين الموصلة والحركية."},{"type":"essay","q":"لماذا يُعدّ مرور السيال في اتجاه واحد عبر التشابك العصبي أمرًا ضروريًا لعمل الجهاز العصبي؟","model":"لمنع ارتداد الإشارات أو تداخلها، ولضمان وصول المعلومات من المستقبلات إلى المركز ثم الأوامر من المركز إلى العضلات بانتظام."},{"type":"tfr","q":"جميع الأفعال المنعكسة تمرّ عبر الحبل الشوكي ولا يمرّ أيّ منها بالدماغ.","answer":false,"reasons":["الدماغ لا ينسق أي منعكس","كل المنعكسات في اليد فقط","منعكسات الرأس كرمش العين وتضيّق الحدقة تنسّقها مناطق في الدماغ، وهي تظل تلقائية لا إرادية"],"reason":2},{"type":"essay","q":"اشرح بدقة تسلسل ما يحدث في التشابك العصبي منذ وصول السيال لنهاية الخلية الأولى حتى بدئه في الثانية.","model":"يصل السيال لنهاية المحور ← تتحرر حويصلات النواقل العصبية وتفرز النواقل في الفجوة ← تنتشر النواقل عبر الفجوة وترتبط بمستقبلات على الخلية التالية ← يتولد سيال كهربائي جديد."}]}},
  {"id":"g9-bio-1-u6-3","grade":"g9","subject":"biology","term":1,"unit":6,"no":3,"title":"العين","summary":"شرح متحرك لتركيب العين ووظائف أجزائها ومنعكس الحدقة والتكيّف البصري للأجسام القريبة والبعيدة، ثم أنشطة بثلاثة مستويات.","page":"lesson-the-eye.html","video":"","pdf":"","notes":["القرنية شفافة وتحدث معظم انكسار الضوء؛ والعدسة مرنة وتجري الضبط الدقيق لتجميع الصورة على الشبكية.","الشبكية تحوي العصيّ (للضوء الخافت) والمخاريط (للألوان والضوء الساطع، وتتركز في النقرة).","البقعة العمياء نقطة خروج العصب البصري وتخلو من المستقبلات الضوئية.","منعكس الحدقة: في الضوء الساطع تنقبض العضلات الدائرية وترتخي الشعاعية فتضيق الحدقة؛ وفي الضوء الخافت يحدث العكس فتتسع.","التكيّف البصري: للقريب تنقبض العضلات الهدبية وترتخي الأربطة فتصبح العدسة سميكة؛ وللبعيد ترتخي الهدبية وتُشد الأربطة فتصبح رقيقة."],"exercises":["قارن بين حالة العضلات الدائرية والشعاعية في القزحية عند دخول غرفة مظلمة وعند الخروج للشمس.","اشرح خطوات التكيّف البصري عند انتقال نظرك من السبورة البعيدة إلى دفترك القريب."],"levels":{"easy":[{"type":"mcq","q":"ما وظيفة العصب البصري في العين؟","options":["نقل السيالات العصبية من الشبكية إلى الدماغ","تغيير حجم الحدقة","إفراز الدموع","كسر أشعة الضوء"],"answer":0,"why":"ينقل الإشارات البصرية للدماغ لتفسير الصورة."},{"type":"mcq","q":"أيُّ خلايا الشبكية مسؤولة عن رؤية الألوان في الضوء الساطع؟","options":["الأربطة المعلّقة","المخاريط","العصيّ","العضلات الدائرية"],"answer":1,"why":"المخاريط للرؤية الملونة والعصيّ للضوء الخافت."},{"type":"mcq","q":"ماذا يحدث للحدقة عند الانتقال إلى مكان مظلم؟","options":["تبقى ثابتة","تضيق","تتسع لإدخال ضوء أكثر","تُغلق تمامًا"],"answer":2,"why":"اتساع الحدقة يسمح بدخول أكبر قدر من الضوء."},{"type":"mcq","q":"ما الجزء الشفاف الأمامي من العين الذي يكسر معظم الضوء؟","options":["البقعة العمياء","الشبكية","العصب البصري","القرنية"],"answer":3,"why":"القرنية مقوّسة وشفافة وتحدث الانكسار الأكبر للضوء."}],"medium":[{"type":"mcq","q":"أين تتركّز خلايا المخاريط في الشبكية لتعطي أوضح رؤية؟","options":["في النقرة (Fovea)","في القرنية","في القزحية","في البقعة العمياء"],"answer":0,"why":"النقرة هي موضع الرؤية الأدق والأكثر وضوحًا."},{"type":"tfr","q":"عند النظر إلى جسم بعيد، تنقبض العضلات الهدبية وتصبح العدسة أكثر سمكًا.","answer":false,"reasons":["بل ترتخي العضلات الهدبية وتُشد الأربطة فتصبح العدسة أرقّ وأقل تحدبًا","للجسم البعيد نحتاج انكسارًا أقوى","العدسة لا يتغير شكلها"],"reason":0},{"type":"essay","q":"قارن بين خلايا العصيّ وخلايا المخاريط في الشبكية من حيث الوظيفة والإضاءة المناسبة.","model":"العصيّ: تعمل في الضوء الخافت ولا تميّز الألوان (أبيض وأسود). المخاريط: تعمل في الضوء الساطع وتميّز الألوان وتتركّز في النقرة."},{"type":"tfr","q":"تعمل العضلات الدائرية والعضلات الشعاعية في القزحية كزوج متضاد.","answer":true,"reasons":["لأنهما تنقبضان معًا","عندما تنقبض إحداهما ترتخي الأخرى لتضييق الحدقة أو توسيعها","لأنهما في العدسة"],"reason":1},{"type":"mcq","q":"ما حالة الأربطة المعلّقة للعدسة عند قراءة كتاب قريب؟","options":["منقبضة","مرتخية","مشدودة بقوة","مقطوعة"],"answer":1,"why":"انقباض العضلات الهدبية يرخي الأربطة المعلّقة فتنتفخ العدسة."},{"type":"essay","q":"فسّر أهمية منعكس الحدقة عند التعرّض المفاجئ لضوء الشمس الساطع.","model":"تضيق الحدقة تلقائيًا وسريعًا لتقليل كمية الضوء الداخلة للعين ومنع تلف المستقبلات الضوئية الحساسة في الشبكية."},{"type":"tfr","q":"الحدقة (البؤبؤ) هي عضلة صلبة ملوّنة في مقدمة العين.","answer":false,"reasons":["الحدقة هي العدسة","الحدقة في خلفية العين","الحدقة مجرد فتحة يدخل منها الضوء، أما الجزء الملوّن العضلي الذي يغيّر حجمها فهو القزحية"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا تبدو الأشياء في الغرفة شبه المظلمة رمادية بلا ألوان واضحة؟","options":["لأن القرنية تصبح معتمة","لأن الألوان تختفي من الأجسام","لأن العصيّ هي التي تعمل في الضوء الخافت ولا تميّز الألوان، بينما لا يُستثار المخاريط إلا بضوء كافٍ","لأن العدسة تتوقف"],"answer":2,"why":"المخاريط المسؤولة عن الألوان تحتاج شدة إضاءة أعلى لتعمل."},{"type":"essay","q":"تتبّع التغيّرات الأربعة التي تحدث في العين عندما ترفع نظرك فجأةً من هاتفك القريب إلى طائرة بعيدة في السماء.","model":"١) ترتخي العضلات الهدبية. ٢) تُشدّ الأربطة المعلّقة. ٣) تصبح العدسة أرقّ وأقل تحدّبًا. ٤) يقل مقدار انكسار الأشعة المتوازية فتتجمع بدقة على الشبكية."},{"type":"tfr","q":"يُعدّ منعكس الحدقة فعلًا منعكسًا لا إراديًا، مستقبله الشبكية ومستجيبه عضلات القزحية.","answer":true,"reasons":["ترصد الشبكية شدة الضوء فترسل إشارات للدماغ الذي يأمر عضلات القزحية بتعديل الحدقة تلقائيًا","لأن المستجيب هو القرنية","لأن الحدقة تتحكم بها إراديًا"],"reason":0},{"type":"mcq","q":"كم نوعًا من خلايا المخاريط يوجد في شبكية عين الإنسان الطبيعية لتمييز الألوان؟","options":["نوعان فقط","١٠ أنواع","نوع واحد فقط","٣ أنواع (حساسة للأحمر والأخضر والأزرق)"],"answer":3,"why":"مزج إشارات الأنواع الثلاثة يتيح رؤية جميع الألوان."},{"type":"essay","q":"لماذا يعاني بعض كبار السن من صعوبة قراءة الكتب القريبة (طول النظر الشيخوخي)؟","model":"لأن العدسة تفقد جزءًا من مرونتها مع التقدم في العمر، فلا تصبح سميكة ومحدّبة بما يكفي لكسر أشعة الأجسام القريبة على الشبكية."},{"type":"tfr","q":"الصورة التي تتكوّن على شبكية العين تكون مقلوبة، ثم يعيد الدماغ تفسيرها معتدلة.","answer":true,"reasons":["الصورة على الشبكية معتدلة دائمًا","العدسة المحدّبة تكوّن صورة حقيقية مقلوبة على الشبكية، ويعالجها الدماغ لنراها معتدلة","الدماغ لا يعالج الصورة"],"reason":1},{"type":"mcq","q":"إذا سقطت أشعة ضوئية على البقعة العمياء بالضبط، ماذا يحدث؟","options":["لا تتولّد سيالات عصبية ولا يُرى الجسم في تلك النقطة","تتضاعف الإضاءة","تُرى الصورة بأوضح شكل","تُرى بالأبيض والأسود فقط"],"answer":0,"why":"لأن البقعة العمياء خالية من العصيّ والمخاريط."},{"type":"essay","q":"قارن بين دور القرنية ودور العدسة في تجميع الضوء على الشبكية.","model":"القرنية تُحدث معظم انكسار الضوء وبمقدار ثابت، أما العدسة فتجري الضبط الدقيق المتغيّر لانكسار الضوء حسب بُعد الجسم."},{"type":"tfr","q":"الأربطة المعلّقة هي عضلات تنقبض وترتخي من تلقاء نفسها.","answer":false,"reasons":["الأربطة هي نفسها العضلات الهدبية","الأربطة تفرز الدموع","الأربطة المعلّقة ألياف غير عضلية تُشد أو ترتخي تبعًا لانقباض وارتخاء العضلات الهدبية"],"reason":2},{"type":"essay","q":"اشرح القوس الانعكاسية لمنعكس الحدقة عند تسليط ضوء مصباح على العين.","model":"المؤثّر (ضوء ساطع) ← المستقبل (الشبكية) ← خلية حسية (العصب البصري) ← المنظّم (الدماغ) ← خلية حركية ← المستجيب (انقباض الدائرية وارتخاء الشعاعية في القزحية) ← تضيق الحدقة."}]}},
  {"id":"g9-bio-1-u6-4","grade":"g9","subject":"biology","term":1,"unit":6,"no":4,"title":"الهرمونات","summary":"شرح متحرك لمفهوم الهرمونات والغدد الصماء وأهم الهرمونات وخاصة الأدرينالين وتأثيراته، ثم أنشطة بثلاثة مستويات.","page":"lesson-hormones.html","video":"","pdf":"","notes":["الهرمون: مادة كيميائية تنتجها غدة صماء (لا قنوية) وتنتقل عبر الدم لتغيّر نشاط عضو مستهدف أو أكثر، ثم يحطّمها الكبد.","الغدة الكظرية (فوق الكلية): تفرز الأدرينالين (هرمون الكرّ والفرّ).","تأثيرات الأدرينالين: زيادة معدل نبض القلب، وزيادة معدل التنفس، وتحويل الجلايكوجين في الكبد إلى جلوكوز في الدم، واتساع حدقة العين.","البنكرياس: يفرز الأنسولين والجلوكاجون لتنظيم مستوى الجلوكوز في الدم.","الخصيتان تفرزان التستوستيرون، والمبيضان يفرزان الإستروجين."],"exercises":["اذكر أربعة تأثيرات لهرمون الأدرينالين وبيّن فائدة كل منها في موقف خطر.","اربط كل غدة صماء بهرمونها: الكظرية، البنكرياس، الخصيتان، المبيضان."],"levels":{"easy":[{"type":"mcq","q":"أين تقع الغدتان الكظريتان في جسم الإنسان؟","options":["في الرقبة","فوق الكليتين","في الدماغ","في الرئتين"],"answer":1,"why":"تقع كل غدة كظرية أعلى إحدى الكليتين."},{"type":"mcq","q":"ما الهرمون الذي يفرزه البنكرياس لخفض سكر الدم؟","options":["الإستروجين","التستوستيرون","الأنسولين","الأدرينالين"],"answer":2,"why":"الأنسولين يخفض مستوى الجلوكوز المرتفع في الدم."},{"type":"mcq","q":"كيف يؤثر الأدرينالين في حدقة العين؟","options":["يغلقها","لا يؤثر فيها","يضيّقها","يوسّعها"],"answer":3,"why":"اتساع الحدقة يُدخل مزيدًا من الضوء لمراقبة المحيط."},{"type":"mcq","q":"ما العضو الذي يتخلّص من الهرمونات ويحطّمها بعد انتهاء عملها؟","options":["الكبد","القلب","الأمعاء","الطحال"],"answer":0,"why":"الكبد يحطّم الهرمونات فيتوقف أثرها بعد زوال الحاجة."}],"medium":[{"type":"mcq","q":"ما الهرمون المسؤول عن ظهور الصفات الجنسية الأنثوية عند البلوغ؟","options":["التستوستيرون","الإستروجين","الأدرينالين","الأنسولين"],"answer":1,"why":"يفرز المبيضان هرمون الإستروجين."},{"type":"tfr","q":"الغدد اللعابية تُعدّ من الغدد الصماء لأنها تفرز سائلًا.","answer":false,"reasons":["الغدد اللعابية غدد قنوية تفرز اللعاب عبر قنوات إلى الفم وليس في الدم","لأنها لا تفرز شيئًا","لأنها تفرز هرمونات في الدم"],"reason":0},{"type":"essay","q":"اذكر أربعة تأثيرات لهرمون الأدرينالين على جسم الإنسان.","model":"١) زيادة معدل نبض القلب. ٢) زيادة معدل التنفس. ٣) زيادة تركيز الجلوكوز في الدم (من الجلايكوجين). ٤) اتّساع حدقة العين."},{"type":"tfr","q":"ينتقل الهرمون في الدم إلى جميع أنحاء الجسم، لكنه يؤثر فقط في «الأعضاء المستهدفة».","answer":true,"reasons":["لأن الدم لا يصل لبقية الأعضاء","لأن الأعضاء المستهدفة وحدها تمتلك مستقبلات خاصة تتعرف على هذا الهرمون","لأن الهرمون يمشي في الأعصاب"],"reason":1},{"type":"mcq","q":"لماذا يرفع الأدرينالين تركيز الجلوكوز في الدم عند الخوف؟","options":["لإبطاء القلب","لتقليل الطاقة","لتوفير وقود إضافي للتنفس الخلوي وإطلاق الطاقة للعضلات","لتخزين الدهون"],"answer":2,"why":"العضلات تحتاج جلوكوز وأكسجين إضافي للهرب أو المواجهة."},{"type":"essay","q":"عرّف الهرمون تعريفًا علميًا كاملًا.","model":"مادة كيميائية تُنتجها غدة صماء وتنتقل عبر الدم لتغيّر نشاط عضو مستهدف أو أكثر، ثم يحطّمها الكبد."},{"type":"tfr","q":"يُعدّ البنكرياس عضوًا فريدًا لأنه يعمل كغدة صماء (يفرز هرمونات في الدم) وغدة قنوية (يفرز أنزيمات هاضمة للأمعاء).","answer":true,"reasons":["لأنه لا يفرز أنزيمات","لأنه يفرز الأدرينالين","البنكرياس يفرز الأنسولين والجلوكاجون في الدم، وعصارة هاضمة عبر قناة للاثني عشر"],"reason":2}],"hard":[{"type":"mcq","q":"أثناء إفراز الأدرينالين، لماذا يقلّ تدفق الدم إلى المعدة والأمعاء ويزداد نحو العضلات؟","options":["لأن الدم يتجمد في المعدة","لخفض ضغط الدم","لأن المعدة تتوقف للأبد","لإعطاء الأولوية للعضلات بالأكسجين والجلوكوز في لحظة الطوارئ بدل الهضم"],"answer":3,"why":"الهضم يمكن تأجيله، أما النجاة والهرب فهما الأولوية الفورية."},{"type":"essay","q":"فسّر لماذا يستمر شعورك بتسارع نبضات القلب لعدة دقائق بعد نجاتك من موقف مخيف مفاجئ.","model":"لأن الأدرينالين لا يزال يدور في مجرى الدم، ويستغرق الكبد بضع دقائق لتحطيمه بالكامل حتى يزول أثره."},{"type":"tfr","q":"زيادة معدل التنفس ونبض القلب معًا بفعل الأدرينالين ترفع معدل التنفُّس الهوائي في العضلات.","answer":true,"reasons":["لأنها تزيد الأكسجين والجلوكوز الواصلين للعضلات فتطلق طاقة أكبر للانقباض","لأنها تمنع الأكسجين","لأنها تقلل الجلوكوز"],"reason":0},{"type":"mcq","q":"أيُّ زوجٍ مما يأتي (غدة : هرمون : عضو مستهدف) صحيح بالكامل؟","options":["الغدة الكظرية : الأدرينالين : القلب والكبد","البنكرياس : الأدرينالين : العين","المبيض : الأنسولين : القلب","الخصية : الإستروجين : الكبد"],"answer":0,"why":"الأدرينالين من الكظرية يستهدف القلب والكبد والعضلات والعين."},{"type":"essay","q":"قارن بين استجابة حدقة العين في الضوء الساطع واستجابتها عند إفراز الأدرينالين في موقف خوف.","model":"في الضوء الساطع تضيق الحدقة لحماية الشبكية؛ أما عند إفراز الأدرينالين فتتسع الحدقة لإدخال مزيد من الضوء وزيادة الوعي بالمحيط."},{"type":"tfr","q":"تُفرَز جميع الهرمونات بكميات ضخمة (مئات الجرامات يوميًا) لتستطيع التأثير في الجسم.","answer":false,"reasons":["لأنها تملأ الدم","تُفرز الهرمونات بكميات دقيقة جدًّا (ميكروجرامات) ومع ذلك تُحدث تأثيرات قوية جدًّا","لأنها تُقاس بالكيلوجرام"],"reason":1},{"type":"mcq","q":"إذا تعطّلت وظيفة الكبد في تحطيم هرمون معيّن، ماذا تتوقّع أن يحدث؟","options":["يتحول الهرمون لماء","يستمر تأثير الهرمون في الدم فترةً أطول من اللازم فيختلّ التوازن","لا يتأثر الجسم","يختفي الهرمون فورًا"],"answer":1,"why":"تحطيم الكبد للهرمون ضروري لإنهاء الاستجابة في الوقت المناسب."},{"type":"essay","q":"قارن بين الأنسولين والأدرينالين من حيث تأثير كلٍّ منهما على مستوى الجلوكوز في الدم.","model":"الأنسولين يخفض مستوى الجلوكوز في الدم (بتحويله إلى جلايكوجين في الكبد)، أما الأدرينالين فيرفع مستوى الجلوكوز في الدم (بتحويل الجلايكوجين إلى جلوكوز)."},{"type":"tfr","q":"استجابة هرمون الأدرينالين أسرع من استجابة هرمونات النمو، لكنها تبقى أبطأ من الفعل المنعكس العصبي.","answer":true,"reasons":["لأن الأدرينالين أسرع من الأعصاب","لأن الأدرينالين ينتقل بالأعصاب","لأن الأدرينالين ينتقل بالدم (ثوانٍ)، أما المنعكس العصبي فكهربائي (أجزاء من الثانية)"],"reason":2},{"type":"essay","q":"اذكر موقفين يوميين يُفرز فيهما الأدرينالين في جسم الإنسان، واشرح كيف يساعدك في أحدهما.","model":"١) قبل انطلاق سباق رياضي. ٢) عند التعرض لخطر مفاجئ (كسيارة مسرعة). في السباق يرفع نبض القلب والتنفس وجلوكوز الدم فيمنح العضلات طاقة قصوى."}]}},
  {"id":"g9-bio-1-u6-5","grade":"g9","subject":"biology","term":1,"unit":6,"no":5,"title":"الاتزان الداخلي","summary":"شرح متحرك لمفهوم الاتزان الداخلي والتغذية الراجعة السلبية وتنظيم سكر الدم ودرجة حرارة الجسم عبر الجلد، ثم أنشطة بثلاثة مستويات.","page":"lesson-homeostasis.html","video":"","pdf":"","notes":["الاتزان الداخلي: الحفاظ على ثبات البيئة الداخلية للجسم ضمن حدود ضيقة عبر التغذية الراجعة السلبية.","ارتفاع سكر الدم ← البنكرياس يفرز الأنسولين ← الكبد والعضلات تحول الجلوكوز إلى جلايكوجين ← ينخفض السكر للطبيعي.","انخفاض سكر الدم ← البنكرياس يفرز الجلوكاجون ← الكبد يحول الجلايكوجين إلى جلوكوز ← يرتفع السكر للطبيعي.","في الحرّ (بإشراف تحت المهاد): إفراز العرق (تبريد بالتبخّر) + توسّع الأوعية الدموية السطحية (Vasodilation).","في البرد: تضيّق الأوعية السطحية (Vasoconstriction) + توقّف العرق + الارتجاف العضلي + انتصاب الشعر."],"exercises":["اشرح كيف يعمل كل من الأنسولين والجلوكاجون معًا كمثال للتغذية الراجعة السلبية.","فسّر لماذا يحمرّ وجهك في الحرّ ويميل للشحوب في البرد الشديد."],"levels":{"easy":[{"type":"mcq","q":"ما درجة الحرارة الطبيعية التقريبية لجسم الإنسان؟","options":["٣٠°م","٤٥°م","٣٧°م","٢٥°م"],"answer":2,"why":"٣٧°م هي الدرجة المثلى لعمل أنزيمات الإنسان."},{"type":"mcq","q":"ما العضو الذي يفرز هرمونَي الأنسولين والجلوكاجون؟","options":["المعدة","الكلية","الكبد","البنكرياس"],"answer":3,"why":"البنكرياس ينظم سكر الدم بهذين الهرمونين."},{"type":"mcq","q":"كيف يبرّد العرق جسم الإنسان؟","options":["بتبخّر الماء من سطح الجلد وامتصاص الحرارة","بزيادة سمك الدهون","بمنع التنفس","بتجمّد العرق"],"answer":0,"why":"التبخّر يسحب الطاقة الحرارية من الجلد."},{"type":"mcq","q":"ما الذي يحدث للأوعية الدموية السطحية في الجلد عند البرد؟","options":["تفرز عرقًا","تضيق لتقليل فقد الحرارة","تتسع","تنفجر"],"answer":1,"why":"التضيّق يقلّل الدم المار قرب السطح فيحفظ حرارة الجسم."}],"medium":[{"type":"mcq","q":"ما وظيفة هرمون الجلوكاجون في تنظيم سكر الدم؟","options":["إفراز العرق","توسيع الحدقة","تحفيز الكبد لتحويل الجلايكوجين إلى جلوكوز","تحويل الجلوكوز إلى جلايكوجين"],"answer":2,"why":"الجلوكاجون يرفع سكر الدم المنخفض."},{"type":"tfr","q":"تنتقل الأوعية الدموية في الجلد نحو السطح أو تبتعد عنه لتنظيم الحرارة.","answer":false,"reasons":["الأوعية لا تغيّر مكانها، بل يتسع قطر الشرايين السطحية (توسع) أو يضيق (تضيق) لتغيير كمية الدم المتدفق قرب السطح","الأوعية تتحرك لأعلى وأسفل","الأوعية تختفي في البرد"],"reason":0},{"type":"essay","q":"عرّف الاتزان الداخلي واذكر مثالين لما ينظّمه في جسم الإنسان.","model":"هو الحفاظ على ثبات البيئة الداخلية للجسم ضمن حدود ضيقة. أمثلة: درجة حرارة الجسم (~٣٧°م)، وتركيز الجلوكوز في الدم، ومحتوى الماء."},{"type":"tfr","q":"في مرض السكري من النوع الأول يظهر الجلوكوز في بول المريض عند عدم العلاج.","answer":true,"reasons":["لأن الكبد يفرز سكرًا في البول","لأن غياب الأنسولين يرفع جلوكوز الدم جدًّا فلا تستطيع الكليتان إعادة امتصاصه كله فيخرج في البول","لأن السكر منعدم في الدم"],"reason":1},{"type":"mcq","q":"أيُّ استجابةٍ مما يأتي تحدث عند ارتفاع حرارة الجسم؟","options":["الارتجاف","تضيّق الأوعية السطحية","انتصاب الشعر","توسّع الأوعية السطحية والتعرّق"],"answer":3,"why":"التوسع والتعرق يخلصان الجسم من الحرارة الزائدة."},{"type":"essay","q":"اشرح ماذا يحدث لمستوى سكر الدم بعد تناول وجبة غنية بالنشا حتى يعود للطبيعي.","model":"يرتفع الجلوكوز في الدم ← يرصده البنكرياس فيفرز الأنسولين ← يحفّز الكبد والعضلات لتحويل الجلوكوز الزائد إلى جلايكوجين ← ينخفض الجلوكوز ويعود للطبيعي."},{"type":"tfr","q":"تتأثّر عملية التبريد بالتعرّق وتصبح أقل كفاءة في الجو شديد الرطوبة.","answer":true,"reasons":["لأن العرق لا يتبخر أبدًا","لأن الرطوبة تسرّع التبخّر","لأن الهواء المشبع ببخار الماء يبطئ تبخّر العرق من سطح الجلد"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا لا يُعطى مريض السكري هرمون الأنسولين على شكل أقراص تُبلع بالفم؟","options":["لأن الأنسولين بروتين فستهضمه أنزيمات البروتياز في المعدة والأمعاء قبل وصوله للدم","لأنه يتحول إلى نشا","لأنه سام للمعدة","لأنه لا يذوب في الماء"],"answer":0,"why":"الأنسولين بروتين فيُحقن تحت الجلد ليصل للدم سليمًا دون هضم."},{"type":"essay","q":"فسّر آلية «التغذية الراجعة السلبية» باستخدام تنظيم درجة حرارة الجسم كمثال.","model":"عندما ترتفع الحرارة فوق ٣٧°م يرسل تحت المهاد أوامر للتعرق وتوسع الأوعية لخفضها؛ وبمجرد عودتها لـ ٣٧°م تتوقف هذه الآليات. وإذا انخفضت تحت ٣٧°م يفعّل الارتجاف وتضيق الأوعية لرفعها مجددًا."},{"type":"tfr","q":"يسبّب تضيّق الأوعية الدموية السطحية في البرد الشديد شحوب لون الجلد.","answer":true,"reasons":["لأن كمية الدم الأحمر الدافئ المتدفق قرب سطح الجلد تقلّ كثيرًا","لأن الدم يتحول للأزرق","لأن الجلد يتوقف عن النمو"],"reason":0},{"type":"mcq","q":"ما دور طبقة الدهون تحت الجلد في الاتزان الحراري؟","options":["تنتج الأنسولين","تعمل كعازل حراري يقلل فقد الحرارة في الجو البارد","ترصد حرارة الدم","تفرز العرق"],"answer":1,"why":"النسيج الدهني موصل رديء للحرارة فيعزل الجسم."},{"type":"essay","q":"لماذا يُعدّ انخفاض سكر الدم الشديد خطيرًا جدًّا على الدماغ؟","model":"لأن خلايا الدماغ تعتمد بشكل أساس على الجلوكوز في التنفس الهوائي لإطلاق الطاقة؛ ونقصه يسبب دوخة وإغماءً وقد يهدد الحياة."},{"type":"tfr","q":"تستطيع العضلات أن تشارك في توليد الحرارة عبر الارتجاف اللاإرادي في الجو البارد.","answer":true,"reasons":["لأن العضلات تفرز عرقًا","لأن الانقباض السريع للعضلات يرفع معدل التنفس الخلوي فيها فتتحرر طاقة حرارية تدفّئ الدم","لأن الارتجاف يبرّد الجسم"],"reason":1},{"type":"mcq","q":"في يوم شتوي بارد، أيُّ مجموعة استجابات تحدث معًا في الجسم؟","options":["توسّع أوعية + تعرّق","تضيّق أوعية + تعرّق غزير","تضيّق أوعية سطحية + ارتجاف + انتصاب شعر + توقف تعرّق","توسّع أوعية + ارتجاف"],"answer":2,"why":"كلها آليات لحفظ الحرارة وتوليدها."},{"type":"essay","q":"قارن بين توسّع الأوعية الدموية وتضيّقها من حيث: الظرف الحراري، وتدفق الدم قرب السطح، وفقد الحرارة.","model":"التوسع: في الحر، يزداد تدفق الدم قرب سطح الجلد، فيزداد فقد الحرارة بالإشعاع. التضيق: في البرد، يقل تدفق الدم قرب السطح، فيقل فقد الحرارة."},{"type":"tfr","q":"الخطأ في وصف توسع الأوعية بأنها «تقترب من سطح الجلد» غير مقبول علميًا.","answer":true,"reasons":["لأن الجلد يتحرك للداخل","لأن الأوعية تتحرك فعليًا","لأن الأوعية ثابتة في مكانها، والذي يتغير هو اتساع قطر الشرايين السطحية ليمر بها دم أكثر"],"reason":2},{"type":"essay","q":"لخّص دور كلٍّ من البنكرياس والكبد في الحفاظ على ثبات مستوى الجلوكوز في الدم طوال اليوم.","model":"البنكرياس يراقب سكر الدم ويفرز الأنسولين عند ارتفاعه أو الجلوكاجون عند انخفاضه؛ والكبد هو المخزن الذي يحوّل الجلوكوز لجلايكوجين (بأمر الأنسولين) أو العكس (بأمر الجلوكاجون)."}]}},
  {"id":"g9-bio-2-u7-1","grade":"g9","subject":"biology","term":2,"unit":7,"no":1,"title":"أنواع التغذية","summary":"شرح متحرك بـ SVG لدرس أنواع التغذية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-types-of-nutrition.html","video":"","pdf":"","notes":["ذاتية التغذية (النباتات والطحالب) تصنع غذاءها العضوي من مواد غير عضوية وضوء؛ وغير الذاتية (الحيوانات والفطريات) تعتمد على غيرها.","النترات (NO₃⁻) لبناء البروتينات والنمو، ونقصها يسبب التقزّم والاصفرار.","المغنيسيوم (Mg²⁺) لبناء الكلوروفيل، ونقصه يسبب اصفرار الأوراق."],"exercises":["قارن بين التغذية الذاتية وغير الذاتية مع ذكر مثالين لكل منهما.","قارن بين دور أيونات النترات ودور أيونات المغنيسيوم في النبات وأثر نقص كل منهما.","لماذا يُنصح المزارع بإضافة سماد يحتوي على نترات ومغنيسيوم عند اصفرار أوراق محصوله؟"],"levels":{"easy":[{"type":"mcq","q":"ما الكائنات التي تصنع غذاءها العضوي بنفسها من الماء و CO₂ باستخدام الضوء؟","options":["الإنسان","الفطريات","الحيوانات اللاحمة","ذاتية التغذية (النباتات الخضراء والطحالب)"],"answer":3,"why":"النباتات والطحالب ذاتية التغذية عبر التمثيل الضوئي."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع صبغة «الكلوروفيل» الخضراء في النبات؟","options":["أيونات المغنيسيوم (Mg²⁺)","أيونات الصوديوم","الكلوريد","الحديد فقط"],"answer":0,"why":"المغنيسيوم عنصر أساس في تركيب جزيء الكلوروفيل."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع «الأحماض الأمينية والبروتينات» في النبات؟","options":["الأكسجين","أيونات النترات (NO₃⁻)","الكربون فقط","الماء"],"answer":1,"why":"النيتروجين في النترات يدخل في بناء الأحماض الأمينية والبروتين."},{"type":"mcq","q":"تُصنّف الفطريات (كعيش الغراب والعفن) من حيث التغذية بأنها:","options":["منتجات ضوئية","ذاتية التغذية","غير ذاتية التغذية (لا تحتوي كلوروفيل)","نباتات خضراء"],"answer":2,"why":"الفطريات تخلو من الكلوروفيل وتعتمد على مواد عضوية جاهزة."}],"medium":[{"type":"mcq","q":"ماذا يظهر على أوراق نبات يعاني من نقص «المغنيسيوم» في التربة؟","options":["لا يتأثر النبات","تحولها للون الأزرق","زيادة سمكها بشدة","اصفرار الأوراق لعدم كفاية الكلوروفيل"],"answer":3,"why":"نقص المغنيسيوم يقلل الكلوروفيل فتصفر الأوراق."},{"type":"mcq","q":"أي المواد الآتية تُعد «مادة غير عضوية» يمتصها النبات؟","options":["الماء وثاني أكسيد الكربون والأملاح المعدنية","النشا","البروتين","الجلوكوز"],"answer":0,"why":"الماء و CO₂ والأملاح مواد غير عضوية بسيطة."},{"type":"mcq","q":"ماذا يسبب نقص «أيونات النترات» للنبات؟","options":["زيادة سريعة في الطول","ضعف النمو وتقزّم النبات واصفرار الأوراق","زيادة البروتين","تضاعف الثمار"],"answer":1,"why":"النترات لازمة لبناء البروتينات ونمو الخلايا."},{"type":"tfr","q":"التغذية الذاتية تعني تحويل مواد غير عضوية بسيطة إلى مواد عضوية معقدة باستخدام طاقة الضوء.","answer":true,"reasons":["وهي العملية التي تقوم بها النباتات الخضراء والطحالب","تحويل العضوي لغير عضوي","تقوم بها الحيوانات"],"reason":0},{"type":"tfr","q":"تستطيع الفطريات القيام بالتمثيل الضوئي لأنها تنمو في التربة.","answer":false,"reasons":["نعم تقوم به","الفطريات لا تحتوي على كلوروفيل ولا بلاستيدات خضراء فهي غير ذاتية التغذية","تحتوي كلوروفيل"],"reason":1},{"type":"essay","q":"قارن بين التغذية الذاتية وغير الذاتية مع ذكر مثالين لكل منهما.","model":"الذاتية: يصنع الكائن غذاءه العضوي من ماء و CO₂ وضوء (النباتات الخضراء، الطحالب). غير الذاتية: يعتمد على غذاء عضوي جاهز من كائنات أخرى (الإنسان، الأسد، الفطريات)."},{"type":"essay","q":"قارن بين دور أيونات النترات ودور أيونات المغنيسيوم في النبات وأثر نقص كل منهما.","model":"النترات: بناء الأحماض الأمينية والبروتينات، ونقصها يسبب تقزم النمو واصفرار الأوراق. المغنيسيوم: بناء الكلوروفيل، ونقصه يسبب اصفرار الأوراق."}],"hard":[{"type":"mcq","q":"لماذا تُسمّى النباتات الخضراء «المنتجات» في النظام البيئي؟","options":["لأنها تأكل الحيوانات","لأنها تبيع الغذاء","لأنها تنتج الغذاء العضوي الأولي لكل الكائنات الحية من طاقة الشمس","لأنها تتحرك بسرعة"],"answer":2,"why":"المنتجات تحوّل الطاقة الضوئية لطاقة كيميائية غذائية."},{"type":"mcq","q":"الإنسان كائن:","options":["يصنع الجلوكوز من الهواء","ذاتي التغذية","منتج ضوئي","غير ذاتي التغذية"],"answer":3,"why":"يحصل الإنسان على غذائه العضوي من النباتات والحيوانات."},{"type":"mcq","q":"أعراض نقص النترات ونقص المغنيسيوم تشترك في:","options":["اصفرار الأوراق وضعف التمثيل الضوئي","تلوّن الأوراق بالأزرق","نمو أسرع","زيادة البروتين"],"answer":0,"why":"كلاهما يضعف الورقة ويسبب الاصفرار، والنترات تسبب تقزمًا شديدًا أيضًا."},{"type":"mcq","q":"المادة العضوية الأولية التي ينتجها النبات في التغذية الذاتية هي:","options":["ثاني أكسيد الكربون","الجلوكوز","الماء","النيتروجين"],"answer":1,"why":"الجلوكوز هو السكر البسيط الناتج عن التمثيل الضوئي."},{"type":"tfr","q":"نقص أيونات المغنيسيوم يسبب اصفرار أوراق النبات لأنه يدخل في تركيب الكلوروفيل.","answer":true,"reasons":["لا أثر له على اللون","المغنيسيوم للماء فقط","فيضعف امتصاص الضوء وتقل كفاءة التمثيل الضوئي"],"reason":2},{"type":"tfr","q":"يستطيع النبات صنع البروتينات من الجلوكوز وحده دون الحاجة لأيونات النترات.","answer":false,"reasons":["البروتينات تحتوي عنصر النيتروجين الذي يحصل عليه النبات من أيونات النترات في التربة","نعم الجلوكوز يكفي","البروتين بلا نيتروجين"],"reason":0},{"type":"tfr","q":"تعتمد جميع الحيوانات (العاشبة واللاحمة) بصورة مباشرة أو غير مباشرة على النباتات ذاتية التغذية.","answer":true,"reasons":["اللاحمة لا تعتمد على النبات أبدًا","لأن النباتات هي المصدر الأول للغذاء العضوي والأكسجين على الأرض","لا توجد علاقة"],"reason":1},{"type":"essay","q":"لماذا يُنصح المزارع بإضافة سماد يحتوي على نترات ومغنيسيوم عند اصفرار أوراق محصوله؟","model":"لتعويض نقص هذين الأيونين في التربة فيعود النبات لتصنيع الكلوروفيل والبروتينات وتستعيد الأوراق خضرتها ونموها."},{"type":"essay","q":"فرّق بين المواد العضوية والمواد غير العضوية في غذاء النبات.","model":"غير العضوية بسيطة كالماء و CO₂ والأملاح؛ والعضوية معقدة غنية بالطاقة كالجلوكوز والنشا والبروتينات التي يبنيها النبات."},{"type":"essay","q":"اشرح لماذا تُعد النباتات الخضراء أساس استمرار الحياة على سطح الأرض.","model":"لأنها تحوّل طاقة الشمس إلى غذاء عضوي يغذي السلاسل الغذائية وتطلق غاز الأكسجين الضروري لتنفس الكائنات الحية."}]}},
  {"id":"g9-bio-2-u7-2","grade":"g9","subject":"biology","term":2,"unit":7,"no":2,"title":"التمثيل الضوئي","summary":"شرح متحرك بـ SVG لدرس التمثيل الضوئي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-photosynthesis.html","video":"","pdf":"","notes":["التمثيل الضوئي: 6CO₂ + 6H₂O —ضوء/كلوروفيل→ C₆H₁₂O₆ + 6O₂.","الكلوروفيل في البلاستيدات الخضراء يمتص الطاقة الضوئية ويحوّلها لكيميائية.","يدخل CO₂ عبر الثغور بالانتشار، والماء عبر الجذور والخشب.","النبات يتنفس ليلًا ونهارًا، ويقوم بالتمثيل الضوئي نهارًا فقط."],"exercises":["اكتب المعادلة اللفظية والرمزية الموزونة لعملية التمثيل الضوئي مع ذكر الشروط.","قارن بين التبادل الغازي للنبات في النهار المشمس وفي الليل المظلم.","اشرح دور الكلوروفيل في عملية التمثيل الضوئي."],"levels":{"easy":[{"type":"mcq","q":"ما المعادلة الرمزية الموزونة الصحيحة للتمثيل الضوئي؟","options":["6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂","CO₂ + H₂O → C₆H₁₂O₆ + O₂","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","6O₂ + 6H₂O → C₆H₁₂O₆"],"answer":0,"why":"تتوازن بوضع 6 أمام CO₂ و H₂O و O₂."},{"type":"mcq","q":"ما وظيفة صبغة «الكلوروفيل» في التمثيل الضوئي؟","options":["امتصاص الماء من التربة","امتصاص الطاقة الضوئية وتحويلها إلى طاقة كيميائية","حماية الجذور","تخزين البروتين"],"answer":1,"why":"الكلوروفيل يلتقط الطاقة الضوئية لتشغيل التفاعل."},{"type":"mcq","q":"كيف يدخل غاز ثاني أكسيد الكربون إلى داخل الورقة؟","options":["عبر اللحاء","عبر الجذور بالأسموزية","عبر الثغور بعملية الانتشار","عبر القشرة الصلبة"],"answer":2,"why":"ينتشر CO₂ من الهواء عبر فتحات الثغور."},{"type":"mcq","q":"أين تحدث عملية التمثيل الضوئي داخل الخلية النباتية؟","options":["في الجدار الخلوي","في النواة","في الفجوة العصارية","في البلاستيدات الخضراء"],"answer":3,"why":"البلاستيدات الخضراء تحتوي الكلوروفيل وإنزيمات التمثيل الضوئي."}],"medium":[{"type":"mcq","q":"ما الغاز الثانوي الناتج عن التمثيل الضوئي والمهم لتنفس الكائنات؟","options":["الأكسجين (O₂)","النيتروجين","ثاني أكسيد الكبريت","الميثان"],"answer":0,"why":"ينتج الأكسجين بجانب الجلوكوز."},{"type":"mcq","q":"متى يقوم النبات بعملية «التمثيل الضوئي» ومتى يقوم بـ«التنفس»؟","options":["كلاهما نهارًا فقط","التمثيل الضوئي بوجود الضوء فقط، والتنفس ليلًا ونهارًا","كلاهما ليلًا فقط","النبات لا يتنفس"],"answer":1,"why":"التنفس مستمر 24 ساعة، والتمثيل الضوئي يحتاج ضوءًا."},{"type":"mcq","q":"ما تحوّل الطاقة الذي يحدث أثناء التمثيل الضوئي؟","options":["حركية ← حرارية","كيميائية ← ضوئية","طاقة ضوئية ← طاقة كيميائية مخزّنة في الجلوكوز","كهربائية ← صوتية"],"answer":2,"why":"تُخزَّن طاقة الضوء كطاقة كيميائية في روابط الجلوكوز."},{"type":"tfr","q":"تحدث عملية التمثيل الضوئي داخل البلاستيدات الخضراء في وجود الضوء والكلوروفيل.","answer":true,"reasons":["تحدث في الجذور تحت الأرض","فتحوّل CO₂ والماء إلى جلوكوز وأكسجين","لا تحتاج كلوروفيل"],"reason":1},{"type":"tfr","q":"يتوقف النبات عن التنفس الخلوي خلال النهار لأنه يقوم بالتمثيل الضوئي.","answer":false,"reasons":["النبات لا يتنفس أبدًا","نعم يتوقف نهارًا","التنفس الخلوي مستمر ليلًا ونهارًا لإمداد خلايا النبات بالطاقة"],"reason":2},{"type":"essay","q":"اكتب المعادلة اللفظية والرمزية الموزونة لعملية التمثيل الضوئي مع ذكر الشروط.","model":"ثاني أكسيد الكربون + ماء —(ضوء وكلوروفيل)→ جلوكوز + أكسجين. 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂."},{"type":"essay","q":"قارن بين التبادل الغازي للنبات في النهار المشمس وفي الليل المظلم.","model":"نهارًا: معدل التمثيل الضوئي أكبر من التنفس فيمتص صافي CO₂ ويطلق صافي O₂. ليلًا: يتوقف التمثيل الضوئي ويبقى التنفس فيمتص O₂ ويطلق CO₂."}],"hard":[{"type":"mcq","q":"في الظلام الدامس، ماذا يمتص النبات وماذا يطلق؟","options":["يصنع جلوكوز","يمتص CO₂ ويطلق O₂","لا يمتص شيئًا","يمتص الأكسجين ويطلق ثاني أكسيد الكربون (تنفس فقط)"],"answer":3,"why":"في الظلام يتوقف التمثيل الضوئي ويبقى التنفس."},{"type":"mcq","q":"صيغة جزيء الجلوكوز الناتج عن التمثيل الضوئي هي:","options":["C₆H₁₂O₆","CO₂","H₂O","O₂"],"answer":0,"why":"يتكوّن الجلوكوز من 6 ذرات كربون و12 هيدروجين و6 أكسجين."},{"type":"mcq","q":"أين ينقل النبات الماء من التربة إلى الأوراق للتمثيل الضوئي؟","options":["عبر الثغور","عبر أوعية الخشب","عبر البشرة الشمعية","عبر الهواء"],"answer":1,"why":"أوعية الخشب تنقل الماء والأملاح صعودًا للأوراق."},{"type":"mcq","q":"لماذا يبدو لون معظم أوراق النباتات أخضر؟","options":["بسبب الماء","لأنها تمتص الأخضر فقط","لأن الكلوروفيل يمتص الأحمر والأزرق ويعكس الضوء الأخضر لأعيننا","بسبب CO₂"],"answer":2,"why":"اللون المرئي هو الضوء المنعكس من الصبغة."},{"type":"tfr","q":"معادلة التمثيل الضوئي هي عكس معادلة التنفس الهوائي تقريبًا.","answer":true,"reasons":["التمثيل يبني الجلوكوز و O₂ من CO₂ والماء، والتنفس يهدم الجلوكوز بـ O₂ منتجًا CO₂ والماء","هما متطابقتان في الاتجاه","لا علاقة بينهما"],"reason":0},{"type":"tfr","q":"تساعد زيادة زراعة الأشجار على خفض نسبة ثاني أكسيد الكربون في الجو.","answer":true,"reasons":["تزيد CO₂","لأن النباتات تستهلك CO₂ في التمثيل الضوئي وتطلق الأكسجين","لا تؤثر في الجو"],"reason":1},{"type":"tfr","q":"يدخل الماء اللازم للتمثيل الضوئي إلى النبات عبر ثغور الأوراق من الهواء.","answer":false,"reasons":["لا يحتاج النبات ماءً","نعم عبر الثغور فقط","يُمتص الماء من التربة عبر الشعيرات الجذرية وينتقل بالخشب إلى الأوراق"],"reason":2},{"type":"essay","q":"اشرح دور الكلوروفيل في عملية التمثيل الضوئي.","model":"صبغة خضراء داخل البلاستيدات تمتص الطاقة الضوئية من الشمس وتحوّلها إلى طاقة كيميائية تُستخدم لصنع الجلوكوز من الماء و CO₂."},{"type":"essay","q":"تتبّع كيف يصل كل من الماء وثاني أكسيد الكربون إلى خلايا الورقة.","model":"الماء يُمتص من التربة بالأسموزية عبر الشعيرات الجذرية ويصعد في الخشب؛ و CO₂ ينتشر من الهواء عبر الثغور إلى الفراغات الهوائية ثم الخلايا."},{"type":"essay","q":"لماذا تُعد مبادرة زراعة الأشجار في المدن العُمانية مفيدةً للبيئة والمناخ؟","model":"لأنها تمتص CO₂ وتقلل الاحتباس الحراري، وتطلق الأكسجين، وتوفر الظل وتلطف حرارة الصيف."}]}},
  {"id":"g9-bio-2-u7-3","grade":"g9","subject":"biology","term":2,"unit":7,"no":3,"title":"الأوراق","summary":"شرح متحرك بـ SVG لدرس الأوراق (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-leaves.html","video":"","pdf":"","notes":["الورقة عريضة لامتصاص الضوء ورقيقة لتقصير مسافة انتشار CO₂.","الكيوتيكل يقلل التبخر، والبشرة العليا شفافة تمرّر الضوء للنسيج العمادي الغني بالبلاستيدات.","النسيج الإسفنجي به فراغات هوائية واسعة لتبادل الغازات، والثغور في البشرة السفلى تفتحها وتغلقها الخلايا الحارسة.","العروق تحوي الخشب (ماء وأملاح) واللحاء (نقل السكر)."],"exercises":["رتّب طبقات المقطع العرضي للورقة من الأعلى إلى الأسفل واذكر وظيفة كل طبقة.","فسّر أربعة تكيّفات في الورقة تجعلها مثالية للتمثيل الضوئي.","علّل: لماذا يكون السطح العلوي لمعظم الأوراق أغمق اخضرارًا من السطح السفلي؟"],"levels":{"easy":[{"type":"mcq","q":"ما الطبقة التي تحتوي «أكبر عدد من البلاستيدات الخضراء» في الورقة؟","options":["البشرة العليا","النسيج الوسطي العمادي","الطبقة الشمعية","أوعية الخشب"],"answer":1,"why":"النسيج العمادي هو المصنع الرئيس للتمثيل الضوئي."},{"type":"mcq","q":"ما وظيفة «الطبقة الشمعية (الكيوتيكل)» التي تغطي سطح الورقة؟","options":["نقل السكر","امتصاص CO₂","تقليل فقدان الماء بالتبخر وحماية الورقة","تخزين النشا"],"answer":2,"why":"الكيوتيكل الشمعي غير منفذ للماء فيقلل التبخر."},{"type":"mcq","q":"ما وظيفة «الفراغات الهوائية» الواسعة في النسيج الوسطي الإسفنجي؟","options":["تخزين الدهون","امتصاص الضوء","تثبيت الجذور","تسهيل انتشار غازي CO₂ و O₂ بين الثغور والخلايا"],"answer":3,"why":"الفراغات الهوائية تسرّع تبادل الغازات داخل الورقة."},{"type":"mcq","q":"ما الخلايا التي تتحكم في فتح وإغلاق الثغور؟","options":["الخلايا الحارسة","خلايا البشرة العليا","أوعية الخشب","الكيوتيكل"],"answer":0,"why":"تنتفخ الخلايا الحارسة فيفتح الثغر، وترتخي فينغلق."}],"medium":[{"type":"mcq","q":"لماذا تخلو خلايا «البشرة العليا» من الكلوروفيل وتكون شفافة؟","options":["لأنها لا تحتاج ماءً","لتسمح بنفاذ الضوء بسهولة إلى النسيج العمادي تحتها","لإغلاق الثغور","لمنع مرور الضوء"],"answer":1,"why":"شفافيتها توصل أقصى ضوء للبلاستيدات في العمادي."},{"type":"mcq","q":"لماذا تتركّز معظم الثغور في «البشرة السفلى» للورقة؟","options":["لأن الأعلى مغطى بخشب","لأن CO₂ لا يوجد في الأعلى","لأنها أقل تعرضًا للشمس المباشرة فيقل فقدان الماء بالتبخر","لزيادة التبخر"],"answer":2,"why":"تقلل حرارة الشمس المباشرة على الثغور فيحفظ النبات ماءه."},{"type":"mcq","q":"ما فائدة كون الورقة «رقيقة جدًّا»؟","options":["تقليل مساحة السطح","زيادة وزنها","منع دخول الهواء","تقصير مسافة انتشار CO₂ ونفاذ الضوء لجميع الخلايا الخضراء"],"answer":3,"why":"قصر مسافة الانتشار يسرّع وصول CO₂."},{"type":"tfr","q":"تحتوي خلايا البشرة العليا للورقة على أكبر عدد من البلاستيدات الخضراء.","answer":false,"reasons":["لا توجد بلاستيدات في العمادي","نعم في البشرة العليا","خلايا البشرة العليا شفافة بلا كلوروفيل، وأكبر عدد للبلاستيدات في النسيج العمادي"],"reason":2},{"type":"tfr","q":"وجود طبقة شمعية سميكة على أوراق نباتات عُمان الصحراوية يساعدها على تقليل فقدان الماء.","answer":true,"reasons":["فالكيوتيكل الشمعي غير منفذ للماء ويحمي النبات من الجفاف","يزيد التبخر","يمنع الضوء"],"reason":0},{"type":"essay","q":"رتّب طبقات المقطع العرضي للورقة من الأعلى إلى الأسفل واذكر وظيفة كل طبقة.","model":"١) الكيوتيكل (تقليل التبخر). ٢) البشرة العليا (شفافة تمرر الضوء). ٣) النسيج العمادي (أكبر بلاستيدات للتمثيل الضوئي). ٤) الإسفنجي (فراغات لتبادل الغازات). ٥) البشرة السفلى والثغور (دخول CO₂ وخروج O₂)."},{"type":"essay","q":"فسّر أربعة تكيّفات في الورقة تجعلها مثالية للتمثيل الضوئي.","model":"عريضة لامتصاص الضوء، رقيقة لتقصير مسافة الانتشار، نسيج عمادي غني بالبلاستيدات في الأعلى، وفراغات هوائية وثغور لتبادل الغازات."}],"hard":[{"type":"mcq","q":"ما وظيفة نسيج «الخشب» داخل عروق الورقة؟","options":["توصيل الماء والأملاح المعدنية إلى خلايا الورقة ودعمها","نقل السكر للجذور","إنتاج الكلوروفيل","إغلاق الثغور"],"answer":0,"why":"الخشب ينقل الماء والأملاح ويدعم الورقة."},{"type":"mcq","q":"أي خلايا في البشرة تحتوي على بلاستيدات خضراء؟","options":["جميع خلايا البشرة العليا","الخلايا الحارسة فقط","الكيوتيكل","أوعية الخشب"],"answer":1,"why":"الخلايا الحارسة هي الوحيدة في البشرة التي تحتوي بلاستيدات خضراء."},{"type":"mcq","q":"لماذا يكون السطح العلوي للورقة أغمق اخضرارًا من السطح السفلي؟","options":["لأن العلوي مبلل","لأن السفلي بلا خلايا","لأن النسيج العمادي الغني بالبلاستيدات الخضراء يقع مباشرةً تحت السطح العلوي","لأن السفلي شمعي أسود"],"answer":2,"why":"كثافة البلاستيدات في العمادي تعطي العلوي لونًا أخضر داكنًا."},{"type":"mcq","q":"تفتح الثغور عادةً في «النهار» بهدف:","options":["إيقاف التمثيل الضوئي","منع دخول الضوء","إدخال النشا","السماح بدخول غاز CO₂ اللازم للتمثيل الضوئي"],"answer":3,"why":"بوجود الضوء يحتاج النبات CO₂ فتفتح الثغور."},{"type":"tfr","q":"تُغلق الخلايا الحارسة الثغور ليلًا أو عند نقص الماء الشديد لحفظ ماء النبات.","answer":true,"reasons":["تفتح ليلًا فقط","ففي الليل لا يوجد تمثيل ضوئي فلا حاجة لبقاء الثغور مفتوحة لفقد الماء","لا تغلق أبدًا"],"reason":1},{"type":"tfr","q":"الشكل العريض والمسطّح للورقة يزيد مساحة السطح لامتصاص أكبر كمية من ضوء الشمس.","answer":true,"reasons":["يعيق الانتشار","يقلل امتصاص الضوء","مما يرفع معدل التمثيل الضوئي"],"reason":2},{"type":"tfr","q":"ينقل نسيج اللحاء في عروق الورقة الماء من التربة إلى الورقة.","answer":false,"reasons":["الخشب ينقل الماء من التربة، أما اللحاء فينقل الغذاء المصنوع (السكروز) من الورقة","نعم اللحاء للماء","الخشب للسكر"],"reason":0},{"type":"essay","q":"علّل: لماذا يكون السطح العلوي لمعظم الأوراق أغمق اخضرارًا من السطح السفلي؟","model":"لتركّز خلايا النسيج العمادي الممتلئة بالبلاستيدات الخضراء مباشرة تحت البشرة العليا."},{"type":"essay","q":"قارن بين النسيج الوسطي العمادي والنسيج الوسطي الإسفنجي من حيث الشكل وعدد البلاستيدات والفراغات.","model":"العمادي: خلايا مستطيلة متراصة، بلاستيدات كثيرة جدًّا، فراغات قليلة. الإسفنجي: خلايا غير منتظمة، بلاستيدات أقل، فراغات هوائية واسعة."},{"type":"essay","q":"ما دور الخلايا الحارسة في التوازن بين التمثيل الضوئي وحفظ الماء؟","model":"تفتح الثغور نهارًا لدخول CO₂، وتغلقها ليلًا أو عند الجفاف الشديد لتقليل فقد الماء بالنتح."}]}},
  {"id":"g9-bio-2-u7-4","grade":"g9","subject":"biology","term":2,"unit":7,"no":4,"title":"المواد الناتجة عن عملية التمثيل الضوئي","summary":"شرح متحرك بـ SVG لدرس المواد الناتجة عن عملية التمثيل الضوئي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-products-of-photosynthesis.html","video":"","pdf":"","notes":["يستخدم النبات الجلوكوز في التنفس (طاقة)، ويخزّنه كنشا غير ذائب (خامل أسموزيًا)، وينقله كسكروز ذائب في اللحاء.","يبني السليولوز للجدران الخلوية، ويصنع البروتينات بإضافة النترات، والدهون في البذور.","جزء من الأكسجين يُستخدم لتنفس النبات والفائض ينتشر للهواء."],"exercises":["اذكر خمسة استخدامات للجلوكوز الناتج عن التمثيل الضوئي في النبات.","علّل: يُحوّل النبات الجلوكوز إلى نشا للتخزين، وإلى سكروز للنقل.","كيف يصنع النبات البروتينات رغم أن التمثيل الضوئي ينتج جلوكوزًا (C,H,O) فقط؟"],"levels":{"easy":[{"type":"mcq","q":"ما الصورة التي يُخزّن بها النبات الفائض من الجلوكوز؟","options":["الأكسجين","السليولوز","النشا (غير الذائب في الماء)","النترات"],"answer":2,"why":"يُخزّن كنشا لأنه غير ذائب فلا يخلّ بالأسموزية."},{"type":"mcq","q":"لماذا لا يُخزّن النبات كميات كبيرة من الجلوكوز كما هو داخل الخلايا؟","options":["لأن النشا يذوب في الماء","لأن الجلوكوز سام","لأن الجلوكوز غاز","لأن الجلوكوز ذائب في الماء فيؤثّر على الأسموزية ويسحب الماء للخلايا"],"answer":3,"why":"خمول النشا أسموزيًا يجعله مثاليًا للتخزين."},{"type":"mcq","q":"ما السكر الذي يُنقل فيه الغذاء عبر نسيج «اللحاء» في النبات؟","options":["السكروز","النشا","السليولوز","الدهون"],"answer":0,"why":"يُحوَّل الجلوكوز إلى سكروز لنقله عبر اللحاء."},{"type":"mcq","q":"ما المادة التي يصنعها النبات من الجلوكوز لبناء «الجدران الخلوية»؟","options":["النشا","السليولوز","الدهون","الكلوروفيل"],"answer":1,"why":"السليولوز يبني جدران الخلايا النباتية."}],"medium":[{"type":"mcq","q":"لصنع «الأحماض الأمينية والبروتينات»، يدمج النبات الجلوكوز مع:","options":["السليولوز","غاز الأكسجين فقط","أيونات النترات الممتصة من التربة","النشا فقط"],"answer":2,"why":"توفّر النترات عنصر النيتروجين اللازم للأحماض الأمينية."},{"type":"mcq","q":"أين يُخزّن النبات «الدهون والزيوت» المصنوعة من الجلوكوز بكثرة؟","options":["في الهواء","في الثغور","في الكيوتيكل فقط","في البذور كمخزن عالي الطاقة لنمو الجنين"],"answer":3,"why":"الزيوت تخزّن طاقةً كبيرةً في حيز صغير داخل البذور."},{"type":"mcq","q":"كيف يستفيد النبات من جزء من الأكسجين الناتج عن التمثيل الضوئي؟","options":["يستخدمه في تنفسه الخلوي، ويطلق الفائض للهواء عبر الثغور","يحوّله لنشا","يبني به الجدار الخلوي","يخزنه في الجذور"],"answer":0,"why":"جزء للتنفس والباقي ينتشر عبر الثغور للهواء."},{"type":"tfr","q":"يُخزّن النبات فائض الجلوكوز على هيئة نشا لأنه غير ذائب في الماء ولا يؤثر على الأسموزية.","answer":true,"reasons":["فلو خُزّن جلوكوزًا ذائبًا لسحب كميات كبيرة من الماء إلى الخلايا","لأن النشا ذائب جدًّا","لأن الجلوكوز لا يذوب"],"reason":0},{"type":"tfr","q":"يستطيع النبات تحويل الجلوكوز إلى سليولوز لبناء جدران خلوية جديدة.","answer":true,"reasons":["السليولوز يأتي من التربة","فالسليولوز بوليمر من وحدات الجلوكوز","لا علاقة له بالجلوكوز"],"reason":1},{"type":"essay","q":"اذكر خمسة استخدامات للجلوكوز الناتج عن التمثيل الضوئي في النبات.","model":"١) التنفس الخلوي (طاقة). ٢) التخزين كنشا. ٣) النقل كسكروز في اللحاء. ٤) بناء الجدران الخلوية (سليولوز). ٥) صنع البروتينات (مع النترات) والدهون والزيوت."},{"type":"essay","q":"علّل: يُحوّل النبات الجلوكوز إلى نشا للتخزين، وإلى سكروز للنقل.","model":"النشا غير ذائب وخامل أسموزيًا فيناسب التخزين دون الإخلال بتوازن الماء؛ أما السكروز فذائب وأقل تفاعلًا فيناسب النقل في اللحاء."}],"hard":[{"type":"mcq","q":"ما المادة التي نكشف عنها في الورقة لإثبات حدوث التمثيل الضوئي (بمحلول اليود)؟","options":["الأكسجين","النشا","السليولوز","الماء"],"answer":1,"why":"يتحول اليود إلى أزرق مسود بوجود النشا."},{"type":"mcq","q":"يُستهلك جزء من الجلوكوز مباشرةً داخل خلايا النبات في عملية:","options":["الترشيح","النتح","التنفس الخلوي لإنتاج الطاقة","التكاثف"],"answer":2,"why":"التنفس يحرر الطاقة من الجلوكوز."},{"type":"mcq","q":"لماذا يُنقل السكر في اللحاء كـ«سكروز» وليس كـ«نشا»؟","options":["لأن اللحاء ينقل النشا فقط","لأن النشا غاز","لأن السكروز لا يذوب","لأن السكروز يذوب في الماء فيسهل تدفقه في اللحاء بينما النشا غير ذائب"],"answer":3,"why":"الذوبان شرط أساسي للنقل داخل عصارة اللحاء."},{"type":"mcq","q":"العناصر الكيميائية الداخلة في تركيب الجلوكوز والنشا والسكروز والسليولوز هي:","options":["الكربون والهيدروجين والأكسجين (C, H, O)","النيتروجين والحديد فقط","المغنيسيوم والصوديوم","الكلور والكالسيوم"],"answer":0,"why":"جميع الكربوهيدرات تتكون من C و H و O."},{"type":"tfr","q":"يُنقل النشا غير الذائب مباشرةً عبر أنابيب اللحاء إلى الجذور.","answer":false,"reasons":["اللحاء ينقل الماء فقط","نعم ينتقل كنشا صلب","يُحوَّل إلى سكروز ذائب للنقل في اللحاء ثم يُعاد تحويله لنشا عند التخزين"],"reason":2},{"type":"tfr","q":"يستخدم النبات أيونات النترات مع الجلوكوز لتكوين الأحماض الأمينية والبروتينات.","answer":true,"reasons":["لأن الجلوكوز لا يحتوي نيتروجينًا، والنترات توفر النيتروجين اللازم","البروتين لا يحتاج نترات","يستخدم الأكسجين فقط"],"reason":0},{"type":"tfr","q":"يطلق النبات كل الأكسجين الناتج عن التمثيل الضوئي للهواء ولا يستخدم منه شيئًا.","answer":false,"reasons":["النبات لا يحتاج أكسجين","يستخدم النبات جزءًا من الأكسجين لتنفس خلاياه ويطلق الفائض عبر الثغور","يخزن كل الأكسجين"],"reason":1},{"type":"essay","q":"كيف يصنع النبات البروتينات رغم أن التمثيل الضوئي ينتج جلوكوزًا (C,H,O) فقط؟","model":"يمتص أيونات النترات (NO₃⁻) من التربة ويدمج النيتروجين مع الجلوكوز لتكوين الأحماض الأمينية ثم البروتينات."},{"type":"essay","q":"ما الفائدة من تخزين الدهون والزيوت داخل بذور النباتات؟","model":"الدهون غنية جدًّا بالطاقة في حجم صغير فتمدّ الجنين بالطاقة اللازمة أثناء الإنبات قبل ظهور الأوراق الخضراء."},{"type":"essay","q":"لماذا يُعد اختبار وجود «النشا» في الورقة دليلًا على حدوث التمثيل الضوئي؟","model":"لأن الفائض من الجلوكوز الناتج عن التمثيل الضوئي يُحوَّل ويُخزّن فورًا على شكل نشا داخل الورقة."}]}},
  {"id":"g9-bio-2-u7-5","grade":"g9","subject":"biology","term":2,"unit":7,"no":5,"title":"استقصاء عملية التمثيل الضوئي","summary":"شرح متحرك بـ SVG لدرس استقصاء عملية التمثيل الضوئي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-investigating-photosynthesis.html","video":"","pdf":"","notes":["إزالة النشا (٤٨ ساعة ظلام) تسبق تجارب التمثيل الضوئي.","اختبار النشا: ماء مغلي ← إيثانول بحمام مائي (إطفاء اللهب!) ← تليين بالماء ← يود (أزرق مسود).","العوامل المحددة: شدة الضوء، تركيز CO₂، ودرجة الحرارة (الحرارة العالية تمسّخ الإنزيمات)."],"exercises":["اكتب الخطوات الأربع لاختبار وجود النشا في ورقة نبات مع ذكر سبب كل خطوة.","صف باختصار كيف تثبت تجريبيًا أن الضوء ضروري للتمثيل الضوئي.","ما العوامل المحدّدة الثلاثة لمعدل التمثيل الضوئي؟ وكيف يؤثر ارتفاع الحرارة الزائد؟"],"levels":{"easy":[{"type":"mcq","q":"لماذا نضع النبات في الظلام لمدة ٤٨ ساعة قبل بدء تجارب التمثيل الضوئي؟","options":["لقتل النبات","لزيادة الكلوروفيل","لتجميد الورقة","لإزالة النشا المخزّن سابقًا حتى نتأكد أن أي نشا جديد صُنع أثناء التجربة"],"answer":3,"why":"تستهلك الخلايا النشا القديم بالتنفس خلال الظلام."},{"type":"mcq","q":"لماذا نُطفئ لهب موقد بنزن قبل تسخين الإيثانول (الكحول) في حمام مائي لإزالة الكلوروفيل؟","options":["لأن الإيثانول سائل شديد الاشتعال","لأنه يتجمد باللهب","لأنه يذيب الزجاج","لأنه يحول اليود لأحمر"],"answer":0,"why":"الحمام المائي مع إطفاء اللهب إجراء سلامة أساسي مع الكحول."},{"type":"mcq","q":"ما وظيفة «الإيثانول الساخن» في اختبار النشا بالورقة؟","options":["إضافة النشا للورقة","إذابة وإزالة صبغة الكلوروفيل الخضراء ليظهر لون اليود بوضوح","زيادة اللون الأخضر","إزالة الماء فقط"],"answer":1,"why":"إزالة اللون الأخضر تجعل تحول اليود لأزرق مسود مرئيًا بوضوح."},{"type":"mcq","q":"ما المادة التي تُوضع في الدورق «لامتصاص CO₂» عند إثبات ضرورته للتمثيل الضوئي؟","options":["بيكربونات الصوديوم","محلول اليود","هيدروكسيد الصوديوم أو البوتاسيوم (أو الجير الصودي)","الإيثانول"],"answer":2,"why":"القواعد القوية تمتص CO₂ الحمضي من الهواء."}],"medium":[{"type":"mcq","q":"لماذا نستخدم «ورقة مبرقشة» (أخضر وأبيض) في تجارب التمثيل الضوئي؟","options":["لإنتاج CO₂","لإثبات ضرورة الماء","لقياس درجة الحرارة","لإثبات أن الكلوروفيل ضروري لحدوث التمثيل الضوئي"],"answer":3,"why":"يتكون النشا في الأجزاء الخضراء فقط دون البيضاء."},{"type":"mcq","q":"في تجربة النبات المائي (الإيلوديا)، ما الغاز الموجود داخل الفقاعات المتصاعدة؟","options":["الأكسجين (O₂)","النيتروجين","الهيدروجين","الأمونيا"],"answer":0,"why":"الأكسجين ناتج التمثيل الضوئي ويُشعل شظية متوهجة."},{"type":"mcq","q":"لماذا نضيف «بيكربونات الصوديوم» إلى الماء في تجربة الإيلوديا؟","options":["لامتصاص CO₂","لتوفير كمية وفيرة وثابتة من CO₂ فلا يكون عاملًا محدّدًا","لقتل النبات","لتلوين الماء"],"answer":1,"why":"بيكربونات الصوديوم تطلق CO₂ ذائبًا في الماء."},{"type":"tfr","q":"تُسخّن الورقة في الإيثانول داخل حمام مائي مع إطفاء اللهب لأن الإيثانول قابل للاشتعال.","answer":true,"reasons":["يُسخن الإيثانول مباشرة على اللهب","وهذه أهم قاعدة أمان مخبرية في اختبار النشا","الإيثانول لا يشتعل"],"reason":1},{"type":"tfr","q":"الورقة التي حُرمت من CO₂ في وجود الضوء والكلوروفيل تتحوّل للأزرق المسود مع اليود.","answer":false,"reasons":["تتحول للأخضر","نعم تكون نشا","تبقى بنية مصفرة لعدم تكوّن النشا بغياب CO₂"],"reason":2},{"type":"essay","q":"اكتب الخطوات الأربع لاختبار وجود النشا في ورقة نبات مع ذكر سبب كل خطوة.","model":"١) ماء مغلي لقتل الخلايا وتكسير الأغشية. ٢) إيثانول ساخن في حمام مائي (بلا لهب) لإزالة الكلوروفيل. ٣) شطف بماء دافئ لتليين الورقة. ٤) إضافة اليود (أزرق مسود = نشا)."},{"type":"essay","q":"صف باختصار كيف تثبت تجريبيًا أن الضوء ضروري للتمثيل الضوئي.","model":"نزيل النشا من النبات (٤٨ ساعة ظلام)، نغطي جزءًا من ورقة بشريط معتم ونعرضها للشمس ساعات، ثم نجري اختبار اليود فنجد النشا في الجزء المكشوف فقط."}],"hard":[{"type":"mcq","q":"ماذا يحدث لمعدل التمثيل الضوئي عند ارتفاع الحرارة كثيرًا «فوق» الدرجة المثلى (مثلًا 50°C)؟","options":["يبقى ثابتًا","يزداد بلا حدود","ينخفض سريعًا ويتوقف لأن إنزيمات التمثيل الضوئي تتمسّخ (تتلف)","يتحول لتجمد"],"answer":2,"why":"التمثيل الضوئي تفاعل إنزيمي يتلف بالحرارة المفرطة."},{"type":"mcq","q":"في منحنى معدل التمثيل الضوئي مقابل شدة الضوء، عند النقطة التي «يثبت» فيها المنحنى أفقيًا رغم زيادة الضوء، فإن:","options":["الكلوروفيل اختفى","الضوء ما زال العامل المحدد","النبات مات","شدة الضوء لم تعد العامل المحدّد، بل عامل آخر كـ CO₂ أو الحرارة"],"answer":3,"why":"ثبات المنحنى يعني أن عاملًا آخر يقيّد السرعة."},{"type":"mcq","q":"ما التغيّر اللوني لمحلول اليود عند وجود النشا في الورقة؟","options":["من البني المصفر إلى الأزرق المسود","من الأزرق إلى الوردي","من الأبيض إلى الأحمر","لا يتغير"],"answer":0,"why":"الأزرق المسود هو النتيجة الإيجابية للنشا."},{"type":"mcq","q":"ما فائدة غلي الورقة في الماء المغلي كأول خطوة في اختبار النشا؟","options":["إزالة الكلوروفيل","قتل الخلايا وإيقاف التفاعلات وتكسير الأغشية ليدخل الكحول واليود","تجميد النشا","إضافة CO₂"],"answer":1,"why":"الغلي يوقف النشاط الخلوي ويجعل الورقة منفذةً للمواد."},{"type":"tfr","q":"العامل المحدّد هو العامل الأقل توفرًا الذي يحدّ من سرعة التمثيل الضوئي.","answer":true,"reasons":["فإذا زدت هذا العامل ارتفع معدل التمثيل الضوئي فورًا","هو العامل الأكثر توفرًا","هو الماء فقط"],"reason":0},{"type":"tfr","q":"تزداد سرعة التمثيل الضوئي باستمرار كلما ارتفعت درجة الحرارة حتى 80°C.","answer":false,"reasons":["نعم تزداد دائمًا","تزداد حتى الدرجة المثلى ثم تهبط بشدة عند تمسّخ الإنزيمات","الحرارة لا تؤثر"],"reason":1},{"type":"tfr","q":"إزالة النشا بوضع النبات في الظلام ٤٨ ساعة تضمن أن أي نشا نكتشفه صُنع خلال التجربة.","answer":true,"reasons":["لا فائدة منها","تزيد النشا في الورقة","لأن النبات يستهلك النشا المخزّن سابقًا بالتنفس خلال الظلام"],"reason":2},{"type":"essay","q":"ما العوامل المحدّدة الثلاثة لمعدل التمثيل الضوئي؟ وكيف يؤثر ارتفاع الحرارة الزائد؟","model":"شدة الضوء، تركيز CO₂، ودرجة الحرارة. ارتفاع الحرارة فوق المثلى يمسّخ الإنزيمات فيتوقف التمثيل الضوئي."},{"type":"essay","q":"في تجربة الإيلوديا، اذكر متغيرين يجب «تثبيتهما» عند استقصاء أثر شدة الضوء.","model":"درجة حرارة الماء (باستخدام درع حراري/حمام مائي) وتركيز CO₂ (بإضافة نفس كمية بيكربونات الصوديوم)."},{"type":"essay","q":"كيف يستفيد المزارعون في البيوت المحمية بعُمان من معرفة العوامل المحدّدة؟","model":"بضبط الإضاءة والتهوية/CO₂ وتبريد البيت المحمي صيفًا للبقاء قرب الدرجة المثلى للإنزيمات لرفع الإنتاج."}]}},
  {"id":"g9-bio-2-u8-1","grade":"g9","subject":"biology","term":2,"unit":8,"no":1,"title":"الهضم","summary":"شرح متحرك بـ SVG لدرس الهضم (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-digestion.html","video":"","pdf":"","notes":["الهضم يحوّل الجزيئات الكبيرة غير الذائبة إلى صغيرة ذائبة قابلة للامتصاص.","الهضم الميكانيكي (الأسنان، المعدة، استحلاب الصفراء) يزيد مساحة السطح للإنزيمات.","الهضم الكيميائي: الأميليز (النشا→سكر)، البروتييز (البروتين→أحماض أمينية)، الليبيز (الدهون→أحماض دهنية وجليسرول).","العصارة الصفراوية (من الكبد) بلا إنزيمات، وتستحلب الدهون وتُعادل حمض HCl."],"exercises":["قارن بين الهضم الميكانيكي والهضم الكيميائي مع ذكر مثالين لكل منهما.","اذكر ناتج الهضم النهائي لكل من: النشا، البروتينات، والدهون، مع اسم الإنزيم المسؤول.","اذكر وظيفتين للعصارة الصفراوية ووظيفتين لحمض الهيدروكلوريك في المعدة."],"levels":{"easy":[{"type":"mcq","q":"ما الغرض الأساسي من «الهضم الميكانيكي» للطعام؟","options":["تفتيت الطعام لقطع أصغر لزيادة مساحة السطح لعمل الإنزيمات","تغيير التركيب الكيميائي للبروتين","امتصاص الطعام في الفم","قتل الإنزيمات"],"answer":0,"why":"زيادة مساحة السطح تسرّع الهضم الكيميائي كثيرًا."},{"type":"mcq","q":"ما الإنزيم الذي يهضم «الدهون» إلى أحماض دهنية وجليسرول؟","options":["الأميليز","الليبيز (Lipase)","البيبسين","المالتيز"],"answer":1,"why":"الليبيز متخصص في هضم الدهون."},{"type":"mcq","q":"أين تُصنع «العصارة الصفراوية» وأين تُخزَّن؟","options":["تُصنع في البنكرياس","تُصنع في المعدة وتُخزّن في الفم","تُصنع في الكبد وتُخزّن في الحوصلة الصفراوية (المرارة)","تُصنع في الكلية"],"answer":2,"why":"الكبد ينتج الصفراء وتخزنها المرارة وتصبها في الإثني عشر."},{"type":"mcq","q":"ما الوظيفتان الرئيستان لحمض الهيدروكلوريك (HCl) في المعدة؟","options":["توفير وسط قلوي","هضم النشا","استحلاب الدهون","قتل البكتيريا وتوفير وسط حمضي مثالي (pH ≈ 2) لإنزيم البيبسين"],"answer":3,"why":"HCl يحمي الجسم من الميكروبات ويهيئ الوسط للبيبسين."}],"medium":[{"type":"mcq","q":"ما ناتج هضم «البروتينات» بواسطة إنزيمات البروتييز (البيبسين والتربسين)؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","النشا"],"answer":0,"why":"البروتينات تتفكك إلى وحداتها البنائية وهي الأحماض الأمينية."},{"type":"mcq","q":"ما وظيفة «العصارة الصفراوية» في هضم الدهون؟","options":["هضم الدهون كيميائيًا بإنزيماتها","استحلاب الدهون (تفتيتها لقطيرات دقيقة) ومعادلة حمض المعدة","تحويل النشا لبروتين","قتل الإنزيمات"],"answer":1,"why":"الصفراء لا تحتوي إنزيمات بل تستحلب الدهون ميكانيكيًا وتُعادل الحمض."},{"type":"mcq","q":"أي مادة مما يلي لا تحتاج إلى هضم ويمكن امتصاصها مباشرةً؟","options":["البروتين","النشا","الجلوكوز والماء والأملاح المعدنية","الدهون"],"answer":2,"why":"الجلوكوز والماء والأملاح جزيئات صغيرة وذائبة أصلًا."},{"type":"tfr","q":"تحتوي العصارة الصفراوية على إنزيم الليبيز لهضم الدهون كيميائيًا.","answer":false,"reasons":["تحتوي أميليز","نعم تحتوي ليبيز","العصارة الصفراوية لا تحتوي أي إنزيمات؛ هي تستحلب الدهون ميكانيكيًا وتُعادل الحمض فقط، والليبيز يفرزه البنكرياس"],"reason":2},{"type":"tfr","q":"مضغ الطعام جيدًا بالأسنان يسرّع الهضم الكيميائي لأنه يزيد مساحة السطح المعرضة للإنزيمات.","answer":true,"reasons":["فتصل الإنزيمات لعدد أكبر من الجزيئات في وقت أقصر","المضغ يبطئ الهضم","لا علاقة للمضغ بالإنزيمات"],"reason":0},{"type":"essay","q":"قارن بين الهضم الميكانيكي والهضم الكيميائي مع ذكر مثالين لكل منهما.","model":"الميكانيكي: تفتيت فيزيائي دون تغيير كيميائي لزيادة مساحة السطح (المضغ، استحلاب الصفراء). الكيميائي: تكسير الروابط بالإنزيمات لتكوين جزيئات صغيرة ذائبة (الأميليز، البيبسين، الليبيز)."},{"type":"essay","q":"اذكر ناتج الهضم النهائي لكل من: النشا، البروتينات، والدهون، مع اسم الإنزيم المسؤول.","model":"النشا ← جلوكوز (أميليز ومالتيز). البروتينات ← أحماض أمينية (بروتييز). الدهون ← أحماض دهنية وجليسرول (ليبيز)."}],"hard":[{"type":"mcq","q":"ما أصلب طبقة خارجية تحمي السن؟","options":["اللثة","اللب","العاج","المينا"],"answer":3,"why":"المينا هي الطبقة الخارجية الصلبة الواقية للسن."},{"type":"mcq","q":"أين يبدأ الهضم الكيميائي لـ«النشا» في الجهاز الهضمي؟","options":["في الفم (بواسطة أميليز اللعاب)","في المعدة","في المريء","في الأمعاء الغليظة"],"answer":0,"why":"يفرز اللعاب إنزيم الأميليز ليبدأ هضم النشا في الفم."},{"type":"mcq","q":"ما وظيفة «الأنياب» و«الأضراس» على الترتيب؟","options":["الطحن ثم القطع","تمزيق الطعام، وطحنه وسحقه","البلع فقط","إفراز اللعاب"],"answer":1,"why":"القواطع للقطع، الأنياب للتمزيق، والأضراس للطحن."},{"type":"mcq","q":"ما الرقم الهيدروجيني المثالي تقريبًا لإنزيم البيبسين في المعدة؟","options":["pH ≈ 12","pH ≈ 8 (قلوي)","pH ≈ 2 (حمضي قوي)","pH = 7"],"answer":2,"why":"البيبسين يعمل بأعلى كفاءة في الوسط الحمضي للمعدة."},{"type":"tfr","q":"تسوس الأسنان يحدث بسبب الأحماض التي تنتجها بكتيريا الفم عند تغذيتها على بقايا السكريات.","answer":true,"reasons":["يحدث بسبب الماء","فتذيب الأحماض طبقة المينا، لذا ننظف أسناننا بمعجون قلوي ونقلل السكريات","يحدث بسبب الأميليز"],"reason":1},{"type":"tfr","q":"يبدأ هضم البروتين كيميائيًا في الفم بواسطة اللعاب.","answer":false,"reasons":["في الأمعاء الغليظة","نعم في الفم","يبدأ هضم البروتين في المعدة بواسطة البيبسين، أما الفم فيبدأ فيه هضم النشا"],"reason":2},{"type":"tfr","q":"تعمل إنزيمات الأمعاء الدقيقة (كالتربسين والليبيز) في وسط قلوي خفيف بفضل العصارة الصفراوية.","answer":true,"reasons":["التي تعادل حمض المعدة القادم مع الطعام","تعمل في وسط حمضي قوي","لا تحتاج لضبط pH"],"reason":0},{"type":"essay","q":"اذكر وظيفتين للعصارة الصفراوية ووظيفتين لحمض الهيدروكلوريك في المعدة.","model":"الصفراء: استحلاب الدهون ومعادلة حمض المعدة. HCl: قتل البكتيريا وتوفير وسط حمضي مثالي للبيبسين."},{"type":"essay","q":"كيف يحدث تسوس الأسنان وكيف نقي أسناننا منه؟","model":"تتغذى بكتيريا الفم على السكريات وتنتج أحماضًا تذيب المينا؛ والوقاية بتقليل السكريات وتنظيف الأسنان مرتين يوميًا بمعجون يحتوي فلورايد ومادة قلوية."},{"type":"essay","q":"اشرح ماذا يحدث لإنزيم أميليز اللعاب عند وصوله إلى المعدة الحمضية.","model":"يتوقف نشاطه ويتمسّخ بسبب الوسط الحمضي القوي (pH ≈ 2) للمعدة، ثم يُستكمل هضم النشا في الأمعاء الدقيقة بأميليز البنكرياس."}]}},
  {"id":"g9-bio-2-u8-2","grade":"g9","subject":"biology","term":2,"unit":8,"no":2,"title":"القناة الهضمية","summary":"شرح متحرك بـ SVG لدرس القناة الهضمية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-alimentary-canal.html","video":"","pdf":"","notes":["القناة الهضمية: الفم ← المريء ← المعدة ← الأمعاء الدقيقة ← الأمعاء الغليظة ← الشرج.","الحركة الدودية تدفع الطعام على طول القناة الهضمية.","الخملات المعوية مكيّفة للامتصاص: مساحة هائلة، جدار رقيق، شعيرات دموية، ووعاء لبني.","الأمعاء الغليظة تمتص الماء المتبقي قبل التبرّز."],"exercises":["اذكر أربعة تكيّفات في الخملات المعوية تجعل الأمعاء الدقيقة مثالية لامتصاص الغذاء.","رتّب أعضاء القناة الهضمية من بداية دخول الطعام حتى خروج الفضلات، واذكر الغدتين الملحقتين الرئيستين.","ما الفرق بين «الامتصاص» و«التمثيل الغذائي» و«التبرّز»؟"],"levels":{"easy":[{"type":"mcq","q":"ما وظيفة «الحركة الدودية» في المريء والأمعاء؟","options":["امتصاص الجلوكوز","دفع الطعام على طول القناة الهضمية بانقباض وانبساط العضلات","إفراز الصفراء","تقطيع الطعام بالأسنان"],"answer":1,"why":"الحركة الدودية تحرّك الطعام باستمرار عبر القناة الهضمية."},{"type":"mcq","q":"أين يحدث الامتصاص الرئيس للغذاء المهضوم في القناة الهضمية؟","options":["المعدة","المريء","الأمعاء الدقيقة (اللفائفي) عبر الخملات","المستقيم"],"answer":2,"why":"الأمعاء الدقيقة مبطّنة بملايين الخملات المكيّفة للامتصاص."},{"type":"mcq","q":"ما وظيفة «الوعاء اللبني (اللمفاوي)» داخل الخملة المعوية؟","options":["هضم النشا","امتصاص الجلوكوز فقط","إفراز HCl","امتصاص ونقل الأحماض الدهنية والجليسرول"],"answer":3,"why":"الشعيرات الدموية للجلوكوز والأحماض الأمينية، والوعاء اللبني للدهون."},{"type":"mcq","q":"ما الوظيفة الرئيسة لـ«الأمعاء الغليظة (القولون)»؟","options":["امتصاص ما تبقى من الماء وتكوين الفضلات الصلبة","هضم البروتين بالبيبسين","إفراز الصفراء","امتصاص كل الجلوكوز"],"answer":0,"why":"تستعيد الأمعاء الغليظة الماء المتبقي قبل التبرّز."}],"medium":[{"type":"mcq","q":"تُسمّى عملية إخراج الفضلات غير المهضومة عبر فتحة الشرج بـ:","options":["الإخراج الخلوي (Excretion)","التبرّز (Egestion)","الامتصاص","التمثيل الغذائي"],"answer":1,"why":"التبرّز خاص بالفضلات غير المهضومة التي لم تدخل الخلايا."},{"type":"mcq","q":"ما الغدة التي تفرز الأميليز والتربسين والليبيز معًا في الإثني عشر؟","options":["المرارة","الغدد اللعابية","البنكرياس","المستقيم"],"answer":2,"why":"البنكرياس يفرز العصارة البنكرياسية الغنية بالإنزيمات الثلاثة."},{"type":"mcq","q":"لماذا يكون جدار الخملة المعوية بسمك «خلية واحدة» فقط؟","options":["لهضم العظام","لمنع امتصاص الماء","لزيادة الوزن","لتقصير مسافة الانتشار وتسريع امتصاص الغذاء إلى الدم"],"answer":3,"why":"رقة الجدار تسرّع الانتشار والنقل النشط."},{"type":"tfr","q":"يُعد الكبد والبنكرياس من الغدد الملحقة بالقناة الهضمية ولا يمر الطعام بداخلهما.","answer":true,"reasons":["بل يصبان عصاراتهما (الصفراء والبنكرياسية) في الإثني عشر عبر قنوات","يمر الطعام داخل الكبد","يمر الطعام داخل البنكرياس"],"reason":0},{"type":"tfr","q":"وجود الخملات والخميلات الدقيقة في الأمعاء الدقيقة يزيد مساحة سطح الامتصاص بشكل هائل.","answer":true,"reasons":["يقلل مساحة السطح","مع جدار رقيق بسمك خلية واحدة وشبكة شعيرات دموية كثيفة","يمنع الامتصاص"],"reason":1},{"type":"essay","q":"اذكر أربعة تكيّفات في الخملات المعوية تجعل الأمعاء الدقيقة مثالية لامتصاص الغذاء.","model":"١) مساحة سطح هائلة (ملايين الخملات والخميلات). ٢) جدار رقيق بسمك خلية واحدة. ٣) شبكة شعيرات دموية كثيفة للجلوكوز والأحماض الأمينية. ٤) وعاء لبني للدهون."},{"type":"essay","q":"رتّب أعضاء القناة الهضمية من بداية دخول الطعام حتى خروج الفضلات، واذكر الغدتين الملحقتين الرئيستين.","model":"الفم ← المريء ← المعدة ← الأمعاء الدقيقة (إثني عشر + لفائفي) ← الأمعاء الغليظة (قولون + مستقيم) ← الشرج. والغدد الملحقة: الغدد اللعابية، الكبد، والبنكرياس."}],"hard":[{"type":"mcq","q":"ما الوعاء الدموي الذي ينقل الغذاء الممتص من الأمعاء الدقيقة إلى الكبد مباشرةً؟","options":["الوريد البابي الكبدي","الشريان الأورطي","الوريد الرئوي","الشريان الكلوي"],"answer":0,"why":"الوريد البابي الكبدي يمرّر الغذاء على الكبد أولًا لتنظيمه."},{"type":"mcq","q":"كيف يُعالج خطر الجفاف الناتج عن الإسهال الشديد (مثل الكوليرا)؟","options":["بمنع شرب الماء","بإعطاء محلول الإرواء الفموي (ماء + أملاح + قليل سكر) لتعويض السوائل والأيونات","بتناول الدهون فقط","بالتوقف عن التنفس"],"answer":1,"why":"محلول الإرواء يعوض الماء والأملاح المفقودة بسرعة."},{"type":"mcq","q":"تُسمّى عملية استفادة خلايا الجسم من الغذاء الممتص في النمو والطاقة بـ:","options":["التبرّز","الابتلاع","التمثيل الغذائي (Assimilation)","الاستحلاب"],"answer":2,"why":"التمثيل الغذائي هو دمج الغذاء في الخلايا أو حرقه للطاقة."},{"type":"mcq","q":"أين يمتص الجسم «معظم» الماء (نحو 80%)؟","options":["في الكبد","في المريء","في الفم","في الأمعاء الدقيقة (ثم يمتص الباقي في الأمعاء الغليظة)"],"answer":3,"why":"الأمعاء الدقيقة تمتص معظم الماء بالإضافة للغذاء، وتكمل الغليظة الباقي."},{"type":"tfr","q":"تُمتص الأحماض الدهنية والجليسرول أساسًا عبر الوعاء اللبني داخل الخملة.","answer":true,"reasons":["لا تمتص الدهون","تمتص في المريء","بينما يُمتص الجلوكوز والأحماض الأمينية في الشعيرات الدموية"],"reason":2},{"type":"tfr","q":"عملية التبرّز (خروج البراز) هي نفسها عملية الإخراج (كالبول وثاني أكسيد الكربون).","answer":false,"reasons":["التبرّز إخراج بقايا طعام لم تُهضم ولم تدخل الخلايا، أما الإخراج فتخلص من فضلات التفاعلات الأيضية","كلاهما نفس الشيء تمامًا","التبرز يتم عبر الكلية"],"reason":0},{"type":"tfr","q":"تحدث الحركة الدودية بفضل انقباض وانبساط العضلات الملساء في جدار القناة الهضمية.","answer":true,"reasons":["حركة إرادية فقط","وهي حركة لا إرادية تدفع الطعام على طول المريء والأمعاء","تحدث في الأسنان فقط"],"reason":1},{"type":"essay","q":"ما الفرق بين «الامتصاص» و«التمثيل الغذائي» و«التبرّز»؟","model":"الامتصاص: عبور الغذاء المهضوم للدم عبر الخملات. التمثيل: استفادة الخلايا من الغذاء في الطاقة والبناء. التبرّز: إخراج الفضلات غير المهضومة عبر الشرج."},{"type":"essay","q":"اشرح كيف تسبب بكتيريا الكوليرا إسهالًا حادًا وكيف ينقذ محلول الإرواء الفموي المريض.","model":"تفرز سمًا يسبب خروج أيونات الكلوريد للّفائفي فيتبعه الماء بالأسموزية مسببًا إسهالًا وجفافًا؛ ومحلول الإرواء يعوّض الماء والأملاح فورًا."},{"type":"essay","q":"ما دور الكبد بعد وصول الدم المحمّل بالغذاء إليه عبر الوريد البابي الكبدي؟","model":"تنظيم سكر الدم (تخزين الفائض كجلايكوجين)، وتحطيم السموم، ومعالجة الأحماض الأمينية الزائدة."}]}},
  {"id":"g9-bio-2-u9-1","grade":"g9","subject":"biology","term":2,"unit":9,"no":1,"title":"جهاز النقل في النبات","summary":"شرح متحرك بـ SVG لدرس جهاز النقل في النبات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-plant-transport-system.html","video":"","pdf":"","notes":["الخشب (ميت مجوّف + لجنين): ينقل الماء والأملاح للأعلى فقط ويدعم النبات.","اللحاء (حي: أنابيب غربالية + خلايا مرافقة): ينقل السكروز والأحماض الأمينية في الاتجاهين.","موضع الخشب: في الجذر بالمركز (X)، وفي الساق للداخل، وفي الورقة للأعلى."],"exercises":["قارن في جدول بين نسيج الخشب ونسيج اللحاء من حيث: طبيعة الخلايا، المواد المنقولة، واتجاه النقل.","اذكر ثلاثة تكيّفات في تركيب أوعية الخشب تلائم وظيفتها.","صف موضع الخشب واللحاء في كل من: الجذر، الساق، والورقة."],"levels":{"easy":[{"type":"mcq","q":"ما المواد التي ينقلها نسيج «الخشب» وفي أي اتجاه؟","options":["البروتين للأسفل فقط","السكر في اتجاهين","الماء والأملاح المعدنية في اتجاه واحد للأعلى فقط","الأكسجين فقط"],"answer":2,"why":"الخشب ينقل الماء والأملاح من الجذور للأوراق صعودًا."},{"type":"mcq","q":"ما وظيفة مادة «اللجنين» الموجودة في جدران أوعية الخشب؟","options":["نقل السكروز","إنتاج الجلوكوز","امتصاص الضوء","تقوية الأوعية ومنع انطباقها وتقديم الدعامة للنبات"],"answer":3,"why":"اللجنين يجعل جدران الخشب صلبةً ومقاومةً للشد."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في المقطع العرضي لـ«الجذر»؟","options":["الخشب في المركز على شكل X واللحاء بين أذرعه","اللحاء في المركز والخشب على الحافة","الخشب في الأعلى فقط","لا يوجد خشب في الجذر"],"answer":0,"why":"الترتيب المركزي في الجذر يقاوم الشد والاقتلاع."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في كل حزمة وعائية في «الساق»؟","options":["اللحاء نحو الداخل والخشب للخارج","الخشب نحو الداخل واللحاء نحو الخارج (في حلقة)","كلاهما في المركز على شكل X","بشكل عشوائي"],"answer":1,"why":"الخشب للداخل واللحاء للخارج في حلقة الساق."}],"medium":[{"type":"mcq","q":"أي عبارة تصف «أوعية الخشب» بدقة؟","options":["تحتوي كلوروفيل","خلايا حية بها نواة كبيرة","خلايا ميتة مجوّفة بلا جدر عرضية ولا سيتوبلازم لتسهيل تدفق الماء","تنقل السكروز"],"answer":2,"why":"تجوّفها وفقدان الجدر العرضية يقلل مقاومة مرور الماء."},{"type":"mcq","q":"ما المواد التي ينقلها نسيج «اللحاء»؟","options":["غاز CO₂","الماء والأملاح للأعلى فقط","النشا الصلب","السكروز والأحماض الأمينية في الاتجاهين (للأعلى وللأسفل)"],"answer":3,"why":"اللحاء ينقل الغذاء المصنوع إلى جميع أجزاء النبات."},{"type":"mcq","q":"في تجربة وضع ساق كرفس في ماء ملوّن بصبغة حمراء، أي نسيج يتلوّن بالأحمر؟","options":["أوعية الخشب فقط","اللحاء فقط","البشرة الشمعية","النسيج العمادي فقط"],"answer":0,"why":"يصعد الماء الملون عبر أوعية الخشب."},{"type":"tfr","q":"أوعية الخشب خلايا ميتة مجوّفة خالية من الجدر العرضية ومقوّاة بمادة اللجنين.","answer":true,"reasons":["خلايا حية بها نواة","لتشكل أنابيب متصلة قليلة المقاومة لصعود الماء وتدعم النبات","تنقل السكروز"],"reason":1},{"type":"tfr","q":"ينقل نسيج اللحاء الغذاء الجاهز في اتجاه واحد للأسفل فقط.","answer":false,"reasons":["للأعلى فقط","نعم للأسفل فقط","ينقله في «الاتجاهين» (للأعلى نحو البراعم والثمار وللأسفل نحو الجذور)"],"reason":2},{"type":"essay","q":"قارن في جدول بين نسيج الخشب ونسيج اللحاء من حيث: طبيعة الخلايا، المواد المنقولة، واتجاه النقل.","model":"الخشب: خلايا ميتة مجوفة بها لجنين، ينقل الماء والأملاح، للأعلى فقط. اللحاء: خلايا حية (أنابيب غربالية ومرافقة)، ينقل السكروز والأحماض الأمينية، في اتجاهين."},{"type":"essay","q":"اذكر ثلاثة تكيّفات في تركيب أوعية الخشب تلائم وظيفتها.","model":"١) خالية من السيتوبلازم والجدر العرضية لتسهيل مرور الماء. ٢) جدران مغلظة باللجنين لمنع الانطباق ودعم النبات. ٣) ضيقة لرفع الماء بالتماسك والتلاصق."}],"hard":[{"type":"mcq","q":"ما وظيفة «الخلايا المرافقة» في نسيج اللحاء؟","options":["تقوية الخشب باللجنين","تزويد الأنابيب الغربالية بالطاقة اللازمة لنقل الغذاء","إغلاق الثغور","امتصاص الماء من التربة"],"answer":1,"why":"الأنابيب الغربالية حية وتستمد طاقتها من الخلايا المرافقة."},{"type":"mcq","q":"في المقطع العرضي لـ«الورقة»، أين يقع الخشب واللحاء في العرق الوسطي؟","options":["لا يوجد لحاء في الورقة","اللحاء في الأعلى والخشب في الأسفل","الخشب في الأعلى واللحاء في الأسفل","كلاهما على السطح الخارجي"],"answer":2,"why":"في الورقة يكون الخشب علويًا واللحاء سفليًا."},{"type":"mcq","q":"لماذا تترتّب الحزم الوعائية في الساق في «حلقة قرب الحافة الخارجية»؟","options":["لأسباب جمالية فقط","لتقليل نقل الماء","لمنع النمو","لتعطي الساق متانةً تقاوم الانحناء بفعل الرياح"],"answer":3,"why":"توزيع الخشب المقوى باللجنين في محيط الساق يقاوم الانحناء."},{"type":"mcq","q":"أي وظيفتين يقوم بهما نسيج الخشب في النبات؟","options":["نقل الماء والأملاح المعدنية، والدعامة الميكانيكية","نقل السكر والتمثيل الضوئي","تخزين النشا وإنتاج الأزهار","امتصاص CO₂"],"answer":0,"why":"اللجنين والأنابيب الصلبة يمنحان النبات الدعامة بجانب النقل."},{"type":"tfr","q":"في الجذر يقع الخشب في المركز على شكل X مما يساعد النبات على مقاومة قوى الشدّ.","answer":true,"reasons":["ويقع اللحاء في الفراغات بين أذرع الـ X","يقع على الحافة الخارجية","لا يوجد خشب في الجذر"],"reason":0},{"type":"tfr","q":"إزالة حلقة كاملة من اللحاء حول ساق شجرة (التحليق) يمنع وصول السكر إلى الجذور فتذبل وتموت لاحقًا.","answer":true,"reasons":["لأن اللحاء ينقل الماء","لأن اللحاء يقع نحو الخارج في الساق وهو المسؤول عن نقل الغذاء للجذور","لا يؤثر على الجذور"],"reason":1},{"type":"tfr","q":"الخشب واللحاء متطابقان تمامًا في التركيب والوظيفة.","answer":false,"reasons":["كلاهما ميت","نعم متطابقان","الخشب ميت مجوّف مقوّى باللجنين ينقل الماء والأملاح ↑، واللحاء حي بأنابيب غربالية ينقل الغذاء ↑↓"],"reason":2},{"type":"essay","q":"صف موضع الخشب واللحاء في كل من: الجذر، الساق، والورقة.","model":"الجذر: الخشب في المركز (شكل X) واللحاء بين أذرعه. الساق: حزم في حلقة، الخشب للداخل واللحاء للخارج. الورقة: الخشب أعلى واللحاء أسفل."},{"type":"essay","q":"فسّر كيف تثبت تجربة ساق الكرفس والصبغة الحمراء أن الماء ينتقل في الخشب.","model":"بعد وضع الساق في ماء ملون بالأحمر وقطعه عرضيًا، تظهر البقع الحمراء في مواضع أوعية الخشب فقط دون بقية الأنسجة."},{"type":"essay","q":"لماذا قد تموت شجرة إذا قرضت الحيوانات اللحاء المحيط بساقها بالكامل؟","model":"لأن اللحاء يقع للخارج فإزالته تقطع إمداد الجذور بالسكروز، فتموت خلايا الجذور ويتوقف امتصاص الماء فتموت الشجرة."}]}},
  {"id":"g9-bio-2-u9-2","grade":"g9","subject":"biology","term":2,"unit":9,"no":2,"title":"امتصاص الماء ونقله","summary":"شرح متحرك بـ SVG لدرس امتصاص الماء ونقله (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-water-uptake-and-transport.html","video":"","pdf":"","notes":["الشعيرات الجذرية تزيد مساحة السطح وتمتص الماء بالأسموزية والأملاح بالنقل النشط.","مسار الماء: التربة ← شعيرة جذرية ← قشرة ← خشب ← ورقة ← ثغور.","يصعد الماء في الخشب بفضل قوة سحب النتح وتماسك جزيئات الماء."],"exercises":["قارن بين طريقة امتصاص الماء وطريقة امتصاص الأملاح المعدنية في الشعيرات الجذرية.","تتبّع مسار جزيء ماء من التربة حتى خروجه كبخار ماء من الورقة.","اذكر ثلاثة تكيّفات للخلية الشعيرية الجذرية تساعدها في وظيفتها."],"levels":{"easy":[{"type":"mcq","q":"بأي عملية فيزيائية يدخل «الماء» من التربة إلى الشعيرات الجذرية؟","options":["الترشيح","النقل النشط","التبخر","الأسموزية"],"answer":3,"why":"ينتقل الماء من جهد الماء المرتفع في التربة إلى المنخفض في الشعيرة الجذرية بالأسموزية."},{"type":"mcq","q":"بأي عملية تمتص الشعيرات الجذرية «الأملاح المعدنية» عندما يكون تركيزها في التربة أقل من الجذر؟","options":["النقل النشط (باستخدام طاقة التنفس)","الأسموزية","الانتشار البسيط فقط","النتح"],"answer":0,"why":"النقل عكس منحدر التركيز يحتاج طاقة وهو النقل النشط."},{"type":"mcq","q":"ما الترتيب الصحيح لمسار الماء من التربة إلى الورقة؟","options":["خشب ← شعيرة جذرية ← قشرة ← ورقة","شعيرة جذرية ← قشرة الجذر ← أوعية الخشب ← خلايا الورقة","ثغور ← خشب ← جذر","لحاء ← قشرة ← شعيرة"],"answer":1,"why":"يعبر الماء القشرة من الشعيرة ليصل إلى الخشب في المركز."},{"type":"mcq","q":"ما التكيّف الأساسي للشعيرات الجذرية الذي يسرّع امتصاص الماء؟","options":["احتواؤها على بلاستيدات خضراء","تغطيتها بطبقة شمعية سميكة","امتدادها الطويل الدقيق الذي يوفر مساحة سطح كبيرة جدًّا","سمك جدارها الكبير"],"answer":2,"why":"الامتداد الطويل يزيد مساحة التلامس مع ماء التربة."}],"medium":[{"type":"mcq","q":"ما القوة الرئيسة التي تسحب عمود الماء للأعلى داخل أوعية الخشب في الأشجار العالية؟","options":["الجاذبية للأسفل","ضخ القلب","انقباض اللحاء","قوة سحب النتح الناتجة عن تبخر الماء من الأوراق مع تماسك جزيئات الماء"],"answer":3,"why":"تبخر الماء في الأوراق يسحب عمود الماء المتماسك صعودًا."},{"type":"mcq","q":"لماذا يذبل النبات ويموت إذا سُقي بماء شديد الملوحة؟","options":["لأن جهد الماء في التربة يصبح أقل من الجذر فيخرج الماء من الجذر بالأسموزية","لأن الملح يرفع جهد الماء","لأن الملح يسد الثغور","لأن الملح يمنع الضوء"],"answer":0,"why":"الملوحة الزائدة تعكس اتجاه الأسموزية فيفقد النبات ماءه."},{"type":"mcq","q":"لماذا تخلو خلايا الشعيرات الجذرية من «البلاستيدات الخضراء»؟","options":["لأنها ميتة","لأنها تنمو تحت الأرض في الظلام فلا يصلها ضوء للتمثيل الضوئي","لأنها تنقل السكر","لأنها شمعية"],"answer":1,"why":"لا فائدة من البلاستيدات تحت التربة المظلمة."},{"type":"tfr","q":"تمتص الشعيرات الجذرية الماء بالأسموزية والأملاح المعدنية بالنقل النشط.","answer":true,"reasons":["كلاهما بالتبخر","كلاهما بالنقل النشط فقط","الأسموزية لا تحتاج طاقة، بينما النقل النشط يحتاج طاقة من التنفس"],"reason":2},{"type":"tfr","q":"تحتوي خلايا الشعيرات الجذرية على أعداد كبيرة من البلاستيدات الخضراء.","answer":false,"reasons":["تخلو من البلاستيدات الخضراء لوجودها في الظلام تحت التربة","نعم مليئة بها","تقوم بالتمثيل الضوئي"],"reason":0},{"type":"essay","q":"قارن بين طريقة امتصاص الماء وطريقة امتصاص الأملاح المعدنية في الشعيرات الجذرية.","model":"الماء: بالأسموزية (من جهد ماء مرتفع بالتربة لمنخفض بالجذر، بلا طاقة). الأملاح: بالنقل النشط (من تركيز منخفض بالتربة لمرتفع بالجذر، يحتاج طاقة تنفس)."},{"type":"essay","q":"تتبّع مسار جزيء ماء من التربة حتى خروجه كبخار ماء من الورقة.","model":"التربة ← الشعيرة الجذرية ← قشرة الجذر ← خشب الجذر والساق ← خشب الورقة ← خلايا النسيج الوسطي ← يتبخر للفراغات الهوائية ← يخرج عبر الثغور."}],"hard":[{"type":"mcq","q":"لماذا يضرّ غمر التربة بالماء لفترات طويلة امتصاصَ «الأملاح المعدنية»؟","options":["لأن الأملاح تختفي","لأن الماء يذيب الخشب","لأنه يطرد الأكسجين من التربة فيتوقف التنفس الهوائي وتقل الطاقة اللازمة للنقل النشط","لأن الأسموزية تتوقف"],"answer":2,"why":"النقل النشط يتطلب طاقة من التنفس الهوائي للجذور."},{"type":"mcq","q":"تُسمّى الخاصية التي تجعل جزيئات الماء تتجاذب مع بعضها لتصعد كعمود واحد متصل في الخشب:","options":["التبلور","التفكك","الانكسار","قوة التماسك (Cohesion)"],"answer":3,"why":"قوة التماسك تحافظ على عمود الماء غير منقطع داخل الخشب."},{"type":"mcq","q":"أي عضيّة تكثر في خلايا الشعيرات الجذرية لتوفير الطاقة للنقل النشط؟","options":["الميتوكوندريا","البلاستيدات الخضراء","الطبقة الشمعية","الأهداب"],"answer":0,"why":"الميتوكوندريا هي مصانع الطاقة بالتنفس الهوائي."},{"type":"mcq","q":"ماذا يحدث لضغط الماء داخل قمة أوعية الخشب عند زيادة معدل التبخر من الأوراق؟","options":["يرتفع الضغط في الأعلى","ينخفض الضغط في الأعلى فيزداد سحب الماء صعودًا من الجذور","ينزل الماء للتربة","يتوقف الخشب"],"answer":1,"why":"انخفاض الضغط أعلى الخشب يولّد سحب النتح."},{"type":"tfr","q":"يساعد «تماسك جزيئات الماء» على صعود عمود الماء متصلًا في أوعية الخشب حتى قمم الأشجار.","answer":true,"reasons":["الماء لا يتماسك","فتسحب كل جزيئة ماء الجزيئة التي تحتها عند حدوث النتح","يصعد كفقاعات منفصلة"],"reason":1},{"type":"tfr","q":"تغطية الشعيرات الجذرية بطبقة شمعية سميكة سيزيد من امتصاصها للماء.","answer":false,"reasons":["الشعيرات شمعية أصلًا","نعم يزيد الامتصاص","الطبقة الشمعية تمنع مرور الماء، لذا فالشعيرات الجذرية بلا كيوتيكل شمعي وجدرانها رقيقة"],"reason":2},{"type":"tfr","q":"وجود تربة مهوّاة جيدة الصرف يدعم امتصاص الأملاح المعدنية بالنقل النشط.","answer":true,"reasons":["لتوفر الأكسجين اللازم لتنفس خلايا الجذور وإنتاج الطاقة","التهوية تضر الجذور","لا تحتاج الجذور أكسجين"],"reason":0},{"type":"essay","q":"اذكر ثلاثة تكيّفات للخلية الشعيرية الجذرية تساعدها في وظيفتها.","model":"١) امتداد طويل يزيد مساحة السطح. ٢) جدار رقيق وبلا طبقة شمعية. ٣) فجوة عصارية مركّزة (للأسموزية) وميتوكوندريا كثيرة (للنقل النشط)."},{"type":"essay","q":"فسّر كيف يصعد الماء إلى قمة نخلة عالية دون وجود مضخة قلبية.","model":"بسبب سحب النتح: يتبخر الماء من الأوراق فينخفض الضغط أعلى الخشب، وبفضل قوة التماسك بين جزيئات الماء يُسحب عمود الماء متصلًا للأعلى."},{"type":"essay","q":"علّل: لماذا يذبل النبات المزروع في تربة مالحة جدًّا رغم ريّه باستمرار؟","model":"لأن زيادة الأملاح تخفض جهد الماء في التربة ليصبح أقل من جهد الماء داخل الجذر، فيخرج الماء من الجذر بالأسموزية ويذبل النبات."}]}},
  {"id":"g9-bio-2-u9-3","grade":"g9","subject":"biology","term":2,"unit":9,"no":3,"title":"عملية النتح","summary":"شرح متحرك بـ SVG لدرس عملية النتح (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-transpiration.html","video":"","pdf":"","notes":["النتح: تبخّر الماء داخل الورقة وانتشار بخاره عبر الثغور للهواء.","يزداد النتح بزيادة الحرارة والضوء والرياح، ويقلّ بزيادة الرطوبة.","البوتوميتر يقيس معدل امتصاص الماء لتقدير النتح.","الذبول يحدث عندما يفوق فقد الماء بالنتح امتصاصه بالجذور."],"exercises":["اذكر العوامل البيئية الأربعة المؤثرة في معدل النتح وبيّن أثر زيادة كل منها (طردي أم عكسي).","اشرح كيف يعمل جهاز البوتوميتر لقياس أثر سرعة الرياح على النتح.","اذكر ثلاثة تكيّفات للنباتات الصحراوية العُمانية لتقليل فقد الماء بالنتح."],"levels":{"easy":[{"type":"mcq","q":"أي عامل مما يلي «يقلّل» معدل النتح عند زيادته (علاقة عكسية)؟","options":["زيادة الرطوبة الجوية","زيادة درجة الحرارة","زيادة سرعة الرياح","زيادة شدة الضوء"],"answer":0,"why":"الهواء الرطب مشبع ببخار الماء فيقلل تدرج انتشار البخار من الورقة."},{"type":"mcq","q":"ما الجهاز المختبري المستخدم لتقدير معدل النتح عبر قياس حركة فقاعة هواء؟","options":["الأميتر","البوتوميتر (مقياس النتح)","الميكرومتر","المنشور"],"answer":1,"why":"يقيس البوتوميتر معدل امتصاص الماء المرتبط بمعدل النتح."},{"type":"mcq","q":"لماذا تزيد «سرعة الرياح» من معدل النتح في النبات؟","options":["لأنها تزيد الرطوبة","لأنها تغلق الثغور","لأنها تُبعد بخار الماء المتجمع حول الثغور فتحافظ على تدرج انتشار حاد","لأنها تبرّد الجذور"],"answer":2,"why":"إزالة البخار المحيط بالورقة تسرّع خروج مزيد من البخار."},{"type":"mcq","q":"متى يحدث «ذبول» النبات؟","options":["في الظلام الدامس فقط","عندما يمتص ماءً أكثر مما يفقد","عند ارتفاع الرطوبة 100%","عندما يفقد النبات الماء بالنتح أسرع مما يمتصه بالجذور"],"answer":3,"why":"نقص الماء يفقد الخلايا ضغط الامتلاء فتتدلّى الأوراق."}],"medium":[{"type":"mcq","q":"ما الفائدتان الرئيستان لعملية النتح للنبات؟","options":["سحب الماء والأملاح عبر الخشب، وتبريد الأوراق بالتبخر","إنتاج السكر فقط","منع دخول CO₂","زيادة وزن الورقة"],"answer":0,"why":"النتح يحرّك تيار الماء ويبرد الأوراق في الحر."},{"type":"mcq","q":"كيف تكيّف نبات الصبّار في البيئة الصحراوية لتقليل النتح؟","options":["أوراقه عريضة جدًّا ورقيقة","تحوّرت أوراقه إلى أشواك وله ساق خضراء سميكة بطبقة شمعية سميكة","له آلاف الثغور المكشوفة","لا يحتوي طبقة شمعية"],"answer":1,"why":"تحور الأوراق لأشواك يقلل مساحة سطح التبخر لأدنى حد."},{"type":"mcq","q":"لماذا يزداد معدل النتح نهارًا عند زيادة شدة الضوء؟","options":["لأن الماء يتجمد","لأن الثغور تنغلق في الضوء","لأن الثغور تفتح أوسع لدخول CO₂ للتمثيل الضوئي فيخرج معها بخار ماء أكثر","لأن الجذور تتوقف"],"answer":2,"why":"فتح الثغور للتمثيل الضوئي يسمح بانتشار بخار الماء للخارج."},{"type":"tfr","q":"زيادة الرطوبة الجوية حول الورقة تقلّل من معدل النتح.","answer":true,"reasons":["لأن تدرّج تركيز بخار الماء بين داخل الورقة وخارجها يصبح أصغر فيبطؤ الانتشار","تزيد النتح بشدة","لا تؤثر على النتح"],"reason":0},{"type":"tfr","q":"يقيس البوتوميتر معدل «امتصاص الماء» وهو يساوي تقريبًا معدل النتح.","answer":true,"reasons":["يقيس إنتاج الأكسجين","لأن معظم الماء الممتص (نحو 99%) يُفقد بالنتح وجزءًا ضئيلًا يُستخدم في التمثيل الضوئي والنمو","يقيس كتلة التربة"],"reason":1},{"type":"essay","q":"اذكر العوامل البيئية الأربعة المؤثرة في معدل النتح وبيّن أثر زيادة كل منها (طردي أم عكسي).","model":"١) الحرارة: طردي (يزداد). ٢) شدة الضوء: طردي (يزداد). ٣) سرعة الرياح: طردي (يزداد). ٤) الرطوبة الجوية: عكسي (يقلّ)."},{"type":"essay","q":"اشرح كيف يعمل جهاز البوتوميتر لقياس أثر سرعة الرياح على النتح.","model":"نقصّ ساق نبات تحت الماء ونثبته بإحكام في البوتوميتر، نقيس المسافة التي تقطعها فقاعة الهواء خلال 5 دقائق في هواء ساكن ثم أمام مروحة فنجد المسافة أكبر مع المروحة."}],"hard":[{"type":"mcq","q":"تحدث عملية النتح أساسًا عبر:","options":["البذور الجافة","الجذور تحت الأرض","أوعية اللحاء","الثغور الموجودة في أوراق النبات"],"answer":3,"why":"يخرج معظم بخار الماء من الفراغات الهوائية عبر الثغور."},{"type":"mcq","q":"إذا غطّينا ورقتين بالفازلين (مادة شمعية): الأولى على سطحها السفلي والثانية على العلوي، أيّهما تفقد ماءً أقل؟","options":["المغطاة على سطحها السفلي (لأن معظم الثغور في البشرة السفلى)","المغطاة على العلوي","تتساويان تمامًا","كلاهما يفقد كل مائه"],"answer":0,"why":"سدّ الثغور في السطح السفلي يوقف معظم النتح."},{"type":"mcq","q":"في تجربة البوتوميتر، ماذا يفعل وضع مروحة أمام الفرع النباتي؟","options":["تتوقف الفقاعة","تتحرك فقاعة الهواء مسافةً أكبر في الدقيقة لزيادة معدل النتح","ترجع للخلف","لا يتغير شيء"],"answer":1,"why":"حركة الهواء (الرياح) تسرّع النتح."},{"type":"mcq","q":"في تجربة البوتوميتر، ماذا يفعل وضع كيس بلاستيكي شفاف مغلق فوق الفرع النباتي؟","options":["يسرّع الفقاعة","يزيد النتح بشدة","يقلل حركة الفقاعة لأن البخار يتجمع داخل الكيس فترتفع الرطوبة ويقل النتح","يرفع الحرارة فقط"],"answer":2,"why":"حبس بخار الماء يرفع الرطوبة حول الورقة فيبطئ النتح."},{"type":"tfr","q":"تُسقى النباتات في حديقة المنزل بعُمان في وقت الظهيرة الحار بدل الصباح الباكر أو المساء لتقليل التبخر.","answer":false,"reasons":["لا فرق في التوقيت","نعم الظهيرة أفضل","يُفضّل الري في الصباح الباكر أو المساء لتقليل التبخر والنتح السريع والاستفادة القصوى من الماء"],"reason":2},{"type":"tfr","q":"عندما يذبل النبات تقلّ كفاءة التمثيل الضوئي مؤقتًا لأن الثغور تُغلق فلا يدخل CO₂ بسهولة.","answer":true,"reasons":["يضحي النبات مؤقتًا بالتمثيل الضوئي لحماية نفسه من الموت بالجفاف","يزداد التمثيل الضوئي عند الذبول","تفتح الثغور أوسع عند الذبول"],"reason":0},{"type":"tfr","q":"يُعد النتح مجرد خسارة ضارة للماء بلا أي فائدة للنبات.","answer":false,"reasons":["نعم ضار فقط","للنتح فائدتان أساسيتان: توليد قوة سحب الماء والأملاح في الخشب وتبريد الأوراق","يمنع وصول الماء"],"reason":1},{"type":"essay","q":"اذكر ثلاثة تكيّفات للنباتات الصحراوية العُمانية لتقليل فقد الماء بالنتح.","model":"١) أوراق صغيرة أو أشواك (الصبّار). ٢) طبقة شمعية سميكة. ٣) ثغور قليلة وغائرة (وجذور عميقة)."},{"type":"essay","q":"فسّر لماذا يذبل نبات عند نقله من أرضه بزراعة جذوره مقطوعة أو في يوم حار عاصف.","model":"لأن فقدان الماء بالنتح يصبح أكبر من امتصاص الجذور فتفقد الخلايا امتلاءها وتتدلّى الأوراق."},{"type":"essay","q":"لماذا يُقطع فرع النبات «تحت الماء» قبل تركيبه في جهاز البوتوميتر؟","model":"لمنع دخول فقاعات هواء إلى أوعية الخشب لأن الهواء يقطع عمود الماء المتماسك ويعيق سحب النتح."}]}},
  {"id":"g9-bio-2-u9-4","grade":"g9","subject":"biology","term":2,"unit":9,"no":4,"title":"نقل الغذاء الجاهز في النبات","summary":"شرح متحرك بـ SVG لدرس نقل الغذاء الجاهز في النبات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-translocation-in-plants.html","video":"","pdf":"","notes":["الانتقال: حركة السكروز والأحماض الأمينية في اللحاء من المصدر (الأوراق) إلى المصبّ (الجذور والثمار والبراعم).","النقل في اللحاء حيوي (خلايا حية + طاقة) وفي الاتجاهين (↑↓).","أعضاء التخزين كالدرنات تكون مصبًّا صيفًا ومصدرًا ربيعًا."],"exercises":["عرّف «الانتقال (Translocation)» و«المصدر» و«المصبّ» مع مثال لكل منها.","اشرح كيف تتبدّل درنة البطاطس بين دور «المصبّ» ودور «المصدر» خلال السنة.","قارن في جدول بين عملية النتح (في الخشب) وعملية الانتقال (في اللحاء)."],"levels":{"easy":[{"type":"mcq","q":"ما اسم عملية نقل السكروز والأحماض الأمينية عبر نسيج اللحاء؟","options":["النتح","الانتقال (Translocation)","التبخر","الترشيح"],"answer":1,"why":"الانتقال هو حركة الغذاء الجاهز في اللحاء من المصدر للمصب."},{"type":"mcq","q":"ما المادتان الرئيستان اللتان تُنقلان عبر نسيج اللحاء؟","options":["النشا الصلب والدهون","الماء والأملاح المعدنية فقط","السكروز والأحماض الأمينية","CO₂ و O₂"],"answer":2,"why":"يُنقل الغذاء الذائب في اللحاء كسكروز وأحماض أمينية."},{"type":"mcq","q":"في فصل الصيف عندما تنشط الأوراق بالتمثيل الضوئي، ماذا تمثّل «الورقة» وماذا تمثّل «ثمرة الرمان أو درنة البطاطس»؟","options":["كلاهما مصدر","الدرنة مصدر والورقة مصب","كلاهما مصب","الورقة = مصدر (Source)، والثمرة/الدرنة = مصبّ (Sink)"],"answer":3,"why":"الورقة تصنع الغذاء (مصدر) والثمرة/الدرنة تخزنه (مصب)."},{"type":"mcq","q":"في بداية الربيع قبل نمو أوراق جديدة، كيف يصبح دور «درنة البطاطس»؟","options":["تصبح «مصدرًا» تحلّل النشا لسكروز لتغذية البراعم النامية (المصبّ)","تبقى مصبًا فقط","تموت الدرنة","تقوم بالتمثيل الضوئي"],"answer":0,"why":"يمكن لعضو التخزين أن يتحول لمصدر في موسم الإنبات."}],"medium":[{"type":"mcq","q":"ما الدليل الذي تقدّمه تجربة «إزالة حلقة من اللحاء» حول ساق نبات؟","options":["توقف صعود الماء فورًا","تورّم الساق فوق الحلقة لتراكم السكر يؤكد أن اللحاء ينقل الغذاء للأسفل","زيادة نمو الجذور","تغير لون الأوراق للأزرق"],"answer":1,"why":"انقطاع اللحاء يوقف نزول السكروز فيتراكم فوق الحلقة."},{"type":"mcq","q":"أي مقارنة صحيحة بين النقل في الخشب والنقل في اللحاء؟","options":["اللحاء للأعلى فقط","كلاهما للأسفل فقط","الخشب باتجاه واحد للأعلى، واللحاء في الاتجاهين (أعلى وأسفل)","الخشب في الاتجاهين"],"answer":2,"why":"يذهب الغذاء في اللحاء صعودًا للثمار والبراعم وهبوطًا للجذور."},{"type":"mcq","q":"لماذا تتغذّى حشرة المنّ بغرس خرطومها في أنابيب اللحاء بالتحديد؟","options":["لتتغذى على اللجنين","لأنها تبحث عن الماء النقي فقط","لأن اللحاء ميت وصلب","لأن عصارة اللحاء غنية جدًّا بالسكروز والأحماض الأمينية"],"answer":3,"why":"عصارة اللحاء غنية بالسكريات والأحماض الأمينية المغذية."},{"type":"tfr","q":"تُنقل المواد الغذائية المصنوعة في اللحاء على هيئة سكروز وأحماض أمينية.","answer":true,"reasons":["تُنقل كنشا صلب","وهي مواد ذائبة يسهل نقلها من المصادر إلى المصبّات","ينقل اللحاء الماء فقط"],"reason":1},{"type":"tfr","q":"يمكن لعضو التخزين (مثل درنة البطاطس) أن يعمل كمصبّ في فصل وكمصدر في فصل آخر.","answer":true,"reasons":["دائمًا مصدر فقط","دائمًا مصبّ فقط","في الصيف يخزّن السكر (مصبّ)، وفي الربيع يمدّ البراعم بالسكر (مصدر)"],"reason":2},{"type":"essay","q":"عرّف «الانتقال (Translocation)» و«المصدر» و«المصبّ» مع مثال لكل منها.","model":"الانتقال: حركة السكروز والأحماض الأمينية في اللحاء. المصدر: ينتج/يطلق السكر (الورقة الناضجة). المصب: يستهلك/يخزن السكر (الجذور، الثمار، البراعم)."},{"type":"essay","q":"اشرح كيف تتبدّل درنة البطاطس بين دور «المصبّ» ودور «المصدر» خلال السنة.","model":"في الصيف تصنع الأوراق السكر وتنقله للدرنة فتكون الدرنة «مصبًّا» تخزنه كنشا؛ وفي الربيع تحلّل الدرنة النشا لسكروز لتغذية البراعم النامية فتصبح «مصدرًا»."}],"hard":[{"type":"mcq","q":"ما نوع الخلايا التي تشكّل أنابيب اللحاء الناقلة للغذاء؟","options":["خلايا حيّة (أنابيب غربالية وخلايا مرافقة)","خلايا ميتة مجوفة بها لجنين","خلايا خشبية فقط","خلايا حارسة"],"answer":0,"why":"الانتقال عملية حيوية تتطلب خلايا لحاء حية."},{"type":"mcq","q":"أي عضو نباتي يُعد دائمًا «مصبًّا (Sink)» أثناء نموه السريع؟","options":["الورقة الناضجة المشمسة","البراعم النامية والثمار والجذور النشطة","الشمس","الهواء"],"answer":1,"why":"الأعضاء النامية تستهلك السكروز والأحماض الأمينية لبناء خلايا جديدة."},{"type":"mcq","q":"لماذا يحتاج النقل في اللحاء إلى طاقة من التنفس الخلوي؟","options":["لإغلاق الثغور","لتبخير الماء","لتحميل وتفريغ السكروز والأحماض الأمينية بنشاط في أنابيب اللحاء","لتقوية اللجنين"],"answer":2,"why":"الخلايا المرافقة الغنية بالميتوكوندريا توفر الطاقة لتحميل الغذاء."},{"type":"mcq","q":"إذا وُجدت ثمرة «أعلى» ورقة خضراء، وجذر «أسفل» نفس الورقة، في أي اتجاه ينقل اللحاء السكروز؟","options":["لا ينتقل السكروز","للأسفل فقط","للأعلى فقط","للأعلى نحو الثمرة وللأسفل نحو الجذر في الوقت نفسه"],"answer":3,"why":"النقل في اللحاء ثنائي الاتجاه نحو جميع المصبّات."},{"type":"tfr","q":"تتكون أنابيب اللحاء من خلايا ميتة مغلّظة باللجنين.","answer":false,"reasons":["الخشب هو الميت المغلّظ باللجنين، أما اللحاء فخلايا حية (أنابيب غربالية وخلايا مرافقة)","نعم كلاهما ميت","اللحاء به لجنين سميك"],"reason":0},{"type":"tfr","q":"يؤدي قطع حلقة اللحاء حول الساق إلى تراكم السكر وتورّم الساق فوق موضع القطع.","answer":true,"reasons":["يتورّم أسفل القطع","مما يثبت عمليًا أن السكر ينتقل عبر اللحاء الخارجي نحو الجذور","لا يحدث أي تورّم"],"reason":1},{"type":"tfr","q":"تُعد الأوراق الخضراء الناضجة المعرضة للشمس «مصدرًا (Source)» للسكروز.","answer":true,"reasons":["لا تصنع سكرًا","تُعد مصبًا فقط","لأنها تصنع الجلوكوز بالتمثيل الضوئي وتحوّله لسكروز للنقل"],"reason":2},{"type":"essay","q":"قارن في جدول بين عملية النتح (في الخشب) وعملية الانتقال (في اللحاء).","model":"الخشب: ماء وأملاح، خلايا ميتة، اتجاه للأعلى فقط، بسحب النتح. اللحاء: سكروز وأحماض أمينية، خلايا حية، اتجاهان ↑↓، يحتاج طاقة."},{"type":"essay","q":"اشرح نتائج تجربة التحليق (إزالة حلقة من اللحاء حول ساق نبات) وماذا تثبت.","model":"يتورم الساق فوق الحلقة بسبب تراكم السكر القادم من الأوراق، ولا تموت الأوراق فورًا لسلامة الخشب الداخلي؛ مما يثبت أن اللحاء ينقل الغذاء."},{"type":"essay","q":"ما دور الخلايا المرافقة والصفائح الغربالية في نسيج اللحاء؟","model":"الصفائح الغربالية المثقبة تسمح بمرور العصارة السكرية بين الخلايا، والخلايا المرافقة تزوّد الأنابيب الغربالية بالطاقة من التنفس الخلوي."}]}},
  {"id":"g9-bio-2-u10-1","grade":"g9","subject":"biology","term":2,"unit":10,"no":1,"title":"التحكّم والاستجابة في النباتات","summary":"شرح متحرك بـ SVG لدرس التحكّم والاستجابة في النباتات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-control-response-in-plants.html","video":"","pdf":"","notes":["الانتحاء: استجابة نمو لمؤثر خارجي (موجب نحوه، سالب بعيدًا عنه).","الساق: انتحاء ضوئي موجب (+) وأرضي سالب (−).","الجذر: انتحاء أرضي موجب (+) وضوئي سالب (−).","الكلينوستات يدور ببطء كعينة ضابطة لإلغاء أثر الجاذبية الأحادي."],"exercises":["قارن بين استجابة «الساق» واستجابة «الجذر» لكل من الضوء والجاذبية الأرضية، مع ذكر الفائدة لكل منهما.","اشرح كيف تُجري تجربة لإثبات الانتحاء الأرضي في جذور بادرات الفول مع ذكر التجربة الضابطة.","لماذا يضع أصحاب المشاتل أصص النباتات المنزلية قرب النوافذ ويُديرون الأصيص كل عدة أيام؟"],"levels":{"easy":[{"type":"mcq","q":"ما نوع استجابة «الساق» للضوء وللجاذبية على الترتيب؟","options":["كلاهما موجب","ضوئي سالب وأرضي موجب","انتحاء ضوئي موجب، وانتحاء أرضي سالب","كلاهما سالب"],"answer":2,"why":"ينمو الساق نحو الضوء (موجب) وعكس الجاذبية للأعلى (سالب)."},{"type":"mcq","q":"ما نوع استجابة «الجذر» للجاذبية الأرضية؟","options":["لا يستجيب للجاذبية","انتحاء أرضي سالب","انتحاء ضوئي موجب","انتحاء أرضي موجب (ينمو للأسفل نحو الجاذبية)"],"answer":3,"why":"نمو الجذر للأسفل يثبت النبات ويصل به للماء والأملاح."},{"type":"mcq","q":"ما وظيفة جهاز «الكلينوستات» (الدوار ببطء) في تجربة الانتحاء الأرضي؟","options":["توزيع تأثير الجاذبية بالتساوي على كل الجوانب كعينة ضابطة فتنمو البادرة مستقيمةً","زيادة الجاذبية","تسخين النبات","منع الضوء"],"answer":0,"why":"الدوران البطيء يلغي التوجيه الأحادي للجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الضوئي الموجب للساق؟","options":["تثبيت الجذور","توجيه الأوراق نحو الضوء لزيادة معدل التمثيل الضوئي","تقليل امتصاص الماء","منع الإزهار"],"answer":1,"why":"الحصول على أكبر قدر من الضوء ضروري لصنع الغذاء."}],"medium":[{"type":"mcq","q":"إذا وُضعت نبتة أصيص «أفقيًا على جانبها» في غرفة مظلمة، كيف ستنمو ساقها بعد أيام؟","options":["تبقى أفقية تمامًا","تنمو للأسفل","تنحني للأعلى عكس الجاذبية (انتحاء أرضي سالب)","تموت فورًا"],"answer":2,"why":"حتى في الظلام تستجيب الساق للجاذبية وتنمو للأعلى."},{"type":"mcq","q":"ما المقصود بـ«الانتحاء (Tropism)» في النباتات؟","options":["تبخر الماء فقط","حركة النبات من مكان لآخر","انقباض عضلات النبات","استجابة نمو أجزاء النبات بالاتجاه نحو مؤثر خارجي أو بعيدًا عنه"],"answer":3,"why":"الانتحاء استجابة نمو موجهة للمؤثرات كالضوء والجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الأرضي الموجب للجذر؟","options":["تثبيت النبات بقوة في التربة والوصول إلى الماء والأملاح المعدنية","امتصاص ضوء الشمس","نشر حبوب اللقاح","إنتاج الثمار"],"answer":0,"why":"التثبيت والماء والأملاح أهم وظائف الجذر."},{"type":"tfr","q":"تُظهر ساق النبات انتحاءً ضوئيًا موجبًا وانتحاءً أرضيًا سالبًا.","answer":true,"reasons":["ضوئيًا سالبًا","أرضيًا موجبًا","فتنمو دائمًا نحو الضوء وللأعلى عكس الجاذبية"],"reason":2},{"type":"tfr","q":"تحتاج النباتات إلى جهاز عصبي ودماغ لتقوم بالانتحاء الضوئي والأرضي.","answer":false,"reasons":["لا تملك النباتات جهازًا عصبيًا، بل تنظّم استجاباتها عبر الهرمونات النباتية كالأكسين","نعم لها دماغ","لها أعصاب"],"reason":0},{"type":"essay","q":"قارن بين استجابة «الساق» واستجابة «الجذر» لكل من الضوء والجاذبية الأرضية، مع ذكر الفائدة لكل منهما.","model":"الساق: ضوئي موجب (لامتصاص الضوء والتمثيل الضوئي) وأرضي سالب (للصعود نحو الضوء). الجذر: أرضي موجب (للتثبيت وامتصاص الماء والأملاح) وضوئي سالب."},{"type":"essay","q":"اشرح كيف تُجري تجربة لإثبات الانتحاء الأرضي في جذور بادرات الفول مع ذكر التجربة الضابطة.","model":"نثبت بادرات أفقيًا في مكان مظلم فتنحني الجذور للأسفل والسيقان للأعلى. والضابطة: نثبت بادرات مماثلة على كلينوستات يدور ببطء في الظلام فتنمو مستقيمة أفقيًا."}],"hard":[{"type":"mcq","q":"لماذا نجري تجربة «الانتحاء الأرضي» عادةً داخل مكان مظلم؟","options":["لأن الجاذبية تعمل في الظلام فقط","لاستبعاد تأثير الضوء حتى نتأكد أن الانحناء ناتج عن الجاذبية وحدها","لأن النبات لا ينمو في الضوء","لتبريد الغرفة"],"answer":1,"why":"تثبيت/عزل المتغيرات يضمن أن الجاذبية هي السبب الوحيد."},{"type":"mcq","q":"في تجربة الصندوق ذي الفتحة الجانبية، تنحني ساق البادرة نحو الفتحة بسبب:","options":["قوة الرياح","الانتحاء الأرضي الموجب","الانتحاء الضوئي الموجب","النتح"],"answer":2,"why":"الضوء القادم من جهة واحدة يسبب انحناء الساق نحوه."},{"type":"mcq","q":"إذا أدرنا بادرة نبات على الكلينوستات ببطء في الظلام، كيف سينمو جذرها؟","options":["يتوقف عن النمو","منحنيًا للأعلى","منحنيًا للأسفل بشدة","مستقيمًا أفقيًا دون انحناء للأسفل"],"answer":3,"why":"الدوران يوزع الجاذبية بالتساوي فيمنع الانحناء."},{"type":"mcq","q":"كيف تختلف استجابة النبات عن استجابة الحيوان للمؤثرات؟","options":["استجابة النبات أبطأ وتتم بالنمو والهرمونات دون جهاز عصبي أو عضلات","النبات أسرع ولها أعصاب","متطابقتان تمامًا","النبات لا يستجيب أبدًا"],"answer":0,"why":"النباتات تستجيب ببطء عبر النمو المنظّم هرمونيًا."},{"type":"tfr","q":"نمو الجذور للأسفل نحو التربة مثال على الانتحاء الأرضي الموجب.","answer":true,"reasons":["مثال على انتحاء أرضي سالب","مما يضمن تثبيت النبات وامتصاص الماء والأملاح","مثال على ضوئي موجب"],"reason":1},{"type":"tfr","q":"استخدام الكلينوستات الدوار في تجربة الانتحاء الأرضي يمثّل «تجربة ضابطة» تثبت أن الجاذبية هي سبب الانحناء.","answer":true,"reasons":["يمنع الماء","يزيد الانحناء","لأن إلغاء اتجاه الجاذبية الأحادي يجعل البادرة تنمو مستقيمة"],"reason":2},{"type":"tfr","q":"إذا زُرعت بذرة بالمقلوب فلن ينمو جذرها نحو الأسفل أبدًا.","answer":false,"reasons":["بل ينحني الجذير تلقائيًا للأسفل بالانتحاء الأرضي الموجب وتصعد الريشة للأعلى","ينمو الجذر في الهواء","لا تنبت البذرة"],"reason":0},{"type":"essay","q":"لماذا يضع أصحاب المشاتل أصص النباتات المنزلية قرب النوافذ ويُديرون الأصيص كل عدة أيام؟","model":"لأن الساق تنحني نحو ضوء النافذة بالانتحاء الضوئي الموجب، وتدوير الأصيص يجعل النمو مستقيمًا ومتوازنًا من كل الجهات."},{"type":"essay","q":"عرّف كلًا من: الانتحاء الموجب، الانتحاء السالب، والكلينوستات.","model":"الموجب: نمو نحو المؤثر. السالب: نمو بعيدًا عن المؤثر. الكلينوستات: جهاز يدور ببطء لتوزيع الجاذبية بالتساوي وإلغاء تأثيرها من جهة واحدة."},{"type":"essay","q":"لماذا يجب إجراء تجربة الانتحاء الأرضي في «الظلام»؟","model":"لمنع تداخل الانتحاء الضوئي مع التجربة، فنتيقّن أن الجاذبية وحدها هي التي سبّبت الانحناء."}]}},
  {"id":"g9-bio-2-u10-2","grade":"g9","subject":"biology","term":2,"unit":10,"no":2,"title":"الهرمونات النباتية","summary":"شرح متحرك بـ SVG لدرس الهرمونات النباتية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-plant-hormones.html","video":"","pdf":"","notes":["الأكسين هرمون يُنتج في القمة النامية وينظّم استطالة الخلايا.","في الساق: الأكسين ينشّط الاستطالة (ضوئي + وأرضي −). في الجذر: يثبّط الاستطالة (أرضي +).","تُستخدم الأكسينات الصناعية كمبيدات أعشاب انتقائية ومساحيق تجذير."],"exercises":["اشرح بالخطوات كيف يسبّب هرمون الأكسين «الانتحاء الضوئي الموجب» في ساق نبات.","قارن بين أثر تجمع الأكسين في الجانب السفلي لكل من «ساق أفقية» و«جذر أفقي».","اشرح كيف تعمل «مبيدات الأعشاب الانتقائية» القائمة على الأكسين الصناعي في مزارع القمح."],"levels":{"easy":[{"type":"mcq","q":"أين يُنتج هرمون «الأكسين (Auxin)» في النبات؟","options":["في التربة","في الكيوتيكل الشمعي","في أوعية الخشب الميتة","في القمم النامية للساق والجذر"],"answer":3,"why":"تُنتج القمة النامية الأكسين ثم ينتشر للخلايا خلفها."},{"type":"mcq","q":"عند سقوط ضوء من جانب واحد على ساق نبات، أين يتركّز الأكسين؟","options":["في الجانب المظلّل (البعيد عن الضوء) فينشّط استطالته","في الجانب المضيء فقط","في الجذر فقط","يختفي تمامًا"],"answer":0,"why":"تراكم الأكسين في الجانب المظلل يجعله يستطيل أسرع فتنحني الساق نحو الضوء."},{"type":"mcq","q":"كيف يختلف تأثير التركيز العالي للأكسين بين «الساق» و«الجذر»؟","options":["ينشّط كليهما","يُنشّط الاستطالة في الساق، ويُثبّط (يبطئ) الاستطالة في الجذر","يثبّط كليهما","لا يؤثر فيهما"],"answer":1,"why":"هذا التأثير المتعاكس يفسّر انحناء الساق للأعلى والجذر للأسفل."},{"type":"mcq","q":"كيف تعمل «مبيدات الأعشاب الانتقائية» المصنوعة من أكسينات صناعية في حقول القمح؟","options":["تمنع الماء عن القمح","تحرق التربة كلها","تُسبب نموًا سريعًا غير منضبط للأعشاب عريضة الأوراق فتموت دون الإضرار بالقمح","تقتل الحشرات فقط"],"answer":2,"why":"الأكسين الصناعي يقتل النباتات عريضة الأوراق ويترك الحبوب سليمة."}],"medium":[{"type":"mcq","q":"في جذر موضوع أفقيًا، يتجمع الأكسين في الجانب السفلي بسبب الجاذبية، فماذا يحدث؟","options":["ينمو مستقيمًا","يستطيل السفلي أسرع فينحني للأعلى","يتوقف الجذر عن النمو","يُثبّط استطالة الجانب السفلي فيستطيل العلوي أسرع وينحني الجذر للأسفل"],"answer":3,"why":"التثبيط في الجانب السفلي للجذر يجعله ينحني للأسفل."},{"type":"mcq","q":"ماذا يحدث لبادرة نبات إذا «قُطعت قمتها النامية» ثم عُرّضت لضوء جانبي؟","options":["لا تستطيل ولا تنحني نحو الضوء لغياب مصدر الأكسين","تنحني بسرعة مضاعفة","تتحول لجذر","تنمو للأسفل"],"answer":0,"why":"القمة النامية هي مصدر الأكسين وموضع الإحساس بالضوء."},{"type":"mcq","q":"ماذا يحدث إذا غطّينا القمة النامية لساق بغطاء ألمنيوم معتم مع وجود ضوء جانبي؟","options":["تنحني نحو الضوء فورًا","تنمو مستقيمةً للأعلى ولا تنحني نحو الضوء","تموت فورًا","تنمو للأسفل"],"answer":1,"why":"منع الضوء عن القمة يمنع إعادة توزيع الأكسين فتستطيل بتساوٍ."},{"type":"tfr","q":"يؤدي تراكم الأكسين في الجانب المظلل للساق إلى استطالة خلاياه أسرع فتنحني الساق نحو الضوء.","answer":true,"reasons":["وهذا يفسّر الانتحاء الضوئي الموجب في السيقان","يثبط الجانب المظلل","ينحني بعيدًا عن الضوء"],"reason":0},{"type":"tfr","q":"تأثير الأكسين العالي في الجذر هو نفسه تمامًا في الساق (كلاهما ينشّط الاستطالة).","answer":false,"reasons":["نعم متطابقان","في الساق ينشّط الاستطالة، أما في الجذر فيُثبّطها مما يفسّر انحناء الجذر للأسفل","في الساق يثبطها"],"reason":1},{"type":"essay","q":"اشرح بالخطوات كيف يسبّب هرمون الأكسين «الانتحاء الضوئي الموجب» في ساق نبات.","model":"تُنتج القمة النامية الأكسين؛ وعند سقوط ضوء جانبي يتجمع الأكسين في الجانب المظلل، وبما أنه ينشط الاستطالة في الساق تستطيل خلايا الجانب المظلل أسرع فتنحني الساق نحو الضوء."},{"type":"essay","q":"قارن بين أثر تجمع الأكسين في الجانب السفلي لكل من «ساق أفقية» و«جذر أفقي».","model":"في الساق: ينشّط الأكسين استطالة الجانب السفلي فتنحني للأعلى (أرضي سالب). في الجذر: يثبّط الأكسين الجانب السفلي فيستطيل العلوي أسرع وينحني للأسفل (أرضي موجب)."}],"hard":[{"type":"mcq","q":"ما الاستخدام الزراعي الآخر للأكسينات بجانب مبيدات الأعشاب؟","options":["قتل الفطريات فقط","تسميد التربة بالنترات","مسحوق التجذير لتشجيع نمو الجذور في العُقل النباتية وإنتاج ثمار بلا بذور","تلوين الأوراق"],"answer":2,"why":"تُستخدم الأكسينات في مساحيق التجذير والإكثار الخضري."},{"type":"mcq","q":"عندما يسطع الضوء «عموديًا بالتساوي» فوق قمة ساق نبات، كيف يتوزع الأكسين؟","options":["يهبط كله للجذر","في جانب واحد فقط","لا يُنتج أكسين","بالتساوي على جميع جوانب الساق فتنمو مستقيمةً للأعلى"],"answer":3,"why":"التوزيع المتساوي يعطي استطالة متساوية ونموًا مستقيمًا."},{"type":"mcq","q":"كيف ينتقل الأكسين من القمة النامية إلى منطقة الاستطالة خلفها؟","options":["بالانتشار من خلية إلى أخرى","عبر أوعية الخشب للأعلى فقط","عبر الهواء","بالأعصاب"],"answer":0,"why":"ينتشر الأكسين كيميائيًا عبر الخلايا خلف القمة النامية."},{"type":"mcq","q":"إذا وُضعت ساق أفقيًا، أي جانب منها يستطيل أسرع لكي تنحني للأعلى؟","options":["الجانب العلوي","الجانب السفلي (حيث يتركّز الأكسين وينشّط الاستطالة)","الجانبان بنفس السرعة","لا يستطيل أي جانب"],"answer":1,"why":"في الساق ينشّط الأكسين الجانب السفلي فترتفع القمة للأعلى."},{"type":"tfr","q":"تُعد القمة النامية للبادرة هي الجزء الحساس للضوء والمنتج لهرمون الأكسين.","answer":true,"reasons":["الأوراق القديمة فقط","الجذور هي الحساسة للضوء","فإذا قُطعت أو غُطّيت بغطاء معتم لم تنحنِ البادرة نحو الضوء"],"reason":2},{"type":"tfr","q":"الأكسينات الصناعية تُستخدم كمبيدات أعشاب انتقائية تقتل الأعشاب عريضة الأوراق دون إيذاء محاصيل الحبوب.","answer":true,"reasons":["لأنها تسبب نموًا مفرطًا غير منضبط للأعشاب عريضة الأوراق فتستهلك غذاءها وتموت","تقتل القمح وتترك الأعشاب","تقتل جميع النباتات بالتساوي"],"reason":0},{"type":"tfr","q":"في الجذر الأفقي، يستطيل الجانب «العلوي» أسرع من السفلي فينحني الجذر للأسفل.","answer":true,"reasons":["السفلي يستطيل أسرع","لأن الأكسين المتجمع في السفلي يثبط استطالته بينما ينمو العلوي طبيعيًا","ينحني للأعلى"],"reason":1},{"type":"essay","q":"اشرح كيف تعمل «مبيدات الأعشاب الانتقائية» القائمة على الأكسين الصناعي في مزارع القمح.","model":"تمتص الأعشاب عريضة الأوراق (ثنائية الفلقة) جرعة كبيرة من الأكسين الصناعي فتنمو بسرعة شاذة وتستهلك مخزونها وتموت، بينما لا تتأثر نباتات القمح ضيقة الأوراق."},{"type":"essay","q":"ماذا يحدث لبادرة شوفان في حالتين: (أ) قطع القمة النامية، (ب) تغطية القمة بغطاء معتم؟","model":"أ) يتوقف النمو والانحناء لغياب الأكسين. ب) تستمر في النمو مستقيمةً للأعلى ولا تنحني نحو الضوء الجانبي لأن القمة لم تشعر بالضوء."},{"type":"essay","q":"ما الفرق بين تنظيم الاستجابة بالهرمونات في النبات وتنظيمها في الإنسان؟","model":"في النبات: أبطأ ويتم كيميائيًا بالهرمونات (كالأكسين) عبر تغيير معدل نمو الخلايا. في الإنسان: يشمل جهازًا عصبيًا سريعًا جدًّا بالإضافة للهرمونات في الدم."}]}}
);
UNITS.push(
  {"id":"g9-bio-1-u1","grade":"g9","subject":"biology","term":1,"title":"الوحدة الأولى: الخلايا","levels":{"easy":[{"type":"mcq","q":"كم عدد الخصائص الأساسية المشتركة بين جميع الكائنات الحية؟","options":["٧ خصائص","٥ خصائص","٦ خصائص","٩ خصائص"],"answer":0,"why":"الخصائص السبع هي: الحركة، التنفس، الإحساس، النمو، التكاثر، الإخراج، التغذية."},{"type":"mcq","q":"ما وظيفة غشاء الخلية؟","options":["صنع الغذاء","التحكم في دخول المواد وخروجها","منح اللون الأخضر","تخزين العصارة"],"answer":1,"why":"غشاء الخلية شبه منفذ ينظّم حركة المواد."},{"type":"mcq","q":"ما الوظيفة الأساسية لخلايا الدم الحمراء؟","options":["امتصاص الماء","التمثيل الضوئي","نقل الأكسجين","تحريك المخاط"],"answer":2,"why":"تحمل الأكسجين عبر بروتين الهيموجلوبين."},{"type":"mcq","q":"ما الخاصية التي تعني إنتاج أفراد جديدة من النوع نفسه؟","options":["التغذية","التكاثر","النمو","الإخراج"],"answer":1,"why":"التكاثر يحفظ بقاء النوع عبر الأجيال."}],"medium":[{"type":"mcq","q":"أيُّ تعريفٍ مما يأتي يصف «النمو» بدقة علمية؟","options":["زيادة دائمة في الحجم والكتلة الجافة","انتقال الكائن من مكان لآخر","إخراج الفضلات السامة","زيادة مؤقتة في الوزن بعد شرب الماء"],"answer":0,"why":"النمو زيادة دائمة بزيادة عدد الخلايا أو حجمها."},{"type":"mcq","q":"لماذا تحتوي خلايا العضلات على أعداد كبيرة جدًّا من الميتوكوندريا؟","options":["لإنتاج الكلوروفيل","لأنها تحتاج طاقة كبيرة للانقباض","لتصنيع الجدار الخلوي","لتخزين النشا"],"answer":1,"why":"الميتوكوندريا تطلق الطاقة بالتنفس الهوائي."},{"type":"mcq","q":"أيُّ خليةٍ نباتيةٍ تحتوي على أكبر عدد من البلاستيدات الخضراء؟","options":["بشرة الجذر","وعاء الخشب","خلية النسيج العمادي","خلية الشعيرة الجذرية"],"answer":2,"why":"خلايا النسيج العمادي هي الموقع الرئيس للتمثيل الضوئي."},{"type":"tfr","q":"النباتات لا تتحرك أبدًا لأنها ثابتة في التربة.","answer":false,"reasons":["لأن النباتات تتحرك حركة بطيئة وموضعية كاتجاه الساق للضوء وتفتح الأزهار","لأن النباتات ليست كائنات حية","لأن النباتات تجري مثل الحيوانات"],"reason":0},{"type":"tfr","q":"توجد البلاستيدات الخضراء في جميع خلايا النبات بما فيها خلايا الجذور تحت التربة.","answer":false,"reasons":["لأن خلايا الجذور لا يصلها الضوء فلا تحتاج إلى بلاستيدات خضراء","لأن البلاستيدات في الحيوانات فقط","لأن الجذور تصنع الغذاء بالضوء"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ العبارات الآتية تفرّق بدقة بين «الإخراج» و«التبرّز»؟","options":["الإخراج لا يحدث في النباتات","التبرّز يحدث في الرئتين","الإخراج يزيل فضلات التفاعلات الخلوية، والتبرّز يزيل طعامًا غير مهضوم","كلاهما يحمل المعنى نفسه تمامًا"],"answer":2,"why":"الفضلات الأيضية كاليوريا وCO₂ هي إخراج، أما الطعام غير المهضوم فلم يدخل الخلايا أصلًا."},{"type":"mcq","q":"صورة خلية طولها ٤٥ مم بتكبير ×٣٠٠. ما طولها الحقيقي بالملليمتر؟","options":["١٫٥ مم","٠٫٠١٥ مم","١٣٥٠٠ مم","٠٫١٥ مم"],"answer":3,"why":"الطول الحقيقي = الصورة ÷ التكبير = ٤٥ ÷ ٣٠٠ = ٠٫١٥ مم."},{"type":"mcq","q":"ماذا يحدث لو توقّفت الأهداب في القصبة الهوائية عن الحركة بسبب التدخين؟","options":["يتراكم المخاط والبكتيريا وتزداد التهابات الرئة","يزداد الأكسجين في الدم","تتحسن عملية الهضم","لا يحدث أي تأثير"],"answer":0,"why":"الأهداب هي التي تكنس المخاط المحمّل بالميكروبات خارج الرئتين."},{"type":"essay","q":"قارن بين سيارة متحرّكة وحصان يركض باستخدام أربع خصائص من خصائص الكائنات الحية.","model":"كلاهما يتحرك ويستخدم مصدر طاقة (وقود/غذاء)، لكن الحصان ينمو بزيادة خلاياه، ويتكاثر، ويحسّ بمحيطه تلقائيًا، ويُصلح أنسجته؛ بينما السيارة تعجز عن ذلك."},{"type":"essay","q":"احسب الطول الحقيقي بالميكرومتر لخلية طولها في الصورة ٣٦ مم إذا كان التكبير ×٦٠٠.","model":"الطول الحقيقي = ٣٦ ÷ ٦٠٠ = ٠٫٠٦ مم. نحول لميكرومتر: ٠٫٠٦ × ١٠٠٠ = ٦٠ ميكرومتر."}]},"test":[{"type":"mcq","q":"كم عدد الخصائص الأساسية المشتركة بين جميع الكائنات الحية؟","options":["٧ خصائص","٥ خصائص","٦ خصائص","٩ خصائص"],"answer":0,"why":"الخصائص السبع هي: الحركة، التنفس، الإحساس، النمو، التكاثر، الإخراج، التغذية."},{"type":"mcq","q":"ما وظيفة غشاء الخلية؟","options":["صنع الغذاء","التحكم في دخول المواد وخروجها","منح اللون الأخضر","تخزين العصارة"],"answer":1,"why":"غشاء الخلية شبه منفذ ينظّم حركة المواد."},{"type":"mcq","q":"ما الوظيفة الأساسية لخلايا الدم الحمراء؟","options":["امتصاص الماء","التمثيل الضوئي","نقل الأكسجين","تحريك المخاط"],"answer":2,"why":"تحمل الأكسجين عبر بروتين الهيموجلوبين."},{"type":"mcq","q":"ما الخاصية التي تعني إنتاج أفراد جديدة من النوع نفسه؟","options":["التغذية","التكاثر","النمو","الإخراج"],"answer":1,"why":"التكاثر يحفظ بقاء النوع عبر الأجيال."},{"type":"mcq","q":"أين تحدث معظم التفاعلات الكيميائية في الخلية؟","options":["خارج الخلية","في الجدار الخلوي","في السيتوبلازم","في الكلوروفيل فقط"],"answer":2,"why":"السيتوبلازم مادة هلامية تحدث فيها معظم التفاعلات الحيوية."},{"type":"mcq","q":"ما وظيفة خلايا الشعيرات الجذرية في النبات؟","options":["صنع الغذاء بالضوء","نقل السيالات العصبية","حماية الرئتين","امتصاص الماء والأملاح من التربة"],"answer":3,"why":"امتدادها الطويل يزيد مساحة امتصاص الماء والأملاح."},{"type":"mcq","q":"اتجاه ساق النبات نحو ضوء الشمس مثال على خاصيتي:","options":["الإخراج والتكاثر","التكاثر فقط","الحركة والإحساس","التنفس والإخراج"],"answer":2,"why":"النبات يحسّ بالضوء ويتحرك باتجاهه."},{"type":"mcq","q":"ما وظيفة الريبوسومات في الخلية؟","options":["التمثيل الضوئي","تخزين الماء","دعم الجدار","تصنيع البروتينات"],"answer":3,"why":"الريبوسومات مسؤولة عن بناء البروتينات."},{"type":"mcq","q":"يُعدّ القلب في جسم الإنسان مثالًا على:","options":["عضو","خلية","جهاز","نسيج"],"answer":0,"why":"القلب عضو يتكون من عدة أنسجة متعاونة."},{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ من فضلات الإخراج في الإنسان؟","options":["الجلوكوز","الأكسجين","النشا","ثاني أكسيد الكربون واليوريا"],"answer":3,"why":"تُخرج الرئتان ثاني أكسيد الكربون وتُخرج الكليتان اليوريا."},{"type":"mcq","q":"كم ميكرومترًا في ١ ملليمتر؟","options":["١٠٠٠","١٠٠٠٠","١٠٠","١٠"],"answer":0,"why":"١ مم = ١٠٠٠ ميكرومتر."},{"type":"mcq","q":"مجموعة الخلايا المتشابهة التي تؤدي وظيفة واحدة تُسمّى:","options":["كائنًا حيًّا","نسيجًا","عضوًا","جهازًا"],"answer":1,"why":"النسيج مجموعة خلايا متشابهة التركيب والوظيفة."},{"type":"tf","q":"النباتات لا تتحرك أبدًا لأنها ثابتة في التربة.","answer":false,"why":"لأن النباتات تتحرك حركة بطيئة وموضعية كاتجاه الساق للضوء وتفتح الأزهار"},{"type":"tf","q":"توجد البلاستيدات الخضراء في جميع خلايا النبات بما فيها خلايا الجذور تحت التربة.","answer":false,"why":"لأن خلايا الجذور لا يصلها الضوء فلا تحتاج إلى بلاستيدات خضراء"},{"type":"tf","q":"تُعدّ الورقة في النبات مثالًا على «نسيج» وليس «عضوًا».","answer":false,"why":"لأن الورقة تتكون من عدة أنسجة مختلفة (البشرة والعمادي والإسفنجي والخشب واللحاء) فهي عضو"},{"type":"tf","q":"التنفُّس الخلوي يحدث داخل خلايا النبات والحيوان معًا لإطلاق الطاقة.","answer":true,"why":"لأن جميع الكائنات الحية تحتاج إلى الطاقة لإتمام عملياتها الحيوية"},{"type":"tfr","q":"يسمح الجدار الخلوي السليلوزي بمرور الماء والمواد الذائبة بحرية (نفاذ تام).","answer":true,"reasons":["لأنه يمنع دخول الماء تمامًا","لأن الجدار الخلوي منفذ تامًا ووظيفته الدعم، أما غشاء الخلية فهو شبه المنفذ","لأنه يتحكم كغشاء الخلية"],"reason":1},{"type":"tfr","q":"تمتلك الخلايا العصبية محورًا طويلًا لنقل الإشارات الكهربائية لمسافات طويلة في الجسم.","answer":true,"reasons":["لأنها تخزن النشا","لأن ذلك يتيح نقل السيال العصبي بسرعة من الأطراف إلى الدماغ والحبل الشوكي","لأنها تمتص الماء"],"reason":1},{"type":"tfr","q":"انتفاخ قطعة إسفنج عند وضعها في الماء يُعدّ مثالًا على النمو الحيوي.","answer":false,"reasons":["لأن الإسفنج كائن حي","لأن النمو يحدث بالماء فقط","لأن الزيادة مؤقتة وتزول بالعصر وليست زيادة دائمة في الكتلة الجافة"],"reason":2},{"type":"tfr","q":"لا يمكن رؤية الريبوسومات بوضوح باستخدام المجهر الضوئي المدرسي العادي.","answer":true,"reasons":["لأنها أكبر من النواة","لأنها غير موجودة في الخلايا","لأنها صغيرة جدًّا وتحتاج إلى المجهر الإلكتروني ذي التكبير العالي"],"reason":2},{"type":"essay","q":"اذكر الخصائص السبع للكائنات الحية.","model":"الحركة، التنفُّس، الإحساس، النمو، التكاثر، الإخراج، التغذية."},{"type":"essay","q":"اذكر ثلاثة تراكيب توجد في الخلية النباتية ولا توجد في الخلية الحيوانية.","model":"الجدار الخلوي السليلوزي، البلاستيدات الخضراء، الفجوة العصارية الكبيرة الدائمة."},{"type":"essay","q":"اذكر تكيّفين في تركيب خلايا الدم الحمراء يلائمان وظيفتها.","model":"١) عدم وجود نواة لزيادة مساحة الهيموجلوبين. ٢) الشكل القرصي مقعّر الوجهين لزيادة مساحة السطح لانتشار الأكسجين."},{"type":"essay","q":"لماذا يُعدّ التخلّص من ثاني أكسيد الكربون عبر الرئتين «إخراجًا»؟","model":"لأنه مادة فضلات ناتجة عن تفاعلات التنفُّس الكيميائية داخل الخلايا، وتراكمه يضر بالجسم."},{"type":"essay","q":"ما وظيفة النواة في الخلية؟","model":"تحتوي على المادة الوراثية (DNA) وتتحكم في جميع أنشطة الخلية وتفاعلاتها وانقسامها."}]},
  {"id":"g9-bio-1-u2","grade":"g9","subject":"biology","term":1,"title":"الوحدة الثانية: انتقال المواد من الخلايا وإليها","levels":{"easy":[{"type":"mcq","q":"الانتشار هو صافي حركة الجزيئات من:","options":["التركيز الأقل إلى الأعلى","الصلب إلى السائل فقط","البارد إلى الساخن","التركيز الأعلى إلى الأقل"],"answer":3,"why":"الانتشار يتحرك دائمًا مع منحدر التركيز."},{"type":"mcq","q":"أيُّ مادةٍ تنتقل تحديدًا في عملية الأسموزية؟","options":["الماء فقط","السكر فقط","الأكسجين","البروتين"],"answer":0,"why":"الأسموزية حالة خاصة من الانتشار تختص بجزيئات الماء."},{"type":"mcq","q":"أيُّ عاملٍ مما يأتي يسرّع معدل الانتشار؟","options":["رفع درجة الحرارة","تقليل مساحة السطح","خفض الحرارة","زيادة المسافة"],"answer":0,"why":"رفع الحرارة يزيد الطاقة الحركية للجزيئات."},{"type":"mcq","q":"أيُّ محلولٍ له أعلى جهد مائي؟","options":["ماء البحر","الماء المقطّر النقي","محلول ملحي مركّز","شراب سكري ثقيل"],"answer":1,"why":"الماء النقي يحتوي على أعلى تركيز من جزيئات الماء الحرة."}],"medium":[{"type":"mcq","q":"أيُّ التغيرات الآتية يبطئ سرعة الانتشار عبر غشاء؟","options":["زيادة فرق التركيز","رفع درجة الحرارة","زيادة مساحة السطح","زيادة سمك الغشاء (المسافة)"],"answer":3,"why":"زيادة المسافة تجعل الجزيئات تستغرق وقتًا أطول للعبور."},{"type":"mcq","q":"وُضعت قطعة بطاطس كتلتها ٥ جم في ماء مقطر فأصبحت ٥٫٦ جم؛ السبب هو:","options":["دخول الماء لخلايا البطاطس بالأسموزية","خروج الماء منها","تبخّر الماء","دخول السكر إليها"],"answer":0,"why":"الجهد المائي للماء المقطر أعلى من خلايا البطاطس فدخل الماء."},{"type":"mcq","q":"لماذا تحتوي الأمعاء الدقيقة على آلاف الخملات الدقيقة؟","options":["لزيادة مساحة سطح الانتشار والامتصاص","لإنتاج الأكسجين","لتبريد الطعام","لتقليل مساحة السطح"],"answer":0,"why":"زيادة مساحة السطح تسرّع انتقال الغذاء المهضوم للدم."},{"type":"tfr","q":"عندما يتساوى تركيز المادة في كل أنحاء الكوب تتوقّف الجزيئات تمامًا عن الحركة.","answer":false,"reasons":["تستمر الجزيئات بالحركة العشوائية، لكن صافي الانتشار فقط يصبح صفرًا","تعود للتركيز العالي","تتجمد الجزيئات فورًا"],"reason":0},{"type":"tfr","q":"الخلية النباتية والخلية الحيوانية تنفجران معًا عند وضعهما في ماء نقي.","answer":false,"reasons":["تنفجر الحيوانية فقط، أما النباتية فيحميها الجدار الخلوي السليلوزي","تنفجر النباتية فقط","كلاهما ينكمش"],"reason":0}],"hard":[{"type":"mcq","q":"وضعنا مكعبًا صغيرًا ومكعبًا كبيرًا من الهلام المصبوغ في حمض؛ أيهما يصله الحمض إلى مركزه أسرع؟","options":["لا ينتشر الحمض","المكعب الصغير لقصر مسافة الانتشار وكبر نسبة السطح للحجم","يصلان في الوقت نفسه","المكعب الكبير"],"answer":1,"why":"الأجسام الأصغر لها نسبة مساحة سطح إلى حجم أكبر ومسافة أقصر للمركز."},{"type":"mcq","q":"في تجربة بطاطس وُضعت شرائح في ٥ تراكيز سكر، وبقيت الكتلة ثابتة عند تركيز ٠٫٣ مول/لتر؛ ماذا يعني ذلك؟","options":["التركيز صفر","البطاطس ميتة","الجهد المائي لخلايا البطاطس يساوي الجهد المائي لمحلول ٠٫٣ مول/لتر","توقّف الماء عن الحركة تمامًا"],"answer":2,"why":"ثبات الكتلة يدل على تساوي الجهد المائي داخل الخلايا وخارجها (صافي حركة الماء = صفر)."},{"type":"mcq","q":"في تجربة أنبوب زجاجي به قطنة أمونيا وقطنة حمض هيدروكلوريك، تتكون سحابة بيضاء أقرب للحمض لأن:","options":["جزيئات الحمض أخف","الحرارة أقل عند الأمونيا","جزيئات الأمونيا أخف فتنتشر أسرع","لا يوجد انتشار"],"answer":2,"why":"الجزيئات الأصغر والأخف كتلة تنتشر بسرعة أكبر."},{"type":"essay","q":"فسّر: لماذا تحتاج الكائنات الكبيرة كالإنسان إلى جهاز دوري لنقل المواد ولا تكتفي بالانتشار وحده؟","model":"لأن المسافة بين سطح الجسم والخلايا العميقة كبيرة جدًّا، والانتشار يصبح بطيئًا جدًّا عبر المسافات الطويلة، لذا ينقل الدم المواد بسرعة قرب الخلايا ليحدث الانتشار عبر مسافة قصيرة."},{"type":"essay","q":"فسّر علميًا لماذا يطيل حفظ الفاكهة في محلول سكري مركّز (المربّى) من مدة صلاحيتها.","model":"المحلول السكري المركّز ذو جهد مائي منخفض جدًّا، فإذا سقطت عليه بكتيريا أو فطريات خرج منها الماء بالأسموزية فتجفّ وتموت ولا تفسد الطعام."}]},"test":[{"type":"mcq","q":"الانتشار هو صافي حركة الجزيئات من:","options":["التركيز الأقل إلى الأعلى","الصلب إلى السائل فقط","البارد إلى الساخن","التركيز الأعلى إلى الأقل"],"answer":3,"why":"الانتشار يتحرك دائمًا مع منحدر التركيز."},{"type":"mcq","q":"أيُّ مادةٍ تنتقل تحديدًا في عملية الأسموزية؟","options":["الماء فقط","السكر فقط","الأكسجين","البروتين"],"answer":0,"why":"الأسموزية حالة خاصة من الانتشار تختص بجزيئات الماء."},{"type":"mcq","q":"أيُّ عاملٍ مما يأتي يسرّع معدل الانتشار؟","options":["رفع درجة الحرارة","تقليل مساحة السطح","خفض الحرارة","زيادة المسافة"],"answer":0,"why":"رفع الحرارة يزيد الطاقة الحركية للجزيئات."},{"type":"mcq","q":"أيُّ محلولٍ له أعلى جهد مائي؟","options":["ماء البحر","الماء المقطّر النقي","محلول ملحي مركّز","شراب سكري ثقيل"],"answer":1,"why":"الماء النقي يحتوي على أعلى تركيز من جزيئات الماء الحرة."},{"type":"mcq","q":"كيف يدخل ثاني أكسيد الكربون إلى ورقة النبات نهارًا؟","options":["بضخ القلب","بالانتشار عبر الثغور","بالهضم","عبر الجذور"],"answer":1,"why":"تركيزه في الهواء أعلى من داخل الورقة فينتشر عبر الثغور."},{"type":"mcq","q":"عند وضع خلية نباتية في ماء نقي فإنها:","options":["تذبل","تنفجر","تمتلئ وتصبح صلبة","تتبلزم"],"answer":2,"why":"يدخل الماء فتنتفخ ويحميها الجدار الخلوي."},{"type":"mcq","q":"عند رش العطر في غرفة، تنتشر رائحته بفضل:","options":["التمثيل الضوئي","التنفس الخلوي","الحركة العشوائية لجزيئات الغاز","الجاذبية فقط"],"answer":2,"why":"جزيئات الغاز تتحرك عشوائيًا في كل الاتجاهات."},{"type":"mcq","q":"ما نوع الغشاء الذي تحدث عبره الأسموزية؟","options":["جدار صلب غير منفذ","ورق ترشيح واسع","زجاج","غشاء شبه منفذ (منفذ جزئيًا)"],"answer":3,"why":"يمرّر الماء ويمنع الجزيئات المذابة الكبيرة."},{"type":"mcq","q":"أيُّ التغيرات الآتية يبطئ سرعة الانتشار عبر غشاء؟","options":["زيادة فرق التركيز","رفع درجة الحرارة","زيادة مساحة السطح","زيادة سمك الغشاء (المسافة)"],"answer":3,"why":"زيادة المسافة تجعل الجزيئات تستغرق وقتًا أطول للعبور."},{"type":"mcq","q":"وُضعت قطعة بطاطس كتلتها ٥ جم في ماء مقطر فأصبحت ٥٫٦ جم؛ السبب هو:","options":["دخول الماء لخلايا البطاطس بالأسموزية","خروج الماء منها","تبخّر الماء","دخول السكر إليها"],"answer":0,"why":"الجهد المائي للماء المقطر أعلى من خلايا البطاطس فدخل الماء."},{"type":"mcq","q":"لماذا تحتوي الأمعاء الدقيقة على آلاف الخملات الدقيقة؟","options":["لزيادة مساحة سطح الانتشار والامتصاص","لإنتاج الأكسجين","لتبريد الطعام","لتقليل مساحة السطح"],"answer":0,"why":"زيادة مساحة السطح تسرّع انتقال الغذاء المهضوم للدم."},{"type":"mcq","q":"ما الحالة التي تصبح عليها الخلية النباتية عندما يبتعد غشاؤها عن جدارها الخلوي؟","options":["الانفجار","البلزمة","الامتلاء","الانقسام"],"answer":1,"why":"البلزمة تنتج عن خروج الماء في محلول مركّز."},{"type":"tf","q":"عندما يتساوى تركيز المادة في كل أنحاء الكوب تتوقّف الجزيئات تمامًا عن الحركة.","answer":false,"why":"تستمر الجزيئات بالحركة العشوائية، لكن صافي الانتشار فقط يصبح صفرًا"},{"type":"tf","q":"الخلية النباتية والخلية الحيوانية تنفجران معًا عند وضعهما في ماء نقي.","answer":false,"why":"تنفجر الحيوانية فقط، أما النباتية فيحميها الجدار الخلوي السليلوزي"},{"type":"tf","q":"يحتاج الانتشار إلى طاقة كيميائية من الميتوكوندريا ليحدث.","answer":false,"why":"لأنه عملية سلبية تعتمد على الطاقة الحركية الذاتية للجزيئات"},{"type":"tf","q":"عند إضافة كمية كبيرة من السماد الكيميائي حول جذور نبات قد يذبل النبات ويموت.","answer":true,"why":"لأن زيادة الأملاح تخفض الجهد المائي للتربة فيخرج الماء من الجذور للتربة بالأسموزية"},{"type":"tfr","q":"كلما كان منحدر التركيز أكبر، كان معدل الانتشار أسرع.","answer":true,"reasons":["لأن المنحدر لا يؤثر","لأن الجزيئات تبطئ","لأن الفارق الكبير في التركيز يزيد صافي عدد الجزيئات المنتقلة في الثانية"],"reason":2},{"type":"tfr","q":"يمتص النبات الماء من التربة لأن الجهد المائي في التربة أعلى من الجهد المائي في خلايا الشعيرات الجذرية.","answer":true,"reasons":["لأن الجذر يضخ الماء للخارج","لأن التربة أكثر تركيزًا بالأملاح من الجذر","فينتقل الماء تلقائيًا من التربة إلى الجذر بالأسموزية"],"reason":2},{"type":"tfr","q":"الانتشار في الغازات أسرع عمومًا من الانتشار في السوائل.","answer":true,"reasons":["لأن جزيئات الغاز أبعد عن بعضها وتتحرك بسرعة أكبر وحرية أعلى من جزيئات السائل","لأن جزيئات الغاز أثقل","لأن السوائل لا تنتشر"],"reason":0},{"type":"tfr","q":"كلما أذبنا سكرًا أكثر في كوب ماء، ارتفع الجهد المائي للمحلول.","answer":false,"reasons":["إذابة المزيد من السكر تقلل تركيز جزيئات الماء الحرة فينخفض الجهد المائي","يزداد الماء الحر","يبقى الجهد المائي ثابتًا"],"reason":0},{"type":"essay","q":"اذكر العوامل الأربعة التي تؤثر في سرعة الانتشار.","model":"مساحة السطح، درجة الحرارة، منحدر التركيز (فرق التركيز)، ومسافة الانتشار."},{"type":"essay","q":"عرّف الأسموزية تعريفًا علميًا دقيقًا.","model":"هي صافي حركة (انتشار) جزيئات الماء من منطقة ذات جهد مائي أعلى إلى منطقة ذات جهد مائي أقل عبر غشاء شبه منفذ."},{"type":"essay","q":"اشرح اتجاه انتشار كلٍّ من الأكسجين وثاني أكسيد الكربون في الحويصلات الهوائية بالرئة.","model":"ينتشر الأكسجين من الحويصلات (تركيز أعلى) إلى الدم (تركيز أقل)، وينتشر ثاني أكسيد الكربون من الدم (تركيز أعلى) إلى الحويصلات (تركيز أقل)."},{"type":"essay","q":"لماذا لا يُحقن المريض بالماء المقطّر النقي مباشرة في الوريد؟","model":"لأن الجهد المائي للماء النقي أعلى من خلايا الدم الحمراء، فيدخل الماء إليها بالأسموزية فتنتفخ وتنفجر."},{"type":"essay","q":"فسّر: لماذا تحتاج الكائنات الكبيرة كالإنسان إلى جهاز دوري لنقل المواد ولا تكتفي بالانتشار وحده؟","model":"لأن المسافة بين سطح الجسم والخلايا العميقة كبيرة جدًّا، والانتشار يصبح بطيئًا جدًّا عبر المسافات الطويلة، لذا ينقل الدم المواد بسرعة قرب الخلايا ليحدث الانتشار عبر مسافة قصيرة."}]},
  {"id":"g9-bio-1-u3","grade":"g9","subject":"biology","term":1,"title":"الوحدة الثالثة: الجُزيئات الحيوية","levels":{"easy":[{"type":"mcq","q":"ما المادة الأكثر وفرة في جسم الإنسان؟","options":["النشا","الماء","الحديد","الدهون"],"answer":1,"why":"يشكّل الماء ٧٠–٨٠٪ من كتلة الجسم."},{"type":"mcq","q":"ما العناصر الكيميائية المكوّنة للكربوهيدرات؟","options":["Fe و O","H و N فقط","C و H و O","C و N فقط"],"answer":2,"why":"الكربون والهيدروجين والأكسجين."},{"type":"mcq","q":"كم عدد الأحماض الدهنية في جزيء الدهن الواحد؟","options":["١","٢","٦","٣"],"answer":3,"why":"جزيء جليسرول واحد + ٣ أحماض دهنية."},{"type":"mcq","q":"ما الوحدة البنائية للبروتينات؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","الماء"],"answer":0,"why":"البروتينات سلاسل طويلة من الأحماض الأمينية."}],"medium":[{"type":"mcq","q":"ما الدور الذي يؤديه الماء في عملية الإخراج عبر الكليتين؟","options":["بناء العظام","إذابة اليوريا والأملاح الزائدة لطرحها في البول","إنتاج الأكسجين","تخزين النشا"],"answer":1,"why":"الماء يذيب الفضلات السامة ليسهل إخراجها."},{"type":"mcq","q":"أيُّ لونٍ في اختبار بندكت يدلّ على أعلى تركيز من الجلوكوز؟","options":["الأزرق","الأخضر","الأحمر الطوبي","البني المصفر"],"answer":2,"why":"تدرج الألوان من الأزرق (صفر) حتى الأحمر الطوبي (تركيز عالٍ)."},{"type":"mcq","q":"ما وظيفة الدهون المحيطة بالكليتين والقلب؟","options":["هضم الطعام","التمثيل الضوئي","نقل الأكسجين","حمايتها من الصدمات"],"answer":3,"why":"تعمل كوسادة واقية للأعضاء الحساسة."},{"type":"tfr","q":"تحدث التفاعلات الكيميائية في السيتوبلازم بشكل طبيعي حتى عند غياب الماء تمامًا.","answer":false,"reasons":["لأن المواد المتفاعلة يجب أن تكون مذابة في الماء لتتفاعل داخل السيتوبلازم","لأن السيتوبلازم صلب","لأن الماء يوقف التفاعلات"],"reason":0},{"type":"tfr","q":"النشا يذوب بسهولة في الماء البارد وطعمه حلو كالجلوكوز.","answer":false,"reasons":["لأن النشا سكر متعدد جزيئاته ضخمة لا تذوب في الماء وليس له طعم حلو","لأن النشا سكر أحادي","لأنه يذوب فورًا"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا يُعدّ الماء مناسبًا جدًّا لتبريد جسم الإنسان عند ارتفاع الحرارة؟","options":["لأن الماء أثقل من الدهون","لأن الماء يمنع التنفس","لأن الماء يتجمد على الجلد","لأن تبخّر العرق يمتص طاقة حرارية كبيرة من الجلد"],"answer":3,"why":"تبخّر الماء يسحب الحرارة الكامنة من الجلد فيبرّده."},{"type":"mcq","q":"أعطت عينة غذاء أزرق مسود مع اليود، وبقيت زرقاء مع بندكت بالتسخين؛ ماذا تحتوي؟","options":["تحتوي على نشا ولا تحتوي على سكر مختزل","تحتوي على جلوكوز فقط","تحتوي على كليهما","خالية منهما"],"answer":0,"why":"إيجابية لليود (نشا) وسلبية لبندكت (لا سكر مختزل)."},{"type":"mcq","q":"لماذا تتكوّن طبقة بيضاء معكّرة عند صبّ خليط الإيثانول والزيت في الماء؟","options":["لأن الماء يذيب الزيت تمامًا","لأن الزيت لا يذوب في الماء فينفصل كقطيرات مجهرية مشتّتة للضوء","لأن الزيت يتفاعل كيميائيًا ليكوّن نشا","لأن الإيثانول يتجمد"],"answer":1,"why":"تكوّن القطيرات الدقيقة العالقة في الماء هو ما يسمى المستحلب."},{"type":"essay","q":"فسّر: لماذا يموت الإنسان بسبب العطش أسرع بكثير من الموت بسبب الجوع؟","model":"لأن الماء يشكّل ٧٠–٨٠٪ من الجسم وتعتمد عليه فورًا التفاعلات الخلوية وحجم الدم ونقل المواد وإخراج السموم وتنظيم الحرارة، بينما يملك الجسم مخزونًا من الدهون والجلايكوجين يكفي لأيام."},{"type":"essay","q":"قارن بين النشا والجلايكوجين والسليلوز من حيث: الوحدة البنائية، ومكان الوجود، والوظيفة.","model":"الوحدة البنائية للثلاثة هي الجلوكوز. النشا في النبات لتخزين الطاقة، الجلايكوجين في كبد وعضلات الحيوان لتخزين الطاقة، والسليلوز في الجدار الخلوي النباتي للدعامة."}]},"test":[{"type":"mcq","q":"ما المادة الأكثر وفرة في جسم الإنسان؟","options":["النشا","الماء","الحديد","الدهون"],"answer":1,"why":"يشكّل الماء ٧٠–٨٠٪ من كتلة الجسم."},{"type":"mcq","q":"ما العناصر الكيميائية المكوّنة للكربوهيدرات؟","options":["Fe و O","H و N فقط","C و H و O","C و N فقط"],"answer":2,"why":"الكربون والهيدروجين والأكسجين."},{"type":"mcq","q":"كم عدد الأحماض الدهنية في جزيء الدهن الواحد؟","options":["١","٢","٦","٣"],"answer":3,"why":"جزيء جليسرول واحد + ٣ أحماض دهنية."},{"type":"mcq","q":"ما الوحدة البنائية للبروتينات؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","الماء"],"answer":0,"why":"البروتينات سلاسل طويلة من الأحماض الأمينية."},{"type":"mcq","q":"ممَّ تتكوّن الأنزيمات كيميائيًا؟","options":["من الماء","من البروتينات","من الدهون","من النشا"],"answer":1,"why":"جميع الأنزيمات بروتينات."},{"type":"mcq","q":"أيُّ جزيءٍ مما يأتي يُعدّ الوحدة البنائية للنشا؟","options":["الحمض الأميني","اليوريا","الجلوكوز","الجليسرول"],"answer":2,"why":"النشا سلسلة طويلة من جزيئات الجلوكوز."},{"type":"mcq","q":"ما الكاشف المستخدم للكشف عن وجود النشا؟","options":["الإيثانول","محلول بندكت","محلول بيوريت","محلول اليود"],"answer":3,"why":"اليود يتحول لأزرق مسود مع النشا."},{"type":"mcq","q":"في أي سائلٍ تذوب الدهون في اختبار الكشف عنها؟","options":["الإيثانول","اليود","الماء المقطّر","بندكت"],"answer":0,"why":"تذوب الدهون في الإيثانول ولا تذوب في الماء."},{"type":"mcq","q":"ما الكاشف المستخدم للكشف عن البروتينات؟","options":["محلول بندكت","كاشف بيوريت","محلول اليود","الإيثانول"],"answer":1,"why":"بيوريت يعطي لونًا بنفسجيًا مع البروتين."},{"type":"mcq","q":"ما الأنزيم الذي يحوّل النشا إلى مالتوز؟","options":["البروتياز","الليبيز","الأميليز","الكاتاليز"],"answer":2,"why":"الأميليز في اللعاب والبنكرياس يهضم النشا."},{"type":"mcq","q":"كيف ينقل الدم الجلوكوز واليوريا في الجسم؟","options":["في العظام","بلا ماء","على هيئة غازات","مذابة في ماء بلازما الدم"],"answer":3,"why":"الماء هو المذيب الرئيس في بلازما الدم."},{"type":"mcq","q":"أين يُخزَّن الجلايكوجين في جسم الإنسان؟","options":["في الكبد والعضلات","في العظام","في الجدار الخلوي","في الرئتين"],"answer":0,"why":"يُخزّن الجلوكوز الزائد كجلايكوجين في الكبد والعضلات."},{"type":"tf","q":"تحدث التفاعلات الكيميائية في السيتوبلازم بشكل طبيعي حتى عند غياب الماء تمامًا.","answer":false,"why":"لأن المواد المتفاعلة يجب أن تكون مذابة في الماء لتتفاعل داخل السيتوبلازم"},{"type":"tf","q":"النشا يذوب بسهولة في الماء البارد وطعمه حلو كالجلوكوز.","answer":false,"why":"لأن النشا سكر متعدد جزيئاته ضخمة لا تذوب في الماء وليس له طعم حلو"},{"type":"tf","q":"تحتاج تجربة الكشف عن الدهون بالإيثانول إلى تسخينها فوق لهب بنسن.","answer":false,"why":"لا تحتاج للتسخين أبدًا، كما أن الإيثانول سريع الاشتعال ويشكّل خطرًا قرب اللهب"},{"type":"tf","q":"يحتاج اختبار بيوريت إلى تسخين العينة في حمام مائي لتظهر النتيجة.","answer":false,"why":"لا يحتاج اختبار بيوريت إلى تسخين، بل يظهر اللون البنفسجي في حرارة الغرفة"},{"type":"tfr","q":"عند تبريد الأنزيم إلى ٠°م يتمسّخ الأنزيم ولا يعود للعمل إذا أعدنا تدفئته.","answer":false,"reasons":["التبريد يبطئ الحركة فقط دون تمسّخ، فيعود الأنزيم للعمل عند تدفئته","لأن الأنزيم يموت بالبرد","لأن التبريد يكسّر الروابط"],"reason":0},{"type":"tfr","q":"يتكوّن جزيء الدهن من جزيء جليسرول واحد مرتبط بثلاثة أحماض دهنية.","answer":true,"reasons":["لأنه يتكون من جلوكوز","هذا هو التركيب البنائي الأساسي للدهون والزيوت","لأنه يتكون من أحماض أمينية"],"reason":1},{"type":"tfr","q":"يُستخدم السليلوز في بناء جدران الخلايا النباتية.","answer":true,"reasons":["لأنه من الدهون","لأنه يتكون من ألياف جلوكوز قوية تمنح الخلية النباتية الدعامة","لأنه يُخزن في الكبد"],"reason":1},{"type":"tfr","q":"تُخزّن الثدييات البحرية كالحيتان والفقمات طبقةً سميكةً من الدهون تحت جلدها للعزل الحراري.","answer":true,"reasons":["لأن الدهون تبرّد الجسم","لأن الدهون موصل رديء للحرارة فتمنع فقدان حرارة الجسم في المياه المتجمدة","لأنها لا تستخدم الطاقة"],"reason":1},{"type":"essay","q":"اذكر أربع وظائف للماء في أجسام الكائنات الحية.","model":"١) مذيب للتفاعلات الكيميائية في الخلايا. ٢) نقل المواد في الدم والنبات. ٣) المساعدة في الهضم. ٤) إذابة الفضلات للإخراج وتنظيم الحرارة بالتعرق."},{"type":"essay","q":"اشرح خطوات إجراء اختبار بندكت للكشف عن الجلوكوز في عينة غذائية.","model":"نضع العينة السائلة في أنبوب اختبار، ونضيف كمية مناسبة من محلول بندكت الأزرق، ثم نسخّن الأنبوب في حمام مائي ساخن (٨٠°م) لبضع دقائق ونلاحظ تغيّر اللون إلى أخضر أو أصفر أو برتقالي أو أحمر طوبي."},{"type":"essay","q":"اشرح خطوات إجراء اختبار مستحلب الإيثانول للكشف عن الدهون في بذور الفول السوداني.","model":"نهرس البذور ونضيف إليها إيثانول ونرجّ جيدًا لإذابة الدهون، ثم نصبّ السائل الصافي في أنبوب به ماء مقطّر ونرجّه؛ فيظهر مستحلب أبيض معكّر."},{"type":"essay","q":"اذكر أربع وظائف للبروتينات في جسم الإنسان.","model":"١) النمو وبناء الخلايا وإصلاح الأنسجة. ٢) تكوين الأنزيمات. ٣) تكوين الأجسام المضادة. ٤) نقل الأكسجين (الهيموجلوبين) وبعض الهرمونات كالأنسولين."},{"type":"essay","q":"اشرح آلية «القفل والمفتاح» لعمل الأنزيمات.","model":"يمتلك الأنزيم موقعًا نشطًا ذا شكل محدد يتطابق فقط مع المادة المتفاعلة الخاصة به، فيرتبط بها ليكوّن معقد الأنزيم والمادة، ثم تتحرر النواتج ويبقى الأنزيم سليمًا."}]},
  {"id":"g9-bio-1-u4","grade":"g9","subject":"biology","term":1,"title":"الوحدة الرابعة: التغذية في الإنسان","levels":{"easy":[{"type":"mcq","q":"كم عدد المكونات الرئيسة للنظام الغذائي المتوازن؟","options":["٣","١٠","٧","٥"],"answer":2,"why":"كربوهيدرات، دهون، بروتينات، فيتامينات، أملاح، ألياف، ماء."},{"type":"mcq","q":"أين تُخزَّن الطاقة الزائدة عن حاجة الجسم على المدى الطويل؟","options":["على هيئة ماء","على هيئة ألياف","تختفي فورًا","على هيئة دهون في الجسم"],"answer":3,"why":"الطاقة الفائضة تُخزّن كدهون فتسبب السمنة."},{"type":"mcq","q":"أيُّ طعامٍ غنيٌّ جدًّا بفيتامين C؟","options":["السكر","الأرز الأبيض","الزبدة","البرتقال والليمون"],"answer":3,"why":"الحمضيات والفواكه الطازجة غنية بفيتامين C."},{"type":"mcq","q":"أيُّ مرضٍ من الآتي يرتبط مباشرةً بالسُّمنة؟","options":["السكري من النوع الثاني","عمى الألوان","الإسقربوط","الكساح"],"answer":0,"why":"السمنة ترفع خطر السكري وأمراض القلب وارتفاع الضغط."}],"medium":[{"type":"mcq","q":"ما دور فيتامين D في الجسم؟","options":["منع الإمساك","نقل الأكسجين","المساعدة في امتصاص الكالسيوم لبناء العظام","هضم النشا"],"answer":2,"why":"بدون فيتامين D لا يمتص الجسم الكالسيوم بكفاءة."},{"type":"mcq","q":"ما السبب الرئيس لمرض «كواشيوركور» عند بعض الأطفال في المناطق الفقيرة؟","options":["زيادة الدهون","زيادة الفيتامينات","شرب الماء","نقص حاد في البروتين"],"answer":3,"why":"نقص البروتين يسبب بطء النمو وانتفاخ البطن وضعف العضلات."},{"type":"mcq","q":"أيُّ شخصٍ مما يأتي يحتاج أكبر كمية يومية من الطاقة؟","options":["طفل رضيع","مسنّ قليل الحركة","موظف مكتبي","شاب رياضي يتدرّب ٣ ساعات يوميًا"],"answer":3,"why":"النشاط العضلي العالي والكتلة العضلية الكبيرة يرفعان استهلاك الطاقة."},{"type":"tfr","q":"الألياف الغذائية تُهضم في المعدة وتُعطي طاقةً عاليةً للجسم.","answer":false,"reasons":["الإنسان لا يهضم الألياف (السليلوز) ولا تعطي طاقة، لكنها تحرّك الأمعاء وتمنع الإمساك","لأنها تتحول لجلوكوز فورًا","لأنها نوع من الدهون"],"reason":0},{"type":"tfr","q":"سوء التغذية يصيب الأشخاص النحيفين فقط ولا يصيب المصابين بالسمنة.","answer":false,"reasons":["سوء التغذية يعني اختلال توازن الغذاء سواء بالنقص أو بالإفراط كالسمنة","لأن النحافة فقط مرض","لأن السمنة دليل صحة دائمًا"],"reason":0}],"hard":[{"type":"mcq","q":"طفل لا يتعرض للشمس أبدًا ويعاني من تقوّس الساقين ولين العظام؛ ما الفيتامين الناقص لديه غالبًا؟","options":["فيتامين D","فيتامين C","الحديد","الألياف"],"answer":0,"why":"نقص فيتامين D يمنع امتصاص الكالسيوم ويسبّب الكساح."},{"type":"mcq","q":"شخص يتناول وجبات سريعة يوميًا ولا يأكل فواكه؛ أيُّ حالتين قد تجتمعان لديه في وقت واحد؟","options":["توازن غذائي تام","السُّمنة مع نقص بعض الفيتامينات والألياف","زيادة الألياف فقط","الهزال فقط"],"answer":1,"why":"الوجبات السريعة عالية الطاقة وفقيرة بالفيتامينات والألياف، فتجمع السمنة مع نقص العناصر!"},{"type":"mcq","q":"أيُّ وجبةٍ مما يأتي تفتقر بشدة إلى الألياف الغذائية وفيتامين C؟","options":["سمك + أرز بني + سلطة خضراء + برتقال","برجر بالجبن + بطاطس مقلية + مشروب غازي","دجاج مشوي + خضار مطهوة + تفاحة","عدس + خبز قمح كامل + خضار طازجة"],"answer":1,"why":"الوجبات السريعة فقيرة بالخضار والفواكه الطازجة والحبوب الكاملة."},{"type":"essay","q":"لماذا كان البحّارة قديمًا يصابون بنزيف اللثة وتساقط الأسنان في الرحلات البحرية الطويلة، وكيف عولج ذلك؟","model":"بسبب غياب الفواكه والخضار الطازجة فحدث نقص حاد في فيتامين C (مرض الإسقربوط)، وعولج بتزويد السفن بالليمون والحمضيات."},{"type":"essay","q":"قارن بين «كواشيوركور» و«الهزال (الماراسمس)» من حيث السبب الرئيس.","model":"كواشيوركور ينتج أساسًا عن نقص حاد في البروتين مع توفر بعض الكربوهيدرات، بينما الهزال (الماراسمس) ينتج عن نقص شديد في الطاقة (الكربوهيدرات والدهون) والبروتين معًا."}]},"test":[{"type":"mcq","q":"كم عدد المكونات الرئيسة للنظام الغذائي المتوازن؟","options":["٣","١٠","٧","٥"],"answer":2,"why":"كربوهيدرات، دهون، بروتينات، فيتامينات، أملاح، ألياف، ماء."},{"type":"mcq","q":"أين تُخزَّن الطاقة الزائدة عن حاجة الجسم على المدى الطويل؟","options":["على هيئة ماء","على هيئة ألياف","تختفي فورًا","على هيئة دهون في الجسم"],"answer":3,"why":"الطاقة الفائضة تُخزّن كدهون فتسبب السمنة."},{"type":"mcq","q":"أيُّ طعامٍ غنيٌّ جدًّا بفيتامين C؟","options":["السكر","الأرز الأبيض","الزبدة","البرتقال والليمون"],"answer":3,"why":"الحمضيات والفواكه الطازجة غنية بفيتامين C."},{"type":"mcq","q":"أيُّ مرضٍ من الآتي يرتبط مباشرةً بالسُّمنة؟","options":["السكري من النوع الثاني","عمى الألوان","الإسقربوط","الكساح"],"answer":0,"why":"السمنة ترفع خطر السكري وأمراض القلب وارتفاع الضغط."},{"type":"mcq","q":"ما العنصر المعدني الأساسي لبناء العظام والأسنان؟","options":["الكالسيوم","اليود","الحديد","النيتروجين"],"answer":0,"why":"الكالسيوم يمنح العظام والأسنان الصلابة."},{"type":"mcq","q":"أيُّ سلوكٍ يساعد في الوقاية من السُّمنة؟","options":["الإكثار من المشروبات الغازية","ممارسة الرياضة وتقليل السكريات","الجلوس طوال اليوم","تجاهل الخضار"],"answer":1,"why":"النشاط البدني والغذاء المتوازن يوازنان الطاقة."},{"type":"mcq","q":"نقص الحديد في الغذاء يؤدي إلى الإصابة بـ:","options":["الإسقربوط","فقر الدم (الأنيميا)","الكساح","السمنة"],"answer":1,"why":"الحديد ضروري لصنع الهيموجلوبين في خلايا الدم الحمراء."},{"type":"mcq","q":"ما الشرايين التي تضيق عند تراكم الدهون وتسبّب أمراض القلب التاجية؟","options":["القصبة الهوائية","المريء","الشرايين التاجية المغذّية لعضلة القلب","أوعية الخشب"],"answer":2,"why":"الشرايين التاجية تزوّد عضلة القلب بالأكسجين والغذاء."},{"type":"mcq","q":"ما دور فيتامين D في الجسم؟","options":["منع الإمساك","نقل الأكسجين","المساعدة في امتصاص الكالسيوم لبناء العظام","هضم النشا"],"answer":2,"why":"بدون فيتامين D لا يمتص الجسم الكالسيوم بكفاءة."},{"type":"mcq","q":"ما السبب الرئيس لمرض «كواشيوركور» عند بعض الأطفال في المناطق الفقيرة؟","options":["زيادة الدهون","زيادة الفيتامينات","شرب الماء","نقص حاد في البروتين"],"answer":3,"why":"نقص البروتين يسبب بطء النمو وانتفاخ البطن وضعف العضلات."},{"type":"mcq","q":"أيُّ شخصٍ مما يأتي يحتاج أكبر كمية يومية من الطاقة؟","options":["طفل رضيع","مسنّ قليل الحركة","موظف مكتبي","شاب رياضي يتدرّب ٣ ساعات يوميًا"],"answer":3,"why":"النشاط العضلي العالي والكتلة العضلية الكبيرة يرفعان استهلاك الطاقة."},{"type":"mcq","q":"ماذا يحدث عندما تتساوى الطاقة المتناولة يوميًا مع الطاقة المستهلكة؟","options":["يبقى وزن الجسم ثابتًا","يصاب الشخص بالكساح","يزداد الوزن بسرعة","ينقص الوزن بشدة"],"answer":0,"why":"توازن الكفتين يحافظ على ثبات الوزن الصحي."},{"type":"tf","q":"الألياف الغذائية تُهضم في المعدة وتُعطي طاقةً عاليةً للجسم.","answer":false,"why":"الإنسان لا يهضم الألياف (السليلوز) ولا تعطي طاقة، لكنها تحرّك الأمعاء وتمنع الإمساك"},{"type":"tf","q":"سوء التغذية يصيب الأشخاص النحيفين فقط ولا يصيب المصابين بالسمنة.","answer":false,"why":"سوء التغذية يعني اختلال توازن الغذاء سواء بالنقص أو بالإفراط كالسمنة"},{"type":"tf","q":"التعرّض المعتدل لأشعة الشمس يساعد الجلد على تصنيع فيتامين D.","answer":true,"why":"لأن الأشعة فوق البنفسجية في ضوء الشمس تحفّز الجلد على إنتاج فيتامين D"},{"type":"tf","q":"قلة الحركة والجلوس الطويل أمام الشاشات يسهمان في زيادة معدلات السمنة.","answer":true,"why":"لأنهما يقللان الطاقة المستهلكة فيتراكم فائض الطاقة كدهون"},{"type":"tfr","q":"تحتاج المرأة الحامل إلى زيادة في البروتين والكالسيوم والحديد لدعم نمو الجنين.","answer":true,"reasons":["لأن الجنين لا يحتاج كالسيوم","لأن الحامل تحتاج ماءً فقط","البروتين لبناء أنسجة الجنين، والكالسيوم لعظامه، والحديد للدم والهيموجلوبين"],"reason":2},{"type":"tfr","q":"المشروبات الغازية المحلّاة بالسكر تحتوي على طاقة عالية جدًّا دون فائدة غذائية حقيقية.","answer":true,"reasons":["لأنها خالية من السكر","لأنها غنية بالبروتين","لأنها غنية بالسكر البسيط وتخلو من الفيتامينات والألياف والبروتين، مما يرفع خطر السمنة"],"reason":2},{"type":"tfr","q":"الفتيات في سن المراهقة يحتجن إلى كمية أكبر من الحديد مقارنةً بالفتيان في العمر نفسه.","answer":true,"reasons":["لتعويض الدم المفقود شهريًا خلال الدورة الشهرية والوقاية من فقر الدم","لأن الفتيات لا يحتجن كالسيوم","لأن الحديد يعطي طاقة"],"reason":0},{"type":"tfr","q":"استبدال المشروبات الغازية بالماء والمشي ٣٠ دقيقة يوميًا يساعدان على خفض الوزن تدريجيًا.","answer":true,"reasons":["لأن ذلك يقلل الطاقة الداخلة ويزيد الطاقة المستهلكة فيحرق الجسم الدهون المخزنة","لأنه يسبب فقر الدم","لأنه يزيد الوزن"],"reason":0},{"type":"essay","q":"اذكر أربعة عوامل تجعل حاجة الإنسان اليومية للطاقة تختلف من شخص لآخر.","model":"١) العمر (النمو). ٢) الجنس. ٣) مستوى النشاط البدني. ٤) الحمل والرضاعة."},{"type":"essay","q":"اذكر ثلاثة مخاطر صحية تسبّبها السُّمنة المفرطة.","model":"١) أمراض القلب التاجية. ٢) السكري من النوع الثاني. ٣) ارتفاع ضغط الدم وآلام وتآكل المفاصل."},{"type":"essay","q":"اشرح سبب شعور الشخص المصاب بنقص الحديد (فقر الدم) بالتعب السريع وضيق التنفس.","model":"لأن نقص الحديد يقلّل إنتاج الهيموجلوبين، فيقلّ الأكسجين المنقول إلى الخلايا، مما يخفض معدل التنفس الهوائي وإطلاق الطاقة."},{"type":"essay","q":"اشرح بإيجاز كيف تؤدي الدهون المتراكمة في الشرايين التاجية إلى نوبة قلبية.","model":"تضيق الشرايين وتقلّل تدفق الدم والأكسجين إلى عضلة القلب، وإذا انسد الشريان بجلطة تموت خلايا جزء من عضلة القلب فتحدث النوبة القلبية."},{"type":"essay","q":"لماذا كان البحّارة قديمًا يصابون بنزيف اللثة وتساقط الأسنان في الرحلات البحرية الطويلة، وكيف عولج ذلك؟","model":"بسبب غياب الفواكه والخضار الطازجة فحدث نقص حاد في فيتامين C (مرض الإسقربوط)، وعولج بتزويد السفن بالليمون والحمضيات."}]},
  {"id":"g9-bio-1-u5","grade":"g9","subject":"biology","term":1,"title":"الوحدة الخامسة: التنفس","levels":{"easy":[{"type":"mcq","q":"ما المادة الغذائية الرئيسة التي تتكسر في التنفُّس الخلوي لإطلاق الطاقة؟","options":["الجلوكوز","اليود","الماء","السليلوز"],"answer":0,"why":"الجلوكوز هو الوقود الأساسي للتنفس الخلوي."},{"type":"mcq","q":"ماذا يحدث لمعدل التنفُّس عند الانتقال من الجلوس إلى الجري؟","options":["ينخفض","يرتفع","يبقى ثابتًا","يتوقف"],"answer":1,"why":"تحتاج العضلات لمزيد من الأكسجين لإطلاق الطاقة."},{"type":"mcq","q":"أيُّ نوعٍ من التنفُّس يطلق كمية أكبر بكثير من الطاقة من جزيء جلوكوز واحد؟","options":["التنفُّس اللاهوائي في العضلات","التنفُّس الهوائي","التنفُّس اللاهوائي في الخميرة","كلها متساوية"],"answer":1,"why":"التنفس الهوائي يكسّر الجلوكوز بالكامل فيطلق طاقة كبيرة."},{"type":"mcq","q":"أين ينتقل حمض اللاكتيك عبر الدم ليُفكّك بعد التمرين؟","options":["إلى العين","إلى الجلد","إلى الكبد","إلى المعدة"],"answer":2,"why":"الكبد هو العضو الذي يفكّك حمض اللاكتيك بالأكسجين."}],"medium":[{"type":"mcq","q":"أيٌّ مما يأتي ليس من نواتج التنفُّس اللاهوائي في عضلات الإنسان؟","options":["طاقة قليلة","ثاني أكسيد الكربون","حمض اللاكتيك","لا شيء مما سبق"],"answer":1,"why":"في عضلات الإنسان ينتج حمض اللاكتيك وطاقة قليلة دون CO₂."},{"type":"mcq","q":"كيف يؤثر ارتفاع ثاني أكسيد الكربون في الدم على الرقم الهيدروجيني (pH) للدم؟","options":["يرفعه كثيرًا","يخفضه قليلًا (يزيد الحموضة قليلًا)","لا يؤثر فيه","يجعله صفرًا"],"answer":1,"why":"ذوبان CO₂ في الدم يشكّل حمضًا ضعيفًا فيخفض الـ pH قليلًا."},{"type":"mcq","q":"ما المعادلة الرمزية الموزونة الصحيحة للتنفُّس الهوائي؟","options":["C₆H₁₂O₆ + O₂ → CO₂ + H₂O","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","C₆H₁₂O₆ → 2CO₂","6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂"],"answer":1,"why":"موزونة بـ ٦ جزيئات O₂ و ٦ CO₂ و ٦ H₂O."},{"type":"tfr","q":"تُنتج الخميرة حمض اللاكتيك عند تنفسها لاهوائيًا.","answer":false,"reasons":["تنتج الخميرة إيثانول وثاني أكسيد الكربون، أما حمض اللاكتيك فينتج في عضلات الإنسان","الخميرة لا تتنفس","تنتج الخميرة أكسجينًا"],"reason":0},{"type":"tfr","q":"بمجرد توقّف العدّاء عن الجري يعود معدل تنفسه فورًا في الثانية نفسها إلى معدل الراحة.","answer":false,"reasons":["يستمر التنفس السريع والعميق لعدة دقائق لسداد دَيْن الأكسجين وتفكيك حمض اللاكتيك","لأن القلب يتوقف","لأن الرئتين لا تتوقفان عن الجري"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا يطلق التنفُّس اللاهوائي طاقةً أقل بكثير من التنفُّس الهوائي؟","options":["لأنه لا يستخدم الجلوكوز","لأنه يحدث في البرد فقط","لأن الجلوكوز يتكسّر جزئيًّا فقط وتبقى معظم الطاقة مخزّنة في حمض اللاكتيك أو الإيثانول","لأنه يستهلك أكسجينًا أكثر"],"answer":2,"why":"التكسير غير الكامل للجلوكوز يحرر جزءًا صغيرًا فقط من طاقته."},{"type":"mcq","q":"كان معدل تنفس طالب وقت الراحة ١٥ نفسًا/دقيقة وبحجم ٠٫٥ لتر للنفس، وأصبح أثناء الجري ٣٠ نفسًا/دقيقة وبحجم ١٫٥ لتر؛ كم تضاعف حجم الهواء الداخل في الدقيقة؟","options":["تضاعف مرتين","لم يتغير","تضاعف ٣ مرات","تضاعف ٦ مرات (من ٧٫٥ إلى ٤٥ لتر/دقيقة)"],"answer":3,"why":"وقت الراحة ١٥×٠٫٥ = ٧٫٥ لتر؛ أثناء الجري ٣٠×١٫٥ = ٤٥ لتر ← ٤٥ ÷ ٧٫٥ = ٦ أضعاف!"},{"type":"mcq","q":"في تجربة التنفس اللاهوائي للخميرة في أنبوب اختبار، لماذا نضيف طبقةً رقيقةً من الزيت فوق محلول السكر والخميرة؟","options":["لامتصاص CO₂","لتسخين المحلول","لإعطاء الخميرة غذاءً إضافيًا","لمنع دخول الأكسجين من الهواء لضمان حدوث تنفّس لاهوائي"],"answer":3,"why":"طبقة الزيت تعزل المحلول عن الأكسجين الجوي."},{"type":"essay","q":"قارن في جدول بين التنفُّس الهوائي والتنفُّس اللاهوائي في الإنسان من حيث: الحاجة للأكسجين، النواتج، كمية الطاقة، ومكان الحدوث.","model":"الهوائي: يحتاج O₂، ينتج CO₂ وماء، طاقة كبيرة، في الميتوكوندريا. اللاهوائي: بلا O₂، ينتج حمض اللاكتيك، طاقة قليلة، في السيتوبلازم."},{"type":"essay","q":"فسّر لماذا يستمر «نبض القلب» سريعًا بعد التمرين الشديد تمامًا كما يستمر «معدّل التنفس» سريعًا.","model":"لأن نبض القلب السريع ضروري لنقل حمض اللاكتيك من العضلات إلى الكبد، ونقل الأكسجين الإضافي من الرئتين إلى الكبد لتفكيك الحمض."}]},"test":[{"type":"mcq","q":"ما المادة الغذائية الرئيسة التي تتكسر في التنفُّس الخلوي لإطلاق الطاقة؟","options":["الجلوكوز","اليود","الماء","السليلوز"],"answer":0,"why":"الجلوكوز هو الوقود الأساسي للتنفس الخلوي."},{"type":"mcq","q":"ماذا يحدث لمعدل التنفُّس عند الانتقال من الجلوس إلى الجري؟","options":["ينخفض","يرتفع","يبقى ثابتًا","يتوقف"],"answer":1,"why":"تحتاج العضلات لمزيد من الأكسجين لإطلاق الطاقة."},{"type":"mcq","q":"أيُّ نوعٍ من التنفُّس يطلق كمية أكبر بكثير من الطاقة من جزيء جلوكوز واحد؟","options":["التنفُّس اللاهوائي في العضلات","التنفُّس الهوائي","التنفُّس اللاهوائي في الخميرة","كلها متساوية"],"answer":1,"why":"التنفس الهوائي يكسّر الجلوكوز بالكامل فيطلق طاقة كبيرة."},{"type":"mcq","q":"أين ينتقل حمض اللاكتيك عبر الدم ليُفكّك بعد التمرين؟","options":["إلى العين","إلى الجلد","إلى الكبد","إلى المعدة"],"answer":2,"why":"الكبد هو العضو الذي يفكّك حمض اللاكتيك بالأكسجين."},{"type":"mcq","q":"ما ناتجا التنفُّس الهوائي إلى جانب الطاقة؟","options":["الجلوكوز والنشا","الإيثانول والأكسجين","ثاني أكسيد الكربون والماء","حمض اللاكتيك فقط"],"answer":2,"why":"جلوكوز + أكسجين ← ثاني أكسيد الكربون + ماء."},{"type":"mcq","q":"أيُّ عضلةٍ رئيسةٍ تتلقى إشارات الدماغ لتسريع التنفُّس؟","options":["عضلات اللسان","عضلات الأصابع","عضلات العين","الحجاب الحاجز وعضلات الضلوع"],"answer":3,"why":"انقباض الحجاب الحاجز والعضلات بين الضلوع يتحكم في التهوية."},{"type":"mcq","q":"ماذا يحدث لماء الجير الرائق عند مرور ثاني أكسيد الكربون فيه؟","options":["يتحول إلى أزرق","يتحول إلى بنفسجي","يبقى صافيًا","يتعكّر ويصبح أبيض حليبيًّا"],"answer":3,"why":"تعكّر ماء الجير هو الكشف القياسي عن CO₂."},{"type":"mcq","q":"قِصر «زمن التعافي» بعد التمرين الرياضي يدلّ على:","options":["لياقة بدنية عالية","نقص الحديد","السمنة","ضعف اللياقة"],"answer":0,"why":"الشخص الأكثر لياقة يعود تنفسه ونبضه للطبيعي أسرع."},{"type":"mcq","q":"أيٌّ مما يأتي ليس من نواتج التنفُّس اللاهوائي في عضلات الإنسان؟","options":["طاقة قليلة","ثاني أكسيد الكربون","حمض اللاكتيك","لا شيء مما سبق"],"answer":1,"why":"في عضلات الإنسان ينتج حمض اللاكتيك وطاقة قليلة دون CO₂."},{"type":"mcq","q":"كيف يؤثر ارتفاع ثاني أكسيد الكربون في الدم على الرقم الهيدروجيني (pH) للدم؟","options":["يرفعه كثيرًا","يخفضه قليلًا (يزيد الحموضة قليلًا)","لا يؤثر فيه","يجعله صفرًا"],"answer":1,"why":"ذوبان CO₂ في الدم يشكّل حمضًا ضعيفًا فيخفض الـ pH قليلًا."},{"type":"mcq","q":"ما المعادلة الرمزية الموزونة الصحيحة للتنفُّس الهوائي؟","options":["C₆H₁₂O₆ + O₂ → CO₂ + H₂O","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","C₆H₁₂O₆ → 2CO₂","6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂"],"answer":1,"why":"موزونة بـ ٦ جزيئات O₂ و ٦ CO₂ و ٦ H₂O."},{"type":"mcq","q":"لماذا يرتفع معدل نبض القلب أثناء التمرين الرياضي؟","options":["لإيقاف التنفس","لتقليل تدفق الدم","لضخ الدم أسرع ونقل الأكسجين والجلوكوز للعضلات وإزالة CO₂","لتبريد العظام"],"answer":2,"why":"تسارع الدم يواكب الطلب العالي للعضلات."},{"type":"tf","q":"تُنتج الخميرة حمض اللاكتيك عند تنفسها لاهوائيًا.","answer":false,"why":"تنتج الخميرة إيثانول وثاني أكسيد الكربون، أما حمض اللاكتيك فينتج في عضلات الإنسان"},{"type":"tf","q":"بمجرد توقّف العدّاء عن الجري يعود معدل تنفسه فورًا في الثانية نفسها إلى معدل الراحة.","answer":false,"why":"يستمر التنفس السريع والعميق لعدة دقائق لسداد دَيْن الأكسجين وتفكيك حمض اللاكتيك"},{"type":"tf","q":"في تجربة انطلاق الحرارة من البذور النابتة نغسل البذور بمطهّر خفيف قبل وضعها في الترمس.","answer":true,"why":"لقتل البكتيريا والفطريات على سطح البذور حتى نضمن أن الحرارة ناتجة عن تنفس البذور وحدها"},{"type":"tf","q":"يزداد عمق التنفُّس أثناء الرياضة ليدخل حجم أكبر من الهواء في كل نفس.","answer":true,"why":"بذلك يزداد الأكسجين الواصل للحويصلات في كل نفس إلى جانب زيادة عدد الأنفاس"},{"type":"tfr","q":"التمثيل الضوئي والتنفُّس الهوائي هما نفس العملية بالاتجاه نفسه.","answer":false,"reasons":["لأنهما يطلقان ثاني أكسيد الكربون","لأنهما يحدثان في الميتوكوندريا","بل هما متعاكسان تقريبًا؛ التنفس الهوائي يستهلك جلوكوز وأكسجين ويطلق طاقة، بينما التمثيل الضوئي يصنع الجلوكوز والأكسجين باستخدام الضوء"],"reason":2},{"type":"tfr","q":"يراقب الدماغ تركيز CO₂ وحموضة الدم لتنظيم معدل التنفُّس تلقائيًا.","answer":true,"reasons":["لأن المعدة هي التي تنظم التنفس","لأن التنفس لا يتأثر بـ CO₂","وهذا يضمن مطابقة كمية الهواء الداخل لحاجة الخلايا الفعلية"],"reason":2},{"type":"tfr","q":"يُعدّ التنفُّس الهوائي تفاعلًا محفّزًا بالأنزيمات داخل الخلايا.","answer":true,"reasons":["لأن سلسلة تفاعلات التنفس تعتمد على أنزيمات متخصصة، لذا يتأثر معدل التنفس بدرجة الحرارة","لأنه يحدث بلا أنزيمات","لأنه احتراق مباشر بلهب"],"reason":0},{"type":"tfr","q":"في سباق الماراثون الطويل (٤٢ كم) يعتمد العدّاء أساسًا على التنفُّس الهوائي وليس اللاهوائي وحده.","answer":true,"reasons":["لأن التنفس اللاهوائي يطلق طاقة قليلة ويراكم حمض اللاكتيك سريعًا فلا يمكن الاستمرار به لساعات","لأن اللاهوائي يعطي طاقة أكبر","لأن الماراثون بلا أكسجين"],"reason":0},{"type":"essay","q":"اذكر أربعة استخدامات للطاقة الناتجة عن التنفُّس الخلوي في جسم الإنسان.","model":"١) انقباض العضلات. ٢) بناء البروتينات. ٣) انقسام الخلايا والنمو. ٤) الحفاظ على ثبات درجة حرارة الجسم، والنقل النشط، ونقل السيالات العصبية."},{"type":"essay","q":"عرّف «دَيْن الأكسجين» واشرح كيف يسدّده الجسم بعد انتهاء التمرين.","model":"هو كمية الأكسجين الإضافية التي يحتاجها الجسم بعد التمرين الشديد لتفكيك حمض اللاكتيك؛ ويُسدد باستمرار التنفس السريع والعميق ونبض القلب السريع لنقل الحمض إلى الكبد وأكسدته."},{"type":"essay","q":"اشرح دور الخميرة في صناعة الخبز.","model":"تتنفس الخميرة لاهوائيًا فتحلّل السكر إلى إيثانول وغاز ثاني أكسيد الكربون؛ وتحتبس فقاعات الغاز داخل العجين فتجعله ينتفخ ويصبح هشًّا، ثم يتبخر الإيثانول في الفرن."},{"type":"essay","q":"لماذا يشعر العدّاء بألم وتعب في عضلات ساقيه في نهاية سباق قصير سريع جدًّا؟","model":"بسبب لجوء العضلات للتنفُّس اللاهوائي وتراكم حمض اللاكتيك فيها."},{"type":"essay","q":"قارن في جدول بين التنفُّس الهوائي والتنفُّس اللاهوائي في الإنسان من حيث: الحاجة للأكسجين، النواتج، كمية الطاقة، ومكان الحدوث.","model":"الهوائي: يحتاج O₂، ينتج CO₂ وماء، طاقة كبيرة، في الميتوكوندريا. اللاهوائي: بلا O₂، ينتج حمض اللاكتيك، طاقة قليلة، في السيتوبلازم."}]},
  {"id":"g9-bio-1-u6","grade":"g9","subject":"biology","term":1,"title":"الوحدة السادسة: التنظيم والاتزان الداخلي في الإنسان","levels":{"easy":[{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ «عضو استجابة» (مستجيبًا)؟","options":["الأنف","العين","العضلة","الأذن"],"answer":2,"why":"المستجيبات هي العضلات والغدد، أما العين والأذن والأنف فأعضاء حس."},{"type":"mcq","q":"أين توجد الخلايا العصبية الموصّلة (البينية)؟","options":["في المعدة","في الجلد","في العظام","في الدماغ والحبل الشوكي"],"answer":3,"why":"تربط بين الحسية والحركية داخل الجهاز العصبي المركزي."},{"type":"mcq","q":"ما وظيفة العصب البصري في العين؟","options":["نقل السيالات العصبية من الشبكية إلى الدماغ","تغيير حجم الحدقة","إفراز الدموع","كسر أشعة الضوء"],"answer":0,"why":"ينقل الإشارات البصرية للدماغ لتفسير الصورة."},{"type":"mcq","q":"أين تقع الغدتان الكظريتان في جسم الإنسان؟","options":["في الرقبة","فوق الكليتين","في الدماغ","في الرئتين"],"answer":1,"why":"تقع كل غدة كظرية أعلى إحدى الكليتين."}],"medium":[{"type":"mcq","q":"عندما تشم رائحة ليمون فيسيل لعابك، ما عضو الاستجابة في هذا الموقف؟","options":["الدماغ","الأنف","الغدد اللعابية","العين"],"answer":2,"why":"الغدد اللعابية هي التي استجابت بإفراز اللعاب."},{"type":"mcq","q":"كيف ينتقل السيال عبر التشابك العصبي؟","options":["بسلك نحاسي","بالأسموزية","بانتقال خلايا الدم","بانتشار مواد كيميائية (نواقل عصبية)"],"answer":3,"why":"تُفرز النواقل العصبية وتنتشر عبر الفجوة."},{"type":"mcq","q":"أين تتركّز خلايا المخاريط في الشبكية لتعطي أوضح رؤية؟","options":["في النقرة (Fovea)","في القرنية","في القزحية","في البقعة العمياء"],"answer":0,"why":"النقرة هي موضع الرؤية الأدق والأكثر وضوحًا."},{"type":"tfr","q":"يقتصر التنظيم في جسم الإنسان على الجهاز العصبي وحده.","answer":false,"reasons":["يتعاون الجهازان العصبي والهرموني معًا لتنظيم وظائف الجسم","لأن الإنسان ليس له هرمونات","لأن الهرمونات في النبات فقط"],"reason":0},{"type":"tfr","q":"تنقل الخلية العصبية الحسية الإشارات من العضلات إلى أعضاء الحس.","answer":false,"reasons":["بل تنقلها من أعضاء الحس (المستقبلات) إلى الجهاز العصبي المركزي","لأنها تنقلها للغدد","لأنها لا تنقل إشارات"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا نحتاج إلى التنظيم العصبي السريع بدل الاكتفاء بالهرموني عند لمس جسم ساخن؟","options":["لحماية الأنسجة من الحرق فورًا قبل حدوث تلف كبير","لأن العضلات لا تستجيب للدم","لأن الحرارة تمنع جريان الدم","لأن الهرمونات لا تصل لليد"],"answer":0,"why":"الاستجابة الهرمونية بطيئة جدًّا مقارنةً بالحاجة الفورية لتجنب الحرق."},{"type":"mcq","q":"إذا قُطع المحور الحركي المتصل بعضلة ذراع شخص وبقي الحسي سليمًا؛ ماذا يحدث عند لمسه جسمًا ساخنًا؟","options":["لا يشعر ولا يسحب يده","يشعر بالألم لكنه لا يستطيع سحب يده","يسحب يده ولا يشعر بالألم","تعمل العضلة طبيعيًا"],"answer":1,"why":"السيال الحسي يصل للدماغ فيشعر بالألم، لكن الأمر الحركي لا يصل للعضلة."},{"type":"mcq","q":"لماذا تبدو الأشياء في الغرفة شبه المظلمة رمادية بلا ألوان واضحة؟","options":["لأن القرنية تصبح معتمة","لأن الألوان تختفي من الأجسام","لأن العصيّ هي التي تعمل في الضوء الخافت ولا تميّز الألوان، بينما لا يُستثار المخاريط إلا بضوء كافٍ","لأن العدسة تتوقف"],"answer":2,"why":"المخاريط المسؤولة عن الألوان تحتاج شدة إضاءة أعلى لتعمل."},{"type":"essay","q":"فسّر لماذا يناسب التنظيم الهرموني عملية «النمو والبلوغ» أكثر من التنظيم العصبي.","model":"لأن النمو والبلوغ عمليتان تدريجيتان طويلتا الأمد وتشملان معظم أعضاء الجسم معًا، وهذا يتوافق مع طبيعة الهرمونات المنتقلة بالدم ذات الأثر الممتد والواسع."},{"type":"essay","q":"فسّر لماذا يبطؤ انتقال السيال العصبي قليلًا عند مروره بالتشابك العصبي مقارنةً بمروره داخل المحور.","model":"لأنه يتحوّل من إشارة كهربائية سريعة جدًّا إلى انتشار كيميائي بطيء نسبيًا للنواقل العصبية عبر فجوة التشابك."}]},"test":[{"type":"mcq","q":"أيٌّ مما يأتي يُعدّ «عضو استجابة» (مستجيبًا)؟","options":["الأنف","العين","العضلة","الأذن"],"answer":2,"why":"المستجيبات هي العضلات والغدد، أما العين والأذن والأنف فأعضاء حس."},{"type":"mcq","q":"أين توجد الخلايا العصبية الموصّلة (البينية)؟","options":["في المعدة","في الجلد","في العظام","في الدماغ والحبل الشوكي"],"answer":3,"why":"تربط بين الحسية والحركية داخل الجهاز العصبي المركزي."},{"type":"mcq","q":"ما وظيفة العصب البصري في العين؟","options":["نقل السيالات العصبية من الشبكية إلى الدماغ","تغيير حجم الحدقة","إفراز الدموع","كسر أشعة الضوء"],"answer":0,"why":"ينقل الإشارات البصرية للدماغ لتفسير الصورة."},{"type":"mcq","q":"أين تقع الغدتان الكظريتان في جسم الإنسان؟","options":["في الرقبة","فوق الكليتين","في الدماغ","في الرئتين"],"answer":1,"why":"تقع كل غدة كظرية أعلى إحدى الكليتين."},{"type":"mcq","q":"ما درجة الحرارة الطبيعية التقريبية لجسم الإنسان؟","options":["٣٠°م","٤٥°م","٣٧°م","٢٥°م"],"answer":2,"why":"٣٧°م هي الدرجة المثلى لعمل أنزيمات الإنسان."},{"type":"mcq","q":"كيف تنتقل الهرمونات من الغدد الصماء إلى الأعضاء المستهدفة؟","options":["عبر المريء","عبر الأعصاب","عبر القصبة الهوائية","عبر الدم"],"answer":3,"why":"تُفرز الهرمونات مباشرةً في مجرى الدم."},{"type":"mcq","q":"ما وظيفة الغمد المياليني حول محور الخلية العصبية؟","options":["العزل وتسريع انتقال السيال العصبي","امتصاص الضوء","هضم الغذاء","إفراز العرق"],"answer":0,"why":"الغمد المياليني يعزل المحور ويسرّع الإشارة."},{"type":"mcq","q":"أيُّ خلايا الشبكية مسؤولة عن رؤية الألوان في الضوء الساطع؟","options":["الأربطة المعلّقة","المخاريط","العصيّ","العضلات الدائرية"],"answer":1,"why":"المخاريط للرؤية الملونة والعصيّ للضوء الخافت."},{"type":"mcq","q":"ما الهرمون الذي يفرزه البنكرياس لخفض سكر الدم؟","options":["الإستروجين","التستوستيرون","الأنسولين","الأدرينالين"],"answer":2,"why":"الأنسولين يخفض مستوى الجلوكوز المرتفع في الدم."},{"type":"mcq","q":"ما العضو الذي يفرز هرمونَي الأنسولين والجلوكاجون؟","options":["المعدة","الكلية","الكبد","البنكرياس"],"answer":3,"why":"البنكرياس ينظم سكر الدم بهذين الهرمونين."},{"type":"mcq","q":"ما المؤثّر الذي تستقبله العين؟","options":["الضوء","الصوت","الضغط","الحرارة فقط"],"answer":0,"why":"مستقبلات الشبكية في العين حساسة للضوء."},{"type":"mcq","q":"أيُّ مثالٍ مما يأتي يُعدّ فعلًا منعكسًا؟","options":["رسم لوحة","رمش العين عند اقتراب جسم فجأة","كتابة الواجب","قراءة كتاب"],"answer":1,"why":"رمش العين استجابة لا إرادية سريعة لحماية العين."},{"type":"tf","q":"يقتصر التنظيم في جسم الإنسان على الجهاز العصبي وحده.","answer":false,"why":"يتعاون الجهازان العصبي والهرموني معًا لتنظيم وظائف الجسم"},{"type":"tf","q":"تنقل الخلية العصبية الحسية الإشارات من العضلات إلى أعضاء الحس.","answer":false,"why":"بل تنقلها من أعضاء الحس (المستقبلات) إلى الجهاز العصبي المركزي"},{"type":"tf","q":"عند النظر إلى جسم بعيد، تنقبض العضلات الهدبية وتصبح العدسة أكثر سمكًا.","answer":false,"why":"بل ترتخي العضلات الهدبية وتُشد الأربطة فتصبح العدسة أرقّ وأقل تحدبًا"},{"type":"tf","q":"الغدد اللعابية تُعدّ من الغدد الصماء لأنها تفرز سائلًا.","answer":false,"why":"الغدد اللعابية غدد قنوية تفرز اللعاب عبر قنوات إلى الفم وليس في الدم"},{"type":"tfr","q":"تنتقل الأوعية الدموية في الجلد نحو السطح أو تبتعد عنه لتنظيم الحرارة.","answer":false,"reasons":["الأوعية لا تغيّر مكانها، بل يتسع قطر الشرايين السطحية (توسع) أو يضيق (تضيق) لتغيير كمية الدم المتدفق قرب السطح","الأوعية تتحرك لأعلى وأسفل","الأوعية تختفي في البرد"],"reason":0},{"type":"tfr","q":"يُعدّ الدماغ والحبل الشوكي هما المركز المنظّم في الجهاز العصبي.","answer":true,"reasons":["لأنهما غدد صماء","يعالجان المعلومات الواردة من المستقبلات ويرسلان الأوامر للمستجيبات","لأنهما أعضاء استجابة"],"reason":1},{"type":"tfr","q":"يمكن للفعل المنعكس أن يحدث دون تفكير واعٍ من الدماغ.","answer":true,"reasons":["لأنه فعل بطيء","لأن المركز المنظم في منعكس سحب اليد هو الحبل الشوكي لتسريع الحماية","لأن الدماغ لا يعمل"],"reason":1},{"type":"tfr","q":"تعمل العضلات الدائرية والعضلات الشعاعية في القزحية كزوج متضاد.","answer":true,"reasons":["لأنهما تنقبضان معًا","عندما تنقبض إحداهما ترتخي الأخرى لتضييق الحدقة أو توسيعها","لأنهما في العدسة"],"reason":1},{"type":"essay","q":"اذكر ثلاثة فروق بين التنظيم العصبي والتنظيم الهرموني.","model":"١) طبيعة الرسالة: كهربائية (عصبي) مقابل كيميائية (هرموني). ٢) السرعة: سريع جدًّا مقابل أبطأ. ٣) مدة الأثر: قصيرة مقابل طويلة."},{"type":"essay","q":"اذكر خطوات القوس الانعكاسية الخمس بالترتيب.","model":"مستقبل حسي ← خلية عصبية حسية ← خلية عصبية موصّلة (في الحبل الشوكي) ← خلية عصبية حركية ← عضو الاستجابة (عضلة أو غدة)."},{"type":"essay","q":"قارن بين خلايا العصيّ وخلايا المخاريط في الشبكية من حيث الوظيفة والإضاءة المناسبة.","model":"العصيّ: تعمل في الضوء الخافت ولا تميّز الألوان (أبيض وأسود). المخاريط: تعمل في الضوء الساطع وتميّز الألوان وتتركّز في النقرة."},{"type":"essay","q":"اذكر أربعة تأثيرات لهرمون الأدرينالين على جسم الإنسان.","model":"١) زيادة معدل نبض القلب. ٢) زيادة معدل التنفس. ٣) زيادة تركيز الجلوكوز في الدم (من الجلايكوجين). ٤) اتّساع حدقة العين."},{"type":"essay","q":"عرّف الاتزان الداخلي واذكر مثالين لما ينظّمه في جسم الإنسان.","model":"هو الحفاظ على ثبات البيئة الداخلية للجسم ضمن حدود ضيقة. أمثلة: درجة حرارة الجسم (~٣٧°م)، وتركيز الجلوكوز في الدم، ومحتوى الماء."}]},
  {"id":"g9-bio-2-u7","grade":"g9","subject":"biology","term":2,"title":"الوحدة السابعة: التغذية في النبات","levels":{"easy":[{"type":"mcq","q":"ما الكائنات التي تصنع غذاءها العضوي بنفسها من الماء و CO₂ باستخدام الضوء؟","options":["الإنسان","الفطريات","الحيوانات اللاحمة","ذاتية التغذية (النباتات الخضراء والطحالب)"],"answer":3,"why":"النباتات والطحالب ذاتية التغذية عبر التمثيل الضوئي."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع صبغة «الكلوروفيل» الخضراء في النبات؟","options":["أيونات المغنيسيوم (Mg²⁺)","أيونات الصوديوم","الكلوريد","الحديد فقط"],"answer":0,"why":"المغنيسيوم عنصر أساس في تركيب جزيء الكلوروفيل."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع «الأحماض الأمينية والبروتينات» في النبات؟","options":["الأكسجين","أيونات النترات (NO₃⁻)","الكربون فقط","الماء"],"answer":1,"why":"النيتروجين في النترات يدخل في بناء الأحماض الأمينية والبروتين."},{"type":"mcq","q":"تُصنّف الفطريات (كعيش الغراب والعفن) من حيث التغذية بأنها:","options":["منتجات ضوئية","ذاتية التغذية","غير ذاتية التغذية (لا تحتوي كلوروفيل)","نباتات خضراء"],"answer":2,"why":"الفطريات تخلو من الكلوروفيل وتعتمد على مواد عضوية جاهزة."}],"medium":[{"type":"mcq","q":"ماذا يظهر على أوراق نبات يعاني من نقص «المغنيسيوم» في التربة؟","options":["لا يتأثر النبات","تحولها للون الأزرق","زيادة سمكها بشدة","اصفرار الأوراق لعدم كفاية الكلوروفيل"],"answer":3,"why":"نقص المغنيسيوم يقلل الكلوروفيل فتصفر الأوراق."},{"type":"mcq","q":"أي المواد الآتية تُعد «مادة غير عضوية» يمتصها النبات؟","options":["الماء وثاني أكسيد الكربون والأملاح المعدنية","النشا","البروتين","الجلوكوز"],"answer":0,"why":"الماء و CO₂ والأملاح مواد غير عضوية بسيطة."},{"type":"mcq","q":"ماذا يسبب نقص «أيونات النترات» للنبات؟","options":["زيادة سريعة في الطول","ضعف النمو وتقزّم النبات واصفرار الأوراق","زيادة البروتين","تضاعف الثمار"],"answer":1,"why":"النترات لازمة لبناء البروتينات ونمو الخلايا."},{"type":"tfr","q":"تعتمد جميع الحيوانات (العاشبة واللاحمة) بصورة مباشرة أو غير مباشرة على النباتات ذاتية التغذية.","answer":true,"reasons":["اللاحمة لا تعتمد على النبات أبدًا","لأن النباتات هي المصدر الأول للغذاء العضوي والأكسجين على الأرض","لا توجد علاقة"],"reason":1},{"type":"tfr","q":"تحدث عملية التمثيل الضوئي داخل البلاستيدات الخضراء في وجود الضوء والكلوروفيل.","answer":true,"reasons":["تحدث في الجذور تحت الأرض","لا تحتاج كلوروفيل","فتحوّل CO₂ والماء إلى جلوكوز وأكسجين"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا تُسمّى النباتات الخضراء «المنتجات» في النظام البيئي؟","options":["لأنها تأكل الحيوانات","لأنها تبيع الغذاء","لأنها تنتج الغذاء العضوي الأولي لكل الكائنات الحية من طاقة الشمس","لأنها تتحرك بسرعة"],"answer":2,"why":"المنتجات تحوّل الطاقة الضوئية لطاقة كيميائية غذائية."},{"type":"mcq","q":"الإنسان كائن:","options":["يصنع الجلوكوز من الهواء","ذاتي التغذية","منتج ضوئي","غير ذاتي التغذية"],"answer":3,"why":"يحصل الإنسان على غذائه العضوي من النباتات والحيوانات."},{"type":"mcq","q":"أعراض نقص النترات ونقص المغنيسيوم تشترك في:","options":["اصفرار الأوراق وضعف التمثيل الضوئي","تلوّن الأوراق بالأزرق","نمو أسرع","زيادة البروتين"],"answer":0,"why":"كلاهما يضعف الورقة ويسبب الاصفرار، والنترات تسبب تقزمًا شديدًا أيضًا."},{"type":"essay","q":"قارن بين التغذية الذاتية وغير الذاتية مع ذكر مثالين لكل منهما.","model":"الذاتية: يصنع الكائن غذاءه العضوي من ماء و CO₂ وضوء (النباتات الخضراء، الطحالب). غير الذاتية: يعتمد على غذاء عضوي جاهز من كائنات أخرى (الإنسان، الأسد، الفطريات)."},{"type":"essay","q":"قارن بين دور أيونات النترات ودور أيونات المغنيسيوم في النبات وأثر نقص كل منهما.","model":"النترات: بناء الأحماض الأمينية والبروتينات، ونقصها يسبب تقزم النمو واصفرار الأوراق. المغنيسيوم: بناء الكلوروفيل، ونقصه يسبب اصفرار الأوراق."}]},"test":[{"type":"mcq","q":"ما الكائنات التي تصنع غذاءها العضوي بنفسها من الماء و CO₂ باستخدام الضوء؟","options":["الإنسان","الفطريات","الحيوانات اللاحمة","ذاتية التغذية (النباتات الخضراء والطحالب)"],"answer":3,"why":"النباتات والطحالب ذاتية التغذية عبر التمثيل الضوئي."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع صبغة «الكلوروفيل» الخضراء في النبات؟","options":["أيونات المغنيسيوم (Mg²⁺)","أيونات الصوديوم","الكلوريد","الحديد فقط"],"answer":0,"why":"المغنيسيوم عنصر أساس في تركيب جزيء الكلوروفيل."},{"type":"mcq","q":"ما الأيون المعدني الضروري لصنع «الأحماض الأمينية والبروتينات» في النبات؟","options":["الأكسجين","أيونات النترات (NO₃⁻)","الكربون فقط","الماء"],"answer":1,"why":"النيتروجين في النترات يدخل في بناء الأحماض الأمينية والبروتين."},{"type":"mcq","q":"تُصنّف الفطريات (كعيش الغراب والعفن) من حيث التغذية بأنها:","options":["منتجات ضوئية","ذاتية التغذية","غير ذاتية التغذية (لا تحتوي كلوروفيل)","نباتات خضراء"],"answer":2,"why":"الفطريات تخلو من الكلوروفيل وتعتمد على مواد عضوية جاهزة."},{"type":"mcq","q":"ماذا يظهر على أوراق نبات يعاني من نقص «المغنيسيوم» في التربة؟","options":["لا يتأثر النبات","تحولها للون الأزرق","زيادة سمكها بشدة","اصفرار الأوراق لعدم كفاية الكلوروفيل"],"answer":3,"why":"نقص المغنيسيوم يقلل الكلوروفيل فتصفر الأوراق."},{"type":"mcq","q":"أي المواد الآتية تُعد «مادة غير عضوية» يمتصها النبات؟","options":["الماء وثاني أكسيد الكربون والأملاح المعدنية","النشا","البروتين","الجلوكوز"],"answer":0,"why":"الماء و CO₂ والأملاح مواد غير عضوية بسيطة."},{"type":"mcq","q":"ماذا يسبب نقص «أيونات النترات» للنبات؟","options":["زيادة سريعة في الطول","ضعف النمو وتقزّم النبات واصفرار الأوراق","زيادة البروتين","تضاعف الثمار"],"answer":1,"why":"النترات لازمة لبناء البروتينات ونمو الخلايا."},{"type":"mcq","q":"لماذا تُسمّى النباتات الخضراء «المنتجات» في النظام البيئي؟","options":["لأنها تأكل الحيوانات","لأنها تبيع الغذاء","لأنها تنتج الغذاء العضوي الأولي لكل الكائنات الحية من طاقة الشمس","لأنها تتحرك بسرعة"],"answer":2,"why":"المنتجات تحوّل الطاقة الضوئية لطاقة كيميائية غذائية."},{"type":"mcq","q":"الإنسان كائن:","options":["يصنع الجلوكوز من الهواء","ذاتي التغذية","منتج ضوئي","غير ذاتي التغذية"],"answer":3,"why":"يحصل الإنسان على غذائه العضوي من النباتات والحيوانات."},{"type":"mcq","q":"أعراض نقص النترات ونقص المغنيسيوم تشترك في:","options":["اصفرار الأوراق وضعف التمثيل الضوئي","تلوّن الأوراق بالأزرق","نمو أسرع","زيادة البروتين"],"answer":0,"why":"كلاهما يضعف الورقة ويسبب الاصفرار، والنترات تسبب تقزمًا شديدًا أيضًا."},{"type":"mcq","q":"المادة العضوية الأولية التي ينتجها النبات في التغذية الذاتية هي:","options":["ثاني أكسيد الكربون","الجلوكوز","الماء","النيتروجين"],"answer":1,"why":"الجلوكوز هو السكر البسيط الناتج عن التمثيل الضوئي."},{"type":"mcq","q":"ما المعادلة الرمزية الموزونة الصحيحة للتمثيل الضوئي؟","options":["C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O","CO₂ + H₂O → C₆H₁₂O₆ + O₂","6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂","6O₂ + 6H₂O → C₆H₁₂O₆"],"answer":2,"why":"تتوازن بوضع 6 أمام CO₂ و H₂O و O₂."},{"type":"tf","q":"التغذية الذاتية تعني تحويل مواد غير عضوية بسيطة إلى مواد عضوية معقدة باستخدام طاقة الضوء.","answer":true,"why":"وهي العملية التي تقوم بها النباتات الخضراء والطحالب"},{"type":"tf","q":"تستطيع الفطريات القيام بالتمثيل الضوئي لأنها تنمو في التربة.","answer":false,"why":"الفطريات لا تحتوي على كلوروفيل ولا بلاستيدات خضراء فهي غير ذاتية التغذية"},{"type":"tf","q":"نقص أيونات المغنيسيوم يسبب اصفرار أوراق النبات لأنه يدخل في تركيب الكلوروفيل.","answer":true,"why":"فيضعف امتصاص الضوء وتقل كفاءة التمثيل الضوئي"},{"type":"tf","q":"يستطيع النبات صنع البروتينات من الجلوكوز وحده دون الحاجة لأيونات النترات.","answer":false,"why":"البروتينات تحتوي عنصر النيتروجين الذي يحصل عليه النبات من أيونات النترات في التربة"},{"type":"tfr","q":"تعتمد جميع الحيوانات (العاشبة واللاحمة) بصورة مباشرة أو غير مباشرة على النباتات ذاتية التغذية.","answer":true,"reasons":["اللاحمة لا تعتمد على النبات أبدًا","لأن النباتات هي المصدر الأول للغذاء العضوي والأكسجين على الأرض","لا توجد علاقة"],"reason":1},{"type":"tfr","q":"تحدث عملية التمثيل الضوئي داخل البلاستيدات الخضراء في وجود الضوء والكلوروفيل.","answer":true,"reasons":["تحدث في الجذور تحت الأرض","لا تحتاج كلوروفيل","فتحوّل CO₂ والماء إلى جلوكوز وأكسجين"],"reason":2},{"type":"tfr","q":"يتوقف النبات عن التنفس الخلوي خلال النهار لأنه يقوم بالتمثيل الضوئي.","answer":false,"reasons":["التنفس الخلوي مستمر ليلًا ونهارًا لإمداد خلايا النبات بالطاقة","نعم يتوقف نهارًا","النبات لا يتنفس أبدًا"],"reason":0},{"type":"tfr","q":"معادلة التمثيل الضوئي هي عكس معادلة التنفس الهوائي تقريبًا.","answer":true,"reasons":["هما متطابقتان في الاتجاه","التمثيل يبني الجلوكوز و O₂ من CO₂ والماء، والتنفس يهدم الجلوكوز بـ O₂ منتجًا CO₂ والماء","لا علاقة بينهما"],"reason":1},{"type":"essay","q":"قارن بين التغذية الذاتية وغير الذاتية مع ذكر مثالين لكل منهما.","model":"الذاتية: يصنع الكائن غذاءه العضوي من ماء و CO₂ وضوء (النباتات الخضراء، الطحالب). غير الذاتية: يعتمد على غذاء عضوي جاهز من كائنات أخرى (الإنسان، الأسد، الفطريات)."},{"type":"essay","q":"قارن بين دور أيونات النترات ودور أيونات المغنيسيوم في النبات وأثر نقص كل منهما.","model":"النترات: بناء الأحماض الأمينية والبروتينات، ونقصها يسبب تقزم النمو واصفرار الأوراق. المغنيسيوم: بناء الكلوروفيل، ونقصه يسبب اصفرار الأوراق."},{"type":"essay","q":"لماذا يُنصح المزارع بإضافة سماد يحتوي على نترات ومغنيسيوم عند اصفرار أوراق محصوله؟","model":"لتعويض نقص هذين الأيونين في التربة فيعود النبات لتصنيع الكلوروفيل والبروتينات وتستعيد الأوراق خضرتها ونموها."},{"type":"essay","q":"فرّق بين المواد العضوية والمواد غير العضوية في غذاء النبات.","model":"غير العضوية بسيطة كالماء و CO₂ والأملاح؛ والعضوية معقدة غنية بالطاقة كالجلوكوز والنشا والبروتينات التي يبنيها النبات."},{"type":"essay","q":"اشرح لماذا تُعد النباتات الخضراء أساس استمرار الحياة على سطح الأرض.","model":"لأنها تحوّل طاقة الشمس إلى غذاء عضوي يغذي السلاسل الغذائية وتطلق غاز الأكسجين الضروري لتنفس الكائنات الحية."}]},
  {"id":"g9-bio-2-u8","grade":"g9","subject":"biology","term":2,"title":"الوحدة الثامنة: الهضم في الإنسان","levels":{"easy":[{"type":"mcq","q":"ما الغرض الأساسي من «الهضم الميكانيكي» للطعام؟","options":["تفتيت الطعام لقطع أصغر لزيادة مساحة السطح لعمل الإنزيمات","تغيير التركيب الكيميائي للبروتين","امتصاص الطعام في الفم","قتل الإنزيمات"],"answer":0,"why":"زيادة مساحة السطح تسرّع الهضم الكيميائي كثيرًا."},{"type":"mcq","q":"ما الإنزيم الذي يهضم «الدهون» إلى أحماض دهنية وجليسرول؟","options":["الأميليز","الليبيز (Lipase)","البيبسين","المالتيز"],"answer":1,"why":"الليبيز متخصص في هضم الدهون."},{"type":"mcq","q":"أين تُصنع «العصارة الصفراوية» وأين تُخزَّن؟","options":["تُصنع في البنكرياس","تُصنع في المعدة وتُخزّن في الفم","تُصنع في الكبد وتُخزّن في الحوصلة الصفراوية (المرارة)","تُصنع في الكلية"],"answer":2,"why":"الكبد ينتج الصفراء وتخزنها المرارة وتصبها في الإثني عشر."},{"type":"mcq","q":"ما الوظيفتان الرئيستان لحمض الهيدروكلوريك (HCl) في المعدة؟","options":["توفير وسط قلوي","هضم النشا","استحلاب الدهون","قتل البكتيريا وتوفير وسط حمضي مثالي (pH ≈ 2) لإنزيم البيبسين"],"answer":3,"why":"HCl يحمي الجسم من الميكروبات ويهيئ الوسط للبيبسين."}],"medium":[{"type":"mcq","q":"ما ناتج هضم «البروتينات» بواسطة إنزيمات البروتييز (البيبسين والتربسين)؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","النشا"],"answer":0,"why":"البروتينات تتفكك إلى وحداتها البنائية وهي الأحماض الأمينية."},{"type":"mcq","q":"ما وظيفة «العصارة الصفراوية» في هضم الدهون؟","options":["هضم الدهون كيميائيًا بإنزيماتها","استحلاب الدهون (تفتيتها لقطيرات دقيقة) ومعادلة حمض المعدة","تحويل النشا لبروتين","قتل الإنزيمات"],"answer":1,"why":"الصفراء لا تحتوي إنزيمات بل تستحلب الدهون ميكانيكيًا وتُعادل الحمض."},{"type":"mcq","q":"أي مادة مما يلي لا تحتاج إلى هضم ويمكن امتصاصها مباشرةً؟","options":["البروتين","النشا","الجلوكوز والماء والأملاح المعدنية","الدهون"],"answer":2,"why":"الجلوكوز والماء والأملاح جزيئات صغيرة وذائبة أصلًا."},{"type":"tfr","q":"تعمل إنزيمات الأمعاء الدقيقة (كالتربسين والليبيز) في وسط قلوي خفيف بفضل العصارة الصفراوية.","answer":true,"reasons":["لا تحتاج لضبط pH","تعمل في وسط حمضي قوي","التي تعادل حمض المعدة القادم مع الطعام"],"reason":2},{"type":"tfr","q":"يُعد الكبد والبنكرياس من الغدد الملحقة بالقناة الهضمية ولا يمر الطعام بداخلهما.","answer":true,"reasons":["بل يصبان عصاراتهما (الصفراء والبنكرياسية) في الإثني عشر عبر قنوات","يمر الطعام داخل الكبد","يمر الطعام داخل البنكرياس"],"reason":0}],"hard":[{"type":"mcq","q":"ما أصلب طبقة خارجية تحمي السن؟","options":["اللثة","اللب","العاج","المينا"],"answer":3,"why":"المينا هي الطبقة الخارجية الصلبة الواقية للسن."},{"type":"mcq","q":"أين يبدأ الهضم الكيميائي لـ«النشا» في الجهاز الهضمي؟","options":["في الفم (بواسطة أميليز اللعاب)","في المعدة","في المريء","في الأمعاء الغليظة"],"answer":0,"why":"يفرز اللعاب إنزيم الأميليز ليبدأ هضم النشا في الفم."},{"type":"mcq","q":"ما وظيفة «الأنياب» و«الأضراس» على الترتيب؟","options":["الطحن ثم القطع","تمزيق الطعام، وطحنه وسحقه","البلع فقط","إفراز اللعاب"],"answer":1,"why":"القواطع للقطع، الأنياب للتمزيق، والأضراس للطحن."},{"type":"essay","q":"قارن بين الهضم الميكانيكي والهضم الكيميائي مع ذكر مثالين لكل منهما.","model":"الميكانيكي: تفتيت فيزيائي دون تغيير كيميائي لزيادة مساحة السطح (المضغ، استحلاب الصفراء). الكيميائي: تكسير الروابط بالإنزيمات لتكوين جزيئات صغيرة ذائبة (الأميليز، البيبسين، الليبيز)."},{"type":"essay","q":"اذكر ناتج الهضم النهائي لكل من: النشا، البروتينات، والدهون، مع اسم الإنزيم المسؤول.","model":"النشا ← جلوكوز (أميليز ومالتيز). البروتينات ← أحماض أمينية (بروتييز). الدهون ← أحماض دهنية وجليسرول (ليبيز)."}]},"test":[{"type":"mcq","q":"ما الغرض الأساسي من «الهضم الميكانيكي» للطعام؟","options":["تفتيت الطعام لقطع أصغر لزيادة مساحة السطح لعمل الإنزيمات","تغيير التركيب الكيميائي للبروتين","امتصاص الطعام في الفم","قتل الإنزيمات"],"answer":0,"why":"زيادة مساحة السطح تسرّع الهضم الكيميائي كثيرًا."},{"type":"mcq","q":"ما الإنزيم الذي يهضم «الدهون» إلى أحماض دهنية وجليسرول؟","options":["الأميليز","الليبيز (Lipase)","البيبسين","المالتيز"],"answer":1,"why":"الليبيز متخصص في هضم الدهون."},{"type":"mcq","q":"أين تُصنع «العصارة الصفراوية» وأين تُخزَّن؟","options":["تُصنع في البنكرياس","تُصنع في المعدة وتُخزّن في الفم","تُصنع في الكبد وتُخزّن في الحوصلة الصفراوية (المرارة)","تُصنع في الكلية"],"answer":2,"why":"الكبد ينتج الصفراء وتخزنها المرارة وتصبها في الإثني عشر."},{"type":"mcq","q":"ما الوظيفتان الرئيستان لحمض الهيدروكلوريك (HCl) في المعدة؟","options":["توفير وسط قلوي","هضم النشا","استحلاب الدهون","قتل البكتيريا وتوفير وسط حمضي مثالي (pH ≈ 2) لإنزيم البيبسين"],"answer":3,"why":"HCl يحمي الجسم من الميكروبات ويهيئ الوسط للبيبسين."},{"type":"mcq","q":"ما ناتج هضم «البروتينات» بواسطة إنزيمات البروتييز (البيبسين والتربسين)؟","options":["الأحماض الأمينية","الجلوكوز","الأحماض الدهنية","النشا"],"answer":0,"why":"البروتينات تتفكك إلى وحداتها البنائية وهي الأحماض الأمينية."},{"type":"mcq","q":"ما وظيفة «العصارة الصفراوية» في هضم الدهون؟","options":["هضم الدهون كيميائيًا بإنزيماتها","استحلاب الدهون (تفتيتها لقطيرات دقيقة) ومعادلة حمض المعدة","تحويل النشا لبروتين","قتل الإنزيمات"],"answer":1,"why":"الصفراء لا تحتوي إنزيمات بل تستحلب الدهون ميكانيكيًا وتُعادل الحمض."},{"type":"mcq","q":"أي مادة مما يلي لا تحتاج إلى هضم ويمكن امتصاصها مباشرةً؟","options":["البروتين","النشا","الجلوكوز والماء والأملاح المعدنية","الدهون"],"answer":2,"why":"الجلوكوز والماء والأملاح جزيئات صغيرة وذائبة أصلًا."},{"type":"mcq","q":"ما أصلب طبقة خارجية تحمي السن؟","options":["اللثة","اللب","العاج","المينا"],"answer":3,"why":"المينا هي الطبقة الخارجية الصلبة الواقية للسن."},{"type":"mcq","q":"أين يبدأ الهضم الكيميائي لـ«النشا» في الجهاز الهضمي؟","options":["في الفم (بواسطة أميليز اللعاب)","في المعدة","في المريء","في الأمعاء الغليظة"],"answer":0,"why":"يفرز اللعاب إنزيم الأميليز ليبدأ هضم النشا في الفم."},{"type":"mcq","q":"ما وظيفة «الأنياب» و«الأضراس» على الترتيب؟","options":["الطحن ثم القطع","تمزيق الطعام، وطحنه وسحقه","البلع فقط","إفراز اللعاب"],"answer":1,"why":"القواطع للقطع، الأنياب للتمزيق، والأضراس للطحن."},{"type":"mcq","q":"ما الرقم الهيدروجيني المثالي تقريبًا لإنزيم البيبسين في المعدة؟","options":["pH ≈ 12","pH ≈ 8 (قلوي)","pH ≈ 2 (حمضي قوي)","pH = 7"],"answer":2,"why":"البيبسين يعمل بأعلى كفاءة في الوسط الحمضي للمعدة."},{"type":"mcq","q":"ما وظيفة «الحركة الدودية» في المريء والأمعاء؟","options":["امتصاص الجلوكوز","تقطيع الطعام بالأسنان","إفراز الصفراء","دفع الطعام على طول القناة الهضمية بانقباض وانبساط العضلات"],"answer":3,"why":"الحركة الدودية تحرّك الطعام باستمرار عبر القناة الهضمية."},{"type":"tf","q":"تحتوي العصارة الصفراوية على إنزيم الليبيز لهضم الدهون كيميائيًا.","answer":false,"why":"العصارة الصفراوية لا تحتوي أي إنزيمات؛ هي تستحلب الدهون ميكانيكيًا وتُعادل الحمض فقط، والليبيز يفرزه البنكرياس"},{"type":"tf","q":"مضغ الطعام جيدًا بالأسنان يسرّع الهضم الكيميائي لأنه يزيد مساحة السطح المعرضة للإنزيمات.","answer":true,"why":"فتصل الإنزيمات لعدد أكبر من الجزيئات في وقت أقصر"},{"type":"tf","q":"تسوس الأسنان يحدث بسبب الأحماض التي تنتجها بكتيريا الفم عند تغذيتها على بقايا السكريات.","answer":true,"why":"فتذيب الأحماض طبقة المينا، لذا ننظف أسناننا بمعجون قلوي ونقلل السكريات"},{"type":"tf","q":"يبدأ هضم البروتين كيميائيًا في الفم بواسطة اللعاب.","answer":false,"why":"يبدأ هضم البروتين في المعدة بواسطة البيبسين، أما الفم فيبدأ فيه هضم النشا"},{"type":"tfr","q":"تعمل إنزيمات الأمعاء الدقيقة (كالتربسين والليبيز) في وسط قلوي خفيف بفضل العصارة الصفراوية.","answer":true,"reasons":["لا تحتاج لضبط pH","تعمل في وسط حمضي قوي","التي تعادل حمض المعدة القادم مع الطعام"],"reason":2},{"type":"tfr","q":"يُعد الكبد والبنكرياس من الغدد الملحقة بالقناة الهضمية ولا يمر الطعام بداخلهما.","answer":true,"reasons":["بل يصبان عصاراتهما (الصفراء والبنكرياسية) في الإثني عشر عبر قنوات","يمر الطعام داخل الكبد","يمر الطعام داخل البنكرياس"],"reason":0},{"type":"tfr","q":"وجود الخملات والخميلات الدقيقة في الأمعاء الدقيقة يزيد مساحة سطح الامتصاص بشكل هائل.","answer":true,"reasons":["يقلل مساحة السطح","مع جدار رقيق بسمك خلية واحدة وشبكة شعيرات دموية كثيفة","يمنع الامتصاص"],"reason":1},{"type":"tfr","q":"تُمتص الأحماض الدهنية والجليسرول أساسًا عبر الوعاء اللبني داخل الخملة.","answer":true,"reasons":["لا تمتص الدهون","تمتص في المريء","بينما يُمتص الجلوكوز والأحماض الأمينية في الشعيرات الدموية"],"reason":2},{"type":"essay","q":"قارن بين الهضم الميكانيكي والهضم الكيميائي مع ذكر مثالين لكل منهما.","model":"الميكانيكي: تفتيت فيزيائي دون تغيير كيميائي لزيادة مساحة السطح (المضغ، استحلاب الصفراء). الكيميائي: تكسير الروابط بالإنزيمات لتكوين جزيئات صغيرة ذائبة (الأميليز، البيبسين، الليبيز)."},{"type":"essay","q":"اذكر ناتج الهضم النهائي لكل من: النشا، البروتينات، والدهون، مع اسم الإنزيم المسؤول.","model":"النشا ← جلوكوز (أميليز ومالتيز). البروتينات ← أحماض أمينية (بروتييز). الدهون ← أحماض دهنية وجليسرول (ليبيز)."},{"type":"essay","q":"اذكر وظيفتين للعصارة الصفراوية ووظيفتين لحمض الهيدروكلوريك في المعدة.","model":"الصفراء: استحلاب الدهون ومعادلة حمض المعدة. HCl: قتل البكتيريا وتوفير وسط حمضي مثالي للبيبسين."},{"type":"essay","q":"كيف يحدث تسوس الأسنان وكيف نقي أسناننا منه؟","model":"تتغذى بكتيريا الفم على السكريات وتنتج أحماضًا تذيب المينا؛ والوقاية بتقليل السكريات وتنظيف الأسنان مرتين يوميًا بمعجون يحتوي فلورايد ومادة قلوية."},{"type":"essay","q":"اشرح ماذا يحدث لإنزيم أميليز اللعاب عند وصوله إلى المعدة الحمضية.","model":"يتوقف نشاطه ويتمسّخ بسبب الوسط الحمضي القوي (pH ≈ 2) للمعدة، ثم يُستكمل هضم النشا في الأمعاء الدقيقة بأميليز البنكرياس."}]},
  {"id":"g9-bio-2-u9","grade":"g9","subject":"biology","term":2,"title":"الوحدة التاسعة: النقل في النبات","levels":{"easy":[{"type":"mcq","q":"ما المواد التي ينقلها نسيج «الخشب» وفي أي اتجاه؟","options":["البروتين للأسفل فقط","الماء والأملاح المعدنية في اتجاه واحد للأعلى فقط","السكر في اتجاهين","الأكسجين فقط"],"answer":1,"why":"الخشب ينقل الماء والأملاح من الجذور للأوراق صعودًا."},{"type":"mcq","q":"ما وظيفة مادة «اللجنين» الموجودة في جدران أوعية الخشب؟","options":["نقل السكروز","إنتاج الجلوكوز","تقوية الأوعية ومنع انطباقها وتقديم الدعامة للنبات","امتصاص الضوء"],"answer":2,"why":"اللجنين يجعل جدران الخشب صلبةً ومقاومةً للشد."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في المقطع العرضي لـ«الجذر»؟","options":["لا يوجد خشب في الجذر","اللحاء في المركز والخشب على الحافة","الخشب في الأعلى فقط","الخشب في المركز على شكل X واللحاء بين أذرعه"],"answer":3,"why":"الترتيب المركزي في الجذر يقاوم الشد والاقتلاع."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في كل حزمة وعائية في «الساق»؟","options":["الخشب نحو الداخل واللحاء نحو الخارج (في حلقة)","اللحاء نحو الداخل والخشب للخارج","كلاهما في المركز على شكل X","بشكل عشوائي"],"answer":0,"why":"الخشب للداخل واللحاء للخارج في حلقة الساق."}],"medium":[{"type":"mcq","q":"أي عبارة تصف «أوعية الخشب» بدقة؟","options":["تحتوي كلوروفيل","خلايا ميتة مجوّفة بلا جدر عرضية ولا سيتوبلازم لتسهيل تدفق الماء","خلايا حية بها نواة كبيرة","تنقل السكروز"],"answer":1,"why":"تجوّفها وفقدان الجدر العرضية يقلل مقاومة مرور الماء."},{"type":"mcq","q":"ما المواد التي ينقلها نسيج «اللحاء»؟","options":["غاز CO₂","الماء والأملاح للأعلى فقط","السكروز والأحماض الأمينية في الاتجاهين (للأعلى وللأسفل)","النشا الصلب"],"answer":2,"why":"اللحاء ينقل الغذاء المصنوع إلى جميع أجزاء النبات."},{"type":"mcq","q":"في تجربة وضع ساق كرفس في ماء ملوّن بصبغة حمراء، أي نسيج يتلوّن بالأحمر؟","options":["النسيج العمادي فقط","اللحاء فقط","البشرة الشمعية","أوعية الخشب فقط"],"answer":3,"why":"يصعد الماء الملون عبر أوعية الخشب."},{"type":"tfr","q":"الخشب واللحاء متطابقان تمامًا في التركيب والوظيفة.","answer":false,"reasons":["الخشب ميت مجوّف مقوّى باللجنين ينقل الماء والأملاح ↑، واللحاء حي بأنابيب غربالية ينقل الغذاء ↑↓","نعم متطابقان","كلاهما ميت"],"reason":0},{"type":"tfr","q":"تمتص الشعيرات الجذرية الماء بالأسموزية والأملاح المعدنية بالنقل النشط.","answer":true,"reasons":["كلاهما بالتبخر","الأسموزية لا تحتاج طاقة، بينما النقل النشط يحتاج طاقة من التنفس","كلاهما بالنقل النشط فقط"],"reason":1}],"hard":[{"type":"mcq","q":"ما وظيفة «الخلايا المرافقة» في نسيج اللحاء؟","options":["تزويد الأنابيب الغربالية بالطاقة اللازمة لنقل الغذاء","تقوية الخشب باللجنين","إغلاق الثغور","امتصاص الماء من التربة"],"answer":0,"why":"الأنابيب الغربالية حية وتستمد طاقتها من الخلايا المرافقة."},{"type":"mcq","q":"في المقطع العرضي لـ«الورقة»، أين يقع الخشب واللحاء في العرق الوسطي؟","options":["لا يوجد لحاء في الورقة","الخشب في الأعلى واللحاء في الأسفل","اللحاء في الأعلى والخشب في الأسفل","كلاهما على السطح الخارجي"],"answer":1,"why":"في الورقة يكون الخشب علويًا واللحاء سفليًا."},{"type":"mcq","q":"لماذا تترتّب الحزم الوعائية في الساق في «حلقة قرب الحافة الخارجية»؟","options":["لأسباب جمالية فقط","لتقليل نقل الماء","لتعطي الساق متانةً تقاوم الانحناء بفعل الرياح","لمنع النمو"],"answer":2,"why":"توزيع الخشب المقوى باللجنين في محيط الساق يقاوم الانحناء."},{"type":"essay","q":"قارن في جدول بين نسيج الخشب ونسيج اللحاء من حيث: طبيعة الخلايا، المواد المنقولة، واتجاه النقل.","model":"الخشب: خلايا ميتة مجوفة بها لجنين، ينقل الماء والأملاح، للأعلى فقط. اللحاء: خلايا حية (أنابيب غربالية ومرافقة)، ينقل السكروز والأحماض الأمينية، في اتجاهين."},{"type":"essay","q":"اذكر ثلاثة تكيّفات في تركيب أوعية الخشب تلائم وظيفتها.","model":"١) خالية من السيتوبلازم والجدر العرضية لتسهيل مرور الماء. ٢) جدران مغلظة باللجنين لمنع الانطباق ودعم النبات. ٣) ضيقة لرفع الماء بالتماسك والتلاصق."}]},"test":[{"type":"mcq","q":"ما المواد التي ينقلها نسيج «الخشب» وفي أي اتجاه؟","options":["البروتين للأسفل فقط","الماء والأملاح المعدنية في اتجاه واحد للأعلى فقط","السكر في اتجاهين","الأكسجين فقط"],"answer":1,"why":"الخشب ينقل الماء والأملاح من الجذور للأوراق صعودًا."},{"type":"mcq","q":"ما وظيفة مادة «اللجنين» الموجودة في جدران أوعية الخشب؟","options":["نقل السكروز","إنتاج الجلوكوز","تقوية الأوعية ومنع انطباقها وتقديم الدعامة للنبات","امتصاص الضوء"],"answer":2,"why":"اللجنين يجعل جدران الخشب صلبةً ومقاومةً للشد."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في المقطع العرضي لـ«الجذر»؟","options":["لا يوجد خشب في الجذر","اللحاء في المركز والخشب على الحافة","الخشب في الأعلى فقط","الخشب في المركز على شكل X واللحاء بين أذرعه"],"answer":3,"why":"الترتيب المركزي في الجذر يقاوم الشد والاقتلاع."},{"type":"mcq","q":"كيف يترتّب الخشب واللحاء في كل حزمة وعائية في «الساق»؟","options":["الخشب نحو الداخل واللحاء نحو الخارج (في حلقة)","اللحاء نحو الداخل والخشب للخارج","كلاهما في المركز على شكل X","بشكل عشوائي"],"answer":0,"why":"الخشب للداخل واللحاء للخارج في حلقة الساق."},{"type":"mcq","q":"أي عبارة تصف «أوعية الخشب» بدقة؟","options":["تحتوي كلوروفيل","خلايا ميتة مجوّفة بلا جدر عرضية ولا سيتوبلازم لتسهيل تدفق الماء","خلايا حية بها نواة كبيرة","تنقل السكروز"],"answer":1,"why":"تجوّفها وفقدان الجدر العرضية يقلل مقاومة مرور الماء."},{"type":"mcq","q":"ما المواد التي ينقلها نسيج «اللحاء»؟","options":["غاز CO₂","الماء والأملاح للأعلى فقط","السكروز والأحماض الأمينية في الاتجاهين (للأعلى وللأسفل)","النشا الصلب"],"answer":2,"why":"اللحاء ينقل الغذاء المصنوع إلى جميع أجزاء النبات."},{"type":"mcq","q":"في تجربة وضع ساق كرفس في ماء ملوّن بصبغة حمراء، أي نسيج يتلوّن بالأحمر؟","options":["النسيج العمادي فقط","اللحاء فقط","البشرة الشمعية","أوعية الخشب فقط"],"answer":3,"why":"يصعد الماء الملون عبر أوعية الخشب."},{"type":"mcq","q":"ما وظيفة «الخلايا المرافقة» في نسيج اللحاء؟","options":["تزويد الأنابيب الغربالية بالطاقة اللازمة لنقل الغذاء","تقوية الخشب باللجنين","إغلاق الثغور","امتصاص الماء من التربة"],"answer":0,"why":"الأنابيب الغربالية حية وتستمد طاقتها من الخلايا المرافقة."},{"type":"mcq","q":"في المقطع العرضي لـ«الورقة»، أين يقع الخشب واللحاء في العرق الوسطي؟","options":["لا يوجد لحاء في الورقة","الخشب في الأعلى واللحاء في الأسفل","اللحاء في الأعلى والخشب في الأسفل","كلاهما على السطح الخارجي"],"answer":1,"why":"في الورقة يكون الخشب علويًا واللحاء سفليًا."},{"type":"mcq","q":"لماذا تترتّب الحزم الوعائية في الساق في «حلقة قرب الحافة الخارجية»؟","options":["لأسباب جمالية فقط","لتقليل نقل الماء","لتعطي الساق متانةً تقاوم الانحناء بفعل الرياح","لمنع النمو"],"answer":2,"why":"توزيع الخشب المقوى باللجنين في محيط الساق يقاوم الانحناء."},{"type":"mcq","q":"أي وظيفتين يقوم بهما نسيج الخشب في النبات؟","options":["امتصاص CO₂","نقل السكر والتمثيل الضوئي","تخزين النشا وإنتاج الأزهار","نقل الماء والأملاح المعدنية، والدعامة الميكانيكية"],"answer":3,"why":"اللجنين والأنابيب الصلبة يمنحان النبات الدعامة بجانب النقل."},{"type":"mcq","q":"بأي عملية فيزيائية يدخل «الماء» من التربة إلى الشعيرات الجذرية؟","options":["الأسموزية","النقل النشط","التبخر","الترشيح"],"answer":0,"why":"ينتقل الماء من جهد الماء المرتفع في التربة إلى المنخفض في الشعيرة الجذرية بالأسموزية."},{"type":"tf","q":"أوعية الخشب خلايا ميتة مجوّفة خالية من الجدر العرضية ومقوّاة بمادة اللجنين.","answer":true,"why":"لتشكل أنابيب متصلة قليلة المقاومة لصعود الماء وتدعم النبات"},{"type":"tf","q":"ينقل نسيج اللحاء الغذاء الجاهز في اتجاه واحد للأسفل فقط.","answer":false,"why":"ينقله في «الاتجاهين» (للأعلى نحو البراعم والثمار وللأسفل نحو الجذور)"},{"type":"tf","q":"في الجذر يقع الخشب في المركز على شكل X مما يساعد النبات على مقاومة قوى الشدّ.","answer":true,"why":"ويقع اللحاء في الفراغات بين أذرع الـ X"},{"type":"tf","q":"إزالة حلقة كاملة من اللحاء حول ساق شجرة (التحليق) يمنع وصول السكر إلى الجذور فتذبل وتموت لاحقًا.","answer":true,"why":"لأن اللحاء يقع نحو الخارج في الساق وهو المسؤول عن نقل الغذاء للجذور"},{"type":"tfr","q":"الخشب واللحاء متطابقان تمامًا في التركيب والوظيفة.","answer":false,"reasons":["الخشب ميت مجوّف مقوّى باللجنين ينقل الماء والأملاح ↑، واللحاء حي بأنابيب غربالية ينقل الغذاء ↑↓","نعم متطابقان","كلاهما ميت"],"reason":0},{"type":"tfr","q":"تمتص الشعيرات الجذرية الماء بالأسموزية والأملاح المعدنية بالنقل النشط.","answer":true,"reasons":["كلاهما بالتبخر","الأسموزية لا تحتاج طاقة، بينما النقل النشط يحتاج طاقة من التنفس","كلاهما بالنقل النشط فقط"],"reason":1},{"type":"tfr","q":"تحتوي خلايا الشعيرات الجذرية على أعداد كبيرة من البلاستيدات الخضراء.","answer":false,"reasons":["تقوم بالتمثيل الضوئي","نعم مليئة بها","تخلو من البلاستيدات الخضراء لوجودها في الظلام تحت التربة"],"reason":2},{"type":"tfr","q":"يساعد «تماسك جزيئات الماء» على صعود عمود الماء متصلًا في أوعية الخشب حتى قمم الأشجار.","answer":true,"reasons":["فتسحب كل جزيئة ماء الجزيئة التي تحتها عند حدوث النتح","الماء لا يتماسك","يصعد كفقاعات منفصلة"],"reason":0},{"type":"essay","q":"قارن في جدول بين نسيج الخشب ونسيج اللحاء من حيث: طبيعة الخلايا، المواد المنقولة، واتجاه النقل.","model":"الخشب: خلايا ميتة مجوفة بها لجنين، ينقل الماء والأملاح، للأعلى فقط. اللحاء: خلايا حية (أنابيب غربالية ومرافقة)، ينقل السكروز والأحماض الأمينية، في اتجاهين."},{"type":"essay","q":"اذكر ثلاثة تكيّفات في تركيب أوعية الخشب تلائم وظيفتها.","model":"١) خالية من السيتوبلازم والجدر العرضية لتسهيل مرور الماء. ٢) جدران مغلظة باللجنين لمنع الانطباق ودعم النبات. ٣) ضيقة لرفع الماء بالتماسك والتلاصق."},{"type":"essay","q":"صف موضع الخشب واللحاء في كل من: الجذر، الساق، والورقة.","model":"الجذر: الخشب في المركز (شكل X) واللحاء بين أذرعه. الساق: حزم في حلقة، الخشب للداخل واللحاء للخارج. الورقة: الخشب أعلى واللحاء أسفل."},{"type":"essay","q":"فسّر كيف تثبت تجربة ساق الكرفس والصبغة الحمراء أن الماء ينتقل في الخشب.","model":"بعد وضع الساق في ماء ملون بالأحمر وقطعه عرضيًا، تظهر البقع الحمراء في مواضع أوعية الخشب فقط دون بقية الأنسجة."},{"type":"essay","q":"لماذا قد تموت شجرة إذا قرضت الحيوانات اللحاء المحيط بساقها بالكامل؟","model":"لأن اللحاء يقع للخارج فإزالته تقطع إمداد الجذور بالسكروز، فتموت خلايا الجذور ويتوقف امتصاص الماء فتموت الشجرة."}]},
  {"id":"g9-bio-2-u10","grade":"g9","subject":"biology","term":2,"title":"الوحدة العاشرة: التحكّم والتنظيم في النبات","levels":{"easy":[{"type":"mcq","q":"ما نوع استجابة «الساق» للضوء وللجاذبية على الترتيب؟","options":["كلاهما موجب","ضوئي سالب وأرضي موجب","انتحاء ضوئي موجب، وانتحاء أرضي سالب","كلاهما سالب"],"answer":2,"why":"ينمو الساق نحو الضوء (موجب) وعكس الجاذبية للأعلى (سالب)."},{"type":"mcq","q":"ما نوع استجابة «الجذر» للجاذبية الأرضية؟","options":["لا يستجيب للجاذبية","انتحاء أرضي سالب","انتحاء ضوئي موجب","انتحاء أرضي موجب (ينمو للأسفل نحو الجاذبية)"],"answer":3,"why":"نمو الجذر للأسفل يثبت النبات ويصل به للماء والأملاح."},{"type":"mcq","q":"ما وظيفة جهاز «الكلينوستات» (الدوار ببطء) في تجربة الانتحاء الأرضي؟","options":["توزيع تأثير الجاذبية بالتساوي على كل الجوانب كعينة ضابطة فتنمو البادرة مستقيمةً","زيادة الجاذبية","تسخين النبات","منع الضوء"],"answer":0,"why":"الدوران البطيء يلغي التوجيه الأحادي للجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الضوئي الموجب للساق؟","options":["تثبيت الجذور","توجيه الأوراق نحو الضوء لزيادة معدل التمثيل الضوئي","تقليل امتصاص الماء","منع الإزهار"],"answer":1,"why":"الحصول على أكبر قدر من الضوء ضروري لصنع الغذاء."}],"medium":[{"type":"mcq","q":"إذا وُضعت نبتة أصيص «أفقيًا على جانبها» في غرفة مظلمة، كيف ستنمو ساقها بعد أيام؟","options":["تبقى أفقية تمامًا","تنمو للأسفل","تنحني للأعلى عكس الجاذبية (انتحاء أرضي سالب)","تموت فورًا"],"answer":2,"why":"حتى في الظلام تستجيب الساق للجاذبية وتنمو للأعلى."},{"type":"mcq","q":"ما المقصود بـ«الانتحاء (Tropism)» في النباتات؟","options":["تبخر الماء فقط","حركة النبات من مكان لآخر","انقباض عضلات النبات","استجابة نمو أجزاء النبات بالاتجاه نحو مؤثر خارجي أو بعيدًا عنه"],"answer":3,"why":"الانتحاء استجابة نمو موجهة للمؤثرات كالضوء والجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الأرضي الموجب للجذر؟","options":["تثبيت النبات بقوة في التربة والوصول إلى الماء والأملاح المعدنية","امتصاص ضوء الشمس","نشر حبوب اللقاح","إنتاج الثمار"],"answer":0,"why":"التثبيت والماء والأملاح أهم وظائف الجذر."},{"type":"tfr","q":"إذا زُرعت بذرة بالمقلوب فلن ينمو جذرها نحو الأسفل أبدًا.","answer":false,"reasons":["ينمو الجذر في الهواء","بل ينحني الجذير تلقائيًا للأسفل بالانتحاء الأرضي الموجب وتصعد الريشة للأعلى","لا تنبت البذرة"],"reason":1},{"type":"tfr","q":"يؤدي تراكم الأكسين في الجانب المظلل للساق إلى استطالة خلاياه أسرع فتنحني الساق نحو الضوء.","answer":true,"reasons":["ينحني بعيدًا عن الضوء","يثبط الجانب المظلل","وهذا يفسّر الانتحاء الضوئي الموجب في السيقان"],"reason":2}],"hard":[{"type":"mcq","q":"لماذا نجري تجربة «الانتحاء الأرضي» عادةً داخل مكان مظلم؟","options":["لأن الجاذبية تعمل في الظلام فقط","لاستبعاد تأثير الضوء حتى نتأكد أن الانحناء ناتج عن الجاذبية وحدها","لأن النبات لا ينمو في الضوء","لتبريد الغرفة"],"answer":1,"why":"تثبيت/عزل المتغيرات يضمن أن الجاذبية هي السبب الوحيد."},{"type":"mcq","q":"في تجربة الصندوق ذي الفتحة الجانبية، تنحني ساق البادرة نحو الفتحة بسبب:","options":["قوة الرياح","الانتحاء الأرضي الموجب","الانتحاء الضوئي الموجب","النتح"],"answer":2,"why":"الضوء القادم من جهة واحدة يسبب انحناء الساق نحوه."},{"type":"mcq","q":"إذا أدرنا بادرة نبات على الكلينوستات ببطء في الظلام، كيف سينمو جذرها؟","options":["يتوقف عن النمو","منحنيًا للأعلى","منحنيًا للأسفل بشدة","مستقيمًا أفقيًا دون انحناء للأسفل"],"answer":3,"why":"الدوران يوزع الجاذبية بالتساوي فيمنع الانحناء."},{"type":"essay","q":"قارن بين استجابة «الساق» واستجابة «الجذر» لكل من الضوء والجاذبية الأرضية، مع ذكر الفائدة لكل منهما.","model":"الساق: ضوئي موجب (لامتصاص الضوء والتمثيل الضوئي) وأرضي سالب (للصعود نحو الضوء). الجذر: أرضي موجب (للتثبيت وامتصاص الماء والأملاح) وضوئي سالب."},{"type":"essay","q":"اشرح كيف تُجري تجربة لإثبات الانتحاء الأرضي في جذور بادرات الفول مع ذكر التجربة الضابطة.","model":"نثبت بادرات أفقيًا في مكان مظلم فتنحني الجذور للأسفل والسيقان للأعلى. والضابطة: نثبت بادرات مماثلة على كلينوستات يدور ببطء في الظلام فتنمو مستقيمة أفقيًا."}]},"test":[{"type":"mcq","q":"ما نوع استجابة «الساق» للضوء وللجاذبية على الترتيب؟","options":["كلاهما موجب","ضوئي سالب وأرضي موجب","انتحاء ضوئي موجب، وانتحاء أرضي سالب","كلاهما سالب"],"answer":2,"why":"ينمو الساق نحو الضوء (موجب) وعكس الجاذبية للأعلى (سالب)."},{"type":"mcq","q":"ما نوع استجابة «الجذر» للجاذبية الأرضية؟","options":["لا يستجيب للجاذبية","انتحاء أرضي سالب","انتحاء ضوئي موجب","انتحاء أرضي موجب (ينمو للأسفل نحو الجاذبية)"],"answer":3,"why":"نمو الجذر للأسفل يثبت النبات ويصل به للماء والأملاح."},{"type":"mcq","q":"ما وظيفة جهاز «الكلينوستات» (الدوار ببطء) في تجربة الانتحاء الأرضي؟","options":["توزيع تأثير الجاذبية بالتساوي على كل الجوانب كعينة ضابطة فتنمو البادرة مستقيمةً","زيادة الجاذبية","تسخين النبات","منع الضوء"],"answer":0,"why":"الدوران البطيء يلغي التوجيه الأحادي للجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الضوئي الموجب للساق؟","options":["تثبيت الجذور","توجيه الأوراق نحو الضوء لزيادة معدل التمثيل الضوئي","تقليل امتصاص الماء","منع الإزهار"],"answer":1,"why":"الحصول على أكبر قدر من الضوء ضروري لصنع الغذاء."},{"type":"mcq","q":"إذا وُضعت نبتة أصيص «أفقيًا على جانبها» في غرفة مظلمة، كيف ستنمو ساقها بعد أيام؟","options":["تبقى أفقية تمامًا","تنمو للأسفل","تنحني للأعلى عكس الجاذبية (انتحاء أرضي سالب)","تموت فورًا"],"answer":2,"why":"حتى في الظلام تستجيب الساق للجاذبية وتنمو للأعلى."},{"type":"mcq","q":"ما المقصود بـ«الانتحاء (Tropism)» في النباتات؟","options":["تبخر الماء فقط","حركة النبات من مكان لآخر","انقباض عضلات النبات","استجابة نمو أجزاء النبات بالاتجاه نحو مؤثر خارجي أو بعيدًا عنه"],"answer":3,"why":"الانتحاء استجابة نمو موجهة للمؤثرات كالضوء والجاذبية."},{"type":"mcq","q":"ما الفائدة الحيوية من الانتحاء الأرضي الموجب للجذر؟","options":["تثبيت النبات بقوة في التربة والوصول إلى الماء والأملاح المعدنية","امتصاص ضوء الشمس","نشر حبوب اللقاح","إنتاج الثمار"],"answer":0,"why":"التثبيت والماء والأملاح أهم وظائف الجذر."},{"type":"mcq","q":"لماذا نجري تجربة «الانتحاء الأرضي» عادةً داخل مكان مظلم؟","options":["لأن الجاذبية تعمل في الظلام فقط","لاستبعاد تأثير الضوء حتى نتأكد أن الانحناء ناتج عن الجاذبية وحدها","لأن النبات لا ينمو في الضوء","لتبريد الغرفة"],"answer":1,"why":"تثبيت/عزل المتغيرات يضمن أن الجاذبية هي السبب الوحيد."},{"type":"mcq","q":"في تجربة الصندوق ذي الفتحة الجانبية، تنحني ساق البادرة نحو الفتحة بسبب:","options":["قوة الرياح","الانتحاء الأرضي الموجب","الانتحاء الضوئي الموجب","النتح"],"answer":2,"why":"الضوء القادم من جهة واحدة يسبب انحناء الساق نحوه."},{"type":"mcq","q":"إذا أدرنا بادرة نبات على الكلينوستات ببطء في الظلام، كيف سينمو جذرها؟","options":["يتوقف عن النمو","منحنيًا للأعلى","منحنيًا للأسفل بشدة","مستقيمًا أفقيًا دون انحناء للأسفل"],"answer":3,"why":"الدوران يوزع الجاذبية بالتساوي فيمنع الانحناء."},{"type":"mcq","q":"كيف تختلف استجابة النبات عن استجابة الحيوان للمؤثرات؟","options":["استجابة النبات أبطأ وتتم بالنمو والهرمونات دون جهاز عصبي أو عضلات","النبات أسرع ولها أعصاب","متطابقتان تمامًا","النبات لا يستجيب أبدًا"],"answer":0,"why":"النباتات تستجيب ببطء عبر النمو المنظّم هرمونيًا."},{"type":"mcq","q":"أين يُنتج هرمون «الأكسين (Auxin)» في النبات؟","options":["في التربة","في القمم النامية للساق والجذر","في أوعية الخشب الميتة","في الكيوتيكل الشمعي"],"answer":1,"why":"تُنتج القمة النامية الأكسين ثم ينتشر للخلايا خلفها."},{"type":"tf","q":"تُظهر ساق النبات انتحاءً ضوئيًا موجبًا وانتحاءً أرضيًا سالبًا.","answer":true,"why":"فتنمو دائمًا نحو الضوء وللأعلى عكس الجاذبية"},{"type":"tf","q":"تحتاج النباتات إلى جهاز عصبي ودماغ لتقوم بالانتحاء الضوئي والأرضي.","answer":false,"why":"لا تملك النباتات جهازًا عصبيًا، بل تنظّم استجاباتها عبر الهرمونات النباتية كالأكسين"},{"type":"tf","q":"نمو الجذور للأسفل نحو التربة مثال على الانتحاء الأرضي الموجب.","answer":true,"why":"مما يضمن تثبيت النبات وامتصاص الماء والأملاح"},{"type":"tf","q":"استخدام الكلينوستات الدوار في تجربة الانتحاء الأرضي يمثّل «تجربة ضابطة» تثبت أن الجاذبية هي سبب الانحناء.","answer":true,"why":"لأن إلغاء اتجاه الجاذبية الأحادي يجعل البادرة تنمو مستقيمة"},{"type":"tfr","q":"إذا زُرعت بذرة بالمقلوب فلن ينمو جذرها نحو الأسفل أبدًا.","answer":false,"reasons":["ينمو الجذر في الهواء","بل ينحني الجذير تلقائيًا للأسفل بالانتحاء الأرضي الموجب وتصعد الريشة للأعلى","لا تنبت البذرة"],"reason":1},{"type":"tfr","q":"يؤدي تراكم الأكسين في الجانب المظلل للساق إلى استطالة خلاياه أسرع فتنحني الساق نحو الضوء.","answer":true,"reasons":["ينحني بعيدًا عن الضوء","يثبط الجانب المظلل","وهذا يفسّر الانتحاء الضوئي الموجب في السيقان"],"reason":2},{"type":"tfr","q":"تأثير الأكسين العالي في الجذر هو نفسه تمامًا في الساق (كلاهما ينشّط الاستطالة).","answer":false,"reasons":["في الساق ينشّط الاستطالة، أما في الجذر فيُثبّطها مما يفسّر انحناء الجذر للأسفل","نعم متطابقان","في الساق يثبطها"],"reason":0},{"type":"tfr","q":"تُعد القمة النامية للبادرة هي الجزء الحساس للضوء والمنتج لهرمون الأكسين.","answer":true,"reasons":["الأوراق القديمة فقط","فإذا قُطعت أو غُطّيت بغطاء معتم لم تنحنِ البادرة نحو الضوء","الجذور هي الحساسة للضوء"],"reason":1},{"type":"essay","q":"قارن بين استجابة «الساق» واستجابة «الجذر» لكل من الضوء والجاذبية الأرضية، مع ذكر الفائدة لكل منهما.","model":"الساق: ضوئي موجب (لامتصاص الضوء والتمثيل الضوئي) وأرضي سالب (للصعود نحو الضوء). الجذر: أرضي موجب (للتثبيت وامتصاص الماء والأملاح) وضوئي سالب."},{"type":"essay","q":"اشرح كيف تُجري تجربة لإثبات الانتحاء الأرضي في جذور بادرات الفول مع ذكر التجربة الضابطة.","model":"نثبت بادرات أفقيًا في مكان مظلم فتنحني الجذور للأسفل والسيقان للأعلى. والضابطة: نثبت بادرات مماثلة على كلينوستات يدور ببطء في الظلام فتنمو مستقيمة أفقيًا."},{"type":"essay","q":"لماذا يضع أصحاب المشاتل أصص النباتات المنزلية قرب النوافذ ويُديرون الأصيص كل عدة أيام؟","model":"لأن الساق تنحني نحو ضوء النافذة بالانتحاء الضوئي الموجب، وتدوير الأصيص يجعل النمو مستقيمًا ومتوازنًا من كل الجهات."},{"type":"essay","q":"عرّف كلًا من: الانتحاء الموجب، الانتحاء السالب، والكلينوستات.","model":"الموجب: نمو نحو المؤثر. السالب: نمو بعيدًا عن المؤثر. الكلينوستات: جهاز يدور ببطء لتوزيع الجاذبية بالتساوي وإلغاء تأثيرها من جهة واحدة."},{"type":"essay","q":"لماذا يجب إجراء تجربة الانتحاء الأرضي في «الظلام»؟","model":"لمنع تداخل الانتحاء الضوئي مع التجربة، فنتيقّن أن الجاذبية وحدها هي التي سبّبت الانحناء."}]}
);
